/// The private library holds author research; every response names the file
/// it came from so a damaged library can be repaired by hand.
fn source_contributors(
    state: &AppState,
) -> BTreeMap<String, openblog_core::contributor::Contributor> {
    site::load_config(&state.root)
        .unwrap_or_default()
        .contributors
}

fn list_sources(state: &AppState) -> Response {
    match source_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => Response::json(
            200,
            &json!({
                "file": source_store::LIBRARY_FILE,
                "revision": snapshot.revision,
                "stored": snapshot.stored,
                "sources": snapshot.library.sources,
            }),
        ),
        Err(error) => source_store_error(state, error, None),
    }
}

/// Read a change request: JSON, bounded, and naming the revision it was based on.
fn source_request(req: &Request) -> Result<(Json, String), Response> {
    require_json(req)?;
    if req.body.len() > MAX_SOURCE_REQUEST_BYTES {
        return Err(Response::error(
            413,
            "A source change is limited to 256 KiB",
        ));
    }
    let body: Json =
        serde_json::from_slice(&req.body).map_err(|_| Response::error(400, "Invalid JSON"))?;
    let Some(revision) = body["revision"].as_str().map(str::to_string) else {
        return Err(Response::error(400, "Missing library revision"));
    };
    Ok((body, revision))
}

/// Create (`POST`) or update (`PUT`) one source from its full JSON record.
fn save_source(state: &AppState, req: &Request, create: bool) -> Response {
    let (body, revision) = match source_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let record = match SourceRecord::from_json(body["source"].clone()) {
        Ok(record) => record,
        Err(diagnostics) => return source_diagnostics(diagnostics),
    };
    let id = record.id.clone();
    let contributors = source_contributors(state);
    let saved = if create {
        source_store::create(&state.root, &revision, record, &contributors)
    } else {
        source_store::update(&state.root, &revision, record, &contributors)
    };
    match saved {
        Ok(snapshot) => {
            let mut view = source_saved_view(&snapshot, &id);
            if !create {
                attach_comparisons_build_if_used(
                    state,
                    &mut view,
                    alignment_store::PublishedUse::Source(&id),
                );
            }
            Response::json(if create { 201 } else { 200 }, &view)
        }
        Err(error) => source_store_error(state, error, Some(&id)),
    }
}

fn archive_source(state: &AppState, req: &Request) -> Response {
    let (body, revision) = match source_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let (Some(id), Some(archived)) = (body["id"].as_str(), body["archived"].as_bool()) else {
        return Response::error(400, "Name the source id and whether it is archived");
    };
    match source_store::set_archived(
        &state.root,
        &revision,
        id,
        archived,
        &source_contributors(state),
    ) {
        Ok(snapshot) => {
            let mut view = source_saved_view(&snapshot, id);
            attach_comparisons_build_if_used(
                state,
                &mut view,
                alignment_store::PublishedUse::Source(id),
            );
            Response::json(200, &view)
        }
        Err(error) => source_store_error(state, error, Some(id)),
    }
}

/// Preview (`apply: false`) or apply a CSL JSON import. The preview never
/// writes. An apply is refused whole if any item conflicts, and otherwise
/// goes through the same revision-checked, atomic store as every other change.
fn import_sources(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    if req.body.len() > MAX_SOURCE_IMPORT_BYTES {
        return Response::error(413, "A source import is limited to 3 MiB");
    }
    let Ok(body) = serde_json::from_slice::<Json>(&req.body) else {
        return Response::error(400, "Invalid JSON");
    };
    let (Some(revision), Some(content)) = (body["revision"].as_str(), body["content"].as_str())
    else {
        return Response::error(400, "Name the library revision and the CSL JSON content");
    };
    let apply = body["apply"].as_bool().unwrap_or(false);
    let contributors = source_contributors(state);
    let snapshot = match source_store::load(&state.root, &contributors) {
        Ok(snapshot) => snapshot,
        Err(error) => return source_store_error(state, error, None),
    };
    if snapshot.revision != revision {
        return source_store_error(state, StoreError::Conflict, None);
    }
    let plan = match plan_csl_import(&snapshot.library, content, &contributors) {
        Ok(plan) => plan,
        Err(diagnostics) => return source_diagnostics(diagnostics),
    };
    if !apply || (!plan.has_changes() && plan.is_applicable()) {
        return Response::json(
            200,
            &json!({
                "file": source_store::LIBRARY_FILE,
                "revision": snapshot.revision,
                "applied": false,
                "applicable": plan.is_applicable(),
                "plan": plan,
            }),
        );
    }
    if !plan.is_applicable() {
        let blockers = plan.blockers();
        let error = blockers.first().map_or_else(
            || "The import has conflicts".to_string(),
            ToString::to_string,
        );
        return Response::json(
            422,
            &json!({ "error": error, "file": source_store::LIBRARY_FILE, "diagnostics": blockers, "plan": plan }),
        );
    }
    match source_store::import_csl(&state.root, revision, content, &contributors) {
        Ok((saved, plan)) => {
            let mut view = json!({
                "file": source_store::LIBRARY_FILE,
                "revision": saved.revision,
                "stored": saved.stored,
                "applied": true,
                "applicable": true,
                "plan": plan,
                "sources": saved.library.sources,
            });
            // An import may fill in attribution on records a comparison publishes.
            attach_comparisons_build_if_used(
                state,
                &mut view,
                alignment_store::PublishedUse::AnySource,
            );
            Response::json(200, &view)
        }
        Err(error) => source_store_error(state, error, None),
    }
}

/// Export the whole library, including archived sources, as CSL JSON or
/// BibTeX. The content is deterministic for a given library revision, and
/// `losses` names everything the format could not carry.
fn export_sources(state: &AppState, req: &Request) -> Response {
    let format = req.query.get("format").map_or("csl-json", String::as_str);
    if !["csl-json", "bibtex"].contains(&format) {
        return Response::error(400, "Export format must be csl-json or bibtex");
    }
    let snapshot = match source_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => snapshot,
        Err(error) => return source_store_error(state, error, None),
    };
    let (export, filename, media_type) = if format == "bibtex" {
        (
            source_interchange::export_bibtex(&snapshot.library),
            "open-blog-sources.bib",
            "application/x-bibtex",
        )
    } else {
        (
            source_interchange::export_csl_json(&snapshot.library),
            "open-blog-sources.json",
            "application/vnd.citationstyles.csl+json",
        )
    };
    Response::json(
        200,
        &json!({
            "file": source_store::LIBRARY_FILE,
            "revision": snapshot.revision,
            "format": format,
            "filename": filename,
            "mediaType": media_type,
            "count": export.count,
            "content": export.content,
            "losses": export.losses,
        }),
    )
}

fn source_saved_view(snapshot: &source_store::Snapshot, id: &str) -> Json {
    json!({
        "revision": snapshot.revision,
        "stored": snapshot.stored,
        "source": snapshot.library.get(id),
    })
}

fn source_diagnostics(diagnostics: Vec<SourceDiagnostic>) -> Response {
    let error = diagnostics.first().map_or_else(
        || "The source is invalid".to_string(),
        |first| first.to_string(),
    );
    Response::json(
        422,
        &json!({
            "error": error,
            "file": source_store::LIBRARY_FILE,
            "diagnostics": diagnostics,
        }),
    )
}

/// A conflict carries the latest revision and the newer copy of the source
/// being changed, so the editor can keep the draft and compare it. Nothing is
/// written either way.
fn source_store_error(state: &AppState, error: StoreError, id: Option<&str>) -> Response {
    match error {
        StoreError::Conflict => {
            let latest = source_store::load(&state.root, &source_contributors(state)).ok();
            let current = latest
                .as_ref()
                .zip(id)
                .and_then(|(snapshot, id)| snapshot.library.get(id));
            Response::json(
                409,
                &json!({
                    "error": error.to_string(),
                    "conflict": true,
                    "revision": latest.as_ref().map(|snapshot| snapshot.revision.as_str()),
                    "current": current,
                }),
            )
        }
        StoreError::Invalid(diagnostics) => source_diagnostics(diagnostics),
        StoreError::Storage(message) => Response::error(500, &message),
    }
}

// ---------------------------------------------------------------------------
// Citations: the editor's citation picker
// ---------------------------------------------------------------------------

const PASSAGE_PREVIEW_CHARS: usize = 160;

/// What the citation picker offers: the source library with the revision a
/// check must name, and the notebook's live passages so a citation can start
/// from one. A passage contributes only its id, source, a short excerpt
/// preview and its locators' kind, value and end. An unreadable notebook
/// leaves the picker working from the library alone.
fn citation_library(state: &AppState) -> Response {
    let contributors = source_contributors(state);
    let snapshot = match source_store::load(&state.root, &contributors) {
        Ok(snapshot) => snapshot,
        Err(error) => return source_store_error(state, error, None),
    };
    let notebook = notebook_store::load(&state.root, &contributors).ok();
    let passages: Vec<Json> = notebook
        .as_ref()
        .map(|notebook| {
            notebook
                .notebook
                .passages
                .iter()
                .filter(|passage| !passage.archived)
                .map(|passage| {
                    let locators: Vec<PublicLocator> =
                        passage.locators.iter().map(PublicLocator::from).collect();
                    json!({
                        "id": passage.id,
                        "source": passage.source,
                        "preview": passage.excerpt.text.chars().take(PASSAGE_PREVIEW_CHARS).collect::<String>(),
                        "locators": locators,
                    })
                })
                .collect()
        })
        .unwrap_or_default();
    Response::json(
        200,
        &json!({
            "file": source_store::LIBRARY_FILE,
            "revision": snapshot.revision,
            "sources": snapshot.library.sources,
            "passages": passages,
            "notebookAvailable": notebook.is_some(),
        }),
    )
}

/// Check one citation for insertion. Read-only: it names the library revision
/// the picker showed, and a newer library is a `409` carrying the latest one
/// so the picker can refresh without losing the author's choices. The
/// citation goes through the core parser and resolver, so the Markdown it
/// returns is exactly what a build will read; a problem is a `422` scoped to
/// this citation. Nothing is written.
fn check_citation_request(state: &AppState, req: &Request) -> Response {
    let body = match research_read_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let Some(revision) = body["revision"].as_str() else {
        return Response::error(400, "Missing source library revision");
    };
    let snapshot = match source_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => snapshot,
        Err(error) => return source_store_error(state, error, None),
    };
    if snapshot.revision != revision {
        return Response::json(
            409,
            &json!({
                "error": "The source library changed after the citation picker opened. Nothing was inserted; review the refreshed sources and insert again.",
                "conflict": true,
                "revision": snapshot.revision,
                "sources": snapshot.library.sources,
            }),
        );
    }
    let checked = citations::citation_from_parts(&body["citation"])
        .map_err(|found| vec![found])
        .and_then(|citation| citations::check_citation(&citation, &snapshot.library));
    match checked {
        Ok(checked) => {
            let mut view = json!(checked);
            view["revision"] = json!(snapshot.revision);
            Response::json(200, &view)
        }
        Err(diagnostics) => Response::json(
            422,
            &json!({
                "error": diagnostics.first().map_or("The citation is invalid", |found| found.message.as_str()),
                "diagnostics": diagnostics,
            }),
        ),
    }
}

// ---------------------------------------------------------------------------
// Draft-side research panel (#61, ADR 0122)
// ---------------------------------------------------------------------------

/// A panel part that could not be read: its own message, naming the file.
/// Store messages name files and ids, never quoted or noted text.
fn draft_research_problem(what: &str, file: &str, error: &impl std::fmt::Display) -> Json {
    let detail = error.to_string();
    json!({
        "error": format!(
            "{what} could not be read, so it is not offered here. Nothing was changed. {}",
            detail.lines().next().unwrap_or_default()
        ),
        "file": file,
    })
}

/// A part of the draft-side research that is not read because a part it is
/// read against (`part`) already failed. It names no file of its own, so
/// nothing sends the author to repair a file that is fine.
fn draft_research_blocked(items: &str, part: &str, what: &str) -> Json {
    json!({
        "error": format!(
            "The {items} are not offered while {what} cannot be read. Nothing was changed."
        ),
        "unavailableBecause": part,
    })
}

/// A rights declaration as the author states it, labelled by the core and
/// never read as permission (ADR 0085).
fn draft_research_rights(
    declared: Option<&openblog_core::source_library::RightsDeclaration>,
    status: openblog_core::source_library::RightsStatus,
) -> Json {
    json!({
        "status": status.tag(),
        "label": status.label(),
        "note": declared.and_then(|rights| rights.note.as_deref()),
        "license": declared.and_then(|rights| rights.license.as_deref()),
    })
}

/// What the draft-side research panel offers (#61, ADR 0122), read-only and
/// for the author only, like the rest of Admin. Each part is read on its own,
/// so a store that cannot be read is reported in its part while the others
/// still work:
///
/// - `library`: the sources with the revision a citation check must name,
///   each version's rights statement, and the interpretations (private and
///   never cited).
/// - `notebook`: live passages with their exact wording and language, public
///   locators and how many notes link to each, and live notes, offered only
///   for explicit conversion.
/// - `atlas` and `comparisons`: whether the site publishes them and, per
///   item, whether the author approved it. A canonical `url` is present only
///   for an item the next build publishes, so nothing else can be linked, and
///   an entry lists only the datings its page publishes.
///
/// Nothing is written and nothing here is public.
fn draft_research(state: &AppState) -> Response {
    use openblog_core::atlas_publication::{entry_url, ATLAS_URL};
    use openblog_core::comparison_publication::{ComparisonInputs, COMPARISONS_URL};
    let contributors = source_contributors(state);
    let config = site::load_config(&state.root).ok();
    let atlas_published = config
        .as_ref()
        .is_some_and(|config| config.knowledge_atlas.publish);
    let comparisons_published = config
        .as_ref()
        .is_some_and(|config| config.comparisons.publish);

    let library = match source_store::load(&state.root, &contributors) {
        Ok(snapshot) => {
            let sources: Vec<Json> = snapshot
                .library
                .sources
                .iter()
                .map(|record| {
                    let mut value = json!(record);
                    if let Some(status) = record.rights_status() {
                        value["rightsStatus"] =
                            draft_research_rights(record.rights.as_ref(), status);
                    }
                    value
                })
                .collect();
            let interpretations: Vec<Json> = snapshot
                .library
                .interpretations
                .iter()
                .map(|interpretation| {
                    json!({
                        "id": interpretation.id,
                        "kind": interpretation.kind,
                        "source": interpretation.source,
                        "locators": interpretation
                            .locators
                            .iter()
                            .map(PublicLocator::from)
                            .collect::<Vec<_>>(),
                        "language": interpretation.language,
                        "text": interpretation.text,
                    })
                })
                .collect();
            json!({
                "revision": snapshot.revision,
                "sources": sources,
                "interpretations": interpretations,
            })
        }
        Err(error) => {
            draft_research_problem("The source library", source_store::LIBRARY_FILE, &error)
        }
    };

    // Each part is read against the parts before it (the notebook against the library, the
    // atlas and the comparisons against both). When an earlier part already failed, that
    // failure is the reason: the later file is not blamed or sent for repair.
    let library_failed = library.get("error").is_some();
    let notebook = if library_failed {
        draft_research_blocked("passages and notes", "library", "the source library")
    } else {
        match notebook_store::load(&state.root, &contributors) {
            Ok(snapshot) => {
                let notebook = &snapshot.notebook;
                let passages: Vec<Json> = notebook
                    .passages
                    .iter()
                    .filter(|passage| !passage.archived)
                    .map(|passage| {
                        let notes = notebook
                            .notes
                            .iter()
                            .filter(|note| note.passages.contains(&passage.id))
                            .count();
                        json!({
                            "id": passage.id,
                            "source": passage.source,
                            "locators": passage
                                .locators
                                .iter()
                                .map(PublicLocator::from)
                                .collect::<Vec<_>>(),
                            "excerpt": {
                                "text": passage.excerpt.text,
                                "language": passage.excerpt.language,
                            },
                            "notes": notes,
                        })
                    })
                    .collect();
                let notes: Vec<Json> = notebook
                    .notes
                    .iter()
                    .filter(|note| !note.archived)
                    .map(|note| {
                        json!({
                            "id": note.id,
                            "kind": note.kind,
                            "status": note.question_state(),
                            "text": note.text,
                            "passages": note.passages,
                        })
                    })
                    .collect();
                json!({ "revision": snapshot.revision, "passages": passages, "notes": notes })
            }
            Err(error) => draft_research_problem(
                "The research notebook",
                notebook_store::NOTEBOOK_FILE,
                &error,
            ),
        }
    };

    let blocked_by = if library_failed {
        Some(("library", "the source library"))
    } else if notebook.get("error").is_some() {
        Some(("notebook", "the research notebook"))
    } else {
        None
    };
    let atlas = if let Some((part, what)) = blocked_by {
        draft_research_blocked("atlas entries", part, what)
    } else {
        match atlas_store::load(&state.root, &contributors) {
            Ok(snapshot) => {
                let atlas = &snapshot.atlas;
                let entries: Vec<Json> = atlas
                    .entries
                    .iter()
                    .map(|entry| {
                        let approved = entry.visibility == knowledge_atlas::Visibility::Approved;
                        let published = atlas_published && approved;
                        let datings: Vec<Json> = entry
                            .dates
                            .iter()
                            .filter(|dating| {
                                published && atlas.is_dating_projected(&entry.id, dating)
                            })
                            .map(|dating| {
                                json!({
                                    "id": dating.id,
                                    "aspect": dating.aspect,
                                    "text": date_text(&dating.date),
                                })
                            })
                            .collect();
                        json!({
                            "id": entry.id,
                            "kind": entry.kind,
                            "label": entry.label,
                            "aliases": entry.aliases,
                            "approved": approved,
                            "url": published.then(|| entry_url(&entry.id)),
                            "datings": datings,
                        })
                    })
                    .collect();
                json!({ "publish": atlas_published, "url": ATLAS_URL, "entries": entries })
            }
            Err(error) => {
                draft_research_problem("The Knowledge Atlas", atlas_store::ATLAS_FILE, &error)
            }
        }
    };

    let comparisons = if let Some((part, what)) = blocked_by {
        draft_research_blocked("comparisons", part, what)
    } else {
        match alignment_store::load(&state.root, &contributors) {
            Ok(snapshot) => {
                let inputs = ComparisonInputs {
                    library: &snapshot.library,
                    notebook: &snapshot.notebook,
                    contributors: &contributors,
                };
                // The projection a build would write, once: an item is
                // published exactly when that projection holds it. A set the
                // build would refuse publishes nothing.
                let projection = comparisons_published
                    .then(|| {
                        openblog_core::comparison_publication::PublicComparisons::project(
                            &snapshot.alignments,
                            inputs,
                        )
                        .ok()
                    })
                    .flatten();
                let items: Vec<Json> = snapshot
                    .alignments
                    .alignments
                    .iter()
                    .map(|alignment| {
                        let approved = alignment.is_approved();
                        let url = projection.as_ref().and_then(|public| {
                            public
                                .comparisons
                                .iter()
                                .find(|comparison| comparison.id == alignment.id)
                                .map(|comparison| comparison.url.clone())
                        });
                        json!({
                            "id": alignment.id,
                            "label": alignment.label,
                            "approved": approved,
                            "url": url,
                            "interpretations": alignment
                                .members
                                .iter()
                                .filter_map(|member| member.interpretation.as_deref())
                                .collect::<Vec<_>>(),
                        })
                    })
                    .collect();
                json!({ "publish": comparisons_published, "url": COMPARISONS_URL, "items": items })
            }
            Err(error) => {
                draft_research_problem("The comparisons", alignment_store::ALIGNMENTS_FILE, &error)
            }
        }
    };

    Response::json(
        200,
        &json!({
            "library": library,
            "notebook": notebook,
            "atlas": atlas,
            "comparisons": comparisons,
        }),
    )
}

// ---------------------------------------------------------------------------
// Research notebook: private passages and notes
// ---------------------------------------------------------------------------

/// The notebook is private author research. Responses are `no-store` like the
/// rest of Admin, name the file for repair, and carry both the notebook
/// revision a change must name and the source library the entries point into.
fn list_notebook(state: &AppState) -> Response {
    match notebook_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => Response::json(200, &notebook_view(&snapshot)),
        Err(error) => notebook_store_error(state, error, None),
    }
}

/// Read a search or backlinks request: a small JSON object. Research text
/// travels in the body, never the URL, so a proxy or access log cannot record it.
fn research_read_body(req: &Request) -> Result<Json, Response> {
    require_json(req)?;
    if req.body.len() > MAX_RESEARCH_READ_BYTES {
        return Err(Response::error(
            413,
            "A notebook search is limited to 16 KiB",
        ));
    }
    match serde_json::from_slice::<Json>(&req.body) {
        Ok(body) if body.is_object() => Ok(body),
        _ => Err(Response::error(400, "Invalid JSON")),
    }
}

/// Search the private notebook. Read-only (a POST only so the text stays out
/// of the URL) and recomputed from the stored files on every call, so it
/// cannot disagree with them. A bad filter is a field-scoped `422`; no match
/// is an ordinary empty result. Nothing is written, and the response is
/// `no-store` like the rest of Admin.
fn search_notebook(state: &AppState, req: &Request) -> Response {
    let body = match research_read_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let param = |name: &str| {
        body[name]
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    };
    let mut problems = Vec::new();
    let question = match param("state").as_deref() {
        None => None,
        Some(text) => {
            let parsed = QuestionState::parse(text);
            if parsed.is_none() {
                problems.push(NoteDiagnostic {
                    code: NoteDiagnosticCode::InvalidField,
                    collection: None,
                    index: None,
                    id: None,
                    field: Some("state".into()),
                    message: "use open or resolved".into(),
                });
            }
            parsed
        }
    };
    if !problems.is_empty() {
        return notebook_diagnostics(problems);
    }
    let query = SearchQuery {
        // Only the query text keeps its inner spacing; the core folds it.
        text: body["q"].as_str().unwrap_or_default().to_string(),
        source: param("source"),
        locator_kind: param("locator"),
        concept: param("concept"),
        state: question,
        include_archived: body["includeArchived"].as_bool().unwrap_or(false),
    };
    let snapshot = match notebook_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => snapshot,
        Err(error) => return notebook_store_error(state, error, None),
    };
    match research_search::search(&snapshot.notebook, &snapshot.library, &query) {
        Ok(results) => {
            let mut view = json!(results);
            view["revision"] = json!(snapshot.revision);
            view["file"] = json!(notebook_store::NOTEBOOK_FILE);
            Response::json(200, &view)
        }
        Err(diagnostics) => notebook_diagnostics(diagnostics),
    }
}

/// What points at a source, a passage, or a concept: `{"type": "source|passage|concept", "id": ...}`
/// in the body, since an id can itself be private research vocabulary.
fn notebook_backlinks(state: &AppState, req: &Request) -> Response {
    let body = match research_read_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = body["id"].as_str().unwrap_or_default().to_string();
    let target = match body["type"].as_str() {
        Some("source") => BacklinkTarget::Source(id),
        Some("passage") => BacklinkTarget::Passage(id),
        Some("concept") => BacklinkTarget::Concept(id),
        _ => return Response::error(400, "Name a type: source, passage, or concept"),
    };
    let snapshot = match notebook_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => snapshot,
        Err(error) => return notebook_store_error(state, error, None),
    };
    match research_search::backlinks(&snapshot.notebook, &snapshot.library, &target) {
        Ok(found) => {
            let mut view = json!(found);
            view["revision"] = json!(snapshot.revision);
            Response::json(200, &view)
        }
        Err(diagnostics) => notebook_diagnostics(diagnostics),
    }
}

fn notebook_view(snapshot: &notebook_store::Snapshot) -> Json {
    json!({
        "file": notebook_store::NOTEBOOK_FILE,
        "revision": snapshot.revision,
        "stored": snapshot.stored,
        "passages": snapshot.notebook.passages,
        "notes": snapshot.notebook.notes,
        "sources": snapshot.library.sources,
    })
}

/// Read a change request: JSON, bounded, and naming the revision it was based on.
fn notebook_request(req: &Request) -> Result<(Json, String), Response> {
    require_json(req)?;
    if req.body.len() > MAX_NOTEBOOK_REQUEST_BYTES {
        return Err(Response::error(
            413,
            "A research change is limited to 256 KiB",
        ));
    }
    let body: Json =
        serde_json::from_slice(&req.body).map_err(|_| Response::error(400, "Invalid JSON"))?;
    let Some(revision) = body["revision"].as_str().map(str::to_string) else {
        return Err(Response::error(400, "Missing notebook revision"));
    };
    Ok((body, revision))
}

/// Create (`POST`) or update (`PUT`) one passage from its full JSON form.
fn save_passage(state: &AppState, req: &Request, create: bool) -> Response {
    let (body, revision) = match notebook_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let passage = match Passage::from_json(body["passage"].clone()) {
        Ok(passage) => passage,
        Err(diagnostics) => return notebook_diagnostics(diagnostics),
    };
    let id = passage.id.clone();
    let contributors = source_contributors(state);
    let saved = if create {
        notebook_store::create_passage(&state.root, &revision, passage, &contributors)
    } else {
        notebook_store::update_passage(&state.root, &revision, passage, &contributors)
    };
    match saved {
        Ok(snapshot) => {
            let mut view = notebook_view(&snapshot);
            view["passage"] = json!(snapshot.notebook.passage(&id));
            if !create {
                attach_comparisons_build_if_used(
                    state,
                    &mut view,
                    alignment_store::PublishedUse::Passage(&id),
                );
            }
            Response::json(if create { 201 } else { 200 }, &view)
        }
        Err(error) => notebook_store_error(state, error, Some((true, &id))),
    }
}

/// Create (`POST`) or update (`PUT`) one note from its full JSON form.
fn save_note(state: &AppState, req: &Request, create: bool) -> Response {
    let (body, revision) = match notebook_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let note = match ResearchNote::from_json(body["note"].clone()) {
        Ok(note) => note,
        Err(diagnostics) => return notebook_diagnostics(diagnostics),
    };
    let id = note.id.clone();
    let contributors = source_contributors(state);
    let saved = if create {
        notebook_store::create_note(&state.root, &revision, note, &contributors)
    } else {
        notebook_store::update_note(&state.root, &revision, note, &contributors)
    };
    match saved {
        Ok(snapshot) => {
            let mut view = notebook_view(&snapshot);
            view["note"] = json!(snapshot.notebook.note(&id));
            Response::json(if create { 201 } else { 200 }, &view)
        }
        Err(error) => notebook_store_error(state, error, Some((false, &id))),
    }
}

/// Remove one passage (refused while a note links to it) or one note.
fn remove_entry(state: &AppState, req: &Request, passage: bool) -> Response {
    let (body, revision) = match notebook_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let Some(id) = body["id"].as_str() else {
        return Response::error(400, "Name the id of the entry to remove");
    };
    let contributors = source_contributors(state);
    let removed = if passage {
        notebook_store::remove_passage(&state.root, &revision, id, &contributors)
    } else {
        notebook_store::remove_note(&state.root, &revision, id, &contributors)
    };
    match removed {
        Ok(snapshot) => Response::json(200, &notebook_view(&snapshot)),
        Err(error) => notebook_store_error(state, error, Some((passage, id))),
    }
}

/// Archive or restore one passage or note. It only sets the entry aside; the
/// text stays in the file and in exports, and removal rules are unchanged.
fn archive_entry(state: &AppState, req: &Request) -> Response {
    let (body, revision) = match notebook_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let (Some(id), Some(archived)) = (body["id"].as_str(), body["archived"].as_bool()) else {
        return Response::error(400, "Name the entry id and whether it is archived");
    };
    let collection = match body["type"].as_str() {
        Some("passage") => notebook_store::Collection::Passages,
        Some("note") => notebook_store::Collection::Notes,
        _ => return Response::error(400, "Name a type: passage or note"),
    };
    match notebook_store::set_archived(
        &state.root,
        &revision,
        collection,
        id,
        archived,
        &source_contributors(state),
    ) {
        Ok(snapshot) => {
            let mut view = notebook_view(&snapshot);
            if collection == notebook_store::Collection::Passages {
                attach_comparisons_build_if_used(
                    state,
                    &mut view,
                    alignment_store::PublishedUse::Passage(id),
                );
            }
            Response::json(200, &view)
        }
        Err(error) => notebook_store_error(
            state,
            error,
            Some((collection == notebook_store::Collection::Passages, id)),
        ),
    }
}

/// Export the whole private notebook as a versioned bundle. Private research
/// text leaves the project only through this route, and only when the request
/// says so explicitly (`includePrivate: true`); nothing else reads the notebook
/// into an export. Read-only, deterministic for a revision, and `no-store`.
fn export_notebook(state: &AppState, req: &Request) -> Response {
    let body = match research_read_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    if body["includePrivate"] != json!(true) {
        return Response::error(
            400,
            "The export contains your private passages and notes; confirm that with includePrivate: true",
        );
    }
    let snapshot = match notebook_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => snapshot,
        Err(error) => return notebook_store_error(state, error, None),
    };
    let export = research_bundle::export(&snapshot.notebook, &snapshot.library);
    Response::json(
        200,
        &json!({
            "file": notebook_store::NOTEBOOK_FILE,
            "revision": snapshot.revision,
            "private": true,
            "filename": research_bundle::BUNDLE_FILENAME,
            "mediaType": "application/json",
            "passages": export.passages,
            "notes": export.notes,
            "archived": export.archived,
            "content": export.content,
        }),
    )
}

/// Preview (`apply: false`) or apply a research bundle, sent as the raw file
/// text in `content` (parsed here, so unknown fields restore byte for byte). The preview never writes. An apply is refused whole when any entry
/// conflicts, and otherwise goes through the same revision-checked, atomic
/// store as every other notebook change.
fn import_notebook(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    if req.body.len() > MAX_RESEARCH_IMPORT_BYTES {
        return Response::error(413, "A research bundle is limited to 4.25 MiB");
    }
    let Ok(body) = serde_json::from_slice::<Json>(&req.body) else {
        return Response::error(400, "Invalid JSON");
    };
    let (Some(revision), true) = (body["revision"].as_str(), body["content"].is_string()) else {
        return Response::error(400, "Name the notebook revision and send the bundle");
    };
    let apply = body["apply"].as_bool().unwrap_or(false);
    let content = body["content"].as_str().unwrap_or_default().to_string();
    let contributors = source_contributors(state);
    let snapshot = match notebook_store::load(&state.root, &contributors) {
        Ok(snapshot) => snapshot,
        Err(error) => return notebook_store_error(state, error, None),
    };
    if snapshot.revision != revision {
        return notebook_store_error(state, notebook_store::StoreError::Conflict, None);
    }
    let plan = match research_bundle::plan_import(&snapshot.notebook, &snapshot.library, &content) {
        Ok(plan) => plan,
        Err(diagnostics) => return notebook_diagnostics(diagnostics),
    };
    if !apply || (!plan.has_changes() && plan.is_applicable()) {
        return Response::json(
            200,
            &json!({
                "file": notebook_store::NOTEBOOK_FILE,
                "revision": snapshot.revision,
                "applied": false,
                "applicable": plan.is_applicable(),
                "plan": plan,
            }),
        );
    }
    if !plan.is_applicable() {
        let blockers = plan.blockers();
        let error = blockers.first().map_or_else(
            || "The import has conflicts".to_string(),
            ToString::to_string,
        );
        return Response::json(
            422,
            &json!({ "error": error, "file": notebook_store::NOTEBOOK_FILE, "diagnostics": blockers, "plan": plan }),
        );
    }
    match notebook_store::import_bundle(&state.root, revision, &content, &contributors) {
        Ok((saved, plan)) => {
            let mut view = notebook_view(&saved);
            view["applied"] = json!(true);
            view["applicable"] = json!(true);
            view["plan"] = json!(plan);
            Response::json(200, &view)
        }
        Err(error) => notebook_store_error(state, error, None),
    }
}

fn notebook_diagnostics(diagnostics: Vec<NoteDiagnostic>) -> Response {
    let error = diagnostics.first().map_or_else(
        || "The research entry is invalid".to_string(),
        |first| first.to_string(),
    );
    Response::json(
        422,
        &json!({
            "error": error,
            "file": notebook_store::NOTEBOOK_FILE,
            "diagnostics": diagnostics,
        }),
    )
}

/// A conflict carries the latest revision and the newer copy of the entry
/// being changed, so the editor can keep the draft and compare it. Nothing is
/// written either way.
fn notebook_store_error(
    state: &AppState,
    error: notebook_store::StoreError,
    entry: Option<(bool, &str)>,
) -> Response {
    match error {
        notebook_store::StoreError::Conflict => {
            let latest = notebook_store::load(&state.root, &source_contributors(state)).ok();
            let current = latest
                .as_ref()
                .zip(entry)
                .and_then(|(snapshot, (passage, id))| {
                    if passage {
                        snapshot.notebook.passage(id).map(|p| json!(p))
                    } else {
                        snapshot.notebook.note(id).map(|n| json!(n))
                    }
                });
            Response::json(
                409,
                &json!({
                    "error": error.to_string(),
                    "conflict": true,
                    "revision": latest.as_ref().map(|snapshot| snapshot.revision.as_str()),
                    "current": current,
                }),
            )
        }
        notebook_store::StoreError::Invalid(diagnostics) => notebook_diagnostics(diagnostics),
        notebook_store::StoreError::Storage(message) => Response::error(500, &message),
    }
}

// ---------------------------------------------------------------------------
// Knowledge Atlas: private entries and attributed relationships (ADR 0057)
// ---------------------------------------------------------------------------

/// A short, character-safe preview of private text for a picker label.
fn atlas_preview(text: &str) -> String {
    let flat = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if flat.chars().count() <= 80 {
        flat
    } else {
        let mut cut: String = flat.chars().take(79).collect();
        cut.push('…');
        cut
    }
}

/// What every relationship kind may join, read from the core so the Admin
/// pickers can never offer an endpoint the store would refuse.
fn atlas_kinds() -> Json {
    let names = |kinds: &[EntryKind]| kinds.iter().map(|k| k.as_str()).collect::<Vec<_>>();
    json!({
        "entries": names(&EntryKind::ALL),
        "relationships": RelationshipKind::ALL
            .iter()
            .map(|kind| json!({
                "kind": kind.as_str(),
                "inverse": kind.inverse_label(),
                "from": names(kind.from_kinds()),
                "to": names(kind.to_kinds()),
                "symmetric": kind.is_symmetric(),
                "sameKind": kind.requires_same_kind(),
                "acyclic": kind.is_acyclic(),
            }))
            .collect::<Vec<_>>(),
        // What a dating may date on each owner, so the dating editor offers
        // only aspects the core accepts and a duration only where one lasts.
        "aspects": Aspect::ALL
            .iter()
            .map(|aspect| json!({
                "aspect": aspect.as_str(),
                "durative": aspect.is_durative(),
                "entries": names(&EntryKind::ALL
                    .into_iter()
                    .filter(|kind| aspect.applies_to(*kind))
                    .collect::<Vec<_>>()),
                "relationship": *aspect == Aspect::Span,
            }))
            .collect::<Vec<_>>(),
        "orders": TemporalOrder::ALL.iter().map(|order| order.as_str()).collect::<Vec<_>>(),
        "maxDatings": MAX_DATINGS,
        "maxYear": MAX_YEAR,
    })
}

/// The chronology index for the explorer (ADR 0096, ADR 0097): every dating,
/// private or approved, in the index's one display order, with its owner, its
/// stated value read back at its own precision, and the first and last year
/// it covers (none for an open end, a relative or an unknown dating), plus the
/// structural prompts. Nothing is chosen, merged or dropped, and this view is
/// for the author only, like the rest of Admin.
fn atlas_chronology(atlas: &knowledge_atlas::Atlas) -> Json {
    let index = ChronologyIndex::of(atlas);
    let mut found = BTreeMap::new();
    for (position, entry) in atlas.entries.iter().enumerate() {
        for (at, dating) in entry.dates.iter().enumerate() {
            found.insert(
                dating.id.as_str(),
                ("entries", position, entry.id.as_str(), at, dating),
            );
        }
    }
    for (position, relationship) in atlas.relationships.iter().enumerate() {
        for (at, dating) in relationship.dates.iter().enumerate() {
            found.insert(
                dating.id.as_str(),
                (
                    "relationships",
                    position,
                    relationship.id.as_str(),
                    at,
                    dating,
                ),
            );
        }
    }
    let timeline: Vec<Json> = index
        .by_time
        .iter()
        .filter_map(|id| found.get(id.as_str()))
        .map(|(collection, position, owner, at, dating)| {
            let (placement, start, end) = match dating.key() {
                ChronoKey::Dated { start, end } => (
                    "dated",
                    (start.0 != i32::MIN).then_some(start.0),
                    (end.0 != i32::MAX).then_some(end.0),
                ),
                ChronoKey::Relative => ("relative", None, None),
                ChronoKey::Unknown => ("unknown", None, None),
            };
            json!({
                "id": dating.id,
                "owner": owner,
                "collection": collection,
                "index": position,
                "field": format!("dates[{at}]"),
                "aspect": dating.aspect,
                "text": date_text(&dating.date),
                "placement": placement,
                "startYear": start,
                "endYear": end,
                "projected": atlas.is_dating_projected(owner, dating),
            })
        })
        .collect();
    json!({
        "timeline": timeline,
        "prompts": index.prompts,
        "unlisted": index.unlisted,
    })
}

/// The atlas as stored, with what the editor picks from: the library's
/// sources and the notebook's passages (id, source, locators and a short
/// preview, never a copy into the atlas). `no-store` like the rest of Admin.
fn atlas_view(snapshot: &atlas_store::Snapshot) -> Json {
    let atlas = &snapshot.atlas;
    let passages: Vec<Json> = snapshot
        .notebook
        .passages
        .iter()
        .map(|passage| {
            json!({
                "id": passage.id,
                "source": passage.source,
                "locators": passage.locators,
                "archived": passage.archived,
                "preview": atlas_preview(&passage.excerpt.text),
            })
        })
        .collect();
    json!({
        "file": atlas_store::ATLAS_FILE,
        "revision": snapshot.revision,
        "stored": snapshot.stored,
        "entries": atlas.entries,
        "relationships": atlas.relationships,
        "notices": atlas.notices(),
        "chronology": atlas_chronology(atlas),
        "missingConcepts": atlas.missing_concepts(&snapshot.notebook),
        "kinds": atlas_kinds(),
        "sources": snapshot.library.sources,
        "passages": passages,
    })
}

fn list_atlas(state: &AppState) -> Response {
    match atlas_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => Response::json(200, &atlas_view(&snapshot)),
        Err(error) => atlas_store_error(state, error, None),
    }
}

/// Every relationship that touches one entry, read from that entry's side
/// (`authored` going out, `authored by` coming in), with its derived standing.
/// Only asserted relationships appear; nothing is mirrored or inferred. The
/// id travels in the body like a notebook backlink, and nothing is written.
fn explore_atlas(state: &AppState, req: &Request) -> Response {
    let body = match research_read_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let Some(id) = body["id"]
        .as_str()
        .filter(|id| knowledge_atlas::valid_id(id))
    else {
        return Response::error(400, "Name the id of the entry to explore");
    };
    let snapshot = match atlas_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => snapshot,
        Err(error) => return atlas_store_error(state, error, None),
    };
    let atlas = &snapshot.atlas;
    let Some(entry) = atlas.entry(id) else {
        return Response::json(
            404,
            &json!({ "error": "No atlas entry has this id", "missing": true, "revision": snapshot.revision }),
        );
    };
    let (mut outgoing, mut incoming) = (Vec::new(), Vec::new());
    for incident in atlas.relationships_of(id) {
        let other = atlas.entry(incident.other);
        let view = json!({
            "label": incident.label,
            "other": {
                "id": incident.other,
                "kind": other.map(|e| e.kind),
                "label": other.map(|e| e.label.as_str()),
            },
            "standing": match incident.relationship.standing() {
                Standing::Asserted => "asserted",
                Standing::Contested => "contested",
            },
            "projected": atlas.is_projected(incident.relationship),
            "relationship": incident.relationship,
        });
        match incident.direction {
            Direction::Outgoing => outgoing.push(view),
            Direction::Incoming => incoming.push(view),
        }
    }
    let notes: Vec<Json> = if entry.kind == EntryKind::Concept {
        snapshot
            .notebook
            .notes
            .iter()
            .filter(|note| note.concepts.iter().any(|concept| concept == id))
            .map(|note| json!({ "id": note.id, "kind": note.kind, "preview": atlas_preview(&note.text) }))
            .collect()
    } else {
        Vec::new()
    };
    Response::json(
        200,
        &json!({
            "revision": snapshot.revision,
            "entry": entry,
            "outgoing": outgoing,
            "incoming": incoming,
            "notes": notes,
        }),
    )
}

/// Read an atlas change request: JSON, bounded, and naming the revision.
fn atlas_request(req: &Request) -> Result<(Json, String), Response> {
    require_json(req)?;
    if req.body.len() > MAX_NOTEBOOK_REQUEST_BYTES {
        return Err(Response::error(
            413,
            "An atlas change is limited to 256 KiB",
        ));
    }
    let body: Json =
        serde_json::from_slice(&req.body).map_err(|_| Response::error(400, "Invalid JSON"))?;
    let Some(revision) = body["revision"].as_str().map(str::to_string) else {
        return Err(Response::error(400, "Missing atlas revision"));
    };
    Ok((body, revision))
}

fn atlas_saved(
    state: &AppState,
    snapshot: &atlas_store::Snapshot,
    key: &str,
    item: Json,
    create: bool,
) -> Response {
    let mut view = atlas_view(snapshot);
    view[key] = item;
    attach_atlas_build(state, &mut view);
    Response::json(if create { 201 } else { 200 }, &view)
}

/// While the site publishes its atlas (ADR 0058), a saved atlas change is
/// published at once, so granting or withdrawing approval reaches the public
/// site without waiting for another save. The outcome travels as `build`; a
/// site that does not publish its atlas is not rebuilt.
fn attach_atlas_build(state: &AppState, view: &mut Json) {
    let publishes = site::load_config(&state.root)
        .map(|config| config.knowledge_atlas.publish)
        .unwrap_or(false);
    if !publishes {
        return;
    }
    view["build"] = match state.rebuild() {
        Ok(report) => json!({ "ok": true, "files": report.files }),
        Err(error) => json!({ "ok": false, "error": error }),
    };
}

/// Create (`POST`) or update (`PUT`) one entry from its full JSON form.
fn save_atlas_entry(state: &AppState, req: &Request, create: bool) -> Response {
    let (body, revision) = match atlas_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let entry = match AtlasEntry::from_json(body["entry"].clone()) {
        Ok(entry) => entry,
        Err(diagnostics) => return atlas_diagnostics(diagnostics),
    };
    let id = entry.id.clone();
    let contributors = source_contributors(state);
    let saved = if create {
        atlas_store::create_entry(&state.root, &revision, entry, &contributors)
    } else {
        atlas_store::update_entry(&state.root, &revision, entry, &contributors)
    };
    match saved {
        Ok(snapshot) => {
            let item = json!(snapshot.atlas.entry(&id));
            atlas_saved(state, &snapshot, "entry", item, create)
        }
        Err(error) => atlas_store_error(state, error, Some((true, &id))),
    }
}

/// Create (`POST`) or update (`PUT`) one relationship from its full JSON form.
fn save_atlas_relationship(state: &AppState, req: &Request, create: bool) -> Response {
    let (body, revision) = match atlas_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let relationship = match AtlasRelationship::from_json(body["relationship"].clone()) {
        Ok(relationship) => relationship,
        Err(diagnostics) => return atlas_diagnostics(diagnostics),
    };
    let id = relationship.id.clone();
    let contributors = source_contributors(state);
    let saved = if create {
        atlas_store::create_relationship(&state.root, &revision, relationship, &contributors)
    } else {
        atlas_store::update_relationship(&state.root, &revision, relationship, &contributors)
    };
    match saved {
        Ok(snapshot) => {
            let item = json!(snapshot.atlas.relationship(&id));
            atlas_saved(state, &snapshot, "relationship", item, create)
        }
        Err(error) => atlas_store_error(state, error, Some((false, &id))),
    }
}

/// Remove one entry (refused while a relationship joins it; notes whose
/// concept link becomes unresolved are reported) or one relationship.
fn remove_atlas_item(state: &AppState, req: &Request, entry: bool) -> Response {
    let (body, revision) = match atlas_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    // Checked before it is named in any message, so a hostile id is never echoed.
    let Some(id) = body["id"]
        .as_str()
        .filter(|id| knowledge_atlas::valid_id(id))
    else {
        return Response::error(400, "Name the id of the entry or relationship to remove");
    };
    let contributors = source_contributors(state);
    if entry {
        match atlas_store::remove_entry(&state.root, &revision, id, &contributors) {
            Ok((snapshot, removal)) => {
                let mut view = atlas_view(&snapshot);
                view["unresolvedNotes"] = json!(removal.unresolved_notes);
                attach_atlas_build(state, &mut view);
                Response::json(200, &view)
            }
            Err(error) => atlas_store_error(state, error, Some((true, id))),
        }
    } else {
        match atlas_store::remove_relationship(&state.root, &revision, id, &contributors) {
            Ok(snapshot) => {
                let mut view = atlas_view(&snapshot);
                attach_atlas_build(state, &mut view);
                Response::json(200, &view)
            }
            Err(error) => atlas_store_error(state, error, Some((false, id))),
        }
    }
}

fn atlas_diagnostics(diagnostics: Vec<AtlasDiagnostic>) -> Response {
    let error = diagnostics.first().map_or_else(
        || "The atlas change is invalid".to_string(),
        |first| first.to_string(),
    );
    Response::json(
        422,
        &json!({
            "error": error,
            "file": atlas_store::ATLAS_FILE,
            "diagnostics": diagnostics,
        }),
    )
}

/// A conflict carries the latest revision and the newer copy of the entry or
/// relationship being changed, so the editor can keep the draft and compare.
/// Nothing is written either way.
fn atlas_store_error(
    state: &AppState,
    error: atlas_store::StoreError,
    item: Option<(bool, &str)>,
) -> Response {
    match error {
        atlas_store::StoreError::Conflict => {
            let latest = atlas_store::load(&state.root, &source_contributors(state)).ok();
            let current = latest
                .as_ref()
                .zip(item)
                .and_then(|(snapshot, (entry, id))| {
                    if entry {
                        snapshot.atlas.entry(id).map(|e| json!(e))
                    } else {
                        snapshot.atlas.relationship(id).map(|r| json!(r))
                    }
                });
            Response::json(
                409,
                &json!({
                    "error": error.to_string(),
                    "conflict": true,
                    "revision": latest.as_ref().map(|snapshot| snapshot.revision.as_str()),
                    "current": current,
                }),
            )
        }
        atlas_store::StoreError::Invalid(diagnostics) => atlas_diagnostics(diagnostics),
        atlas_store::StoreError::Storage(message) => Response::error(500, &message),
    }
}

// ---- claims and evidence links (Evidence Studio, ADR 0071 to 0073) ----------

/// The saved drafts by slug, with each post's content path for findings.
type SavedPosts = (claims::Drafts, BTreeMap<String, String>);

/// The anchor texts claims are checked against: every saved post's body, by
/// slug. Unsaved editor text is never used.
fn claim_drafts(state: &AppState) -> Result<SavedPosts, Response> {
    let config = site::load_config(&state.root).map_err(|error| Response::error(500, &error))?;
    Ok(claims_store::read_saved_posts(
        &state.root,
        &config.paths.content,
    ))
}

/// The claims file as stored, with what the editor picks from (library
/// sources and notebook passages, previews only), every anchored claim's
/// status against the saved drafts, per-relation counts that are never
/// combined, the projection notices, and which links a projection could copy.
fn claims_view(snapshot: &claims_store::Snapshot, posts: &SavedPosts) -> Json {
    let (drafts, paths) = posts;
    let set = &snapshot.claims;
    // The same findings, in the same order, as `openblog check` and builds.
    let findings = openblog_core::claim_review::review_claims(
        set,
        &openblog_core::claim_review::ReviewContext {
            drafts,
            paths,
            claims_file: claims_store::CLAIMS_FILE,
            library: &snapshot.library,
            notebook: &snapshot.notebook,
        },
    );
    let passages: Vec<Json> = snapshot
        .notebook
        .passages
        .iter()
        .map(|passage| {
            json!({
                "id": passage.id,
                "source": passage.source,
                "locators": passage.locators,
                "archived": passage.archived,
                "preview": atlas_preview(&passage.excerpt.text),
            })
        })
        .collect();
    let mut anchors = Map::new();
    let mut counts = Map::new();
    for claim in &set.claims {
        counts.insert(claim.id.clone(), json!(set.counts(&claim.id)));
        if let Some(check) = claims::anchor_status(claim, drafts) {
            let mut status = json!({ "status": check.as_str() });
            if let claims::AnchorCheck::Moved { start } = check {
                status["start"] = json!(start);
            }
            if !drafts.contains_key(&claim.post) {
                status["missingPost"] = json!(true);
            }
            anchors.insert(claim.id.clone(), status);
        }
    }
    let projected: Vec<&str> = set
        .projected_links()
        .iter()
        .map(|link| link.id.as_str())
        .collect();
    json!({
        "file": claims_store::CLAIMS_FILE,
        "revision": snapshot.revision,
        "stored": snapshot.stored,
        "claims": set.claims,
        "links": set.links,
        "notices": set.notices(),
        "findings": findings,
        "anchors": anchors,
        "counts": counts,
        "projected": projected,
        "relations": claims::Relation::ALL.map(claims::Relation::as_str),
        "sources": snapshot.library.sources,
        "passages": passages,
    })
}

/// The claims view. With `?path=posts/...md` it also names the slug that
/// post's claims carry, decided from its saved front matter as a build does.
fn list_claims(state: &AppState, req: &Request) -> Response {
    let posts = match claim_drafts(state) {
        Ok(posts) => posts,
        Err(response) => return response,
    };
    let post = match req.query.get("path") {
        Some(rel) => {
            if check_rel_path(rel) != Ok("posts") {
                return Response::error(400, "Claims are made in posts");
            }
            let config = match site::load_config(&state.root) {
                Ok(config) => config,
                Err(error) => return Response::error(500, &error),
            };
            let path = match resolve_content_path(&state.root, &config, rel) {
                Ok(path) => path,
                Err(error) => return Response::error(400, &error),
            };
            fs::read_to_string(&path)
                .ok()
                .and_then(|source| claims::post_slug(rel, &source))
        }
        None => None,
    };
    match claims_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => {
            let mut view = claims_view(&snapshot, &posts);
            if let Some(post) = post {
                view["post"] = json!(post);
            }
            Response::json(200, &view)
        }
        Err(error) => claims_store_error(state, error, None),
    }
}

/// Check a selection against the saved draft of one post, without writing
/// anything. The editor sends the post's path and the revision (`etag`) it
/// loaded, and UTF-8 byte offsets into the post's anchor text with the exact
/// words selected. A draft saved elsewhere since it was opened is a conflict,
/// so a selection made in older text is never checked against newer text.
fn claim_anchor(state: &AppState, req: &Request) -> Response {
    let body = match research_read_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let (Some(rel), Some(revision)) = (body["path"].as_str(), body["etag"].as_str()) else {
        return Response::error(400, "Name the post's path and the revision you selected in");
    };
    let (Some(start), Some(end), Some(text)) = (
        body["start"].as_u64().and_then(|v| usize::try_from(v).ok()),
        body["end"].as_u64().and_then(|v| usize::try_from(v).ok()),
        body["text"].as_str(),
    ) else {
        return Response::error(400, "Send the selection's byte offsets and its words");
    };
    let _content = lock(&state.build);
    let config = match site::load_config(&state.root) {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    if check_rel_path(rel) != Ok("posts") {
        return Response::error(400, "Claims are made in posts");
    }
    let path = match resolve_content_path(&state.root, &config, rel) {
        Ok(path) => path,
        Err(error) => return Response::error(400, &error),
    };
    let Ok(source) = fs::read_to_string(&path) else {
        return Response::error(404, "No such post; save it first");
    };
    if etag(&source) != revision {
        return Response::json(
            409,
            &json!({ "error": "The post was saved elsewhere after you opened it, so the selection was not checked. Reload the post, then select the words again.", "draftChanged": true }),
        );
    }
    let (Some(post), Ok(draft)) = (
        claims::post_slug(rel, &source),
        claims::anchor_text(&source),
    ) else {
        return Response::error(
            422,
            "The post's front matter cannot be read, so no claim can be anchored in it",
        );
    };
    if text.is_empty() || text.contains('\r') || end <= start || end - start != text.len() {
        return Response::error(
            422,
            "The selection must be the exact words between its byte offsets",
        );
    }
    let anchor = claims::Anchor {
        start,
        end,
        text: text.to_string(),
        extra: BTreeMap::new(),
    };
    let check = anchor.check(&draft);
    let mut status = json!({ "post": post, "status": check.as_str(), "anchor": anchor });
    if let claims::AnchorCheck::Moved { start } = check {
        status["start"] = json!(start);
    }
    Response::json(200, &status)
}

/// Read a claims change request: JSON, bounded, and naming the revision.
fn claims_request(req: &Request) -> Result<(Json, String), Response> {
    require_json(req)?;
    if req.body.len() > MAX_NOTEBOOK_REQUEST_BYTES {
        return Err(Response::error(
            413,
            "A claims change is limited to 256 KiB",
        ));
    }
    let body: Json =
        serde_json::from_slice(&req.body).map_err(|_| Response::error(400, "Invalid JSON"))?;
    let Some(revision) = body["revision"].as_str().map(str::to_string) else {
        return Err(Response::error(400, "Missing claims revision"));
    };
    Ok((body, revision))
}

fn claims_saved(
    state: &AppState,
    build: &mut BuildStatus,
    snapshot: &claims_store::Snapshot,
    posts: &SavedPosts,
    key: &str,
    item: Json,
    status: u16,
) -> Response {
    let mut view = claims_view(snapshot, posts);
    view[key] = item;
    attach_claims_build(state, build, &mut view);
    Response::json(status, &view)
}

/// While the site publishes claim evidence (ADR 0075), a saved claims change
/// is published at once, so granting or withdrawing approval reaches the
/// public site without waiting for another save. The outcome travels as
/// `build`; a site that does not publish claim evidence is not rebuilt. The
/// caller already holds the content lock, which the build runs under.
fn attach_claims_build(state: &AppState, build: &mut BuildStatus, view: &mut Json) {
    let publishes = site::load_config(&state.root)
        .map(|config| config.claim_evidence.publish)
        .unwrap_or(false);
    if !publishes {
        return;
    }
    view["build"] = match state.rebuild_locked(build) {
        Ok(report) => json!({ "ok": true, "files": report.files }),
        Err(error) => json!({ "ok": false, "error": error }),
    };
}

/// Create (`POST`) or update (`PUT`) one claim from its full JSON form. The
/// saved drafts are read and the file written while the content lock is held,
/// so an Admin post save cannot slip between the anchor check and the write.
fn save_claim(state: &AppState, req: &Request, create: bool) -> Response {
    let (body, revision) = match claims_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let claim = match claims::Claim::from_json(body["claim"].clone()) {
        Ok(claim) => claim,
        Err(diagnostics) => return claims_diagnostics(diagnostics),
    };
    let id = claim.id.clone();
    let contributors = source_contributors(state);
    let mut content = lock(&state.build);
    let posts = match claim_drafts(state) {
        Ok(posts) => posts,
        Err(response) => return response,
    };
    let drafts = &posts.0;
    let saved = if create {
        claims_store::create_claim(&state.root, &revision, claim, drafts, &contributors)
    } else {
        claims_store::update_claim(&state.root, &revision, claim, drafts, &contributors)
    };
    match saved {
        Ok(snapshot) => {
            let item = json!(snapshot.claims.claim(&id));
            claims_saved(
                state,
                &mut content,
                &snapshot,
                &posts,
                "claim",
                item,
                if create { 201 } else { 200 },
            )
        }
        Err(error) => claims_store_error(state, error, Some((true, &id))),
    }
}

/// Create (`POST`) or update (`PUT`) one evidence link from its full JSON form.
fn save_claim_link(state: &AppState, req: &Request, create: bool) -> Response {
    let (body, revision) = match claims_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let link = match claims::EvidenceLink::from_json(body["link"].clone()) {
        Ok(link) => link,
        Err(diagnostics) => return claims_diagnostics(diagnostics),
    };
    let id = link.id.clone();
    let contributors = source_contributors(state);
    let mut content = lock(&state.build);
    let posts = match claim_drafts(state) {
        Ok(posts) => posts,
        Err(response) => return response,
    };
    let drafts = &posts.0;
    let saved = if create {
        claims_store::create_link(&state.root, &revision, link, drafts, &contributors)
    } else {
        claims_store::update_link(&state.root, &revision, link, drafts, &contributors)
    };
    match saved {
        Ok(snapshot) => {
            let item = json!(snapshot.claims.link(&id));
            claims_saved(
                state,
                &mut content,
                &snapshot,
                &posts,
                "link",
                item,
                if create { 201 } else { 200 },
            )
        }
        Err(error) => claims_store_error(state, error, Some((false, &id))),
    }
}

/// Remove one claim (refused while a link rests on it) or one link (always
/// allowed). The removed item travels back so the editor can offer undo.
fn remove_claim_item(state: &AppState, req: &Request, claim: bool) -> Response {
    let (body, revision) = match claims_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    // Checked before it is named in any message, so a hostile id is never echoed.
    let Some(id) = body["id"]
        .as_str()
        .filter(|id| knowledge_atlas::valid_id(id))
    else {
        return Response::error(400, "Name the id of the claim or link to remove");
    };
    let contributors = source_contributors(state);
    let mut content = lock(&state.build);
    let posts = match claim_drafts(state) {
        Ok(posts) => posts,
        Err(response) => return response,
    };
    let removed = if claim {
        claims_store::remove_claim(&state.root, &revision, id, &contributors)
    } else {
        claims_store::remove_link(&state.root, &revision, id, &contributors)
    };
    match removed {
        Ok(snapshot) => {
            let mut view = claims_view(&snapshot, &posts);
            attach_claims_build(state, &mut content, &mut view);
            Response::json(200, &view)
        }
        Err(error) => claims_store_error(state, error, Some((claim, id))),
    }
}

fn claims_diagnostics(diagnostics: Vec<AtlasDiagnostic>) -> Response {
    let error = diagnostics.first().map_or_else(
        || "The claims change is invalid".to_string(),
        |first| first.to_string(),
    );
    Response::json(
        422,
        &json!({
            "error": error,
            "file": claims_store::CLAIMS_FILE,
            "diagnostics": diagnostics,
        }),
    )
}

/// A conflict carries the latest revision and the newer copy of the claim or
/// link being changed, so the editor can offer "use stored" or "keep my
/// draft". Nothing is written either way.
fn claims_store_error(
    state: &AppState,
    error: claims_store::StoreError,
    item: Option<(bool, &str)>,
) -> Response {
    match error {
        claims_store::StoreError::Conflict => {
            let latest = claims_store::load(&state.root, &source_contributors(state)).ok();
            let current = latest
                .as_ref()
                .zip(item)
                .and_then(|(snapshot, (claim, id))| {
                    if claim {
                        snapshot.claims.claim(id).map(|c| json!(c))
                    } else {
                        snapshot.claims.link(id).map(|l| json!(l))
                    }
                });
            Response::json(
                409,
                &json!({
                    "error": error.to_string(),
                    "conflict": true,
                    "revision": latest.as_ref().map(|snapshot| snapshot.revision.as_str()),
                    "current": current,
                }),
            )
        }
        claims_store::StoreError::Invalid(diagnostics) => claims_diagnostics(diagnostics),
        claims_store::StoreError::Storage(message) => Response::json(
            500,
            &json!({ "error": message, "file": claims_store::CLAIMS_FILE }),
        ),
    }
}

// ---- Passage alignments (A6.2, ADR 0088 and ADR 0089) ----------------------
//
// Private research like the notebook and the claims file: these routes sit
// behind the session, CSRF token and deny-by-default router, are `no-store`,
// cap a change at 256 KiB, need the revision, and never publish anything. The
// comparison workspace (#54) builds its controls on them.

fn alignments_view(
    snapshot: &alignment_store::Snapshot,
    contributors: &BTreeMap<String, openblog_core::contributor::Contributor>,
) -> Json {
    let links = openblog_core::knowledge_atlas::Links {
        library: &snapshot.library,
        notebook: &snapshot.notebook,
    };
    let mut view = comparison_context(snapshot, contributors);
    let extra = json!({
        "file": alignment_store::ALIGNMENTS_FILE,
        "revision": snapshot.revision,
        "stored": snapshot.stored,
        "alignments": snapshot.alignments.alignments,
        "notices": snapshot.alignments.notices(links),
        "notice": openblog_core::alignment::ALIGNMENT_NOTICE,
        "publication": publication_preview(snapshot, contributors),
        // Approved alignments whose places moved since the approval: out of
        // the next build until the author checks them and approves again.
        "staleApprovals": openblog_core::comparison_publication::stale_approvals(
            &snapshot.alignments,
            openblog_core::comparison_publication::ComparisonInputs {
                library: &snapshot.library,
                notebook: &snapshot.notebook,
                contributors,
            },
        ),
    });
    if let (Some(view), Json::Object(extra)) = (view.as_object_mut(), extra) {
        view.extend(extra);
    }
    view
}

/// What each alignment would publish (ADR 0092), approved or not, so the
/// author sees before approving which places are quoted and which are only
/// identified: per alignment, one status per member in member order
/// (`shown`, `absent`, `unquoted`, or `withheld-rights` / `withheld-length`).
/// Admin-only like the rest of the view; nothing here is published.
fn publication_preview(
    snapshot: &alignment_store::Snapshot,
    contributors: &BTreeMap<String, openblog_core::contributor::Contributor>,
) -> Json {
    use openblog_core::comparison_publication::{
        ComparisonInputs, PublicComparison, Withheld, COMPARISONS_URL, MAX_PUBLIC_EXCERPT_CHARS,
    };
    let inputs = ComparisonInputs {
        library: &snapshot.library,
        notebook: &snapshot.notebook,
        contributors,
    };
    let mut places = serde_json::Map::new();
    for alignment in &snapshot.alignments.alignments {
        let Ok(projected) = PublicComparison::project(alignment, inputs) else {
            continue;
        };
        let statuses: Vec<Json> = projected
            .places_in_member_order()
            .into_iter()
            .map(|place| {
                json!(match (place.absent, &place.text, place.withheld) {
                    (true, _, _) => "absent",
                    (_, Some(_), _) => "shown",
                    (_, None, Some(Withheld::Rights)) => "withheld-rights",
                    (_, None, Some(Withheld::Length)) => "withheld-length",
                    (_, None, None) => "unquoted",
                })
            })
            .collect();
        places.insert(alignment.id.clone(), Json::Array(statuses));
    }
    json!({
        "url": COMPARISONS_URL,
        "maxExcerptChars": MAX_PUBLIC_EXCERPT_CHARS,
        "places": places,
    })
}

/// What the comparison workspace (#54) shows beside the alignments, read
/// under the same snapshot: every library record with its rights label and
/// realization chain, every notebook passage with its exact wording, and
/// every interpretation with its interpreters' names. Admin-only and
/// `no-store` like the rest of the private research routes; labels state the
/// author's declaration and never grant permission (ADR 0085).
fn comparison_context(
    snapshot: &alignment_store::Snapshot,
    contributors: &BTreeMap<String, openblog_core::contributor::Contributor>,
) -> Json {
    use openblog_core::alignment::Correspondence;
    use openblog_core::interpretation::InterpreterIdentity;
    use openblog_core::source_library::RightsStatus;
    let library = &snapshot.library;
    let rights = |declared: Option<&openblog_core::source_library::RightsDeclaration>,
                  status: RightsStatus| {
        json!({
            "status": status.tag(),
            "label": status.label(),
            "declared": declared.is_some(),
            "note": declared.and_then(|rights| rights.note.as_deref()),
            "license": declared.and_then(|rights| rights.license.as_deref()),
        })
    };
    let sources: Vec<Json> = library
        .sources
        .iter()
        .map(|record| {
            let mut value = json!(record);
            value["chain"] = Json::Array(
                library
                    .realization_chain(&record.id)
                    .iter()
                    .skip(1)
                    .map(|link| json!({ "id": link.id, "kind": link.kind, "title": link.title }))
                    .collect(),
            );
            if let Some(status) = record.rights_status() {
                value["rightsStatus"] = rights(record.rights.as_ref(), status);
            }
            value
        })
        .collect();
    let interpretations: Vec<Json> = library
        .interpretations
        .iter()
        .map(|interpretation| {
            let mut value = json!(interpretation);
            value["interpreters"] = Json::Array(
                interpretation
                    .interpreters
                    .iter()
                    .map(|interpreter| {
                        let mut named = json!(interpreter);
                        named["display"] = json!(match interpreter.identity() {
                            InterpreterIdentity::Contributor(key) => contributors
                                .get(key)
                                .map_or(key, |contributor| contributor.name.as_str()),
                            InterpreterIdentity::Named(name) => name,
                        });
                        named
                    })
                    .collect(),
            );
            value["rightsStatus"] = rights(
                interpretation.rights.as_ref(),
                interpretation.rights_status(),
            );
            value
        })
        .collect();
    json!({
        "sources": sources,
        "passages": snapshot.notebook.passages,
        "interpretations": interpretations,
        "correspondences": Correspondence::ALL
            .iter()
            .map(|c| json!({ "value": c.as_str(), "label": c.label() }))
            .collect::<Vec<_>>(),
    })
}

fn list_alignments(state: &AppState) -> Response {
    match alignment_store::load(&state.root, &source_contributors(state)) {
        Ok(snapshot) => {
            let mut view = alignments_view(&snapshot, &source_contributors(state));
            view["publication"]["publish"] = json!(site::load_config(&state.root)
                .map(|config| config.comparisons.publish)
                .unwrap_or(false));
            Response::json(200, &view)
        }
        Err(error) => alignments_store_error(state, error, None),
    }
}

fn alignments_request(req: &Request) -> Result<(Json, String), Response> {
    require_json(req)?;
    if req.body.len() > MAX_NOTEBOOK_REQUEST_BYTES {
        return Err(Response::error(
            413,
            "An alignments change is limited to 256 KiB",
        ));
    }
    let body: Json =
        serde_json::from_slice(&req.body).map_err(|_| Response::error(400, "Invalid JSON"))?;
    let Some(revision) = body["revision"].as_str().map(str::to_string) else {
        return Err(Response::error(400, "Missing alignments revision"));
    };
    Ok((body, revision))
}

/// Create (`POST`) or update (`PUT`) one alignment from its full JSON form.
fn save_alignment(state: &AppState, req: &Request, create: bool) -> Response {
    let (body, revision) = match alignments_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let alignment = match openblog_core::alignment::Alignment::from_json(body["alignment"].clone())
    {
        Ok(alignment) => alignment,
        Err(diagnostics) => return alignments_diagnostics(diagnostics),
    };
    let id = alignment.id.clone();
    let contributors = source_contributors(state);
    let saved = if create {
        alignment_store::create_alignment(&state.root, &revision, alignment, &contributors)
    } else {
        let reapprove = body["reapprove"].as_bool().unwrap_or(false);
        alignment_store::update_alignment(
            &state.root,
            &revision,
            alignment,
            reapprove,
            &contributors,
        )
    };
    match saved {
        Ok(snapshot) => {
            let mut view = alignments_view(&snapshot, &contributors);
            view["alignment"] = json!(snapshot.alignments.alignment(&id));
            attach_comparisons_build(state, &mut view);
            Response::json(if create { 201 } else { 200 }, &view)
        }
        Err(error) => alignments_store_error(state, error, Some(&id)),
    }
}

/// Remove one alignment. The removed alignment travels back so the editor
/// can offer undo.
fn remove_alignment_item(state: &AppState, req: &Request) -> Response {
    let (body, revision) = match alignments_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    // Checked before it is named in any message, so a hostile id is never echoed.
    let Some(id) = body["id"]
        .as_str()
        .filter(|id| knowledge_atlas::valid_id(id))
    else {
        return Response::error(400, "Name the id of the alignment to remove");
    };
    match alignment_store::remove_alignment(&state.root, &revision, id, &source_contributors(state))
    {
        Ok((snapshot, removed)) => {
            let mut view = alignments_view(&snapshot, &source_contributors(state));
            view["removed"] = json!(removed);
            attach_comparisons_build(state, &mut view);
            Response::json(200, &view)
        }
        Err(error) => alignments_store_error(state, error, Some(id)),
    }
}

/// While the site publishes comparisons (ADR 0092), a saved alignments change
/// is published at once, so approving or withdrawing a comparison reaches the
/// public site without waiting for another save. The outcome travels as
/// `build`; a site that does not publish comparisons is not rebuilt.
fn attach_comparisons_build(state: &AppState, view: &mut Json) {
    let publishes = site::load_config(&state.root)
        .map(|config| config.comparisons.publish)
        .unwrap_or(false);
    view["publication"]["publish"] = json!(publishes);
    if !publishes {
        return;
    }
    view["build"] = match state.rebuild() {
        Ok(report) => json!({ "ok": true, "files": report.files }),
        Err(error) => json!({ "ok": false, "error": error }),
    };
}

/// While the site publishes comparisons (ADR 0092), a saved or archived
/// library source or notebook passage that an approved comparison uses is
/// published at once, so a version whose rights become reserved or unknown,
/// or a passage whose wording changes, never leaves a public page quoting
/// the old wording. The outcome travels as `build`, as for alignment saves;
/// a change nothing published uses, or a site that does not publish
/// comparisons, is not rebuilt.
fn attach_comparisons_build_if_used(
    state: &AppState,
    view: &mut Json,
    used: alignment_store::PublishedUse<'_>,
) {
    let Ok(config) = site::load_config(&state.root) else {
        return;
    };
    if !config.comparisons.publish
        || !alignment_store::publishes(&state.root, &config.contributors, used)
    {
        return;
    }
    view["build"] = match state.rebuild() {
        Ok(report) => json!({ "ok": true, "files": report.files }),
        Err(error) => json!({ "ok": false, "error": error }),
    };
}

fn alignments_diagnostics(diagnostics: Vec<AtlasDiagnostic>) -> Response {
    let error = diagnostics.first().map_or_else(
        || "The alignments change is invalid".to_string(),
        |first| first.to_string(),
    );
    Response::json(
        422,
        &json!({
            "error": error,
            "file": alignment_store::ALIGNMENTS_FILE,
            "diagnostics": diagnostics,
        }),
    )
}

/// A conflict carries the latest revision and the newer copy of the
/// alignment being changed. Nothing is written either way.
fn alignments_store_error(
    state: &AppState,
    error: alignment_store::StoreError,
    id: Option<&str>,
) -> Response {
    match error {
        alignment_store::StoreError::Conflict => {
            let latest = alignment_store::load(&state.root, &source_contributors(state)).ok();
            let current = latest
                .as_ref()
                .zip(id)
                .and_then(|(snapshot, id)| snapshot.alignments.alignment(id).map(|a| json!(a)));
            Response::json(
                409,
                &json!({
                    "error": error.to_string(),
                    "conflict": true,
                    "revision": latest.as_ref().map(|snapshot| snapshot.revision.as_str()),
                    "current": current,
                }),
            )
        }
        alignment_store::StoreError::Invalid(diagnostics) => alignments_diagnostics(diagnostics),
        alignment_store::StoreError::Storage(message) => Response::json(
            500,
            &json!({ "error": message, "file": alignment_store::ALIGNMENTS_FILE }),
        ),
    }
}

fn content_transaction(
    state: &AppState,
) -> Result<Option<crate::transaction::ContentTransactionLock>, Response> {
    if DURABLE_TRANSACTION.with(std::cell::Cell::get) {
        return Ok(None);
    }
    crate::transaction::ContentTransactionLock::acquire(&state.root)
        .map(Some)
        .map_err(|error| Response::error(409, &error))
}

fn session_cookie(token: &str, max_age: u64, secure: bool) -> String {
    format!(
        "{SESSION_COOKIE}={token}; HttpOnly; SameSite=Strict; Path=/admin; Max-Age={max_age}{}",
        if secure { "; Secure" } else { "" }
    )
}

fn login(state: &AppState, req: &Request) -> Response {
    if req.method != "POST" {
        return Response::error(405, "Use POST");
    }
    if let Err(r) = check_origin(req) {
        return r;
    }
    if let Err(r) = require_json(req) {
        return r;
    }
    let config = site::load_config(&state.root).unwrap_or_default();
    let users = match Users::load(&state.root.join(&config.admin.users_file)) {
        Ok(u) => u,
        Err(e) => return Response::error(500, &e),
    };
    if users.users.is_empty() {
        return Response::error(
            503,
            "No users exist yet. Run `openblog user add <name>` on the server.",
        );
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(b) => b,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let username = body["username"].as_str().unwrap_or("").trim().to_string();
    let password = body["password"].as_str().unwrap_or("");
    if password.len() > auth::MAX_PASSWORD_LEN * 4 {
        return Response::error(400, "Password too long");
    }

    // Two limits with different jobs. The client address locks after repeated
    // failures (brute force from one place). The username only slows down
    // (brute force from many places), because a lock on a username would let
    // anyone who knows it shut its owner out.
    let client = client_ip(&config, req);
    let ip_key = format!("ip:{client}");
    let user_key = format!("user:{username}");
    let delay = {
        let mut throttle = lock(&state.throttle);
        if let Err(wait) = throttle.reserve(&ip_key) {
            return Response::error(
                429,
                &format!("Too many failed attempts. Try again in {wait} seconds."),
            )
            .with_header("Retry-After", &wait.to_string());
        }
        throttle.delay(&user_key)
    };
    std::thread::sleep(delay);

    // Always verify against *some* hash so timing does not reveal valid usernames.
    let record = users.find(&username);
    let ok = auth::verify_password(
        record
            .map(|r| r.hash.as_str())
            .unwrap_or_else(|| auth::dummy_hash()),
        password,
    ) && record.is_some();
    if !ok {
        eprintln!(
            "admin: failed login for '{}' from {client}",
            username.chars().take(32).collect::<String>()
        );
        std::thread::sleep(Duration::from_millis(300));
        return Response::error(401, "Invalid username or password");
    }

    {
        let mut throttle = lock(&state.throttle);
        throttle.clear(&ip_key);
        throttle.clear(&user_key);
    }
    let ttl = Duration::from_secs(u64::from(config.admin.session_hours.clamp(1, 24 * 30)) * 3600);
    let credential = record.map(|r| r.hash.clone()).unwrap_or_default();
    let (token, session) = match lock(&state.sessions).create(&username, &credential, ttl) {
        Ok(v) => v,
        Err(e) => return Response::error(500, &e),
    };
    eprintln!("admin: '{username}' signed in from {client}");
    Response::json(
        200,
        &json!({ "user": username, "csrf": session.csrf, "now": clock::now().rfc3339() }),
    )
    .with_header(
        "Set-Cookie",
        &session_cookie(&token, ttl.as_secs(), config.admin.secure_cookies),
    )
}

/// The address login limits apply to. The socket peer, unless that peer is a
/// configured trusted proxy, in which case the last `X-Forwarded-For` entry
/// (the one the trusted proxy itself appended; earlier entries are client-controlled).
pub(crate) fn client_ip(config: &SiteConfig, req: &Request) -> String {
    let trusted = config
        .admin
        .trusted_proxies
        .iter()
        .any(|p| p.trim() == "*" || p.trim() == req.peer);
    if trusted {
        if let Some(forwarded) = req.header("x-forwarded-for") {
            if let Some(last) = forwarded
                .rsplit(',')
                .next()
                .map(str::trim)
                .filter(|s| !s.is_empty())
            {
                let clean: String = last
                    .chars()
                    .filter(|c| c.is_ascii_hexdigit() || matches!(c, '.' | ':'))
                    .take(45)
                    .collect();
                if !clean.is_empty() {
                    return clean;
                }
            }
        }
    }
    req.peer.clone()
}

fn logout(state: &AppState, req: &Request) -> Response {
    if let Some(token) = req.cookie(SESSION_COOKIE) {
        lock(&state.sessions).remove(token);
    }
    let config = site::load_config(&state.root).unwrap_or_default();
    Response::json(200, &json!({ "ok": true })).with_header(
        "Set-Cookie",
        &session_cookie("", 0, config.admin.secure_cookies),
    )
}

// ---------------------------------------------------------------------------
// Content paths
// ---------------------------------------------------------------------------

/// Validate a client-supplied content path like `posts/2026-10-21-hello.md`.
/// Returns the content kind (`posts`, `series`, or `pages`).
fn check_rel_path(rel: &str) -> Result<&'static str, String> {
    if rel.is_empty() || rel.len() > 200 {
        return Err("path is empty or too long".into());
    }
    if !rel.ends_with(".md") {
        return Err("only Markdown (.md) files can be edited".into());
    }
    let parts: Vec<&str> = rel.split('/').collect();
    if parts.len() < 2 || parts.len() > 3 {
        return Err("path must look like posts/<name>.md".into());
    }
    for part in &parts {
        let ok = !part.is_empty()
            && !part.starts_with('.')
            && part
                .chars()
                .all(|c| c.is_alphanumeric() || matches!(c, '-' | '_' | '.'))
            && !part.contains("..");
        if !ok {
            return Err("path contains characters that are not allowed".into());
        }
    }
    match parts[0] {
        "posts" => Ok("posts"),
        "series" => Ok("series"),
        "pages" => Ok("pages"),
        "services" => Ok("services"),
        _ => Err("path must start with posts/, series/, pages/, or services/".into()),
    }
}

/// Resolve a validated relative path inside the content directory, refusing
/// anything that (via symlinks) lands outside it.
fn resolve_content_path(root: &Path, config: &SiteConfig, rel: &str) -> Result<PathBuf, String> {
    check_rel_path(rel)?;
    let content_dir = root.join(&config.paths.content);
    let canonical_content = fs::canonicalize(&content_dir)
        .map_err(|_| "the content directory does not exist".to_string())?;
    let full = content_dir.join(rel);
    let mut probe = full.as_path();
    loop {
        if probe.exists() {
            let canonical = fs::canonicalize(probe).map_err(|e| e.to_string())?;
            if !canonical.starts_with(&canonical_content) {
                return Err("path resolves outside the content directory".into());
            }
            break;
        }
        probe = probe.parent().ok_or("invalid path")?;
    }
    Ok(full)
}

/// Resolve the sidecar derived from an already validated post path with the
/// same containment guarantee as the Markdown file. Direct sidecar symlinks
/// are rejected even when they point back inside content: Admin mutations must
/// always address the regular file beside the post.
fn resolve_credit_path(root: &Path, config: &SiteConfig, rel: &str) -> Result<PathBuf, String> {
    check_rel_path(rel)?;
    let sidecar_rel = openblog_core::contributor::sidecar_path(rel)
        .ok_or_else(|| "cannot derive the post credit sidecar path".to_string())?;
    let content_dir = root.join(&config.paths.content);
    let canonical_content = fs::canonicalize(&content_dir)
        .map_err(|_| "the content directory does not exist".to_string())?;
    let full = content_dir.join(&sidecar_rel);
    if fs::symlink_metadata(&full).is_ok_and(|metadata| metadata.file_type().is_symlink()) {
        return Err("credit sidecar symlinks are not allowed".into());
    }
    let mut probe = full.as_path();
    loop {
        if probe.exists() {
            let canonical = fs::canonicalize(probe).map_err(|error| error.to_string())?;
            if !canonical.starts_with(&canonical_content) {
                return Err("credit sidecar resolves outside the content directory".into());
            }
            break;
        }
        probe = probe.parent().ok_or("invalid credit sidecar path")?;
    }
    Ok(full)
}

/// The portable projection of `post` that the Admin previews and that an acknowledgement checks,
/// with the post's series context taken from `site` (ADR 0041). The portability preview and the
/// acknowledgement both build it here, so the source revision a preview hands out is the one the
/// acknowledgement recomputes: `Site::series_context` counts only published parts whether `site`
/// holds drafts or scheduled posts or not, so a draft or scheduled part has no context in either.
fn admin_portable_projection<'a>(
    site: &Site,
    post: &'a openblog_core::Post,
    config: &SiteConfig,
) -> Result<openblog_core::portability::PortableProjection<'a>, String> {
    Ok(
        openblog_core::portability::PortableProjection::for_authenticated_preview(post, config)?
            .with_series(site.series_context(post)),
    )
}

fn resolve_portability_acknowledgement_path(
    root: &Path,
    config: &SiteConfig,
    rel: &str,
) -> Result<PathBuf, String> {
    check_rel_path(rel)?;
    if openblog_core::classify_source(rel) != Some(openblog_core::SourceKind::Post) {
        return Err("portability acknowledgements are only available for posts".into());
    }
    let sidecar_rel = openblog_core::contributor::portability_sidecar_path(rel)
        .ok_or_else(|| "cannot derive the post portability sidecar path".to_string())?;
    let content_dir = root.join(&config.paths.content);
    let canonical_content = fs::canonicalize(&content_dir)
        .map_err(|_| "the content directory does not exist".to_string())?;
    let full = content_dir.join(sidecar_rel);
    if fs::symlink_metadata(&full).is_ok_and(|metadata| metadata.file_type().is_symlink()) {
        return Err("portability sidecar symlinks are not allowed".into());
    }
    let mut probe = full.as_path();
    loop {
        if probe.exists() {
            let canonical = fs::canonicalize(probe).map_err(|error| error.to_string())?;
            if !canonical.starts_with(&canonical_content) {
                return Err("portability sidecar resolves outside the content directory".into());
            }
            break;
        }
        probe = probe.parent().ok_or("invalid portability sidecar path")?;
    }
    Ok(full)
}

fn load_portability_acknowledgements(
    path: &Path,
) -> Result<(PortabilityAcknowledgementSidecar, String), String> {
    let bytes = read_optional_bytes(path)?;
    let etag = etag_bytes(bytes.as_deref().unwrap_or_default());
    let Some(bytes) = bytes else {
        return Ok((
            PortabilityAcknowledgementSidecar {
                version: 1,
                acknowledgements: Vec::new(),
            },
            etag,
        ));
    };
    if bytes.len() > 128 * 1024 {
        return Err("portability acknowledgement sidecar exceeds 128 KiB".into());
    }
    let sidecar: PortabilityAcknowledgementSidecar = serde_json::from_slice(&bytes)
        .map_err(|error| format!("cannot parse {}: {error}", path.display()))?;
    if sidecar.version != 1 || sidecar.acknowledgements.len() > MAX_PORTABILITY_ACKNOWLEDGEMENTS {
        return Err(
            "portability acknowledgement sidecar has an unsupported version or size".into(),
        );
    }
    for acknowledgement in &sidecar.acknowledgements {
        validate_portability_acknowledgement(acknowledgement)?;
    }
    Ok((sidecar, etag))
}

fn validate_portability_acknowledgement(
    acknowledgement: &PortabilityAcknowledgement,
) -> Result<(), String> {
    if acknowledgement.source_revision.len() != 40
        || !acknowledgement
            .source_revision
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit())
        || acknowledgement.capability_id.is_empty()
        || acknowledgement.capability_id.len() > 64
        || !acknowledgement
            .capability_id
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
        || !acknowledgement_scope_supported(
            &acknowledgement.destination,
            &acknowledgement.representation,
        )
    {
        return Err("invalid portability acknowledgement scope".into());
    }
    Ok(())
}

fn acknowledgement_scope_supported(destination: &str, representation: &str) -> bool {
    match destination {
        "portable-export" => matches!(
            representation,
            "portable-html" | "portable-markdown" | "portable-text"
        ),
        "dev" | "hashnode" | "ghost" | "wordpress" | "medium" => {
            let provider = match destination {
                "dev" => SyndicationProvider::Dev,
                "hashnode" => SyndicationProvider::Hashnode,
                "ghost" => SyndicationProvider::Ghost,
                "wordpress" => SyndicationProvider::Wordpress,
                "medium" => SyndicationProvider::Medium,
                _ => return false,
            };
            let policy = destination_policy(provider);
            match policy.representation {
                DestinationRepresentation::PortableMarkdown => {
                    representation == "portable-markdown"
                }
                DestinationRepresentation::PortableHtml => representation == "portable-html",
                DestinationRepresentation::ManualMarkdown => representation == "manual-markdown",
            }
        }
        _ => false,
    }
}

fn etag(text: &str) -> String {
    etag_bytes(text.as_bytes())
}

fn etag_bytes(bytes: &[u8]) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in bytes {
        h ^= u64::from(*byte);
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    format!("{h:016x}")
}

// ---------------------------------------------------------------------------
// Reading
// ---------------------------------------------------------------------------

/// Check a job's fields with the same validation the build uses and say, in
/// the build's own sentences, what is still missing. Nothing is written.
fn job_check(state: &AppState, req: &Request) -> Response {
    if let Err(r) = require_json(req) {
        return r;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(b) => b,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let fields = match fields_from_json(&body["fields"]) {
        Ok(f) => f,
        Err(e) => return Response::error(422, &e),
    };
    let config = match site::load_config(&state.root) {
        Ok(c) => c,
        Err(e) => return Response::error(500, &e),
    };
    let front_matter = frontmatter::FrontMatter { fields };
    let problems = match openblog_core::job::from_front_matter(&front_matter, &config.extra_trades)
    {
        Ok(_) => Vec::new(),
        Err(problems) => problems,
    };
    Response::json(
        200,
        &json!({ "ok": problems.is_empty(), "problems": problems }),
    )
}

fn fields_to_json(fields: &BTreeMap<String, Value>) -> Json {
    let mut map = Map::new();
    for (k, v) in fields {
        map.insert(
            k.clone(),
            match v {
                Value::Scalar(s) => Json::String(s.clone()),
                Value::List(items) => {
                    Json::Array(items.iter().cloned().map(Json::String).collect())
                }
            },
        );
    }
    Json::Object(map)
}

/// A front matter key. The only dotted keys are the flattened `job.*` ones the
/// job profile uses (ADR 0285) and a service's `faq.<n>.<key>` ones (ADR 0311);
/// every segment is a plain word.
fn is_field_name(key: &str) -> bool {
    let plain = |part: &str| {
        !part.is_empty()
            && part
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
    };
    if let Some(rest) = key.strip_prefix("faq.") {
        let mut parts = rest.split('.');
        return matches!(
            (parts.next(), parts.next(), parts.next()),
            (Some(number), Some(name), None)
                if number.len() <= 3 && number.bytes().all(|b| b.is_ascii_digit()) && plain(name)
        );
    }
    match key.strip_prefix("job.") {
        Some(rest) => rest.split('.').count() <= 3 && rest.split('.').all(plain),
        None => plain(key),
    }
}

fn fields_from_json(value: &Json) -> Result<BTreeMap<String, Value>, String> {
    let object = value.as_object().ok_or("fields must be an object")?;
    if object.len() > 60 {
        return Err("too many fields".into());
    }
    let mut out = BTreeMap::new();
    for (key, v) in object {
        let valid_key = !key.is_empty()
            && key.len() <= 40
            && key.chars().next().is_some_and(|c| c.is_ascii_alphabetic())
            && is_field_name(key);
        if !valid_key {
            return Err(format!("field name `{key}` is not allowed"));
        }
        let scalar = |s: &str| -> Result<String, String> {
            if s.len() > 20_000 || s.contains('\0') {
                Err(format!(
                    "field `{key}` is too long or contains invalid characters"
                ))
            } else {
                Ok(s.to_string())
            }
        };
        match v {
            Json::Null => {}
            Json::String(s) => {
                out.insert(key.clone(), Value::Scalar(scalar(s)?));
            }
            Json::Bool(b) => {
                out.insert(key.clone(), Value::Scalar(b.to_string()));
            }
            Json::Number(n) => {
                out.insert(key.clone(), Value::Scalar(n.to_string()));
            }
            Json::Array(items) => {
                if items.len() > 100 {
                    return Err(format!("field `{key}` has too many items"));
                }
                let mut list = Vec::new();
                for item in items {
                    let s = item
                        .as_str()
                        .ok_or_else(|| format!("field `{key}` must be a list of text"))?;
                    if s.chars().count() > 200 {
                        return Err(format!("an item in `{key}` is too long"));
                    }
                    list.push(scalar(s)?);
                }
                out.insert(key.clone(), Value::List(list));
            }
            Json::Object(_) => return Err(format!("field `{key}` cannot be an object")),
        }
    }
    Ok(out)
}

fn meta(state: &AppState) -> Response {
    let _content_transaction = lock(&state.build);
    let config = match site::load_config(&state.root) {
        Ok(c) => c,
        Err(e) => return Response::error(500, &e),
    };
    let themes = site::load_themes(&state.root, &config).unwrap_or_default();
    let theme_list: Vec<Json> = themes
        .names()
        .into_iter()
        .filter_map(|n| {
            themes
                .resolve(&n)
                .ok()
                .map(|t| json!({ "name": n, "label": t.label }))
        })
        .collect();
    let sources = site::read_sources(&state.root, &config).unwrap_or_default();
    let mut series: Vec<Json> = Vec::new();
    for file in &sources.series {
        if let Ok(doc) = frontmatter::parse(&file.contents) {
            let stem = file
                .path
                .rsplit('/')
                .next()
                .unwrap_or("")
                .trim_end_matches(".md");
            let slug = doc
                .front_matter
                .get("slug")
                .map(slugify)
                .unwrap_or_else(|| slugify(stem));
            let name = doc
                .front_matter
                .get("name")
                .or_else(|| doc.front_matter.get("title"))
                .unwrap_or(&slug)
                .to_string();
            series.push(json!({ "slug": slug, "name": name }));
        }
    }
    let mut tags: Vec<String> = Vec::new();
    for file in &sources.posts {
        if let Ok(doc) = frontmatter::parse(&file.contents) {
            for t in doc.front_matter.get_list("tags") {
                if !tags.iter().any(|x| x.eq_ignore_ascii_case(&t)) {
                    tags.push(t);
                }
            }
        }
    }
    tags.sort_by_key(|t| t.to_lowercase());
    let mut services: Vec<String> = Vec::new();
    for file in &sources.posts {
        if let Ok(doc) = frontmatter::parse(&file.contents) {
            if let Some(service) = doc.front_matter.get("job.service") {
                if let Ok(service) = openblog_core::job::normalize_service(service) {
                    if !services.contains(&service) {
                        services.push(service);
                    }
                }
            }
        }
    }
    for file in &sources.services {
        let Ok(doc) = frontmatter::parse(&file.contents) else {
            continue;
        };
        if let Some(id) = doc.front_matter.get("id").map(str::trim) {
            if openblog_core::service::check_id(id).is_ok()
                && !doc.front_matter.get_bool("draft").unwrap_or(false)
                && !services.iter().any(|known| known == id)
            {
                services.push(id.to_string());
            }
        }
    }
    services.sort();
    let job_form = json!({
        "trades": openblog_core::job::known_trades(&config.extra_trades),
        "costBands": openblog_core::job::CostBand::ALL.map(openblog_core::job::CostBand::as_str),
        "services": services,
        "scaffold": openblog_core::job::scaffold_body(),
    });
    let profiles: Vec<Json> = openblog_core::profile::catalog()
        .iter()
        .map(|profile| {
            json!({
                "id": profile.id,
                "label": profile.label,
                "description": profile.description,
                "fields": profile.fields.iter().map(|field| json!({
                    "key": field.key,
                    "label": field.label,
                    "kind": field.kind.as_str(),
                    "help": field.help,
                })).collect::<Vec<_>>(),
            })
        })
        .collect();
    let credit_roles = openblog_core::contributor::role_catalog()
        .into_iter()
        .map(|role| {
            json!({
                "vocabulary": role.vocabulary.as_str(),
                "role": role.role,
                "label": role.label(),
            })
        })
        .collect::<Vec<_>>();
    let assistant_ready = assistant_configuration_ready(
        &config,
        assistant_credential(&state.root, &config)
            .ok()
            .flatten()
            .is_some(),
    );
    let mut code_runner_languages = vec!["rust".to_string(), "web".to_string()];
    if !config.code_runner.endpoint.is_empty() {
        code_runner_languages.extend(config.code_runner.languages.iter().cloned());
    }
    Response::json(
        200,
        &json!({
            "siteTitle": config.title,
            "siteUrl": config.url,
            "authorReady": !config.author.name.trim().is_empty()
                && !config.author.url.trim().is_empty(),
            "postPath": config.post_path,
            "defaultTheme": config.theme,
            "themes": theme_list,
            "profiles": profiles,
            "job": job_form,
            "capture": openblog_core::capture::limits_json(config.admin.max_upload_mb),
            "contributors": config.contributors,
            "creditRoles": credit_roles,
            "pieces": openblog_core::piece::schema_json(),
            "compare": openblog_core::compare::schema_json(),
            "series": series,
            "tags": tags,
            "maxUploadMb": config.admin.max_upload_mb,
            "quizGeneration": assistant_ready,
            "codeInteractionGeneration": assistant_ready,
            "codeRunnerLanguages": code_runner_languages,
            "social": social::is_configured(),
            "now": clock::now().rfc3339(),
        }),
    )
}

fn assistant_status(state: &AppState) -> Response {
    let (config, credential) = match assistant_provider_snapshot(state) {
        Ok(snapshot) => snapshot,
        Err(response) => return response,
    };
    let credential_configured = credential.is_some();
    let status = match config.knowledge_checks.provider {
        AssistantProviderKind::CustomHttps => AssistantProviderStatus::legacy_quiz(
            &config.knowledge_checks.generation_endpoint,
            &config.knowledge_checks.model,
            credential_configured,
        ),
        AssistantProviderKind::Anthropic => AssistantProviderStatus::anthropic(
            &config.knowledge_checks.model,
            credential_configured,
        ),
        provider => AssistantProviderStatus::native(
            provider.as_str(),
            &config.knowledge_checks.model,
            assistant_provider_destination(provider),
            credential_configured,
        ),
    };
    Response::json(200, &json!(status))
}

fn assistant_provider_kind(config: &SiteConfig) -> &str {
    config.knowledge_checks.provider.as_str()
}

fn assistant_credential_target(config: &SiteConfig) -> String {
    match config.knowledge_checks.provider {
        AssistantProviderKind::CustomHttps => format!(
            "custom-https:{}",
            config.knowledge_checks.generation_endpoint.trim()
        ),
        provider => provider.as_str().into(),
    }
}

#[derive(Clone, Copy)]
struct AssistantProviderDescriptor {
    environment_name: &'static str,
    destination: &'static str,
    native_kind: Option<NativeProviderKind>,
}

fn assistant_provider_descriptor(provider: AssistantProviderKind) -> AssistantProviderDescriptor {
    let descriptor = |environment_name, kind: NativeProviderKind| AssistantProviderDescriptor {
        environment_name,
        destination: kind.destination(),
        native_kind: Some(kind),
    };
    match provider {
        AssistantProviderKind::CustomHttps => AssistantProviderDescriptor {
            environment_name: "OPENBLOG_LESSONS_API_KEY",
            destination: "",
            native_kind: None,
        },
        AssistantProviderKind::Anthropic => AssistantProviderDescriptor {
            environment_name: "ANTHROPIC_API_KEY",
            destination: "https://api.anthropic.com",
            native_kind: None,
        },
        AssistantProviderKind::OpenAi => descriptor("OPENAI_API_KEY", NativeProviderKind::OpenAi),
        AssistantProviderKind::Gemini => descriptor("GEMINI_API_KEY", NativeProviderKind::Gemini),
        AssistantProviderKind::Xai => descriptor("XAI_API_KEY", NativeProviderKind::Xai),
        AssistantProviderKind::DeepSeek => {
            descriptor("DEEPSEEK_API_KEY", NativeProviderKind::DeepSeek)
        }
        AssistantProviderKind::Mistral => {
            descriptor("MISTRAL_API_KEY", NativeProviderKind::Mistral)
        }
        AssistantProviderKind::OpenRouter => {
            descriptor("OPENROUTER_API_KEY", NativeProviderKind::OpenRouter)
        }
    }
}

fn assistant_environment_name(provider: AssistantProviderKind) -> &'static str {
    assistant_provider_descriptor(provider).environment_name
}

fn assistant_provider_destination(provider: AssistantProviderKind) -> &'static str {
    assistant_provider_descriptor(provider).destination
}

fn assistant_configuration_ready(config: &SiteConfig, credential_configured: bool) -> bool {
    credential_configured
        && match config.knowledge_checks.provider {
            AssistantProviderKind::CustomHttps => !config
                .knowledge_checks
                .generation_endpoint
                .trim()
                .is_empty(),
            _ => !config.knowledge_checks.model.trim().is_empty(),
        }
}

thread_local! {
    /// The provider timeout in tests. It leaves a loaded machine plenty of time to answer; a test
    /// that exercises the timeout itself shortens it.
    static TEST_PROVIDER_TIMEOUT: std::cell::Cell<Duration> =
        const { std::cell::Cell::new(Duration::from_secs(10)) };
}

fn assistant_provider_timeout(provider: AssistantProviderKind, test_mode: bool) -> Duration {
    if test_mode {
        return TEST_PROVIDER_TIMEOUT.with(std::cell::Cell::get);
    }
    match provider {
        // Structured-output grammars can take additional time to compile on first use.
        AssistantProviderKind::Anthropic => Duration::from_secs(240),
        AssistantProviderKind::OpenAi
        | AssistantProviderKind::Gemini
        | AssistantProviderKind::Xai
        | AssistantProviderKind::DeepSeek
        | AssistantProviderKind::Mistral
        | AssistantProviderKind::OpenRouter => Duration::from_secs(120),
        AssistantProviderKind::CustomHttps => Duration::from_secs(30),
    }
}

fn configured_assistant_provider(
    config: &SiteConfig,
    credential: Option<String>,
    timeout: Duration,
) -> Result<Box<dyn AssistantProvider>, crate::assistant::AssistantError> {
    match config.knowledge_checks.provider {
        AssistantProviderKind::CustomHttps => GenericHttpsProvider::new(
            &config.knowledge_checks.generation_endpoint,
            credential,
            timeout,
            cfg!(test),
        )
        .map(|provider| Box::new(provider) as Box<dyn AssistantProvider>),
        AssistantProviderKind::Anthropic => AnthropicProvider::new(credential, timeout)
            .map(|provider| Box::new(provider) as Box<dyn AssistantProvider>),
        provider => NativeProvider::new(
            assistant_provider_descriptor(provider)
                .native_kind
                .expect("native providers have an adapter kind"),
            credential,
            timeout,
        )
        .map(|provider| Box::new(provider) as Box<dyn AssistantProvider>),
    }
}

const ASSISTANT_CREDENTIAL_FILE: &str = ".openblog/private/assistant/api-key";

fn assistant_credential_path(root: &Path) -> Result<PathBuf, String> {
    crate::assistant_storage::contained_target(root, Path::new(ASSISTANT_CREDENTIAL_FILE))
}

fn private_assistant_credential(
    root: &Path,
    config: &SiteConfig,
) -> Result<Option<String>, String> {
    let target = assistant_credential_target(config);
    Ok(
        private_assistant_credential_envelope(root)?.and_then(|(credential, _, stored_target)| {
            (stored_target.as_deref() == Some(target.as_str())).then_some(credential)
        }),
    )
}

fn private_assistant_credential_envelope(
    root: &Path,
) -> Result<Option<(String, String, Option<String>)>, String> {
    let path = assistant_credential_path(root)?;
    match fs::read(&path) {
        Ok(bytes) if bytes.len() > 32 * 1024 => {
            Err("private Assistant credential is too large".into())
        }
        Ok(bytes) => {
            let bytes = unprotect_private_credential(&bytes)?;
            if bytes.len() > 32 * 1024 {
                return Err("private Assistant credential is too large".into());
            }
            let envelope: Json = serde_json::from_slice(&bytes)
                .map_err(|_| "private Assistant credential is not valid".to_string())?;
            let credential = envelope["credential"]
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| "private Assistant credential is not valid".to_string())?;
            let revision = envelope["revision"]
                .as_str()
                .filter(|value| {
                    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
                })
                .ok_or_else(|| "private Assistant credential is not valid".to_string())?;
            if credential.len() > 16 * 1024 {
                return Err("private Assistant credential is too large".into());
            }
            let target = envelope["target"]
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string);
            Ok(Some((credential.to_string(), revision.to_string(), target)))
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(format!("cannot read private Assistant credential: {error}")),
    }
}

fn assistant_credential(root: &Path, config: &SiteConfig) -> Result<Option<String>, String> {
    let environment_name = assistant_environment_name(config.knowledge_checks.provider);
    if let Ok(value) = std::env::var(environment_name) {
        let value = value.trim();
        if !value.is_empty() {
            return Ok(Some(value.to_string()));
        }
    }
    private_assistant_credential(root, config)
}

fn assistant_provider_snapshot(state: &AppState) -> Result<(SiteConfig, Option<String>), Response> {
    let _transaction = content_transaction(state)?;
    let config = site::load_config(&state.root).map_err(|error| {
        Response::error(
            500,
            &format!("Cannot read assistant configuration: {error}"),
        )
    })?;
    let credential =
        assistant_credential(&state.root, &config).map_err(|error| Response::error(500, &error))?;
    Ok((config, credential))
}

fn write_private_assistant_credential(
    path: &Path,
    credential: &str,
    target: &str,
) -> Result<(), String> {
    let revision = auth::random_token()?;
    let envelope = serde_json::to_vec(&json!({
        "credential": credential,
        "revision": revision,
        "target": target,
    }))
    .map_err(|error| format!("cannot encode private Assistant credential: {error}"))?;
    let protected = protect_private_credential(&envelope)?;
    write_private_bytes_atomic(path, &protected)
}

#[cfg(windows)]
fn protect_private_credential(value: &[u8]) -> Result<Vec<u8>, String> {
    use std::ptr::{null, null_mut};
    use windows_sys::Win32::Foundation::LocalFree;
    use windows_sys::Win32::Security::Cryptography::{
        CryptProtectData, CRYPTPROTECT_UI_FORBIDDEN, CRYPT_INTEGER_BLOB,
    };

    let input = CRYPT_INTEGER_BLOB {
        cbData: value.len() as u32,
        pbData: value.as_ptr().cast_mut(),
    };
    let mut output = CRYPT_INTEGER_BLOB {
        cbData: 0,
        pbData: null_mut(),
    };
    let ok = unsafe {
        CryptProtectData(
            &input,
            null(),
            null(),
            null(),
            null(),
            CRYPTPROTECT_UI_FORBIDDEN,
            &mut output,
        )
    };
    if ok == 0 {
        return Err("Windows could not protect the private Assistant credential".into());
    }
    let protected =
        unsafe { std::slice::from_raw_parts(output.pbData, output.cbData as usize) }.to_vec();
    unsafe { LocalFree(output.pbData.cast()) };
    Ok(protected)
}

#[cfg(windows)]
fn unprotect_private_credential(value: &[u8]) -> Result<Vec<u8>, String> {
    use std::ptr::{null, null_mut};
    use windows_sys::Win32::Foundation::LocalFree;
    use windows_sys::Win32::Security::Cryptography::{
        CryptUnprotectData, CRYPTPROTECT_UI_FORBIDDEN, CRYPT_INTEGER_BLOB,
    };

    let input = CRYPT_INTEGER_BLOB {
        cbData: value.len() as u32,
        pbData: value.as_ptr().cast_mut(),
    };
    let mut output = CRYPT_INTEGER_BLOB {
        cbData: 0,
        pbData: null_mut(),
    };
    let ok = unsafe {
        CryptUnprotectData(
            &input,
            null_mut(),
            null(),
            null(),
            null(),
            CRYPTPROTECT_UI_FORBIDDEN,
            &mut output,
        )
    };
    if ok == 0 {
        return Err(
            "Windows could not decrypt the private Assistant credential for this account".into(),
        );
    }
    let clear =
        unsafe { std::slice::from_raw_parts(output.pbData, output.cbData as usize) }.to_vec();
    unsafe { LocalFree(output.pbData.cast()) };
    Ok(clear)
}

#[cfg(not(windows))]
fn protect_private_credential(value: &[u8]) -> Result<Vec<u8>, String> {
    Ok(value.to_vec())
}

#[cfg(not(windows))]
fn unprotect_private_credential(value: &[u8]) -> Result<Vec<u8>, String> {
    Ok(value.to_vec())
}

fn write_private_bytes_atomic(path: &Path, contents: &[u8]) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .map_err(|error| format!("cannot create private Assistant directory: {error}"))?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(parent, fs::Permissions::from_mode(0o700))
                .map_err(|error| format!("cannot protect private Assistant directory: {error}"))?;
        }
    }
    let temporary = path.with_extension("key.tmp");
    #[cfg(unix)]
    {
        use std::io::Write;
        use std::os::unix::fs::OpenOptionsExt;
        let mut file = fs::OpenOptions::new()
            .create(true)
            .truncate(true)
            .write(true)
            .mode(0o600)
            .open(&temporary)
            .map_err(|error| format!("cannot create private Assistant credential: {error}"))?;
        file.write_all(contents)
            .map_err(|error| format!("cannot write private Assistant credential: {error}"))?;
    }
    #[cfg(not(unix))]
    fs::write(&temporary, contents)
        .map_err(|error| format!("cannot write private Assistant credential: {error}"))?;
    crate::fsutil::replace_file(&temporary, path).map_err(|error| {
        let _ = fs::remove_file(&temporary);
        format!("cannot replace private Assistant credential: {error}")
    })
}

fn restore_private_assistant_credential(
    path: &Path,
    previous: Option<&[u8]>,
) -> Result<(), String> {
    match previous {
        Some(contents) => write_private_bytes_atomic(path, contents),
        None if path.exists() => fs::remove_file(path)
            .map_err(|error| format!("cannot remove private Assistant credential: {error}")),
        None => Ok(()),
    }
}

fn mutation_with_rollback_error(mutation: &str, rollback: Result<(), String>) -> String {
    match rollback {
        Ok(()) => mutation.to_string(),
        Err(rollback) => format!("{mutation}; rollback also failed: {rollback}"),
    }
}

fn assistant_credential_summary(root: &Path, config: &SiteConfig) -> Result<Json, String> {
    let environment_name = assistant_environment_name(config.knowledge_checks.provider);
    let environment = std::env::var(environment_name).is_ok_and(|value| !value.trim().is_empty());
    let private_configured = private_assistant_credential_envelope(root)?.is_some();
    let private = private_assistant_credential(root, config)?.is_some();
    let source = if environment {
        "environment"
    } else if private {
        "private"
    } else {
        "none"
    };
    Ok(json!({
        "configured": environment || private,
        "source": source,
        "privateConfigured": private_configured,
        "environmentOverride": environment,
        "environmentName": environment_name,
        "targetMismatch": private_configured && !private,
    }))
}

fn assistant_settings_etag(root: &Path, config: &[u8]) -> Result<String, String> {
    let credential_revision = private_assistant_credential_envelope(root)?
        .map(|(_, revision, _)| revision)
        .unwrap_or_default();
    let mut digest = Blake2s256::new();
    digest.update(config);
    digest.update([0]);
    digest.update(credential_revision);
    Ok(digest
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect())
}

fn assistant_settings(state: &AppState) -> Response {
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = state.root.join(site::CONFIG_FILE);
    let bytes = match fs::read(&path) {
        Ok(bytes) => bytes,
        Err(error) => return Response::error(500, &format!("cannot read openblog.json: {error}")),
    };
    let config = match std::str::from_utf8(&bytes)
        .map_err(|error| error.to_string())
        .and_then(SiteConfig::from_json)
    {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    let credential = match assistant_credential_summary(&state.root, &config) {
        Ok(summary) => summary,
        Err(error) => return Response::error(500, &error),
    };
    Response::json(
        200,
        &json!({
            "provider": assistant_provider_kind(&config),
            "generationEndpoint": config.knowledge_checks.generation_endpoint,
            "model": config.knowledge_checks.model,
        "etag": match assistant_settings_etag(&state.root, &bytes) {
            Ok(etag) => etag,
            Err(error) => return Response::error(500, &error),
        },
            "credential": credential,
        }),
    )
}

fn save_assistant_settings(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let provider = body["provider"].as_str().unwrap_or("custom-https").trim();
    let endpoint = body["generationEndpoint"].as_str().unwrap_or("").trim();
    let model = body["model"].as_str().unwrap_or("").trim();
    if endpoint.len() > 2048 || model.len() > 200 {
        return Response::error(422, "Assistant endpoint or model is too long");
    }
    if !matches!(
        provider,
        "custom-https"
            | "anthropic"
            | "open-ai"
            | "gemini"
            | "xai"
            | "deep-seek"
            | "mistral"
            | "open-router"
    ) {
        return Response::error(422, "Assistant provider is not supported");
    }
    if provider == "custom-https" && !endpoint.is_empty() {
        let valid = url::Url::parse(endpoint).is_ok_and(|url| {
            url.scheme() == "https"
                && url.host_str().is_some()
                && url.username().is_empty()
                && url.password().is_none()
        });
        if !valid {
            return Response::error(
                422,
                "Assistant endpoint must be an HTTPS URL without embedded credentials",
            );
        }
    }
    let action = body["credentialAction"].as_str().unwrap_or("keep");
    let replacement = body["credential"].as_str().unwrap_or("").trim();
    if !matches!(action, "keep" | "replace" | "clear") {
        return Response::error(422, "credentialAction must be keep, replace, or clear");
    }
    if action == "replace" && (replacement.is_empty() || replacement.len() > 16 * 1024) {
        return Response::error(422, "Enter a credential no larger than 16 KiB");
    }

    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let config_path = state.root.join(site::CONFIG_FILE);
    let current = match fs::read(&config_path) {
        Ok(bytes) => bytes,
        Err(error) => return Response::error(500, &format!("cannot read openblog.json: {error}")),
    };
    let current_etag = match assistant_settings_etag(&state.root, &current) {
        Ok(etag) => etag,
        Err(error) => return Response::error(500, &error),
    };
    if body["etag"].as_str() != Some(current_etag.as_str()) {
        return Response::error(
            409,
            "Assistant settings changed on disk; reload before saving",
        );
    }
    let mut value: Json = match serde_json::from_slice(&current) {
        Ok(Json::Object(object)) => Json::Object(object),
        Ok(_) => return Response::error(500, "openblog.json must contain a JSON object"),
        Err(error) => return Response::error(500, &format!("invalid openblog.json: {error}")),
    };
    let stored_endpoint = if provider == "custom-https" {
        endpoint
    } else {
        ""
    };
    value["knowledgeChecks"] = json!({
        "provider": provider,
        "generationEndpoint": stored_endpoint,
        "model": model,
    });
    let candidate = match serde_json::to_string_pretty(&value) {
        Ok(value) => format!("{value}\n"),
        Err(error) => {
            return Response::error(500, &format!("cannot serialize openblog.json: {error}"))
        }
    };
    let candidate_config = match SiteConfig::from_json(&candidate) {
        Ok(config) => config,
        Err(error) => return Response::error(422, &error),
    };
    let credential_path = match assistant_credential_path(&state.root) {
        Ok(path) => path,
        Err(error) => return Response::error(500, &error),
    };
    let previous_credential = match read_optional_bytes(&credential_path) {
        Ok(value) => value,
        Err(error) => return Response::error(500, &error),
    };
    let credential_result = match action {
        "replace" => write_private_assistant_credential(
            &credential_path,
            replacement,
            &assistant_credential_target(&candidate_config),
        ),
        "clear" if credential_path.exists() => fs::remove_file(&credential_path)
            .map_err(|error| format!("cannot clear private Assistant credential: {error}")),
        "clear" | "keep" => Ok(()),
        _ => unreachable!(),
    };
    if let Err(error) = credential_result {
        let rollback =
            restore_private_assistant_credential(&credential_path, previous_credential.as_deref());
        return Response::error(500, &mutation_with_rollback_error(&error, rollback));
    }
    if let Err(error) = write_atomic(&config_path, &candidate) {
        let rollback =
            restore_private_assistant_credential(&credential_path, previous_credential.as_deref());
        return Response::error(500, &mutation_with_rollback_error(&error, rollback));
    }
    let credential = match assistant_credential_summary(&state.root, &candidate_config) {
        Ok(summary) => summary,
        Err(error) => return Response::error(500, &error),
    };
    Response::json(
        200,
        &json!({
            "provider": provider,
            "generationEndpoint": stored_endpoint,
            "model": model,
        "etag": match assistant_settings_etag(&state.root, candidate.as_bytes()) {
            Ok(etag) => etag,
            Err(error) => return Response::error(500, &error),
        },
            "credential": credential,
        }),
    )
}

const ENGAGEMENT_CREDENTIAL_FILE: &str = ".openblog/private/engagement/api-key";
const ENGAGEMENT_ENVIRONMENT_NAME: &str = "OPENBLOG_ENGAGEMENT_API_KEY";
const ENGAGEMENT_ORIGIN_ENVIRONMENT_NAME: &str = "OPENBLOG_ENGAGEMENT_API_ORIGIN";

fn engagement_credential_path(root: &Path) -> Result<PathBuf, String> {
    crate::assistant_storage::contained_target(root, Path::new(ENGAGEMENT_CREDENTIAL_FILE))
}

fn engagement_endpoint_origin(endpoint: &str) -> Option<String> {
    let url = url::Url::parse(endpoint).ok()?;
    (url.scheme() == "https" && url.host_str().is_some())
        .then(|| url.origin().ascii_serialization())
}

fn private_engagement_credential(root: &Path) -> Result<Option<(String, String)>, String> {
    let path = engagement_credential_path(root)?;
    match fs::read(path) {
        Ok(bytes) if bytes.len() > 32 * 1024 => {
            Err("private engagement credential is too large".into())
        }
        Ok(bytes) => {
            let bytes = unprotect_private_credential(&bytes)?;
            let envelope: Json = serde_json::from_slice(&bytes)
                .map_err(|_| "private engagement credential envelope is invalid".to_string())?;
            let credential = envelope["credential"].as_str().unwrap_or("").trim();
            let target_origin = envelope["targetOrigin"].as_str().unwrap_or("").trim();
            if credential.is_empty()
                || engagement_endpoint_origin(target_origin).as_deref() != Some(target_origin)
            {
                return Err("private engagement credential envelope is invalid".into());
            }
            Ok(Some((credential.to_string(), target_origin.to_string())))
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(format!(
            "cannot read private engagement credential: {error}"
        )),
    }
}

fn engagement_credential(root: &Path, endpoint: &str) -> Result<Option<String>, String> {
    let target_origin = engagement_endpoint_origin(endpoint)
        .ok_or_else(|| "hosted engagement endpoint is invalid".to_string())?;
    if let Ok(value) = std::env::var(ENGAGEMENT_ENVIRONMENT_NAME) {
        if !value.trim().is_empty() {
            let bound_origin = std::env::var(ENGAGEMENT_ORIGIN_ENVIRONMENT_NAME)
                .unwrap_or_default()
                .trim_end_matches('/')
                .to_string();
            if bound_origin != target_origin {
                return Err(format!(
                    "{ENGAGEMENT_ENVIRONMENT_NAME} is not bound to this endpoint; set {ENGAGEMENT_ORIGIN_ENVIRONMENT_NAME} to {target_origin}"
                ));
            }
            return Ok(Some(value.trim().to_string()));
        }
    }
    match private_engagement_credential(root)? {
        Some((credential, bound_origin)) if bound_origin == target_origin => Ok(Some(credential)),
        Some(_) => Err("The saved hosted engagement token belongs to a different origin. Replace it explicitly before connecting to this endpoint.".into()),
        None => Ok(None),
    }
}

fn engagement_credential_summary(root: &Path, endpoint: &str) -> Result<Json, String> {
    let environment =
        std::env::var(ENGAGEMENT_ENVIRONMENT_NAME).is_ok_and(|value| !value.trim().is_empty());
    let private_credential = private_engagement_credential(root)?;
    let private = private_credential.is_some();
    let target_origin = engagement_endpoint_origin(endpoint).unwrap_or_default();
    let environment_bound = environment
        && std::env::var(ENGAGEMENT_ORIGIN_ENVIRONMENT_NAME)
            .is_ok_and(|value| value.trim_end_matches('/') == target_origin);
    let private_bound = private_credential
        .as_ref()
        .is_some_and(|(_, origin)| origin == &target_origin);
    Ok(json!({
        "configured": environment_bound || (!environment && private_bound),
        "source": if environment { "environment" } else if private { "private" } else { "none" },
        "privateConfigured": private,
        "environmentOverride": environment,
        "environmentName": ENGAGEMENT_ENVIRONMENT_NAME,
        "originEnvironmentName": ENGAGEMENT_ORIGIN_ENVIRONMENT_NAME,
        "boundToEndpoint": environment_bound || (!environment && private_bound),
    }))
}

fn appearance_json(root: &Path, bytes: &[u8]) -> Result<Json, String> {
    let source = std::str::from_utf8(bytes).map_err(|error| error.to_string())?;
    let config = SiteConfig::from_json(source)?;
    let theme = site::load_themes(root, &config)?.resolve(&config.theme)?;
    Ok(json!({
        "colorSchemeToggle": config.color_scheme_toggle,
        "themeColorSchemeToggle": theme.color_scheme_toggle,
        "etag": etag_bytes(bytes),
    }))
}

fn appearance_settings(state: &AppState) -> Response {
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    match fs::read(state.root.join(site::CONFIG_FILE))
        .map_err(|error| format!("cannot read openblog.json: {error}"))
        .and_then(|bytes| appearance_json(&state.root, &bytes))
    {
        Ok(settings) => Response::json(200, &settings),
        Err(error) => Response::error(500, &error),
    }
}

fn save_appearance_settings(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let choice = match body.get("colorSchemeToggle") {
        Some(value) if value.is_null() || value.is_boolean() => value.clone(),
        _ => return Response::error(422, "colorSchemeToggle must be true, false, or null"),
    };
    let mut build = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = state.root.join(site::CONFIG_FILE);
    let current = match fs::read(&path) {
        Ok(bytes) => bytes,
        Err(error) => return Response::error(500, &format!("cannot read openblog.json: {error}")),
    };
    if body["etag"].as_str() != Some(etag_bytes(&current).as_str()) {
        return Response::error(409, "Site settings changed on disk; reload before saving");
    }
    let mut config: Json = match serde_json::from_slice(&current) {
        Ok(Json::Object(object)) => Json::Object(object),
        _ => return Response::error(500, "openblog.json must contain a valid JSON object"),
    };
    config["colorSchemeToggle"] = choice;
    let candidate = match serde_json::to_string_pretty(&config) {
        Ok(json) => format!("{json}\n"),
        Err(error) => {
            return Response::error(500, &format!("cannot serialize openblog.json: {error}"))
        }
    };
    let mut settings = match appearance_json(&state.root, candidate.as_bytes()) {
        Ok(settings) => settings,
        Err(error) => return Response::error(422, &error),
    };
    if let Err(error) = write_atomic(&path, &candidate) {
        return Response::error(500, &error);
    }
    // Report the saved revision even when an unrelated content error blocks rebuilding.
    settings["buildError"] = match state.rebuild_locked(&mut build) {
        Ok(_) => Json::Null,
        Err(error) => Json::String(error),
    };
    Response::json(200, &settings)
}

fn engagement_settings_etag(root: &Path, config: &[u8]) -> Result<String, String> {
    let credential = read_optional_bytes(&engagement_credential_path(root)?)?.unwrap_or_default();
    let mut digest = Blake2s256::new();
    digest.update(config);
    digest.update([0]);
    digest.update(credential);
    Ok(digest
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect())
}

fn engagement_settings(state: &AppState) -> Response {
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let bytes = match fs::read(state.root.join(site::CONFIG_FILE)) {
        Ok(bytes) => bytes,
        Err(error) => return Response::error(500, &format!("cannot read openblog.json: {error}")),
    };
    let config = match std::str::from_utf8(&bytes)
        .map_err(|error| error.to_string())
        .and_then(SiteConfig::from_json)
    {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    let credential = match engagement_credential_summary(&state.root, &config.engagement.endpoint) {
        Ok(summary) => summary,
        Err(error) => return Response::error(500, &error),
    };
    let etag = match engagement_settings_etag(&state.root, &bytes) {
        Ok(etag) => etag,
        Err(error) => return Response::error(500, &error),
    };
    Response::json(
        200,
        &json!({
            "enabled": config.engagement.enabled,
            "comments": config.engagement.comments,
            "analytics": config.engagement.analytics,
            "endpoint": config.engagement.endpoint,
            "feedback": config.engagement.feedback,
            "captcha": config.engagement.captcha,
            "etag": etag,
            "credential": credential,
        }),
    )
}

fn valid_engagement_endpoint(endpoint: &str) -> bool {
    url::Url::parse(endpoint).is_ok_and(|url| {
        url.scheme() == "https"
            && url.host_str().is_some()
            && url.username().is_empty()
            && url.password().is_none()
            && url.query().is_none()
            && url.fragment().is_none()
    })
}

fn save_engagement_settings(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let enabled = body["enabled"].as_bool().unwrap_or(false);
    let comments = body["comments"].as_bool().unwrap_or(true);
    let analytics = body["analytics"].as_bool().unwrap_or(true);
    let endpoint = body["endpoint"]
        .as_str()
        .unwrap_or("")
        .trim()
        .trim_end_matches('/');
    if endpoint.len() > 2048 || (enabled && !valid_engagement_endpoint(endpoint)) {
        return Response::error(
            422,
            "Hosted endpoint must be an HTTPS URL without credentials, query, or fragment",
        );
    }
    let action = body["credentialAction"].as_str().unwrap_or("keep");
    let replacement = body["credential"].as_str().unwrap_or("").trim();
    if !matches!(action, "keep" | "replace" | "clear")
        || (action == "replace" && (replacement.is_empty() || replacement.len() > 16 * 1024))
    {
        return Response::error(
            422,
            "Choose keep, replace, or clear and provide a bounded credential when replacing",
        );
    }
    let target_origin = engagement_endpoint_origin(endpoint);
    if action == "replace" && target_origin.is_none() {
        return Response::error(422, "Enter a valid HTTPS endpoint before saving a token");
    }
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let config_path = state.root.join(site::CONFIG_FILE);
    let current = match fs::read(&config_path) {
        Ok(bytes) => bytes,
        Err(error) => return Response::error(500, &format!("cannot read openblog.json: {error}")),
    };
    let current_etag = match engagement_settings_etag(&state.root, &current) {
        Ok(etag) => etag,
        Err(error) => return Response::error(500, &error),
    };
    if body["etag"].as_str() != Some(current_etag.as_str()) {
        return Response::error(
            409,
            "Hosted engagement settings changed on disk; reload before saving",
        );
    }
    let mut value: Json = match serde_json::from_slice(&current) {
        Ok(Json::Object(object)) => Json::Object(object),
        Ok(_) => return Response::error(500, "openblog.json must contain a JSON object"),
        Err(error) => return Response::error(500, &format!("invalid openblog.json: {error}")),
    };
    // Merge into the existing object, so settings this form does not manage
    // (the passage-feedback opt-in, ADR 0081) survive a save unchanged.
    let mut engagement = match value.get("engagement") {
        Some(Json::Object(existing)) => existing.clone(),
        _ => serde_json::Map::new(),
    };
    engagement.insert("enabled".into(), json!(enabled));
    engagement.insert("comments".into(), json!(comments));
    engagement.insert("analytics".into(), json!(analytics));
    engagement.insert("endpoint".into(), json!(endpoint));
    if let Some(feedback) = body["feedback"].as_bool() {
        engagement.insert("feedback".into(), json!(feedback));
    }
    if let Some(captcha) = body.get("captcha") {
        let mut parsed =
            match serde_json::from_value::<openblog_core::config::CaptchaConfig>(captcha.clone()) {
                Ok(parsed) => parsed,
                Err(_) => {
                    return Response::error(
                        422,
                        "Captcha accepts only provider, scope, and the public siteKey; secrets are server environment variables",
                    )
                }
            };
        parsed.provider = parsed.provider.trim().to_lowercase();
        parsed.scope = parsed.scope.trim().to_lowercase();
        parsed.site_key = parsed.site_key.trim().to_string();
        if parsed == openblog_core::config::CaptchaConfig::default() {
            engagement.remove("captcha");
        } else {
            engagement.insert("captcha".into(), json!(parsed));
        }
    }
    value["engagement"] = Json::Object(engagement);
    let candidate = match serde_json::to_string_pretty(&value) {
        Ok(value) => format!("{value}\n"),
        Err(error) => {
            return Response::error(500, &format!("cannot serialize openblog.json: {error}"))
        }
    };
    let validated = match SiteConfig::from_json(&candidate) {
        Ok(config) => config,
        Err(error) => return Response::error(422, &error),
    };
    let credential_path = match engagement_credential_path(&state.root) {
        Ok(path) => path,
        Err(error) => return Response::error(500, &error),
    };
    let previous_credential = match read_optional_bytes(&credential_path) {
        Ok(value) => value,
        Err(error) => return Response::error(500, &error),
    };
    let credential_result = match action {
        "replace" => serde_json::to_vec(&json!({
            "credential": replacement,
            "targetOrigin": target_origin.expect("validated above"),
        }))
        .map_err(|error| format!("cannot serialize private engagement credential: {error}"))
        .and_then(|envelope| protect_private_credential(&envelope))
        .and_then(|bytes| write_private_bytes_atomic(&credential_path, &bytes)),
        "clear" if credential_path.exists() => fs::remove_file(&credential_path)
            .map_err(|error| format!("cannot clear private engagement credential: {error}")),
        "clear" | "keep" => Ok(()),
        _ => unreachable!(),
    };
    if let Err(error) = credential_result {
        let rollback =
            restore_private_assistant_credential(&credential_path, previous_credential.as_deref());
        return Response::error(500, &mutation_with_rollback_error(&error, rollback));
    }
    if let Err(error) = write_atomic(&config_path, &candidate) {
        let rollback =
            restore_private_assistant_credential(&credential_path, previous_credential.as_deref());
        return Response::error(500, &mutation_with_rollback_error(&error, rollback));
    }
    let credential = match engagement_credential_summary(&state.root, endpoint) {
        Ok(summary) => summary,
        Err(error) => return Response::error(500, &error),
    };
    let etag = match engagement_settings_etag(&state.root, candidate.as_bytes()) {
        Ok(etag) => etag,
        Err(error) => return Response::error(500, &error),
    };
    Response::json(
        200,
        &json!({
            "enabled": enabled, "comments": comments, "analytics": analytics,
            "endpoint": endpoint, "etag": etag, "credential": credential,
            "captcha": validated.engagement.captcha,
        }),
    )
}

fn hosted_text<'a>(object: &'a Json, key: &str, max: usize) -> Result<&'a str, String> {
    object[key]
        .as_str()
        .filter(|value| value.len() <= max && !value.chars().any(char::is_control))
        .ok_or_else(|| format!("hosted engagement returned an invalid {key}"))
}

fn hosted_count(object: &Json, key: &str) -> Result<u64, String> {
    object[key]
        .as_u64()
        .ok_or_else(|| format!("hosted engagement returned an invalid {key}"))
}

fn hosted_site_path(value: &str) -> bool {
    (2..=500).contains(&value.len())
        && value.starts_with('/')
        && !value.starts_with("//")
        && value.ends_with('/')
        && !value.contains(['\\', '?', '#'])
        && !value.chars().any(char::is_control)
        && !value.split('/').any(|part| matches!(part, "." | ".."))
}

fn validate_hosted_analytics(value: &Json) -> Result<Json, String> {
    let days = hosted_count(value, "days")?;
    if !matches!(days, 7 | 30 | 90 | 365) {
        return Err("hosted engagement returned an invalid days value".into());
    }
    let series = value["series"]
        .as_array()
        .filter(|rows| rows.len() <= 365)
        .ok_or_else(|| "hosted engagement returned an invalid series".to_string())?;
    let mut safe_series = Vec::with_capacity(series.len());
    for row in series {
        safe_series.push(json!({
            "day": hosted_text(row, "day", 16)?,
            "views": hosted_count(row, "views")?,
            "uniques": hosted_count(row, "uniques")?,
        }));
    }
    let posts = value["topPosts"]
        .as_array()
        .filter(|rows| rows.len() <= 50)
        .ok_or_else(|| "hosted engagement returned invalid topPosts".to_string())?;
    let mut safe_posts = Vec::with_capacity(posts.len());
    for row in posts {
        let path = hosted_text(row, "path", 500)?;
        if !hosted_site_path(path) {
            return Err("hosted engagement returned an invalid post path".into());
        }
        safe_posts.push(json!({
            "path": path, "views": hosted_count(row, "views")?,
            "uniques": hosted_count(row, "uniques")?, "allTime": hosted_count(row, "allTime")?,
        }));
    }
    let referrers = value["referrers"]
        .as_array()
        .filter(|rows| rows.len() <= 50)
        .ok_or_else(|| "hosted engagement returned invalid referrers".to_string())?;
    let mut safe_referrers = Vec::with_capacity(referrers.len());
    for row in referrers {
        safe_referrers.push(json!({
            "host": hosted_text(row, "host", 253)?, "views": hosted_count(row, "views")?,
        }));
    }
    Ok(json!({
        "days": days,
        "from": hosted_text(value, "from", 16)?,
        "to": hosted_text(value, "to", 16)?,
        "views": hosted_count(value, "views")?,
        "uniques": hosted_count(value, "uniques")?,
        "allTimeViews": hosted_count(value, "allTimeViews")?,
        "firstDay": value["firstDay"].as_str().filter(|text| text.len() <= 16).unwrap_or(""),
        "series": safe_series,
        "topPosts": safe_posts,
        "referrers": safe_referrers,
        "agentRequests": 0,
        "agents": [],
        "agentPages": [],
    }))
}

fn validate_hosted_engagement_response(
    method: &str,
    operation: &str,
    value: &Json,
) -> Result<Json, String> {
    match (method, operation) {
        ("GET", "admin/analytics") => validate_hosted_analytics(value),
        _ => Err("unsupported hosted engagement operation".into()),
    }
}

fn hosted_engagement_request(state: &AppState, req: &Request, operation: &str) -> Response {
    let config = match site::load_config(&state.root) {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    if !config.engagement.enabled || !valid_engagement_endpoint(&config.engagement.endpoint) {
        return Response::error(404, "Hosted engagement is not configured");
    }
    let credential = match engagement_credential(&state.root, &config.engagement.endpoint) {
        Ok(Some(credential)) => credential,
        Ok(None) => {
            return Response::error(503, "Hosted engagement admin credential is not configured")
        }
        Err(error) => return Response::error(500, &error),
    };
    let mut url = format!(
        "{}/{}",
        config.engagement.endpoint.trim_end_matches('/'),
        operation
    );
    if !req.query.is_empty() {
        let query = req
            .query
            .iter()
            .map(|(key, value)| {
                format!(
                    "{}={}",
                    url::form_urlencoded::byte_serialize(key.as_bytes()).collect::<String>(),
                    url::form_urlencoded::byte_serialize(value.as_bytes()).collect::<String>()
                )
            })
            .collect::<Vec<_>>()
            .join("&");
        url.push('?');
        url.push_str(&query);
    }
    let agent: ureq::Agent = ureq::Agent::config_builder()
        .timeout_global(Some(Duration::from_secs(20)))
        .max_redirects(0)
        .user_agent(concat!("open.blog-admin/", env!("CARGO_PKG_VERSION")))
        .build()
        .into();
    let authorization = format!("Bearer {credential}");
    let response = if req.method == "PATCH" {
        agent
            .patch(&url)
            .header("Authorization", &authorization)
            .header("Content-Type", "application/json")
            .send(&req.body)
    } else {
        agent
            .get(&url)
            .header("Authorization", &authorization)
            .call()
    };
    let mut response = match response {
        Ok(response) => response,
        Err(ureq::Error::StatusCode(status)) => {
            return Response::error(502, &format!("Hosted engagement returned HTTP {status}"))
        }
        Err(ureq::Error::Timeout(_)) => return Response::error(504, "Hosted engagement timed out"),
        Err(_) => return Response::error(502, "Hosted engagement request failed"),
    };
    let bytes = match response
        .body_mut()
        .with_config()
        .limit(2 * 1024 * 1024)
        .read_to_vec()
    {
        Ok(bytes) => bytes,
        Err(_) => return Response::error(502, "Cannot read hosted engagement response"),
    };
    match serde_json::from_slice::<Json>(&bytes)
        .map_err(|_| "Hosted engagement returned invalid JSON".to_string())
        .and_then(|value| validate_hosted_engagement_response(&req.method, operation, &value))
    {
        Ok(value) => Response::json(200, &value),
        Err(error) => Response::error(502, &error),
    }
}

// ---- Passage feedback moderation (ADR 0083)
//
// The hosted moderation routes hold the queue; Admin reaches them only
// through this server, which keeps the bearer token. Every item is re-read
// with the shared validator and checked against the post as it is now, so a
// moderator never acts on a passage that silently moved. What a site
// publishes of approved feedback lives in `reader-feedback.json` in the
// content folder, written only here, under the content lock.

const MAX_FEEDBACK_REQUEST_BYTES: usize = 16 * 1024;

fn feedback_body(req: &Request) -> Result<Json, Response> {
    require_json(req)?;
    if req.body.len() > MAX_FEEDBACK_REQUEST_BYTES {
        return Err(Response::error(
            413,
            "A feedback request is limited to 16 KiB",
        ));
    }
    match serde_json::from_slice::<Json>(&req.body) {
        Ok(body) if body.is_object() => Ok(body),
        _ => Err(Response::error(400, "Invalid JSON")),
    }
}

fn feedback_id(value: &Json) -> Result<String, Response> {
    value
        .as_str()
        .map(str::to_ascii_lowercase)
        .filter(|id| HostedFeedback::is_id(id))
        .ok_or_else(|| Response::error(422, "Name the feedback item by its id"))
}

/// One request to the hosted feedback routes, with the server-held token.
/// Unlike the other hosted requests, a `404` for a missing item and a `409`
/// answer are returned with their bodies, so a conflict can carry the item as
/// it is now.
fn hosted_feedback_call(
    state: &AppState,
    query: &[(&str, &str)],
    body: Option<&Json>,
) -> Result<(u16, Json), Response> {
    let config = site::load_config(&state.root).map_err(|error| Response::error(500, &error))?;
    if !config.engagement.enabled
        || !config.participation.passage_feedback_enabled()
        || !valid_engagement_endpoint(&config.engagement.endpoint)
    {
        return Err(Response::error(
            404,
            "Passage feedback is not turned on: enable hosted engagement with an endpoint and set engagement.feedback (or a passage feedback kind in participation.kinds) in openblog.json.",
        ));
    }
    let credential = match engagement_credential(&state.root, &config.engagement.endpoint) {
        Ok(Some(credential)) => credential,
        Ok(None) => {
            return Err(Response::error(
                503,
                "Hosted engagement admin credential is not configured",
            ))
        }
        Err(error) => return Err(Response::error(500, &error)),
    };
    let mut url = format!(
        "{}/admin/feedback",
        config.engagement.endpoint.trim_end_matches('/')
    );
    if !query.is_empty() {
        url.push('?');
        url.push_str(
            &url::form_urlencoded::Serializer::new(String::new())
                .extend_pairs(query)
                .finish(),
        );
    }
    let agent: ureq::Agent = ureq::Agent::config_builder()
        .timeout_global(Some(Duration::from_secs(20)))
        .max_redirects(0)
        .http_status_as_error(false)
        .user_agent(concat!("open.blog-admin/", env!("CARGO_PKG_VERSION")))
        .build()
        .into();
    let authorization = format!("Bearer {credential}");
    let response = match body {
        Some(body) => agent
            .patch(&url)
            .header("Authorization", &authorization)
            .header("Content-Type", "application/json")
            .send(body.to_string().as_bytes()),
        None => agent
            .get(&url)
            .header("Authorization", &authorization)
            .call(),
    };
    let mut response = match response {
        Ok(response) => response,
        Err(ureq::Error::Timeout(_)) => {
            return Err(Response::error(504, "Hosted engagement timed out"))
        }
        Err(_) => return Err(Response::error(502, "Hosted engagement request failed")),
    };
    let status = response.status().as_u16();
    let bytes = response
        .body_mut()
        .with_config()
        .limit(2 * 1024 * 1024)
        .read_to_vec()
        .map_err(|_| Response::error(502, "Cannot read hosted engagement response"))?;
    let value = serde_json::from_slice::<Json>(&bytes).unwrap_or(Json::Null);
    hosted_feedback_answer(status, value)
}

/// What Admin makes of a hosted feedback answer. Messages from the function
/// are passed on only when short and plain; nothing names the token.
fn hosted_feedback_answer(status: u16, value: Json) -> Result<(u16, Json), Response> {
    match status {
        200 | 409 => Ok((status, value)),
        404 if value["code"] == "notFound" => Ok((status, value)),
        404 => Err(Response::error(
            404,
            "The hosted function does not offer passage feedback: set OPENBLOG_FEEDBACK_ENABLED=true in Netlify and run supabase/feedback.sql.",
        )),
        401 => Err(Response::error(
            502,
            "The hosted function refused the saved moderation token",
        )),
        422 => Err(Response::error(
            422,
            value["error"]
                .as_str()
                .filter(|message| message.len() <= 200 && !message.chars().any(char::is_control))
                .unwrap_or("The hosted function refused the change"),
        )),
        _ => Err(Response::error(
            502,
            &format!("Hosted engagement returned HTTP {status}"),
        )),
    }
}

/// The items of a hosted answer, each re-read with the shared validator; a
/// bad item is counted and skipped, never shown half-checked.
fn hosted_feedback_items(value: &Json) -> Result<(Vec<HostedFeedback>, usize), Response> {
    let rows = value["feedback"]
        .as_array()
        .filter(|rows| rows.len() <= 200)
        .ok_or_else(|| Response::error(502, "hosted engagement returned invalid feedback"))?;
    let mut items = Vec::with_capacity(rows.len());
    let mut invalid = 0;
    for row in rows {
        match HostedFeedback::from_value(row) {
            Ok(item) => items.push(item),
            Err(_) => invalid += 1,
        }
    }
    Ok((items, invalid))
}

fn hosted_feedback_item(state: &AppState, id: &str) -> Result<HostedFeedback, Response> {
    let (_, value) = hosted_feedback_call(state, &[("id", id)], None)?;
    let (mut items, invalid) = hosted_feedback_items(&value)?;
    if invalid > 0 {
        return Err(Response::error(
            502,
            "The hosted feedback item is not valid; it was not changed",
        ));
    }
    items
        .pop()
        .filter(|item| item.id == id)
        .ok_or_else(|| Response::error(404, "No such feedback item"))
}

fn reader_feedback_path(state: &AppState) -> Result<PathBuf, Response> {
    let config = site::load_config(&state.root).map_err(|error| Response::error(500, &error))?;
    let path = state
        .root
        .join(&config.paths.content)
        .join(feedback_publication::READER_FEEDBACK_FILE);
    if fs::symlink_metadata(&path).is_ok_and(|metadata| !metadata.is_file()) {
        return Err(Response::error(
            409,
            "reader-feedback.json must be a regular file in the content folder",
        ));
    }
    Ok(path)
}

/// The published reader feedback and its revision (`etag`); an absent file
/// is an empty one. A file that cannot be read is refused, naming the file,
/// and nothing is written over it.
fn load_reader_feedback(
    path: &Path,
) -> Result<(feedback_publication::ReaderFeedbackFile, String), Response> {
    let bytes = read_optional_bytes(path).map_err(|error| Response::error(500, &error))?;
    let Some(bytes) = bytes else {
        return Ok((Default::default(), "absent".into()));
    };
    let etag = etag_bytes(&bytes);
    let text = String::from_utf8(bytes).map_err(|_| {
        Response::error(
            409,
            "reader-feedback.json is not UTF-8; fix it in source mode before moderating",
        )
    })?;
    let file = feedback_publication::ReaderFeedbackFile::from_json(&text).map_err(|error| {
        Response::error(
            409,
            &format!("reader-feedback.json {error}; fix it in source mode before moderating"),
        )
    })?;
    Ok((file, etag))
}

fn write_reader_feedback(
    path: &Path,
    file: &feedback_publication::ReaderFeedbackFile,
) -> Result<String, String> {
    let text = file.to_json();
    write_atomic_bytes(path, text.as_bytes())?;
    Ok(etag(&text))
}

fn feedback_build_json(build: &Result<BuildReport, String>) -> Json {
    match build {
        Ok(report) => json!({ "ok": true, "posts": report.posts }),
        Err(error) => json!({ "ok": false, "error": error }),
    }
}

/// The site as readers see it now, for checking passages.
fn feedback_site(state: &AppState) -> Result<Site, Response> {
    site::load_site(&state.root, false, Some(clock::now()))
        .map(|(site, _)| site)
        .map_err(|error| Response::error(500, &error))
}

/// Put one approved item on its post, or say why not. The caller holds the
/// content lock.
fn publish_approved_feedback(
    path: &Path,
    site: &Site,
    item: &HostedFeedback,
    claims: Option<&openblog_core::claims::ClaimSet>,
) -> Result<(), String> {
    if item.status != ModerationState::Approved {
        return Err("Only approved feedback is published".into());
    }
    let post = feedback_moderation::post_for_work(site, &item.feedback.provenance.work)
        .ok_or_else(|| "No post has this address now, so the note is not on the site yet. Publish it from the Approved list once the post is back.".to_string())?;
    let (mut file, _) = load_reader_feedback(path).map_err(|_| {
        "reader-feedback.json cannot be read; fix it in source mode, then publish the note from the Approved list".to_string()
    })?;
    // The author's decision in force on this text goes with the note (ADR 0119); a decision
    // about an earlier text, or none, publishes none.
    let decision = decision_to_publish(item, &post.slug, claims);
    let record = feedback_publication::PublishedFeedback::from_record(
        &item.id,
        &post.source.replace('\\', "/"),
        &item.feedback,
        item.moderated_at.unwrap_or_else(clock::now),
    )?
    .with_decision(decision)?;
    file.publish(record)?;
    write_reader_feedback(path, &file)
        .map(|_| ())
        .map_err(|_| "reader-feedback.json could not be written".to_string())
}

/// The author's claims file, for deciding what a public decision may name; `None` when it cannot
/// be read, in which case no evidence link is published (ADR 0119).
fn claims_for_publication(state: &AppState) -> Option<openblog_core::claims::ClaimSet> {
    claims_store::load(&state.root, &source_contributors(state))
        .ok()
        .map(|snapshot| snapshot.claims)
}

/// The decision in force on the item's text as the public file may hold it: an evidence link is
/// kept only while `claims` approves and publishes it on the post `slug`, and a private claim or
/// link id is never copied (ADR 0119).
fn decision_to_publish(
    item: &HostedFeedback,
    slug: &str,
    claims: Option<&openblog_core::claims::ClaimSet>,
) -> Option<feedback_publication::PublishedDecision> {
    item.decisions
        .as_ref()
        .and_then(|log| feedback_publication::PublishedDecision::in_force(log, item.revision))
        .map(|decision| decision.with_published_evidence(claims, slug))
}

/// Put the author's decision in force on an item that is already on its post, or take a
/// superseded one off (ADR 0119). Nothing else about the published note changes, and an item
/// that is not published is left alone: recording a decision never publishes a note. Returns
/// whether the file changed, with the rebuild's result.
fn publish_decision_outcome(
    state: &AppState,
    item: &moderation_inbox::InboxItem,
) -> Result<Option<Json>, String> {
    let Some(hosted) = item.feedback() else {
        return Ok(None);
    };
    // Only a note readers see now carries an outcome: approved at its current text.
    if !moderation::is_public(
        &item.facts(),
        openblog_core::participation::ParticipationMode::Open,
    ) {
        return Ok(None);
    }
    if published_feedback_file(state).is_none_or(|file| file.get(&item.id).is_none()) {
        return Ok(None);
    }
    let site = feedback_site(state).map_err(|_| "The site cannot be read now.".to_string())?;
    let post = feedback_moderation::post_for_work(&site, &hosted.feedback.provenance.work)
        .ok_or_else(|| {
            "No post has this address now, so its outcome is not updated.".to_string()
        })?;
    let claims = claims_for_publication(state);
    let mut status = lock(&state.build);
    let _transaction = content_transaction(state)
        .map_err(|_| "The site is being changed; try again in a moment.".to_string())?;
    let path = reader_feedback_path(state)
        .map_err(|_| "reader-feedback.json cannot be written".to_string())?;
    let (mut file, _) = load_reader_feedback(&path)
        .map_err(|_| "reader-feedback.json cannot be read; fix it in source mode".to_string())?;
    let decision = decision_to_publish(hosted, &post.slug, claims.as_ref());
    let Some(current) = file.get(&item.id).cloned() else {
        return Ok(None);
    };
    // Check it as the file is read before writing it, so a decision that would make the file
    // unreadable is never written.
    current.with_decision(decision.clone())?;
    if !file.set_decision(&item.id, decision) {
        return Ok(None);
    }
    write_reader_feedback(&path, &file)
        .map_err(|_| "reader-feedback.json could not be written".to_string())?;
    Ok(Some(feedback_build_json(
        &state.rebuild_locked(&mut status),
    )))
}

/// Take one item off the site. The caller holds the content lock.
fn unpublish_feedback(path: &Path, id: &str) -> Result<(), String> {
    let (mut file, _) = load_reader_feedback(path).map_err(|_| {
        "reader-feedback.json cannot be read; remove the note from it in source mode".to_string()
    })?;
    if file.unpublish(id) {
        write_reader_feedback(path, &file)
            .map_err(|_| "reader-feedback.json could not be written".to_string())?;
    }
    Ok(())
}

/// Take a removed or rejected item off its post, or say why not. The caller
/// holds the content lock.
fn unpublish_moderated_feedback(path: &Path, item: &HostedFeedback) -> Result<(), String> {
    if !matches!(
        item.status,
        ModerationState::Removed | ModerationState::Rejected | ModerationState::Withdrawn
    ) {
        return Err("Only removed, rejected or withdrawn feedback is taken off a post here".into());
    }
    unpublish_feedback(path, &item.id)
}

// ---- Published Third Perspectives (ADR 0115)
//
// What a site publishes of approved Third Perspectives lives in
// `third-perspectives.json` in the content folder, beside
// `reader-feedback.json`, written only here, under the content lock. Each
// record holds exactly the parts the one public projection reads, taken
// from the hosted copy only while that projection shows it.

fn third_perspectives_path(state: &AppState) -> Result<PathBuf, Response> {
    let config = site::load_config(&state.root).map_err(|error| Response::error(500, &error))?;
    let path = state
        .root
        .join(&config.paths.content)
        .join(perspective_publication::THIRD_PERSPECTIVES_FILE);
    if fs::symlink_metadata(&path).is_ok_and(|metadata| !metadata.is_file()) {
        return Err(Response::error(
            409,
            "third-perspectives.json must be a regular file in the content folder",
        ));
    }
    Ok(path)
}

/// The published Third Perspectives; an absent file is an empty one. A file
/// that cannot be read is refused, naming the file, and nothing is written
/// over it.
fn load_third_perspectives(
    path: &Path,
) -> Result<perspective_publication::ThirdPerspectivesFile, Response> {
    let bytes = read_optional_bytes(path).map_err(|error| Response::error(500, &error))?;
    let Some(bytes) = bytes else {
        return Ok(Default::default());
    };
    let text = String::from_utf8(bytes).map_err(|_| {
        Response::error(
            409,
            "third-perspectives.json is not UTF-8; fix it in source mode before moderating",
        )
    })?;
    perspective_publication::ThirdPerspectivesFile::from_json(&text).map_err(|error| {
        Response::error(
            409,
            &format!("third-perspectives.json {error}; fix it in source mode before moderating"),
        )
    })
}

fn published_perspectives_file(
    state: &AppState,
) -> Option<perspective_publication::ThirdPerspectivesFile> {
    third_perspectives_path(state)
        .and_then(|path| load_third_perspectives(&path))
        .ok()
}

/// Put one approved Third Perspective on its post, or say why not: only
/// while the one projection shows it now. The caller holds the content lock.
fn publish_approved_perspective(
    path: &Path,
    site: &Site,
    item: &third_perspective::HostedPerspective,
) -> Result<(), String> {
    if item.state != ModerationState::Approved {
        return Err("Only an approved Third Perspective is published".into());
    }
    let post = feedback_moderation::post_for_work(site, &item.copy.provenance.work)
        .ok_or_else(|| "No post has this address now, so the reflection is not on the site yet. Publish it from the Approved list once the post is back.".to_string())?;
    let mut file = load_third_perspectives(path).map_err(|_| {
        "third-perspectives.json cannot be read; fix it in source mode, then publish the reflection from the Approved list".to_string()
    })?;
    let record = perspective_publication::PublishedPerspective::from_hosted(
        &post.source.replace('\\', "/"),
        item,
        post,
        &site.config,
        item.moderated_at.unwrap_or_else(clock::now),
    )?;
    file.publish(record)?;
    write_atomic_bytes(path, file.to_json().as_bytes())
        .map_err(|_| "third-perspectives.json could not be written".to_string())
}

/// Take one Third Perspective off the site. The caller holds the content lock.
fn unpublish_perspective(path: &Path, id: &str) -> Result<(), String> {
    let mut file = load_third_perspectives(path).map_err(|_| {
        "third-perspectives.json cannot be read; remove the reflection from it in source mode"
            .to_string()
    })?;
    // A feature never outlives its reflection (ADR 0178): it comes off first.
    unfeature_beside(path, id);
    if file.unpublish(id) {
        write_atomic_bytes(path, file.to_json().as_bytes())
            .map_err(|_| "third-perspectives.json could not be written".to_string())?;
    }
    Ok(())
}

/// Put one approved author response under the reflection it answers on the
/// site, or say why not. The reflection is published first when it is not on
/// the file yet. The caller holds the content lock and has checked the answer
/// against its parent (`check_answer_approval`).
fn publish_approved_answer(
    path: &Path,
    site: &Site,
    parent: &moderation_inbox::InboxItem,
    answer: &author_response::HostedAuthorResponse,
) -> Result<(), String> {
    let published = perspective_publication::PublishedAnswer::from_hosted(
        answer,
        answer.moderated_at.unwrap_or_else(clock::now),
    )?;
    let hosted = parent.perspective().ok_or_else(|| {
        "The reflection this answers has no text left, so the answer is not on the site".to_string()
    })?;
    let on_file = load_third_perspectives(path)
        .map_err(|_| "third-perspectives.json cannot be read; fix it in source mode".to_string())?
        .get(&parent.id)
        .is_some();
    if !on_file {
        publish_approved_perspective(path, site, hosted)?;
    }
    let mut file = load_third_perspectives(path)
        .map_err(|_| "third-perspectives.json cannot be read; fix it in source mode".to_string())?;
    file.set_answer(&parent.id, published)?;
    write_atomic_bytes(path, file.to_json().as_bytes())
        .map_err(|_| "third-perspectives.json could not be written".to_string())
}

/// Take one published author response off its reflection (the reflection stays).
/// The caller holds the content lock.
fn unpublish_published_answer(path: &Path, answer: &str) -> Result<(), String> {
    let mut file = load_third_perspectives(path).map_err(|_| {
        "third-perspectives.json cannot be read; remove the answer from it in source mode"
            .to_string()
    })?;
    if file.unpublish_answer(answer) {
        write_atomic_bytes(path, file.to_json().as_bytes())
            .map_err(|_| "third-perspectives.json could not be written".to_string())?;
    }
    Ok(())
}

/// Whether a published author response must come off now: its hosted row is
/// no longer approved at its current text (withdrawn, removed, rejected,
/// reopened, purged). A purged answer keeps no text, so none may stay public.
fn answer_must_come_off(item: &moderation_inbox::InboxItem) -> bool {
    match item.author_response() {
        Some(hosted) => {
            hosted.state != ModerationState::Approved
                || hosted.approved_revision != Some(hosted.item_revision)
        }
        None => true,
    }
}

/// Whether a published Third Perspective must come off its post now: the
/// hosted copy is no longer one the one projection shows (withdrawn,
/// removed, rejected, purged, reopened, under a consent that no longer allows
/// it, or about a work that is gone). `None` when it cannot be told: the
/// hosted function does not read the consent an approval covers (Third
/// Perspectives switched off or rolled back), so an approved copy may or may
/// not be shown.
fn perspective_must_come_off(
    site: &Site,
    third_perspectives: bool,
    item: &moderation_inbox::InboxItem,
) -> Option<bool> {
    match item.perspective() {
        Some(hosted) => {
            if !third_perspectives && hosted.state == ModerationState::Approved {
                return None;
            }
            let post = feedback_moderation::post_for_work(site, &hosted.copy.provenance.work);
            Some(!perspective_publication::PublishedPerspective::shown_now(
                hosted,
                post,
                &site.config,
            ))
        }
        // A purged item keeps no text: nothing of it may stay public.
        None => Some(item.kind == ParticipationKind::ThirdPerspective),
    }
}

/// Whether the published file still shows a name the hosted copy no longer
/// shows (the reader hid it after approval): the one step that removes it from
/// the committed file is publishing the reflection again (ADR 0115, 0177).
/// Only where the hosted function reads consent, else the copy cannot say.
fn perspective_name_narrowed(
    site: &Site,
    third_perspectives: bool,
    file: &perspective_publication::ThirdPerspectivesFile,
    item: &moderation_inbox::InboxItem,
) -> bool {
    let (true, Some(hosted), Some(record)) =
        (third_perspectives, item.perspective(), file.get(&item.id))
    else {
        return false;
    };
    let post = feedback_moderation::post_for_work(site, &hosted.copy.provenance.work);
    record.name_standing(hosted, post, &site.config)
        == perspective_publication::NameStanding::Narrowed
}

/// `POST engagement/third-perspectives/publish` or `/unpublish`: put an
/// approved Third Perspective on its post again, after a failed write or an
/// approval made outside Admin, or take one off that may no longer be shown
/// (a reader withdrew it through their receipt). Only the site Admin of the
/// item's work may, and only as the hosted copy says now.
fn sync_published_perspective(
    state: &AppState,
    req: &Request,
    session: &auth::Session,
    publish: bool,
) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let found = match hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, &id) {
        Ok(found) => found,
        Err(response) => return response,
    };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let Some((protocol, third_perspectives, item)) = found else {
        // The hosted row is gone. Removing is always safe, so the site Admin
        // (bound in no shared publication) may take the copy off the site;
        // publishing needs the row.
        if publish {
            return Response::error(404, "No such item");
        }
        return remove_unlisted_publication(state, &sources, session, &id, false);
    };
    let role = sources.inbox(session, protocol, third_perspectives, |inbox| {
        inbox.actor(&item).role()
    });
    apply_perspective_sync(state, role, third_perspectives, &item, &id, publish)
}

/// Take a published reflection (`answer` false) or answer off the site when
/// its hosted row is missing: only the site Admin, and only a removal.
fn remove_unlisted_publication(
    state: &AppState,
    sources: &InboxSources,
    session: &auth::Session,
    id: &str,
    answer: bool,
) -> Response {
    if !retention_admin(sources, session) {
        return Response::json(
            403,
            &json!({ "error": "Only the site Admin can change what the site publishes.", "code": "denied" }),
        );
    }
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match third_perspectives_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let outcome = if answer {
        unpublish_published_answer(&path, id)
    } else {
        unpublish_perspective(&path, id)
    };
    if let Err(error) = outcome {
        return Response::error(409, &error);
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!(
        "admin: {} {id} unpublished (no hosted row)",
        if answer {
            "author response"
        } else {
            "third perspective"
        }
    );
    Response::json(200, &json!({ "published": false, "build": build }))
}

/// What a publish or take-off does once the hosted copy is read and the
/// account's role on it is known: only a Third Perspective, only the site
/// Admin, a publish only of an approved copy the projection shows now, and a
/// take-off only of one that may not be shown (or cannot be told).
fn apply_perspective_sync(
    state: &AppState,
    role: moderation::ActorRole,
    third_perspectives: bool,
    item: &moderation_inbox::InboxItem,
    id: &str,
    publish: bool,
) -> Response {
    if item.kind != ParticipationKind::ThirdPerspective {
        return Response::error(404, "No such Third Perspective");
    }
    if role != moderation::ActorRole::SiteAdmin {
        return Response::json(
            403,
            &json!({ "error": "Only the site Admin can change what the site publishes.", "code": "denied" }),
        );
    }
    let site = match feedback_site(state) {
        Ok(site) => site,
        Err(response) => return response,
    };
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match third_perspectives_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let outcome = if publish {
        match item.perspective() {
            Some(hosted) => publish_approved_perspective(&path, &site, hosted),
            None => Err("Its text was deleted, so it cannot be published".into()),
        }
    } else if perspective_must_come_off(&site, third_perspectives, item) != Some(false) {
        unpublish_perspective(&path, id)
    } else {
        Err("This reflection is approved and the reader's consent allows it, so it stays on the post. Remove it in the inbox to take it off.".into())
    };
    if let Err(error) = outcome {
        return Response::error(409, &error);
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!(
        "admin: third perspective {id} {}",
        if publish { "published" } else { "unpublished" }
    );
    Response::json(200, &json!({ "published": publish, "build": build }))
}

/// `POST engagement/author-responses/publish` or `/unpublish`: put an
/// approved author response under its published reflection again, after a
/// failed write, or take one off that may no longer be shown (the author
/// withdrew it). Only the site Admin of the answer's work may, and only as the
/// hosted copy and its parent say now (ADR 0137).
fn sync_published_answer(
    state: &AppState,
    req: &Request,
    session: &auth::Session,
    publish: bool,
) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let found = match hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, &id) {
        Ok(found) => found,
        Err(response) => return response,
    };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let Some((protocol, third_perspectives, item)) = found else {
        if publish {
            return Response::error(404, "No such item");
        }
        return remove_unlisted_publication(state, &sources, session, &id, true);
    };
    if item.kind != ParticipationKind::AuthorResponse {
        return Response::error(404, "No such author response");
    }
    let role = sources.inbox(session, protocol, third_perspectives, |inbox| {
        inbox.actor(&item).role()
    });
    if role != moderation::ActorRole::SiteAdmin {
        return Response::json(
            403,
            &json!({ "error": "Only the site Admin can change what the site publishes.", "code": "denied" }),
        );
    }
    // A publish checks the answer under its parent as an approval does.
    let parent = if publish {
        let Some(answer) = item.author_response() else {
            return Response::error(409, "Its text was deleted, so it cannot be published");
        };
        match hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, &answer.parent) {
            Ok(Some((parent_protocol, parent_perspectives, parent))) => {
                let checked =
                    sources.inbox(session, parent_protocol, parent_perspectives, |inbox| {
                        inbox.check_answer_approval(&item, &parent)
                    });
                if let Err(code) = checked {
                    return Response::json(
                        409,
                        &json!({ "error": "The reflection this answers is not shown to readers now, or is not about this author’s section, so the answer cannot be published.", "code": code }),
                    );
                }
                Some(parent)
            }
            Ok(None) => {
                return Response::error(409, "The reflection this answers is not on the site")
            }
            Err(response) => return response,
        }
    } else {
        None
    };
    let site = match feedback_site(state) {
        Ok(site) => site,
        Err(response) => return response,
    };
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match third_perspectives_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let outcome = if publish {
        match (item.author_response(), &parent) {
            (Some(answer), Some(parent)) => publish_approved_answer(&path, &site, parent, answer),
            _ => Err("Its text was deleted, so it cannot be published".into()),
        }
    } else if answer_must_come_off(&item) {
        unpublish_published_answer(&path, &id)
    } else {
        Err("This answer is approved, so it stays on the post. Remove it in the inbox to take it off.".into())
    };
    if let Err(error) = outcome {
        return Response::error(409, &error);
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!(
        "admin: author response {id} {}",
        if publish { "published" } else { "unpublished" }
    );
    Response::json(200, &json!({ "published": publish, "build": build }))
}

/// The most published reflections one audit reads from the hosted copy.
const PERSPECTIVE_AUDIT_LIMIT: usize = 200;

/// `GET engagement/third-perspectives/published`: every reflection the site
/// publishes, checked against its hosted copy, so a withdrawal or a removal
/// that left one on its post is seen on every tab of the inbox, not only on
/// the card under one filter (ADR 0115). Answers only for the site Admin of
/// each reflection's work, and lists only the reflections that must come off
/// or whose hosted state cannot be told (Third Perspectives switched off or
/// rolled back), never their text.
fn published_perspectives_audit(state: &AppState, session: &auth::Session) -> Response {
    let path = match third_perspectives_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let file = match load_third_perspectives(&path) {
        Ok(file) => file,
        Err(response) => return response,
    };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let mut must_come_off = Vec::new();
    let mut unknown = Vec::new();
    let mut answers_off = Vec::new();
    let mut name_narrowed = Vec::new();
    for record in file.items.iter().take(PERSPECTIVE_AUDIT_LIMIT) {
        let entry = json!({ "id": record.id, "post": record.post });
        match hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, &record.id) {
            Ok(Some((protocol, third_perspectives, item))) => {
                let (role, state_now, narrowed) =
                    sources.inbox(session, protocol, third_perspectives, |inbox| {
                        (
                            inbox.actor(&item).role(),
                            perspective_must_come_off(inbox.site, third_perspectives, &item),
                            perspective_name_narrowed(inbox.site, third_perspectives, &file, &item),
                        )
                    });
                if role != moderation::ActorRole::SiteAdmin {
                    continue;
                }
                // An answer under a reflection that stays is checked on its own:
                // its hosted row must still be approved (ADR 0137).
                if let (Some(answer), Some(false) | None) = (&record.answer, state_now) {
                    match hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, &answer.id)
                    {
                        Ok(Some((_, _, hosted_answer)))
                            if !answer_must_come_off(&hosted_answer) => {}
                        Ok(_) => answers_off.push(json!({
                            "id": answer.id, "post": record.post, "parent": record.id,
                        })),
                        Err(response) => return response,
                    }
                }
                match state_now {
                    Some(true) => must_come_off.push(entry),
                    None => unknown.push(entry),
                    Some(false) if narrowed => name_narrowed.push(entry),
                    Some(false) => {}
                }
            }
            // The hosted copy is gone altogether: nothing may stay public.
            Ok(None) => {
                if retention_admin(&sources, session) {
                    must_come_off.push(entry);
                }
            }
            Err(response) => return response,
        }
    }
    Response::json(
        200,
        &json!({
            "checked": file.items.len().min(PERSPECTIVE_AUDIT_LIMIT),
            "truncated": file.items.len() > PERSPECTIVE_AUDIT_LIMIT,
            "mustComeOff": must_come_off,
            "unknown": unknown,
            "answersMustComeOff": answers_off,
            "nameNarrowed": name_narrowed,
        }),
    )
}

// ---- Featured reflections (#229, ADRs 0176 to 0182)
//
// An editor's choice to show one approved reflection again in the community
// section of its post lives in `community-perspectives.json` in the content
// folder, beside `third-perspectives.json`, written only here under the content
// lock. A feature is a reference (never the reader's words), made only for a
// reflection the one projection shows, whose reader agreed to feature exactly
// its approved text. Every route is the site Admin's and denies the rest.

fn community_features_path(state: &AppState) -> Result<PathBuf, Response> {
    let config = site::load_config(&state.root).map_err(|error| Response::error(500, &error))?;
    let path = state
        .root
        .join(&config.paths.content)
        .join(community_feature::COMMUNITY_FEATURES_FILE);
    if fs::symlink_metadata(&path).is_ok_and(|metadata| !metadata.is_file()) {
        return Err(Response::error(
            409,
            "community-perspectives.json must be a regular file in the content folder",
        ));
    }
    Ok(path)
}

/// The features; an absent file is an empty one. A file that cannot be read is
/// refused, naming the file, and nothing is written over it.
fn load_community_features(path: &Path) -> Result<community_feature::FeaturesFile, Response> {
    let Some(bytes) = read_optional_bytes(path).map_err(|error| Response::error(500, &error))?
    else {
        return Ok(Default::default());
    };
    let text = String::from_utf8(bytes).map_err(|_| {
        Response::error(
            409,
            "community-perspectives.json is not UTF-8; fix it in source mode before featuring",
        )
    })?;
    community_feature::FeaturesFile::from_json(&text).map_err(|error| {
        Response::error(
            409,
            &format!("community-perspectives.json {error}; fix it in source mode before featuring"),
        )
    })
}

fn write_community_features(
    path: &Path,
    file: &community_feature::FeaturesFile,
) -> Result<(), Response> {
    write_atomic_bytes(path, file.to_json().as_bytes())
        .map_err(|_| Response::error(500, "community-perspectives.json could not be written"))
}

/// A refused feature, with its stable code and a message that carries no
/// reader's words.
fn feature_error_response(error: community_feature::FeatureError) -> Response {
    use community_feature::FeatureError as E;
    let status = match error {
        E::InvalidEditor => 403,
        E::InvalidContext | E::PopularityClaim => 422,
        _ => 409,
    };
    Response::json(
        status,
        &json!({ "error": error.message(), "code": error.code() }),
    )
}

fn feature_denied() -> Response {
    Response::json(
        403,
        &json!({ "error": "Only the site Admin can change what the site features.", "code": "denied" }),
    )
}

/// The hosted reflection a request names, once the account is its site Admin.
fn feature_target(
    state: &AppState,
    body: &Json,
    session: &auth::Session,
) -> Result<(String, moderation_inbox::InboxItem, bool), Response> {
    let id = feedback_id(&body["id"])?;
    let Some((protocol, third_perspectives, item)) =
        hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, &id)?
    else {
        return Err(Response::error(404, "No such Third Perspective"));
    };
    if item.kind != ParticipationKind::ThirdPerspective {
        return Err(Response::error(404, "No such Third Perspective"));
    }
    let sources = inbox_sources(state)?;
    let role = sources.inbox(session, protocol, third_perspectives, |inbox| {
        inbox.actor(&item).role()
    });
    if role != moderation::ActorRole::SiteAdmin {
        return Err(feature_denied());
    }
    Ok((id, item, third_perspectives))
}

/// The site Admin check for taking a feature off or changing its note, which
/// needs no hosted copy: a reflection whose row is gone is the site Admin's
/// (bound in no shared publication) to take off.
fn feature_admin(state: &AppState, id: &str, session: &auth::Session) -> Result<(), Response> {
    let sources = inbox_sources(state)?;
    // Taking a feature off, or editing its note, is always safe, so the site
    // Admin of every work needs no hosted service for it; a per-work Admin does
    // (the work is the hosted row's).
    let lookup = match hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, id) {
        Ok(lookup) => lookup,
        Err(_) if retention_admin(&sources, session) => return Ok(()),
        Err(response) => return Err(response),
    };
    match lookup {
        Some((protocol, third_perspectives, item)) => {
            if item.kind != ParticipationKind::ThirdPerspective {
                return Err(Response::error(404, "No such Third Perspective"));
            }
            let role = sources.inbox(session, protocol, third_perspectives, |inbox| {
                inbox.actor(&item).role()
            });
            if role == moderation::ActorRole::SiteAdmin {
                Ok(())
            } else {
                Err(feature_denied())
            }
        }
        None if retention_admin(&sources, session) => Ok(()),
        None => Err(feature_denied()),
    }
}

fn hosted_facts(
    hosted: &third_perspective::HostedPerspective,
) -> third_perspective::ModerationFacts {
    third_perspective::ModerationFacts {
        state: hosted.state,
        revision: hosted.copy.revision,
        approved_revision: hosted.approved_revision,
        approved_consent: hosted.approved_consent,
        clarification_asked: hosted.clarification_asked,
        content_retained: true,
    }
}

/// `POST engagement/community/preview` or `/feature`: show, or make, one
/// feature of an approved reflection. Both run every check a feature needs, so
/// a preview never promises what choosing would refuse: the one projection
/// shows the reflection now, the reader agreed to feature exactly its approved
/// text, the published file holds that text and name, the note passes ADR
/// 0180's lint, the reflection is not already featured. The preview is the
/// public form (`FeaturedPerspective`) the page will project, and writes
/// nothing. Choosing also publishes the reflection first when it is not on
/// `third-perspectives.json` yet, in the same step.
fn feature_reflection(
    state: &AppState,
    req: &Request,
    session: &auth::Session,
    preview: bool,
) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let (_, item, third_perspectives) = match feature_target(state, &body, session) {
        Ok(target) => target,
        Err(response) => return response,
    };
    let context = match body.get("context") {
        None | Some(Json::Null) => String::new(),
        Some(Json::String(text)) => text.clone(),
        Some(_) => return Response::error(422, "An editors' note is plain text"),
    };
    apply_feature(
        state,
        &session.user,
        &item,
        third_perspectives,
        context,
        body["expectedVersion"].as_u64(),
        preview,
    )
}

/// What a preview or a choice does once the hosted reflection is read and its
/// site Admin known (see `feature_reflection`). `expected` is the version the
/// editor saw, which a choice needs and a preview does not.
fn apply_feature(
    state: &AppState,
    user: &str,
    item: &moderation_inbox::InboxItem,
    third_perspectives: bool,
    context: String,
    expected: Option<u64>,
    preview: bool,
) -> Response {
    let id = item.id.clone();
    if !preview && expected != Some(item.version) {
        return Response::json(409, &json!({ "error": INBOX_CHANGED, "code": "stale" }));
    }
    if !third_perspectives {
        return Response::error(
            409,
            "Third Perspectives are switched off or rolled back on the hosted service, so the reader's consent cannot be checked",
        );
    }
    let Some(hosted) = item.perspective() else {
        return Response::error(409, "Its text was deleted, so it cannot be featured");
    };
    let site = match feedback_site(state) {
        Ok(site) => site,
        Err(response) => return response,
    };
    let Some(post) = feedback_moderation::post_for_work(&site, &hosted.copy.provenance.work) else {
        return Response::error(
            409,
            "No post has this address now, so the reflection cannot be featured",
        );
    };
    let source = post.source.replace('\\', "/");
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let (third_path, features_path) = match (
        third_perspectives_path(state),
        community_features_path(state),
    ) {
        (Ok(third), Ok(features)) => (third, features),
        (Err(response), _) | (_, Err(response)) => return response,
    };
    let mut third = match load_third_perspectives(&third_path) {
        Ok(file) => file,
        Err(response) => return response,
    };
    let mut features = match load_community_features(&features_path) {
        Ok(file) => file,
        Err(response) => return response,
    };
    let publishing = third.get(&id).is_none();
    let candidate = match third.get(&id) {
        Some(published) => published.clone(),
        None => match perspective_publication::PublishedPerspective::from_hosted(
            &source,
            hosted,
            post,
            &site.config,
            hosted.moderated_at.unwrap_or_else(clock::now),
        ) {
            Ok(published) => published,
            Err(error) => return Response::error(409, &error),
        },
    };
    let record = match community_feature::FeatureRecord::new(
        &source,
        hosted,
        &hosted_facts(hosted),
        &candidate,
        post,
        &site.config,
        &community_feature::FeatureRequest {
            selected_by: user.to_string(),
            context,
            at: clock::now(),
        },
    ) {
        Ok(record) => record,
        Err(error) => return feature_error_response(error),
    };
    if features.get(&id).is_some() {
        return feature_error_response(community_feature::FeatureError::AlreadyFeatured);
    }
    // The public form the page will project, from the same code the build
    // uses, for the file as it would be after choosing. A choice runs the same
    // mode check as the preview, so a kind that is hidden or locked on the post
    // never gets a feature it would not show.
    let mut shown = third.clone();
    if let Err(error) = shown.publish(candidate.clone()) {
        return Response::error(409, &error);
    }
    let mode =
        participation::published_mode(&site.config, post, ParticipationKind::ThirdPerspective);
    let answers =
        participation::published_mode(&site.config, post, ParticipationKind::AuthorResponse);
    let featured =
        community_feature::project_post(&[&record], &shown, post, &site.config, mode, answers);
    let Some(featured) = featured.into_iter().next() else {
        return Response::error(
            409,
            "The post would not show this feature now: the kind is hidden or locked out",
        );
    };
    if preview {
        return Response::json(
            200,
            &json!({
                "preview": featured,
                "notice": community_feature::NON_CONSENSUS_NOTICE,
                "willPublish": publishing,
            }),
        );
    }
    if let Err(error) = features.feature(record) {
        return feature_error_response(error);
    }
    // The published reflection first, so a feature never stands without it.
    if publishing {
        if let Err(error) = third.publish(candidate) {
            return Response::error(409, &error);
        }
        if write_atomic_bytes(&third_path, third.to_json().as_bytes()).is_err() {
            return Response::error(500, "third-perspectives.json could not be written");
        }
    }
    if let Err(response) = write_community_features(&features_path, &features) {
        return response;
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!("admin: community feature {id} featured");
    Response::json(200, &json!({ "featured": true, "build": build }))
}

/// `POST engagement/community/unfeature`: take a feature off its post. An
/// editor may do it by choice at any time, and it is the step for a feature
/// the audit says must come off. The reflection stays published; the file keeps
/// nothing of the feature (ADR 0179).
fn unfeature_reflection(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    if let Err(response) = feature_admin(state, &id, session) {
        return response;
    }
    apply_unfeature(state, &id)
}

/// Take the feature of `id` off, once its site Admin is known.
fn apply_unfeature(state: &AppState, id: &str) -> Response {
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match community_features_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let mut features = match load_community_features(&path) {
        Ok(file) => file,
        Err(response) => return response,
    };
    if !features.unfeature(id) {
        return Response::error(404, "This reflection is not featured");
    }
    if let Err(response) = write_community_features(&path, &features) {
        return response;
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!("admin: community feature {id} taken off");
    Response::json(200, &json!({ "featured": false, "build": build }))
}

/// `POST engagement/community/note`: change a feature's editors' note (blank
/// clears it). The note is the editors' own words and passes the same lint
/// as when it was made; the reader's words and the day are untouched.
fn update_feature_note(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let Some(context) = body["context"].as_str() else {
        return Response::error(422, "An editors' note is plain text");
    };
    if let Err(response) = feature_admin(state, &id, session) {
        return response;
    }
    apply_note(state, &id, context)
}

/// Change the note of the feature of `id`, once its site Admin is known.
fn apply_note(state: &AppState, id: &str, context: &str) -> Response {
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match community_features_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let mut features = match load_community_features(&path) {
        Ok(file) => file,
        Err(response) => return response,
    };
    match features.set_context(id, context) {
        Ok(true) => {}
        Ok(false) => return Response::error(404, "This reflection is not featured"),
        Err(error) => return feature_error_response(error),
    }
    if let Err(response) = write_community_features(&path, &features) {
        return response;
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    Response::json(200, &json!({ "updated": true, "build": build }))
}

/// Take a feature off beside its published reflection, before the reflection
/// goes: a feature never outlives its reflection (ADR 0178). A features file
/// that cannot be read does not stop the take-off (a withdrawal comes first):
/// the page hides a feature whose reflection is gone. The caller holds the
/// content lock.
fn unfeature_beside(third_perspectives_file: &Path, id: &str) {
    let path = third_perspectives_file.with_file_name(community_feature::COMMUNITY_FEATURES_FILE);
    if let Ok(mut features) = load_community_features(&path) {
        if features.unfeature(id) {
            let _ = write_community_features(&path, &features);
        }
    }
}

/// What the audit knows of a feature's hosted reflection.
enum HostedCheck<'a> {
    /// The row, and whether the hosted service reads consent.
    Row(&'a moderation_inbox::InboxItem, bool),
    /// The hosted service says there is no such row.
    Gone,
    /// The hosted service could not be asked.
    Unavailable,
}

/// Whether one feature still stands, as the audit and a test ask it: against
/// its hosted reflection (ADR 0178's order), then against the committed
/// `third-perspectives.json` the page is built from, so a feature the page
/// would not show is reported with the page's own reason (the reflection is not
/// published, its text is not the agreed text, or it is dated before it was
/// approved). `None` when the hosted copy cannot say and the page shows no
/// reason either, so it cannot be told.
fn feature_standing(
    site: &Site,
    record: &community_feature::FeatureRecord,
    published: &perspective_publication::ThirdPerspectivesFile,
    hosted: HostedCheck,
) -> Option<community_feature::HostedStanding> {
    use community_feature::{HostedStanding, NotShown};
    let post = site
        .posts
        .iter()
        .find(|post| post.source.replace('\\', "/") == record.post);
    let mode = post.map_or(participation::ParticipationMode::Open, |post| {
        participation::published_mode(&site.config, post, ParticipationKind::ThirdPerspective)
    });
    let standing = match hosted {
        HostedCheck::Row(item, third_perspectives) => match item.perspective() {
            Some(hosted) if third_perspectives => Some(record.hosted_standing(
                Some((Some(hosted), &hosted_facts(hosted))),
                post,
                &site.config,
                mode,
            )),
            Some(_) => None,
            None => Some(record.hosted_standing(
                Some((
                    None,
                    &third_perspective::ModerationFacts {
                        state: item.state,
                        revision: item.revision,
                        approved_revision: item.approved_revision,
                        approved_consent: None,
                        clarification_asked: None,
                        content_retained: false,
                    },
                )),
                post,
                &site.config,
                mode,
            )),
        },
        HostedCheck::Gone => Some(record.hosted_standing(None, post, &site.config, mode)),
        HostedCheck::Unavailable => None,
    };
    if matches!(standing, Some(HostedStanding::MustComeOff(_))) {
        return standing;
    }
    if let Some(post) = post {
        let answers =
            participation::published_mode(&site.config, post, ParticipationKind::AuthorResponse);
        let resolved = community_feature::resolve_post(
            &[record],
            published,
            Some(post),
            &site.config,
            mode,
            answers,
        );
        if let Some((_, Err(NotShown::Off(reason)))) = resolved.into_iter().next() {
            return Some(HostedStanding::MustComeOff(reason));
        }
    }
    standing
}

/// The most features one audit reads from the hosted copy.
const FEATURE_AUDIT_LIMIT: usize = 200;

/// `GET engagement/community/features`: every feature the site makes, checked
/// against its hosted copy on each load (ADR 0178), for the site Admin of each
/// reflection's work. Each is `covered`, `hidden` (the article is not published
/// now; the record stays), `mustComeOff` with a stated reason, or `unknown` when
/// the hosted service does not read consent. Only ids, posts, days, the editors'
/// notes and fixed reasons: never a reader's words.
fn featured_audit(state: &AppState, session: &auth::Session) -> Response {
    let path = match community_features_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let file = match load_community_features(&path) {
        Ok(file) => file,
        Err(response) => return response,
    };
    // A site that features nothing has nothing to check, and needs no hosted service.
    if file.items.is_empty() {
        return Response::json(200, &json!({ "truncated": false, "features": [] }));
    }
    let published = match third_perspectives_path(state).and_then(|p| load_third_perspectives(&p)) {
        Ok(published) => published,
        Err(response) => return response,
    };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let site = match feedback_site(state) {
        Ok(site) => site,
        Err(response) => return response,
    };
    let mut out = Vec::new();
    // Once the hosted service cannot be asked, it is not asked again for each
    // feature; the site Admin of every work still sees what the committed file
    // alone shows, and may take any feature off (removing is always safe).
    let mut hosted_down = false;
    for record in file.items.iter().take(FEATURE_AUDIT_LIMIT) {
        let mut entry = json!({
            "id": record.id, "post": record.post, "featured": record.featured,
            "context": record.context,
        });
        let lookup = if hosted_down {
            Err(Response::error(
                502,
                "The hosted service could not be asked",
            ))
        } else {
            hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, &record.id)
        };
        let standing = match lookup {
            Ok(Some((protocol, third_perspectives, item))) => {
                let role = sources.inbox(session, protocol, third_perspectives, |inbox| {
                    inbox.actor(&item).role()
                });
                if role != moderation::ActorRole::SiteAdmin {
                    continue;
                }
                feature_standing(
                    &site,
                    record,
                    &published,
                    HostedCheck::Row(&item, third_perspectives),
                )
            }
            Ok(None) => {
                if !retention_admin(&sources, session) {
                    continue;
                }
                feature_standing(&site, record, &published, HostedCheck::Gone)
            }
            Err(response) => {
                if !retention_admin(&sources, session) {
                    return response;
                }
                hosted_down = true;
                feature_standing(&site, record, &published, HostedCheck::Unavailable)
            }
        };
        match standing {
            Some(community_feature::HostedStanding::Covered) => {
                entry["standing"] = json!("covered")
            }
            Some(community_feature::HostedStanding::Hidden(reason)) => {
                entry["standing"] = json!("hidden");
                entry["reason"] = json!(reason.id());
                entry["explanation"] = json!(reason.explanation());
            }
            Some(community_feature::HostedStanding::MustComeOff(reason)) => {
                entry["standing"] = json!("mustComeOff");
                entry["reason"] = json!(reason.id());
                entry["explanation"] = json!(reason.explanation());
            }
            None => entry["standing"] = json!("unknown"),
        }
        out.push(entry);
    }
    Response::json(
        200,
        &json!({
            "truncated": file.items.len() > FEATURE_AUDIT_LIMIT,
            "features": out,
        }),
    )
}

// ---- Author responses (#223, ADRs 0131 to 0135)
//
// An author answers a reader's Third Perspective about their own section of
// a shared reflection. Admin is where that is decided, because only Admin
// holds the private shared-publication record: the signed-in account must be
// the contributor bound to the participant whose public contributor id is on
// the section's anchor, and the section must be published now (from the
// committed body and credits alone). The hosted function never holds the
// record; it reads the one request Admin sends strictly, reads the parent
// from its own store and checks it again, and stores the answer pending.
// Moderation is the one inbox's.

/// What Admin makes of the hosted function's answer to an author response
/// request: stored (`202`), or refused with a short plain message and its
/// code. Nothing names the token.
fn hosted_author_answer(status: u16, value: Json) -> Result<(u16, Json), Response> {
    let refusal = |status: u16| {
        Response::json(
            status,
            &json!({
                "error": value["error"]
                    .as_str()
                    .filter(|message| message.len() <= 300 && !message.chars().any(char::is_control))
                    .unwrap_or("The hosted function refused the answer"),
                "code": value["code"].as_str().filter(|code| code.len() <= 40 && code.chars().all(|c| c.is_ascii_alphabetic())),
            }),
        )
    };
    match status {
        200 | 202 => Ok((status, value)),
        401 => Err(Response::error(
            502,
            "The hosted function refused the saved moderation token",
        )),
        404 if value["code"] == "unavailable" || value["code"] == "notFound" => Err(refusal(404)),
        404 => Err(Response::error(
            404,
            "The hosted function does not take author responses yet: deploy netlify/functions from this version of open.blog.",
        )),
        403 | 409 | 413 | 422 | 429 => Err(refusal(status)),
        _ => Err(Response::error(
            502,
            &format!("Hosted engagement returned HTTP {status}"),
        )),
    }
}

/// The raw credits sidecar the post's source file names, as committed.
fn post_credits_text(state: &AppState, config: &SiteConfig, source: &str) -> Option<String> {
    let path = openblog_core::contributor::sidecar_path(source)?;
    fs::read_to_string(state.root.join(&config.paths.content).join(path)).ok()
}

/// One refusal of an author response, with its code, for the answering page.
fn answer_refusal(status: u16, code: &str, message: &str) -> Response {
    Response::json(status, &json!({ "error": message, "code": code }))
}

/// `POST engagement/author-response`: `{"parent": id, "parentVersion": n,
/// "body": text}`. The parent is read from the hosted inbox; nothing about
/// who is answering, as whom or about which section comes from the request.
fn author_answer(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let parent_id = match feedback_id(&body["parent"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let Some(parent_version) = body["parentVersion"]
        .as_u64()
        .filter(|version| (1..=i32::MAX as u64).contains(version))
    else {
        return Response::error(422, "Send the reflection's version as you loaded it");
    };
    let Some(text) = body["body"].as_str() else {
        return Response::error(422, "Write the answer as plain text");
    };
    let (_, _, parent) =
        match hosted_inbox_item(state, moderation_inbox::Source::Feedback, &parent_id) {
            Ok(found) => found,
            Err(response) => return response,
        };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let credits = feedback_moderation::post_for_work(&sources.published, &parent.work)
        .and_then(|post| post_credits_text(state, &sources.config, &post.source));
    answer_as_author(
        &sources,
        session,
        &parent,
        parent_version,
        text,
        credits.as_deref(),
        |request| {
            hosted_inbox_raw(
                state,
                "admin/author-response",
                &[],
                Some(("POST", &request.to_value())),
            )
            .and_then(|(status, value)| hosted_author_answer(status, value))
        },
    )
}

/// The decision of an author response, before anything is sent: `send` is
/// handed the one checked request and reaches the hosted function.
fn answer_as_author(
    sources: &InboxSources,
    session: &auth::Session,
    parent: &moderation_inbox::InboxItem,
    parent_version: u64,
    text: &str,
    credits: Option<&str>,
    send: impl FnOnce(&author_response::AuthorResponseRequest) -> Result<(u16, Json), Response>,
) -> Response {
    use attributed_perspective::{admit_response, ResponseError};
    let Some(hosted) = parent.perspective() else {
        return Response::error(404, "No such reflection");
    };
    let works = moderation::SharedWorks::new(&sources.records, &sources.loaded);
    let admin_users: Vec<&str> = sources.admin_users.iter().map(String::as_str).collect();
    let contributor_ids: Vec<&str> = sources.contributor_ids.iter().map(String::as_str).collect();
    let identities = Identities {
        active_admin_users: &admin_users,
        contributor_ids: &contributor_ids,
    };
    let Some(post) = feedback_moderation::post_for_work(&sources.published, &parent.work) else {
        return answer_refusal(
            409,
            "parentUnavailable",
            "That work is not published now, so its reflections cannot be answered.",
        );
    };
    let Some(record) = works.record_for_work(&parent.work) else {
        // Not a shared work, or its post is not loaded: nobody answers as an author.
        return answer_refusal(
            403,
            "denied",
            "You cannot answer this reflection as its author.",
        );
    };
    let Ok(target) =
        third_perspective::PerspectiveTarget::try_from(hosted.copy.provenance.target.clone())
    else {
        return answer_refusal(
            422,
            "notAttributed",
            "That reflection is not about one author’s section.",
        );
    };
    let parent_mode = participation::effective_mode(
        &sources.published.config,
        post,
        ParticipationKind::ThirdPerspective,
    );
    let mode = participation::effective_mode(
        &sources.published.config,
        post,
        ParticipationKind::AuthorResponse,
    );
    let policy = moderation::ModerationPolicy::from_config(&sources.config);
    let facts = parent.facts();
    let admitted = admit_response(
        &policy,
        &attributed_perspective::ResponseRequest {
            id: "new",
            record,
            identities: &identities,
            admin_user: &session.user,
            works: &works,
            work: &parent.work,
            mode,
            parent: &facts,
            parent_mode,
            parent_target: &target,
            body: post.authored_markdown(),
            credits,
            registry: &sources.published.config.contributors,
            at: clock::now(),
        },
    );
    let admitted =
        match admitted {
            Ok(admitted) => admitted,
            Err(ResponseError::NotAttributed) => {
                return answer_refusal(
                    422,
                    "notAttributed",
                    "That reflection is not about one author’s section.",
                )
            }
            Err(ResponseError::Denied)
            | Err(ResponseError::Policy(moderation::PolicyError::Denied)) => {
                return answer_refusal(
                    403,
                    "denied",
                    "You cannot answer this reflection as its author.",
                )
            }
            Err(ResponseError::AuthorUnconfirmed) => return answer_refusal(
                409,
                "authorUnconfirmed",
                "No section by that author is published now, so there is nothing left to answer.",
            ),
            Err(ResponseError::Unavailable) => {
                return answer_refusal(
                    409,
                    "parentUnavailable",
                    "That reflection is not shown to readers now, so it cannot be answered.",
                )
            }
            Err(ResponseError::Policy(moderation::PolicyError::Closed)) => {
                return answer_refusal(
                    403,
                    "closed",
                    "This work is not taking author responses now.",
                )
            }
            Err(ResponseError::Policy(moderation::PolicyError::Unavailable)) => {
                return answer_refusal(
                    404,
                    "unavailable",
                    "Author responses are not turned on for this work.",
                )
            }
            Err(ResponseError::Policy(error)) => {
                return answer_refusal(
                    422,
                    error.code(),
                    &format!("{}.", capitalize(&error.to_string())),
                )
            }
        };
    // Only now, with the author confirmed, does the parent's own state matter.
    let contributor = admitted.responder.contributor.clone();
    let shown = parent
        .parent_facts()
        .ok_or("parentUnavailable")
        .and_then(|facts| facts.check_answer(&parent.work, &contributor));
    if let Err(code) = shown {
        return answer_refusal(
            if code == "parentUnavailable" {
                409
            } else {
                422
            },
            code,
            "That reflection cannot be answered now.",
        );
    }
    if parent.version != parent_version {
        return Response::json(409, &json!({ "error": INBOX_CHANGED, "code": "conflict" }));
    }
    let request = match author_response::AuthorResponseRequest::new(
        &parent.work,
        &parent.id,
        parent.version,
        text,
        author_response::StoredResponder::of(&admitted.responder, &session.user),
    ) {
        Ok(request) => request,
        Err(error) => return answer_refusal(422, error.code, &error.message),
    };
    match send(&request) {
        Ok((_, value)) => {
            eprintln!(
                "admin: author response to {} by {} as {}",
                parent.id, session.user, contributor
            );
            Response::json(
                200,
                &json!({
                    "ok": true,
                    "answer": { "id": value["id"], "status": value["status"], "receivedAt": value["receivedAt"] },
                }),
            )
        }
        Err(response) => response,
    }
}

/// `PATCH engagement/author-response`: `{"id": id, "version": n}`. An author
/// takes their own answer back, while they are still bound to their section.
fn withdraw_author_answer(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let Some(version) = body["version"]
        .as_u64()
        .filter(|version| (1..=i32::MAX as u64).contains(version))
    else {
        return Response::error(422, "Send the answer's version as you loaded it");
    };
    let (protocol, third_perspectives, item) =
        match hosted_inbox_item(state, moderation_inbox::Source::Feedback, &id) {
            Ok(found) => found,
            Err(response) => return response,
        };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let response = withdraw_answer_with(
        &sources,
        session,
        protocol,
        third_perspectives,
        &item,
        version,
        |request| {
            hosted_inbox_raw(
                state,
                "admin/author-response",
                &[],
                Some(("PATCH", request)),
            )
            .and_then(|(status, value)| hosted_author_answer(status, value))
        },
    );
    // A withdrawn answer is never public again: take it off its reflection.
    // A failure here is not hidden: the inbox's audit lists the answer until
    // it is off (ADR 0137).
    if response.status == 200 {
        take_answer_off(state, &id);
    }
    response
}

/// Take an answer off the published file when it is on it, then rebuild.
/// Best effort: the audit and the card say when it stayed.
fn take_answer_off(state: &AppState, answer: &str) -> bool {
    let mut status = lock(&state.build);
    let Ok(_transaction) = content_transaction(state) else {
        return false;
    };
    let Ok(path) = third_perspectives_path(state) else {
        return false;
    };
    let Ok(file) = load_third_perspectives(&path) else {
        return false;
    };
    if file.parent_of_answer(answer).is_none() {
        return true;
    }
    if unpublish_published_answer(&path, answer).is_err() {
        return false;
    }
    let _ = state.rebuild_locked(&mut status);
    true
}

fn withdraw_answer_with(
    sources: &InboxSources,
    session: &auth::Session,
    protocol: moderation_inbox::Protocol,
    third_perspectives: bool,
    item: &moderation_inbox::InboxItem,
    version: u64,
    send: impl FnOnce(&Json) -> Result<(u16, Json), Response>,
) -> Response {
    if item.author_response().is_none() {
        return Response::error(404, "No such answer");
    }
    let decided = sources.inbox(session, protocol, third_perspectives, |inbox| {
        inbox.withdraw_answer(item, version)
    });
    match decided {
        Err(moderation::PolicyError::Denied) => {
            // The same answer for another account, a binding since removed and a
            // role since changed: nothing says which.
            return answer_refusal(404, "notFound", "No such answer");
        }
        Err(moderation::PolicyError::Stale) => {
            return Response::json(409, &json!({ "error": INBOX_CHANGED, "code": "conflict" }))
        }
        Err(error) => {
            return answer_refusal(422, error.code(), "This answer cannot be taken back now.")
        }
        Ok(_) => {}
    }
    let request = json!({ "id": item.id, "expectedVersion": version, "actor": session.user });
    match send(&request) {
        Ok((_, value)) => {
            eprintln!(
                "admin: author response {} withdrawn by {}",
                item.id, session.user
            );
            let view = moderation_inbox::InboxItem::from_value(&value["item"])
                .ok()
                .and_then(|changed| {
                    sources.inbox(session, protocol, third_perspectives, |inbox| {
                        inbox.view(&changed)
                    })
                });
            Response::json(200, &json!({ "ok": true, "item": view }))
        }
        Err(response) => response,
    }
}

// ---- The moderation inbox (ADR 0105)
//
// One list for hosted comments and passage feedback, driven by the one state
// machine. The hosted function holds the items; Admin reaches it only
// through this server, which keeps the token. Each item is read again with a
// strict validator, given the actor the signed-in account is on that item's
// work (`SharedWorks::actor`, ADR 0103), shown only as far as that actor may
// see it, and offered only the decisions the policy accepts now. A decision
// re-reads the item and decides again before the hosted function, which
// decides a third time, writes it conditionally with its audit event.

/// One request to the hosted inbox, with the server-held token. A `404` for
/// a missing item, a `403` refusal and a `409` conflict are returned with
/// their bodies; anything else becomes a short message naming no secret.
fn hosted_moderation_call(
    state: &AppState,
    query: &[(&str, &str)],
    body: Option<&Json>,
) -> Result<(u16, Json), Response> {
    hosted_inbox_request(
        state,
        "admin/moderation",
        query,
        body.map(|body| ("PATCH", body)),
    )
}

/// One request to a hosted inbox route (`admin/moderation` or
/// `admin/retention`) with the server-held token: a `GET` with `query`, or
/// `body` sent with its method.
fn hosted_inbox_request(
    state: &AppState,
    operation: &str,
    query: &[(&str, &str)],
    body: Option<(&str, &Json)>,
) -> Result<(u16, Json), Response> {
    let (status, value) = hosted_inbox_raw(state, operation, query, body)?;
    hosted_moderation_answer(status, value)
}

/// The same request, answered as the hosted function answered it: the status
/// and the body, for a caller that maps them itself. Failing to reach the
/// function, or having no endpoint or credential, is still an error.
fn hosted_inbox_raw(
    state: &AppState,
    operation: &str,
    query: &[(&str, &str)],
    body: Option<(&str, &Json)>,
) -> Result<(u16, Json), Response> {
    let config = site::load_config(&state.root).map_err(|error| Response::error(500, &error))?;
    if !config.engagement.enabled || !valid_engagement_endpoint(&config.engagement.endpoint) {
        return Err(Response::error(
            404,
            "Hosted engagement is not turned on: enable it with an endpoint in Settings to moderate comments and reader feedback.",
        ));
    }
    let credential = match engagement_credential(&state.root, &config.engagement.endpoint) {
        Ok(Some(credential)) => credential,
        Ok(None) => {
            return Err(Response::error(
                503,
                "Hosted engagement admin credential is not configured",
            ))
        }
        Err(error) => return Err(Response::error(500, &error)),
    };
    let mut url = format!(
        "{}/{operation}",
        config.engagement.endpoint.trim_end_matches('/')
    );
    if !query.is_empty() {
        url.push('?');
        url.push_str(
            &url::form_urlencoded::Serializer::new(String::new())
                .extend_pairs(query)
                .finish(),
        );
    }
    let agent: ureq::Agent = ureq::Agent::config_builder()
        .timeout_global(Some(Duration::from_secs(20)))
        .max_redirects(0)
        .http_status_as_error(false)
        .user_agent(concat!("open.blog-admin/", env!("CARGO_PKG_VERSION")))
        .build()
        .into();
    let authorization = format!("Bearer {credential}");
    let response = match body {
        Some(("POST", body)) => agent
            .post(&url)
            .header("Authorization", &authorization)
            .header("Content-Type", "application/json")
            .send(body.to_string().as_bytes()),
        Some((_, body)) => agent
            .patch(&url)
            .header("Authorization", &authorization)
            .header("Content-Type", "application/json")
            .send(body.to_string().as_bytes()),
        None => agent
            .get(&url)
            .header("Authorization", &authorization)
            .call(),
    };
    let mut response = match response {
        Ok(response) => response,
        Err(ureq::Error::Timeout(_)) => {
            return Err(Response::error(504, "Hosted engagement timed out"))
        }
        Err(_) => return Err(Response::error(502, "Hosted engagement request failed")),
    };
    let status = response.status().as_u16();
    let bytes = response
        .body_mut()
        .with_config()
        .limit(2 * 1024 * 1024)
        .read_to_vec()
        .map_err(|_| Response::error(502, "Cannot read hosted engagement response"))?;
    let value = serde_json::from_slice::<Json>(&bytes).unwrap_or(Json::Null);
    Ok((status, value))
}

/// What Admin makes of a hosted inbox answer. A refusal's message is passed
/// on only when short and plain; nothing names the token.
fn hosted_moderation_answer(status: u16, value: Json) -> Result<(u16, Json), Response> {
    match status {
        200 | 409 => Ok((status, value)),
        403 if value["code"] == "denied" => Ok((status, value)),
        404 if value["code"] == "notFound" => Ok((status, value)),
        404 => Err(Response::error(
            404,
            "The hosted function does not offer the moderation inbox yet: deploy netlify/functions from this version of open.blog.",
        )),
        401 => Err(Response::error(
            502,
            "The hosted function refused the saved moderation token",
        )),
        422 => Err(Response::json(
            422,
            &json!({
                "error": value["error"]
                    .as_str()
                    .filter(|message| message.len() <= 300 && !message.chars().any(char::is_control))
                    .unwrap_or("The hosted function refused the change"),
                "code": value["code"].as_str().filter(|code| code.len() <= 40 && code.chars().all(|c| c.is_ascii_alphabetic())),
            }),
        )),
        _ => Err(Response::error(
            502,
            &format!("Hosted engagement returned HTTP {status}"),
        )),
    }
}

/// What deciding who a viewer is needs: the site as readers see it now (for
/// passage checks and modes), the site as Admin loads it, drafts included
/// (for shared works, ADR 0103), the shared-publication records and the
/// accounts and contributor keys their bindings must still resolve to.
struct InboxSources {
    config: SiteConfig,
    published: Site,
    loaded: Site,
    records: Vec<SharedPublication>,
    admin_users: Vec<String>,
    contributor_ids: Vec<String>,
}

fn inbox_sources(state: &AppState) -> Result<InboxSources, Response> {
    let config = site::load_config(&state.root).map_err(|error| Response::error(500, &error))?;
    let now = clock::now();
    let published = site::load_site(&state.root, false, Some(now))
        .map(|(site, _)| site)
        .map_err(|error| Response::error(500, &error))?;
    let loaded = site::load_site(&state.root, true, Some(now))
        .map(|(site, _)| site)
        .map_err(|error| Response::error(500, &error))?;
    let records = crate::shared_publications::load_all(&state.root)
        .map_err(|error| Response::error(500, &error))?
        .into_iter()
        .map(|(_, record)| record)
        .collect();
    let (admin_users, contributor_ids) = collaboration_identities(&state.root, &config)?;
    Ok(InboxSources {
        config,
        published,
        loaded,
        records,
        admin_users,
        contributor_ids,
    })
}

impl InboxSources {
    /// Run `with` on the signed-in account's inbox.
    fn inbox<T>(
        &self,
        session: &auth::Session,
        protocol: moderation_inbox::Protocol,
        third_perspectives: bool,
        with: impl FnOnce(&moderation_inbox::Inbox<'_>) -> T,
    ) -> T {
        let works = moderation::SharedWorks::new(&self.records, &self.loaded);
        let admin_users: Vec<&str> = self.admin_users.iter().map(String::as_str).collect();
        let contributor_ids: Vec<&str> = self.contributor_ids.iter().map(String::as_str).collect();
        let identities = Identities {
            active_admin_users: &admin_users,
            contributor_ids: &contributor_ids,
        };
        with(&moderation_inbox::Inbox {
            site: &self.published,
            works: &works,
            principal: moderation::Principal::AdminSession {
                admin_user: &session.user,
            },
            identities: &identities,
            policy: moderation::ModerationPolicy::from_config(&self.config),
            protocol,
            third_perspectives,
            now: clock::now(),
        })
    }
}

/// An item as the viewer may see it, with, for passage feedback, whether the
/// site publishes it now (`null` when the published file cannot be read, so
/// nothing claims either way).
fn inbox_view(
    inbox: &moderation_inbox::Inbox<'_>,
    item: &moderation_inbox::InboxItem,
    published: Option<&feedback_publication::ReaderFeedbackFile>,
    perspectives: Option<&perspective_publication::ThirdPerspectivesFile>,
) -> Option<Json> {
    let mut view = inbox.view(item)?;
    if item.source == moderation_inbox::Source::Feedback {
        // A Third Perspective is published in third-perspectives.json (ADR
        // 0115), never in reader-feedback.json; the card also says whether
        // it must come off its post now.
        if item.kind == ParticipationKind::ThirdPerspective {
            view["published"] = match perspectives {
                Some(file) => json!(file.get(&item.id).is_some()),
                None => Json::Null,
            };
            // `null` when the hosted copy cannot say (the flag is off or rolled back).
            view["mayBeShown"] =
                match perspective_must_come_off(inbox.site, inbox.third_perspectives, item) {
                    Some(must) => json!(!must),
                    None => Json::Null,
                };
            // The reader hid their name after it was published: the file still holds it.
            // What the reader agreed about featuring, for the card's choose button.
            if let Some(hosted) = item.perspective() {
                view["featureConsent"] = json!(community_feature::FeatureConsent::of(hosted).id());
            }
            view["nameNarrowed"] = json!(perspectives.is_some_and(|file| {
                perspective_name_narrowed(inbox.site, inbox.third_perspectives, file, item)
            }));
        } else if item.kind == ParticipationKind::FutureSuggestion {
            // A suggestion is never published, in any file, whatever its state:
            // accepting it admits it to the editors' private list (ADR 0152).
            view["published"] = json!(false);
        } else if item.kind == ParticipationKind::AuthorResponse {
            // An author response is published under its reflection in the same
            // file (ADR 0137); the card says whether it is, and whether the
            // hosted copy may be shown now.
            view["published"] = match perspectives {
                Some(file) => json!(file.parent_of_answer(&item.id).is_some()),
                None => Json::Null,
            };
            view["mayBeShown"] = json!(!answer_must_come_off(item));
        } else {
            view["published"] = match published {
                Some(file) => json!(file.get(&item.id).is_some()),
                None => Json::Null,
            };
            // Whether the decision on the post is the one in force: a decision recorded when
            // the file write failed leaves it behind, and the inbox offers to update it.
            if let (Some(entry), Some(hosted)) = (
                published.and_then(|file| file.get(&item.id)),
                item.feedback().filter(|hosted| hosted.decisions.is_some()),
            ) {
                let in_force = hosted.decisions.as_ref().and_then(|log| {
                    feedback_publication::PublishedDecision::in_force(log, hosted.revision)
                });
                view["decisionPublished"] = json!(feedback_publication::PublishedDecision::agrees(
                    entry.decision.as_ref(),
                    in_force.as_ref()
                ));
            }
        }
    }
    Some(view)
}

fn published_feedback_file(state: &AppState) -> Option<feedback_publication::ReaderFeedbackFile> {
    reader_feedback_path(state)
        .and_then(|path| load_reader_feedback(&path))
        .ok()
        .map(|(file, _)| file)
}

/// `GET engagement/moderation?state=&kind=&after=`: one page of the inbox,
/// oldest first, holding only what this account may see. Nothing counts what
/// it may not see, so no count or preview reveals a pending item
/// (`collect_inbox_page`).
fn moderation_inbox_page(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let wanted_state = req.query.get("state").map_or("pending", String::as_str);
    let Some(wanted_state) = moderation::ModerationState::from_id(wanted_state) else {
        return Response::error(422, "Unknown moderation state");
    };
    let kind = req.query.get("kind").map_or("", String::as_str);
    if !kind.is_empty() && ParticipationKind::from_id(kind).is_none() {
        return Response::error(422, "Unknown participation kind");
    }
    let after = req.query.get("after").map_or("", String::as_str);
    if !after.is_empty() && !moderation_inbox::is_cursor(after) {
        return Response::error(422, "Invalid page cursor");
    }
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let bound = sources.records.iter().any(|record| {
        record
            .authorization
            .bindings
            .iter()
            .any(|binding| binding.admin_user == session.user)
    });
    let published = published_feedback_file(state);
    let perspectives = published_perspectives_file(state);
    let page_size = moderation_inbox::PAGE_SIZE.to_string();
    let collected = collect_inbox_page(
        bound,
        (!after.is_empty()).then(|| after.to_string()),
        |cursor| {
            let mut query = vec![("state", wanted_state.id()), ("limit", page_size.as_str())];
            if !kind.is_empty() {
                query.push(("kind", kind));
            }
            if let Some(cursor) = cursor {
                query.push(("after", cursor));
            }
            match hosted_moderation_call(state, &query, None) {
                Ok((200, value)) => moderation_inbox::read_page(&value)
                    .map_err(|error| Response::error(502, &error)),
                Ok(_) => Err(Response::error(
                    502,
                    "hosted engagement returned an invalid inbox",
                )),
                Err(response) => Err(response),
            }
        },
        |page| {
            sources.inbox(session, page.protocol, page.third_perspectives, |inbox| {
                let shown: Vec<(&moderation_inbox::InboxItem, Json)> = page
                    .items
                    .iter()
                    .filter_map(|item| {
                        inbox_view(inbox, item, published.as_ref(), perspectives.as_ref())
                            .map(|view| (item, view))
                    })
                    .collect();
                // Possible duplicates, among the items this account may see.
                let visible: Vec<&moderation_inbox::InboxItem> =
                    shown.iter().map(|(item, _)| *item).collect();
                let cues = moderation_inbox::similar_items(&visible);
                shown
                    .into_iter()
                    .map(|(item, mut view)| {
                        if let Some(similar) = cues.get(&item.id) {
                            view["similar"] = json!(similar);
                        }
                        view
                    })
                    .collect()
            })
        },
    );
    let mut collected = match collected {
        Ok(collected) => collected,
        Err(response) => return response,
    };
    add_decision_choices(state, &sources.published, &mut collected.items);
    Response::json(
        200,
        &json!({
            "state": wanted_state.id(),
            "kind": kind,
            "protocol": collected.protocol.id(),
            "items": collected.items,
            "invalid": collected.invalid,
            "next": collected.next,
        }),
    )
}

/// One page of the inbox as one account sees it.
struct CollectedPage {
    protocol: moderation_inbox::Protocol,
    items: Vec<Json>,
    invalid: usize,
    next: Option<String>,
}

/// The most hosted pages one inbox page may read for an account that may not
/// see every item.
const MAX_INBOX_REQUESTS: usize = 20;

/// Read hosted pages from `cursor`, keeping what `visible` lets the account
/// see. An account that sees everything gets one hosted page. One `bound` in
/// a shared publication, which may not, is given further pages until it has
/// a page of items it may see, the list ends or `MAX_INBOX_REQUESTS` pages
/// were read, so an empty page or a next link never betrays items hidden
/// from it (at the cap with nothing it may see, the list ends for it); and
/// it is never told how many items failed validation, which it
/// might not have been allowed to see.
fn collect_inbox_page(
    bound: bool,
    mut cursor: Option<String>,
    mut fetch: impl FnMut(Option<&str>) -> Result<moderation_inbox::HostedPage, Response>,
    mut visible: impl FnMut(&moderation_inbox::HostedPage) -> Vec<Json>,
) -> Result<CollectedPage, Response> {
    let mut items = Vec::new();
    let mut invalid = 0;
    let mut requests = 0;
    loop {
        let page = fetch(cursor.as_deref())?;
        requests += 1;
        invalid += page.invalid;
        items.extend(visible(&page));
        cursor = page.next.clone();
        if !bound
            || cursor.is_none()
            || items.len() >= moderation_inbox::PAGE_SIZE
            || requests >= MAX_INBOX_REQUESTS
        {
            // A bound account that reached the cap seeing nothing is told
            // the list ended: a next link would say hidden items exist.
            let next = if bound && items.is_empty() {
                None
            } else {
                cursor
            };
            return Ok(CollectedPage {
                protocol: page.protocol,
                items,
                invalid: if bound { 0 } else { invalid },
                next,
            });
        }
    }
}

/// One item read again from the hosted inbox, with what it can store.
fn hosted_inbox_item(
    state: &AppState,
    source: moderation_inbox::Source,
    id: &str,
) -> Result<
    (
        moderation_inbox::Protocol,
        bool,
        moderation_inbox::InboxItem,
    ),
    Response,
> {
    hosted_inbox_lookup(state, source, id)?.ok_or_else(|| Response::error(404, "No such item"))
}

/// The same, with `None` for an item the hosted function answers it does not
/// hold, which is not an error of reaching it.
#[allow(clippy::type_complexity)]
fn hosted_inbox_lookup(
    state: &AppState,
    source: moderation_inbox::Source,
    id: &str,
) -> Result<
    Option<(
        moderation_inbox::Protocol,
        bool,
        moderation_inbox::InboxItem,
    )>,
    Response,
> {
    let (_, value) = hosted_moderation_call(state, &[("id", id), ("source", source.id())], None)?;
    let page = moderation_inbox::read_page(&value).map_err(|error| Response::error(502, &error))?;
    if page.invalid > 0 {
        return Err(Response::error(
            502,
            "The hosted item is not valid; it was not changed",
        ));
    }
    let protocol = page.protocol;
    let third_perspectives = page.third_perspectives;
    Ok(page
        .items
        .into_iter()
        .find(|item| item.id == id && item.source == source)
        .map(|item| (protocol, third_perspectives, item)))
}

const INBOX_CHANGED: &str = "This item changed since you loaded it. Review it again before acting.";

// ---- The retention job (ADRs 0104 and 0108)
//
// Retention never runs on its own. The site Admin asks for a dry run, which
// lists what is due under the site's periods without changing anything,
// then runs it; both Admin and the hosted function decide each item's step,
// and only items both agree on, still as they were, are changed. Comments
// are part of a run only when the site set `participation.retention`.

/// Whether the signed-in account is the site Admin for every work: bound in
/// no shared publication, so retention, which spans every work, is theirs.
fn retention_admin(sources: &InboxSources, session: &auth::Session) -> bool {
    !sources.records.iter().any(|record| {
        record
            .authorization
            .bindings
            .iter()
            .any(|binding| binding.admin_user == session.user)
    })
}

/// The run's due items, as both Admin and the hosted function decide them
/// at `as_of`, with what the hosted dry run reported.
struct RetentionPlan {
    cutoffs: moderation::RetentionCutoffs,
    items: Vec<(moderation_inbox::InboxItem, moderation::RetentionStep)>,
    audit: Json,
    truncated: bool,
    disagreed: usize,
}

fn retention_step_id(step: moderation::RetentionStep) -> &'static str {
    match step {
        moderation::RetentionStep::Expire => "expire",
        moderation::RetentionStep::PurgeContent => "purge-content",
        moderation::RetentionStep::ScrubIdentity => "scrub-identity",
    }
}

fn retention_plan(
    state: &AppState,
    policy: &moderation::ModerationPolicy,
    as_of: DateTime,
) -> Result<RetentionPlan, Response> {
    let cutoffs = policy.cutoffs(as_of);
    let wire = cutoffs.to_json();
    let comments = if cutoffs.comments { "true" } else { "false" };
    let query: Vec<(&str, &str)> = [
        "pendingUntil",
        "clarificationUntil",
        "closedUntil",
        "auditUntil",
    ]
    .into_iter()
    .map(|key| (key, wire[key].as_str().unwrap_or_default()))
    .chain([("comments", comments)])
    .collect();
    let value = match hosted_inbox_request(state, "admin/retention", &query, None) {
        Ok((200, value)) => value,
        Ok(_) => return Err(Response::error(502, "hosted engagement returned an invalid retention report")),
        Err(response) if response.status == 404 => {
            return Err(Response::error(
                404,
                "Retention needs the hosted protection schema: run supabase/protection.sql, then set OPENBLOG_PROTECTION_ENABLED=true in Netlify.",
            ))
        }
        Err(response) => return Err(response),
    };
    let rows = value["items"]
        .as_array()
        .filter(|rows| rows.len() <= 3 * 200)
        .ok_or_else(|| {
            Response::error(
                502,
                "hosted engagement returned an invalid retention report",
            )
        })?;
    let mut items = Vec::new();
    let mut disagreed = 0;
    for row in rows {
        let hosted_step = row["step"].as_str().unwrap_or_default().to_string();
        let mut row = row.clone();
        if let Some(object) = row.as_object_mut() {
            object.remove("step");
        }
        let item = moderation_inbox::InboxItem::from_value(&row);
        let step = item
            .as_ref()
            .ok()
            .and_then(|item| item.retention_step(policy, as_of));
        match (item, step) {
            (Ok(item), Some(step)) if retention_step_id(step) == hosted_step => {
                if item.source != moderation_inbox::Source::Comment || cutoffs.comments {
                    items.push((item, step));
                } else {
                    disagreed += 1;
                }
            }
            _ => disagreed += 1,
        }
    }
    let audit = value["audit"].clone();
    let audit = if audit.as_object().is_some_and(|counts| {
        counts.len() <= 3 && counts.values().all(|count| count.as_u64().is_some())
    }) {
        audit
    } else {
        json!({})
    };
    Ok(RetentionPlan {
        cutoffs,
        items,
        audit,
        truncated: value["truncated"] == true,
        disagreed,
    })
}

/// The dry run as Admin shows it: counts by step and kind, and each item's
/// facts, never its text or a reader's name.
fn retention_report(
    policy: &moderation::ModerationPolicy,
    as_of: DateTime,
    plan: &RetentionPlan,
) -> Json {
    let mut summary: std::collections::BTreeMap<(&str, &str), (usize, &str)> =
        std::collections::BTreeMap::new();
    for (item, step) in &plan.items {
        summary
            .entry((retention_step_id(*step), item.kind.id()))
            .or_insert((0, item.kind.label()))
            .0 += 1;
    }
    json!({
        "asOf": as_of.rfc3339(),
        "periods": {
            "pendingDays": policy.retention.pending_days,
            "clarificationDays": policy.retention.clarification_days,
            "closedDays": policy.retention.closed_days,
            "auditDays": policy.retention.audit_days,
            "comments": policy.comment_retention,
        },
        "cutoffs": plan.cutoffs.to_json(),
        "summary": summary.into_iter().map(|((step, kind), (count, label))| json!({"step": step, "kind": kind, "kindLabel": label, "count": count})).collect::<Vec<_>>(),
        "items": plan.items.iter().map(|(item, step)| json!({
            "source": item.source.id(), "id": item.id, "kind": item.kind.id(), "kindLabel": item.kind.label(),
            "status": item.state.id(), "statusLabel": item.state.label(), "since": item.facts().state_since.rfc3339(),
            "step": retention_step_id(*step), "work": item.work,
        })).collect::<Vec<_>>(),
        "audit": plan.audit,
        "truncated": plan.truncated,
        "skipped": plan.disagreed,
    })
}

/// `GET engagement/retention`: the dry run. Nothing changes.
fn retention_dry_run(state: &AppState, session: &auth::Session) -> Response {
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    if !retention_admin(&sources, session) {
        return Response::error(
            403,
            "Only the site Admin runs retention, because it covers every post.",
        );
    }
    let policy = moderation::ModerationPolicy::from_config(&sources.config);
    let as_of = clock::now();
    match retention_plan(state, &policy, as_of) {
        Ok(plan) => Response::json(200, &retention_report(&policy, as_of, &plan)),
        Err(response) => response,
    }
}

/// `POST engagement/retention` with the dry run's `asOf` (at most an hour
/// old) and whether to delete old audit events: runs exactly what is due at
/// that time and still as it was, and reports what it did.
fn run_retention(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let now = clock::now();
    let Some(as_of) = body["asOf"]
        .as_str()
        .and_then(DateTime::parse)
        .filter(|as_of| as_of.unix() <= now.unix() && now.unix() - as_of.unix() <= 3_600)
    else {
        return Response::error(
            422,
            "Check what retention would do again, then run it within the hour.",
        );
    };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    if !retention_admin(&sources, session) {
        return Response::error(
            403,
            "Only the site Admin runs retention, because it covers every post.",
        );
    }
    let policy = moderation::ModerationPolicy::from_config(&sources.config);
    let plan = match retention_plan(state, &policy, as_of) {
        Ok(plan) => plan,
        Err(response) => return response,
    };
    let mut request = plan.cutoffs.to_json();
    request["audit"] = json!(body["audit"] == true);
    request["items"] = Json::Array(
        plan.items
            .iter()
            .take(200)
            .map(|(item, step)| json!({"source": item.source.id(), "id": item.id, "version": item.version, "step": retention_step_id(*step)}))
            .collect(),
    );
    let result = match hosted_inbox_request(state, "admin/retention", &[], Some(("POST", &request)))
    {
        Ok((200, value)) => value,
        Ok(_) => {
            return Response::error(
                502,
                "hosted engagement returned an invalid retention result",
            )
        }
        Err(response) => return response,
    };
    let count = |key: &str| result[key].as_u64().unwrap_or(0);
    eprintln!(
        "admin: retention by {} expired {} purged {} skipped {}",
        session.user,
        count("expired"),
        count("purged"),
        count("skipped")
    );
    Response::json(
        200,
        &json!({
            "expired": count("expired"),
            "purged": count("purged"),
            "scrubbed": count("scrubbed"),
            "skipped": count("skipped") as usize + plan.disagreed,
            "auditDeleted": result["auditDeleted"].as_object().map(|counts| counts.values().filter_map(Json::as_u64).sum::<u64>()),
            "more": plan.truncated || plan.items.len() > 200,
        }),
    )
}

/// `PATCH engagement/moderation`: one decision on one item. The request names
/// the item's source, id, state and version as loaded, the action, a reason
/// when it takes one and, to approve passage feedback whose passage is not
/// current, the passage check the moderator read. Nothing about who is
/// acting comes from the request.
fn moderate_inbox_item(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let Some(source) = body["source"]
        .as_str()
        .and_then(moderation_inbox::Source::from_id)
    else {
        return Response::error(422, "Name the item's source: comment, feedback or report");
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    // A deletion request is not a moderation transition: it purges the
    // item's text and name and leaves its state as it is (ADR 0107).
    let erase = body["action"].as_str() == Some(moderation_inbox::ERASE_ACTION);
    let action = if erase {
        None
    } else {
        match body["action"]
            .as_str()
            .and_then(moderation::ModerationAction::from_id)
            .filter(|action| {
                moderation_inbox::INBOX_ACTIONS.contains(action)
                    || *action == moderation::ModerationAction::UpholdReport
            }) {
            Some(action) => Some(action),
            None => return Response::error(422, "Choose one of the item's actions"),
        }
    };
    let Some(version) = body["version"]
        .as_u64()
        .filter(|version| (1..=i32::MAX as u64).contains(version))
    else {
        return Response::error(422, "Send the item's version as you loaded it");
    };
    let Some(from) = body["from"]
        .as_str()
        .and_then(moderation::ModerationState::from_id)
    else {
        return Response::error(422, "Send the item's state as you loaded it");
    };
    let reason = match &body["reason"] {
        Json::Null => None,
        Json::String(id) if id.is_empty() => None,
        Json::String(id) => match moderation::ReasonCode::from_id(id) {
            Some(reason) => Some(reason),
            None => {
                return Response::json(
                    422,
                    &json!({ "error": "Choose one of the listed reasons.", "code": "reasonNotAllowed" }),
                )
            }
        },
        _ => return Response::error(422, "A reason is a reason code"),
    };
    let (protocol, third_perspectives, item) = match hosted_inbox_item(state, source, &id) {
        Ok(found) => found,
        Err(response) => return response,
    };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let published = published_feedback_file(state);
    let perspectives = published_perspectives_file(state);
    // A Third Perspective's approval names the text revision and consent
    // record the moderator saw (ADR 0111); both are checked again here and
    // by the hosted function and the database.
    let seen = |key: &str| {
        body[key]
            .as_u64()
            .and_then(|value| u32::try_from(value).ok())
            .filter(|value| *value >= 1)
    };
    let approving_perspective =
        action == Some(moderation::ModerationAction::Approve) && item.perspective().is_some();
    let seen_perspective = (seen("seenRevision"), seen("seenConsent"));
    if approving_perspective && (seen_perspective.0.is_none() || seen_perspective.1.is_none()) {
        return Response::error(
            422,
            "Send the reflection's revision and consent record as you reviewed them",
        );
    }
    // Decided here first, with this account's role on the item's work: the
    // state the item ends in, and the item an upheld report takes down.
    let decided = sources.inbox(session, protocol, third_perspectives, |inbox| {
        let view = inbox_view(inbox, &item, published.as_ref(), perspectives.as_ref());
        let role = inbox.actor(&item).role();
        let binding = match seen_perspective {
            (Some(revision), Some(consent)) if approving_perspective => {
                Some(inbox.check_perspective_approval(&item, &session.user, revision, consent))
            }
            _ => None,
        };
        let decision = match action {
            Some(action) => inbox
                .decide(&item, action, version, reason)
                .map(|decision| {
                    (
                        decision.item.to,
                        decision.reported_item.map(|change| change.item),
                    )
                }),
            None if reason.is_some() => Err(moderation::PolicyError::ReasonNotAllowed),
            None => inbox
                .erase(&item, version)
                .map(|erasure| (erasure.state, None)),
        };
        (view, role, decision, binding)
    });
    let (view, role, decision, binding) = decided;
    let conflict = |view: Option<Json>, message: &str| {
        Response::json(
            409,
            &json!({ "error": message, "code": "conflict", "item": view }),
        )
    };
    let decision = match decision {
        Err(moderation::PolicyError::Denied) => {
            return Response::json(
                403,
                &json!({ "error": "You cannot take this decision on this item.", "code": "denied" }),
            )
        }
        Err(moderation::PolicyError::Stale) => return conflict(view, INBOX_CHANGED),
        Err(error) => {
            return Response::json(
                422,
                &json!({ "error": format!("{}.", capitalize(&error.to_string())), "code": error.code() }),
            )
        }
        Ok(_) if item.state != from => return conflict(view, INBOX_CHANGED),
        Ok(decision) => decision,
    };
    let (decided_to, removed_target) = decision;
    // An answer is approved only under the reflection it answers, read again
    // from the hosted store now, shown to readers and about the answering
    // contributor's own section (ADR 0132); the hosted function checks the
    // same again.
    let mut answer_parent: Option<moderation_inbox::InboxItem> = None;
    if action == Some(moderation::ModerationAction::Approve) {
        if let Some(answer) = item.author_response() {
            let parent = match hosted_inbox_lookup(
                state,
                moderation_inbox::Source::Feedback,
                &answer.parent,
            ) {
                Ok(parent) => parent,
                Err(response) => return response,
            };
            let checked = match &parent {
                Some((parent_protocol, parent_perspectives, parent)) => {
                    sources.inbox(session, *parent_protocol, *parent_perspectives, |inbox| {
                        inbox.check_answer_approval(&item, parent)
                    })
                }
                None => Err(author_response::PARENT_UNAVAILABLE),
            };
            let parent_item = parent.map(|(_, _, parent)| parent);
            if checked.is_ok() {
                answer_parent = parent_item;
            }
            if let Err(code) = checked {
                return Response::json(
                    if code == author_response::PARENT_UNAVAILABLE {
                        409
                    } else if code == author_response::RESPONDER_DENIED {
                        403
                    } else {
                        422
                    },
                    &json!({
                        "error": "The reflection this answers is not shown to readers now, is not about this author’s section, or the account that wrote the answer is no longer that section’s author, so the answer cannot be approved.",
                        "code": code,
                        "item": view,
                    }),
                );
            }
        }
    }
    let binding = match binding {
        None => None,
        Some(Ok(binding)) => Some(binding),
        Some(Err(
            error @ (third_perspective::LifecycleError::StaleRevision
            | third_perspective::LifecycleError::StaleConsent
            | third_perspective::LifecycleError::OutOfStep),
        )) => return conflict(view, &format!("{}.", capitalize(&error.to_string()))),
        Some(Err(error)) => {
            return Response::json(
                422,
                &json!({ "error": format!("{}.", capitalize(&error.to_string())), "code": error.code() }),
            )
        }
    };
    // A passage that moved or changed is approved only once the moderator
    // has confirmed the check they read (ADR 0083).
    if action == Some(moderation::ModerationAction::Approve) {
        if let Some(hosted) = item.feedback() {
            if !feedback_moderation::approval_acknowledged(
                &hosted.feedback,
                &sources.published,
                body["acknowledge"].as_str(),
            ) {
                return conflict(
                    view,
                    "The passage is not where the reader saw it. Read the passage check as it is now and confirm it before approving.",
                );
            }
        }
    }
    let action_id = action.map_or(
        moderation_inbox::ERASE_ACTION,
        moderation::ModerationAction::id,
    );
    let mut request = json!({
        "source": source.id(),
        "id": id,
        "action": action_id,
        "from": item.state.id(),
        "expectedVersion": version,
        "reason": reason.map(moderation::ReasonCode::id),
        "actor": session.user,
        "actorRole": role.id(),
    });
    if let Some(binding) = &binding {
        request["seenRevision"] = json!(binding.revision);
        request["seenConsent"] = json!(binding.consent);
    }
    if action == Some(moderation::ModerationAction::UpholdReport) {
        // The hosted function upholds only while the reported item is
        // exactly as this decision saw it (ADR 0104).
        request["targetVersion"] = json!(item.target.as_ref().map(|target| target.version));
    }
    let reread = |value: &Json| moderation_inbox::InboxItem::from_value(&value["item"]).ok();
    let changed = match hosted_moderation_call(state, &[], Some(&request)) {
        Ok((200, value)) => match reread(&value) {
            Some(changed)
                if changed.id == id
                    && stored_as(protocol, &changed, decided_to)
                    && (!erase || changed.content == moderation_inbox::Content::Purged) =>
            {
                changed
            }
            _ => {
                return Response::error(
                    502,
                    "hosted engagement returned an invalid moderation response",
                )
            }
        },
        Ok((409, value)) => {
            let current = reread(&value).and_then(|current| {
                sources.inbox(session, protocol, third_perspectives, |inbox| {
                    inbox_view(inbox, &current, published.as_ref(), perspectives.as_ref())
                })
            });
            return conflict(current, INBOX_CHANGED);
        }
        Ok((403, _)) => {
            return Response::json(
                403,
                &json!({ "error": "You cannot take this decision on this item.", "code": "denied" }),
            )
        }
        Ok(_) => return Response::error(404, "No such item"),
        Err(response) => return response,
    };
    eprintln!(
        "admin: moderation {} {id} {action_id} by {} as {}",
        source.id(),
        session.user,
        role.id()
    );
    // What the site publishes of passage feedback and Third Perspectives
    // follows the decision: an approval publishes the note or reflection; a
    // removal, an upheld report that took one down, or a deletion request
    // takes it off its post. Each kind has its own file (ADRs 0083, 0115).
    let approve = action == Some(moderation::ModerationAction::Approve);
    let unpublish = match (&item.target, &removed_target) {
        (Some(target), Some(_)) if target.source == moderation_inbox::Source::Feedback => Some((
            target.id.clone(),
            target.kind == ParticipationKind::ThirdPerspective,
        )),
        // An author response is published nowhere by this change (ADR 0132), so
        // there is no file to take it off.
        // Nor is a suggestion, which was never on a post to take off.
        _ if source == moderation_inbox::Source::Feedback
            && item.kind != ParticipationKind::AuthorResponse
            && item.kind != ParticipationKind::FutureSuggestion
            && (erase || action == Some(moderation::ModerationAction::Remove)) =>
        {
            Some((id.clone(), item.kind == ParticipationKind::ThirdPerspective))
        }
        _ => None,
    };
    let unpublish = unpublish.filter(|(target, perspective)| {
        // Only touch the file when the item is on it, or for a removal,
        // which always says what the file holds.
        action == Some(moderation::ModerationAction::Remove)
            || if *perspective {
                perspectives
                    .as_ref()
                    .is_none_or(|file| file.get(target).is_some())
            } else {
                published
                    .as_ref()
                    .is_none_or(|file| file.get(target).is_some())
            }
    });
    let mut published_now = false;
    let mut publish_error = None;
    let mut build = None;
    let approved_note = changed.feedback().filter(|_| approve);
    let approved_perspective = changed.perspective().filter(|_| approve);
    // An approved author response is published under its reflection; any
    // other decision on one that is on the site takes it off (ADR 0137).
    let approved_answer = changed
        .author_response()
        .filter(|_| approve)
        .zip(answer_parent.as_ref());
    let answer_off = (changed.kind == ParticipationKind::AuthorResponse
        && !approve
        && perspectives
            .as_ref()
            .is_some_and(|file| file.parent_of_answer(&id).is_some()))
    .then(|| id.clone());
    if approved_note.is_some()
        || approved_perspective.is_some()
        || unpublish.is_some()
        || approved_answer.is_some()
        || answer_off.is_some()
    {
        let mut status = lock(&state.build);
        let _transaction = match content_transaction(state) {
            Ok(lock) => lock,
            Err(response) => return response,
        };
        let feedback_path = || {
            reader_feedback_path(state)
                .map_err(|_| "reader-feedback.json cannot be written".to_string())
        };
        let perspectives_path = || {
            third_perspectives_path(state)
                .map_err(|_| "third-perspectives.json cannot be written".to_string())
        };
        let outcome = match (approved_note, approved_perspective, &unpublish) {
            _ if approved_answer.is_some() || answer_off.is_some() => {
                perspectives_path().and_then(|path| match (&approved_answer, &answer_off) {
                    (Some((answer, parent)), _) => {
                        publish_approved_answer(&path, &sources.published, parent, answer)
                    }
                    (None, Some(answer)) => unpublish_published_answer(&path, answer),
                    (None, None) => Ok(()),
                })
            }
            (Some(hosted), _, _) => feedback_path().and_then(|path| {
                publish_approved_feedback(
                    &path,
                    &sources.published,
                    hosted,
                    claims_for_publication(state).as_ref(),
                )
            }),
            (None, Some(hosted), _) => perspectives_path()
                .and_then(|path| publish_approved_perspective(&path, &sources.published, hosted)),
            (None, None, Some((target, true))) => {
                perspectives_path().and_then(|path| unpublish_perspective(&path, target))
            }
            (None, None, Some((target, false))) => {
                feedback_path().and_then(|path| unpublish_feedback(&path, target))
            }
            (None, None, None) => Ok(()),
        };
        match outcome {
            Ok(()) => {
                published_now = approve;
                build = Some(feedback_build_json(&state.rebuild_locked(&mut status)));
            }
            Err(error) => {
                // A removal that could not be written leaves the item on the
                // post; say so when the file says so.
                match &unpublish {
                    Some((target, true)) => {
                        published_now = third_perspectives_path(state)
                            .and_then(|path| load_third_perspectives(&path))
                            .is_ok_and(|file| file.get(target).is_some());
                    }
                    Some((target, false)) => {
                        published_now = reader_feedback_path(state)
                            .and_then(|path| load_reader_feedback(&path))
                            .is_ok_and(|(file, _)| file.get(target).is_some());
                    }
                    None => {
                        if let Some(answer) = &answer_off {
                            published_now = third_perspectives_path(state)
                                .and_then(|path| load_third_perspectives(&path))
                                .is_ok_and(|file| file.parent_of_answer(answer).is_some());
                        }
                    }
                }
                publish_error = Some(error)
            }
        }
    }
    // A submission that is no longer approved, or whose text was deleted, takes
    // its continuation links off both pages (ADR 0221); so does the item an
    // upheld report took down.
    let mut continuations_dropped = 0;
    let mut continuations_error: Option<&'static str> = None;
    let removed_target_id = match (&item.target, &removed_target) {
        (Some(target), Some(_)) => Some(target.id.as_str()),
        _ => None,
    };
    let forgotten = continuation_origins_to_forget(erase, changed.state, &id, removed_target_id);
    for origin in forgotten {
        let (count, rebuilt, failed) = forget_continuations(state, &origin);
        continuations_dropped += count;
        if rebuilt.is_some() {
            build = rebuilt;
        }
        continuations_error = continuations_error.or(failed);
    }
    let published = published_feedback_file(state);
    let perspectives = published_perspectives_file(state);
    let view = sources.inbox(session, protocol, third_perspectives, |inbox| {
        inbox_view(inbox, &changed, published.as_ref(), perspectives.as_ref())
    });
    Response::json(
        200,
        &json!({
            "item": view,
            "published": published_now,
            "publishError": publish_error,
            "build": build,
            "removedTarget": removed_target.is_some(),
            "continuationsDropped": continuations_dropped,
            "continuationsError": continuations_error,
        }),
    )
}

// ---- Continuation links (#231, ADRs 0218 to 0223)
//
// An editor's typed link from one approved reflection, question or source
// suggestion to a later published work lives in `continuations.json` in the
// content folder, written only here under the content lock. It holds ids and
// paths, never the reader's words. Every route is the site Admin's and denies
// the rest. A submission that is removed, withdrawn or deleted takes its links
// off the file (ADR 0221).

fn continuations_path(state: &AppState) -> Result<PathBuf, Response> {
    let config = site::load_config(&state.root).map_err(|error| Response::error(500, &error))?;
    let path = state
        .root
        .join(&config.paths.content)
        .join(continuation::CONTINUATIONS_FILE);
    if fs::symlink_metadata(&path).is_ok_and(|metadata| !metadata.is_file()) {
        return Err(Response::error(
            409,
            "continuations.json must be a regular file in the content folder",
        ));
    }
    Ok(path)
}

/// The links; an absent file is an empty one. A file that cannot be read is
/// refused, naming the file, and nothing is written over it.
fn load_continuations(path: &Path) -> Result<continuation::ContinuationsFile, Response> {
    let Some(bytes) = read_optional_bytes(path).map_err(|error| Response::error(500, &error))?
    else {
        return Ok(Default::default());
    };
    let text = String::from_utf8(bytes).map_err(|_| {
        Response::error(
            409,
            "continuations.json is not UTF-8; fix it in source mode before linking",
        )
    })?;
    continuation::ContinuationsFile::from_json(&text).map_err(|error| {
        Response::error(
            409,
            &format!("continuations.json {error}; fix it in source mode before linking"),
        )
    })
}

fn write_continuations(
    path: &Path,
    file: &continuation::ContinuationsFile,
) -> Result<(), Response> {
    write_atomic_bytes(path, file.to_json().as_bytes())
        .map_err(|_| Response::error(500, "continuations.json could not be written"))
}

fn continuation_error_response(error: continuation::ContinuationError) -> Response {
    use continuation::ContinuationError as E;
    let status = match error {
        E::Duplicate | E::TooMany => 409,
        _ => 422,
    };
    Response::json(
        status,
        &json!({ "error": error.message(), "code": "invalid" }),
    )
}

fn continuation_denied() -> Response {
    Response::json(
        403,
        &json!({ "error": "Only the site Admin can change the continuation links.", "code": "denied" }),
    )
}

/// What kind of submission a hosted item is, for a link; `None` when it cannot
/// start one (a comment, passage feedback, a report, or text that was deleted).
fn continuation_origin_kind(
    item: &moderation_inbox::InboxItem,
) -> Option<continuation::OriginKind> {
    use continuation::OriginKind;
    match item.kind {
        ParticipationKind::ThirdPerspective => item.perspective().map(|_| OriginKind::Reflection),
        ParticipationKind::FutureSuggestion => item.suggestion().map(|suggestion| {
            if suggestion.submission.suggestion_type
                == openblog_core::future_suggestion::SuggestionType::Question
            {
                OriginKind::Question
            } else {
                OriginKind::SourceSuggestion
            }
        }),
        _ => None,
    }
}

const CONTINUATION_AUDIT_LIMIT: usize = 100;

/// What the hosted service says about the submission behind a link.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum HostedStanding {
    Approved,
    /// Gone, or in any state but approved.
    NotApproved,
    /// The hosted service could not be asked, so nothing is judged.
    Unknown,
}

impl HostedStanding {
    fn id(self) -> &'static str {
        match self {
            Self::Approved => "approved",
            Self::NotApproved => "notApproved",
            Self::Unknown => "unknown",
        }
    }
}

/// A lookup's answer as a standing: found and approved, found otherwise or not
/// held, or not reachable.
fn hosted_standing<E>(found: Result<Option<ModerationState>, E>) -> HostedStanding {
    match found {
        Ok(Some(ModerationState::Approved)) => HostedStanding::Approved,
        Ok(_) => HostedStanding::NotApproved,
        Err(_) => HostedStanding::Unknown,
    }
}

/// The origins the sweep drops links for: those the hosted service says are
/// not approved. An origin it could not be asked about is kept.
fn origins_no_longer_approved(
    origins: impl IntoIterator<Item = String>,
    mut standing: impl FnMut(&str) -> HostedStanding,
) -> Vec<String> {
    origins
        .into_iter()
        .filter(|origin| standing(origin) == HostedStanding::NotApproved)
        .collect()
}

/// Whose links a moderation decision takes off both pages (ADR 0221): the
/// decided item when it is deleted or no longer approved, and the item an
/// upheld report removed.
fn continuation_origins_to_forget(
    erase: bool,
    state: ModerationState,
    id: &str,
    removed_target: Option<&str>,
) -> Vec<String> {
    let mut forgotten = Vec::new();
    if erase || state != ModerationState::Approved {
        forgotten.push(id.to_string());
    }
    if let Some(target) = removed_target {
        forgotten.push(target.to_string());
    }
    forgotten
}

/// `GET engagement/continuations`: every link, checked on each load against
/// the pages and the hosted submission, and the published works an editor may
/// link to. `standing` is `approved`, `notApproved` (the submission is gone or
/// no longer approved: sweep it) or `unknown` (the hosted service could not be
/// asked, so nothing is judged). Only ids, paths, days and the editors' notes.
fn continuations_list(state: &AppState, session: &auth::Session) -> Response {
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    if !retention_admin(&sources, session) {
        return continuation_denied();
    }
    let path = match continuations_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let file = match load_continuations(&path) {
        Ok(file) => file,
        Err(response) => return response,
    };
    let site = match feedback_site(state) {
        Ok(site) => site,
        Err(response) => return response,
    };
    let now = clock::now();
    let works: Vec<Json> = site
        .posts
        .iter()
        .filter(|post| !post.draft && post.date <= now)
        .map(|post| json!({ "path": post.url, "title": post.title, "series": post.series }))
        .collect();
    let published: std::collections::BTreeSet<String> = works
        .iter()
        .filter_map(|work| work["path"].as_str().map(str::to_string))
        .collect();
    let series: std::collections::BTreeSet<String> = site
        .posts
        .iter()
        .filter_map(|post| post.series.clone())
        .collect();
    let aliases = std::collections::BTreeMap::new();
    let view = continuation::Site {
        published: &published,
        series: &series,
        series_aliases: &aliases,
    };
    let mut standing: std::collections::BTreeMap<String, &'static str> = Default::default();
    let mut links = Vec::new();
    for edge in file.items.iter().take(CONTINUATION_AUDIT_LIMIT) {
        let origin = *standing.entry(edge.origin.clone()).or_insert_with(|| {
            hosted_standing(
                hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, &edge.origin)
                    .map(|found| found.map(|(_, _, item)| item.state)),
            )
            .id()
        });
        let shown = continuation::resolve(edge, continuation::OriginStanding::Approved, &view);
        links.push(json!({
            "id": edge.id, "origin": edge.origin, "kind": edge.kind.id(),
            "relation": edge.relation.id(), "from": edge.from, "to": edge.to,
            "series": edge.series, "note": edge.note, "linked": edge.linked,
            "standing": origin,
            "shown": shown.is_ok() && origin != "notApproved",
            "hidden": shown.err().map(continuation::Hidden::id),
        }));
    }
    Response::json(
        200,
        &json!({
            "truncated": file.items.len() > CONTINUATION_AUDIT_LIMIT,
            "links": links,
            "works": works,
            "notice": continuation::NO_CAUSATION_NOTICE,
        }),
    )
}

/// `POST engagement/continuations/link` (or `/preview`): link one approved
/// submission to a later published work. The kind, the earlier page and the
/// series come from the hosted submission and the site, never the request; the
/// request names the submission, the later work, the relation and an optional
/// note. A preview runs every check and writes nothing.
fn continuations_link(
    state: &AppState,
    req: &Request,
    session: &auth::Session,
    preview: bool,
) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let Some(relation) = body["relation"]
        .as_str()
        .and_then(continuation::Relation::from_id)
    else {
        return Response::error(
            422,
            "Choose how the later work relates: takes-up, revisits or uses-source",
        );
    };
    let note = match &body["note"] {
        Json::Null => None,
        Json::String(note) => Some(note.clone()),
        _ => return Response::error(422, "An editors note is plain text"),
    };
    let Some(to) = body["to"].as_str().map(str::to_string) else {
        return Response::error(422, "Choose the later work");
    };
    let (protocol, third_perspectives, item) =
        match hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, &id) {
            Ok(Some(found)) => found,
            Ok(None) => return Response::error(404, "No such submission"),
            Err(response) => return response,
        };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let role = sources.inbox(session, protocol, third_perspectives, |inbox| {
        inbox.actor(&item).role()
    });
    if role != moderation::ActorRole::SiteAdmin {
        return continuation_denied();
    }
    let expected_version = if preview {
        None
    } else {
        Some(body["expectedVersion"].as_u64())
    };
    link_approved_item(
        state,
        &id,
        &item,
        &to,
        relation,
        note,
        expected_version,
        preview,
    )
}

/// The checks and the write of one link, for an item already read from the
/// hosted inbox and already known to belong to the site Admin. `expected_version`
/// is `None` for a preview and `Some(version the editor saw)` otherwise.
#[allow(clippy::too_many_arguments)]
fn link_approved_item(
    state: &AppState,
    id: &str,
    item: &moderation_inbox::InboxItem,
    to: &str,
    relation: continuation::Relation,
    note: Option<String>,
    expected_version: Option<Option<u64>>,
    preview: bool,
) -> Response {
    let id = id.to_string();
    let to = to.to_string();
    if item.state != ModerationState::Approved {
        return Response::error(
            409,
            "Only an approved submission can be linked to a later work",
        );
    }
    let Some(kind) = continuation_origin_kind(item) else {
        return Response::error(
            409,
            "This item cannot start a continuation, or its text was deleted",
        );
    };
    if expected_version.is_some_and(|seen| seen != Some(item.version)) {
        return Response::json(409, &json!({ "error": INBOX_CHANGED, "code": "stale" }));
    }
    let site = match feedback_site(state) {
        Ok(site) => site,
        Err(response) => return response,
    };
    let now = clock::now();
    let published = |path: &str| {
        site.posts
            .iter()
            .find(|post| post.url == path && !post.draft && post.date <= now)
    };
    let Some(target) = published(&to) else {
        return Response::json(
            409,
            &json!({ "error": "The later work is not published now, so it cannot be linked", "code": "unpublished" }),
        );
    };
    if published(&item.work).is_none() {
        return Response::json(
            409,
            &json!({ "error": "The page the submission was about is not published now, so it cannot be linked", "code": "unpublished" }),
        );
    }
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match continuations_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let mut file = match load_continuations(&path) {
        Ok(file) => file,
        Err(response) => return response,
    };
    let short: String = id.chars().filter(char::is_ascii_hexdigit).take(8).collect();
    let link_id = (1..)
        .map(|n| format!("link-{short}-{n}"))
        .find(|candidate| file.get(candidate).is_none())
        .unwrap_or_default();
    let edge = continuation::Continuation {
        id: link_id,
        kind,
        origin: id.clone(),
        from: item.work.clone(),
        to: to.clone(),
        series: target.series.clone(),
        relation,
        note,
        linked: now.ymd(),
    };
    let edge = match edge.validated() {
        Ok(edge) => edge,
        Err(error) => return continuation_error_response(error),
    };
    if let Err(error) = file.add(edge.clone()) {
        return continuation_error_response(error);
    }
    if preview {
        return Response::json(
            200,
            &json!({
                "preview": {
                    "kind": edge.kind.id(), "relation": edge.relation.id(),
                    "from": edge.from, "to": edge.to, "series": edge.series, "note": edge.note,
                },
                "notice": continuation::NO_CAUSATION_NOTICE,
            }),
        );
    }
    if let Err(response) = write_continuations(&path, &file) {
        return response;
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!("admin: continuation {} linked", edge.id);
    Response::json(
        200,
        &json!({ "linked": true, "id": edge.id, "build": build }),
    )
}

/// `POST engagement/continuations/unlink`: take one link off both pages.
fn continuations_unlink(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let Some(link) = body["id"].as_str().map(str::to_string) else {
        return Response::error(422, "Name the link");
    };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    if !retention_admin(&sources, session) {
        return continuation_denied();
    }
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match continuations_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let mut file = match load_continuations(&path) {
        Ok(file) => file,
        Err(response) => return response,
    };
    if !file.remove(&link) {
        return Response::error(404, "No such link");
    }
    if let Err(response) = write_continuations(&path, &file) {
        return response;
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    Response::json(200, &json!({ "unlinked": true, "build": build }))
}

/// `POST engagement/continuations/sweep`: drop every link whose submission the
/// hosted service says is no longer approved, such as one its reader withdrew.
/// A submission the hosted service could not be asked about is kept.
fn continuations_sweep(state: &AppState, session: &auth::Session) -> Response {
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    if !retention_admin(&sources, session) {
        return continuation_denied();
    }
    let path = match continuations_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let origins: std::collections::BTreeSet<String> = match load_continuations(&path) {
        Ok(file) => file.items.iter().map(|edge| edge.origin.clone()).collect(),
        Err(response) => return response,
    };
    let gone = origins_no_longer_approved(origins, |origin| {
        hosted_standing(
            hosted_inbox_lookup(state, moderation_inbox::Source::Feedback, origin)
                .map(|found| found.map(|(_, _, item)| item.state)),
        )
    });
    let mut dropped = 0;
    let mut build = Json::Null;
    let mut error = None;
    for origin in &gone {
        let (count, rebuilt, failed) = forget_continuations(state, origin);
        dropped += count;
        if let Some(rebuilt) = rebuilt {
            build = rebuilt;
        }
        error = error.or(failed);
    }
    Response::json(
        200,
        &json!({ "dropped": dropped, "build": build, "error": error }),
    )
}

/// The words the moderator gets when a submission's continuation links could
/// not be taken off (ADR 0221): the decision stands, the link may still show.
const CONTINUATIONS_NOT_DROPPED: &str = "The submission's continuation links could not be removed, so a link may still show on the pages. Run \"Check for withdrawn submissions\" or remove the link by hand.";

/// Drop every link of a submission that is removed, withdrawn or deleted, and
/// rebuild when any went (ADR 0221). Returns how many went, the build, and a
/// plain message when the links could not be dropped (the content could not be
/// locked, or the file could not be read or written). The moderation decision
/// stands in that case, the message reaches the moderator, and the sweep route
/// finishes the job.
fn forget_continuations(
    state: &AppState,
    origin: &str,
) -> (usize, Option<Json>, Option<&'static str>) {
    let Ok(path) = continuations_path(state) else {
        eprintln!("admin: continuations.json could not be located to drop the links of {origin}");
        return (0, None, Some(CONTINUATIONS_NOT_DROPPED));
    };
    if !path.exists() {
        return (0, None, None);
    }
    let mut status = lock(&state.build);
    let Ok(_transaction) = content_transaction(state) else {
        eprintln!("admin: the content could not be locked to drop the links of {origin}");
        return (0, None, Some(CONTINUATIONS_NOT_DROPPED));
    };
    let mut file = match load_continuations(&path) {
        Ok(file) => file,
        Err(_) => {
            eprintln!("admin: continuations.json could not be read to drop the links of {origin}");
            return (0, None, Some(CONTINUATIONS_NOT_DROPPED));
        }
    };
    let count = file.forget_origin(origin);
    if count == 0 {
        return (0, None, None);
    }
    if write_continuations(&path, &file).is_err() {
        eprintln!("admin: continuations.json could not be written to drop the links of {origin}");
        return (0, None, Some(CONTINUATIONS_NOT_DROPPED));
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    (count, Some(build), None)
}

// ---- Suggestions for future work (RD13)

/// The id a note made from a suggestion gets when the author names none: the
/// start of the hosted item's id, which names no reader and no time.
fn suggestion_note_id(item_id: &str) -> String {
    let short: String = item_id
        .chars()
        .filter(char::is_ascii_hexdigit)
        .take(8)
        .collect();
    format!("suggestion-{short}")
}

/// `POST engagement/suggestions/export`: the author's own, explicit copy of
/// one accepted suggestion into a note of the private research notebook
/// (RD13, ADR 0157). The request names the item and the version the author
/// saw; the item is read again from the hosted store, the one view and grant
/// rules decide whether this account may act on it (the site Admin or a
/// coordinator of its work, on an accepted suggestion still kept), and the
/// note is the draft the core builds: labelled unverified reader text and
/// where it came from, with no name, no contact and no time. Nothing is
/// fetched, nothing is published and the hosted suggestion is not changed, so
/// a refusal or a failed write leaves both exactly as they were.
fn export_suggestion_to_research(
    state: &AppState,
    req: &Request,
    session: &auth::Session,
) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let Some(version) = body["version"]
        .as_u64()
        .filter(|version| (1..=i32::MAX as u64).contains(version))
    else {
        return Response::error(422, "Send the suggestion's version as you loaded it");
    };
    let note_id = match &body["noteId"] {
        Json::Null => None,
        Json::String(note_id) if openblog_core::knowledge_atlas::valid_id(note_id) => {
            Some(note_id.clone())
        }
        _ => {
            return Response::error(
                422,
                "Name the note with a lowercase slug of at most 64 characters",
            )
        }
    };
    let (protocol, third_perspectives, item) =
        match hosted_inbox_item(state, moderation_inbox::Source::Feedback, &id) {
            Ok(found) => found,
            Err(response) => return response,
        };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    export_suggestion_with(
        state,
        &sources,
        session,
        protocol,
        third_perspectives,
        &item,
        version,
        note_id,
    )
}

/// The export once the hosted item is read: everything that decides it, apart
/// from reaching the hosted function.
#[allow(clippy::too_many_arguments)]
fn export_suggestion_with(
    state: &AppState,
    sources: &InboxSources,
    session: &auth::Session,
    protocol: moderation_inbox::Protocol,
    third_perspectives: bool,
    item: &moderation_inbox::InboxItem,
    version: u64,
    note_id: Option<String>,
) -> Response {
    let id = item.id.clone();
    if item.suggestion().is_none() {
        return Response::error(404, "No such suggestion");
    }
    let published = published_feedback_file(state);
    let perspectives = published_perspectives_file(state);
    let (draft, view) = sources.inbox(session, protocol, third_perspectives, |inbox| {
        (
            inbox.research_draft(item),
            inbox_view(inbox, item, published.as_ref(), perspectives.as_ref()),
        )
    });
    let draft = match draft {
        Ok(draft) => draft,
        Err(openblog_core::future_suggestion::ConversionError::Denied) => {
            return Response::json(
                403,
                &json!({ "error": "You cannot copy this suggestion into your research.", "code": "denied" }),
            )
        }
        Err(openblog_core::future_suggestion::ConversionError::WrongKind) => {
            return Response::error(404, "No such suggestion")
        }
        Err(error) => {
            return Response::json(
                422,
                &json!({ "error": format!("{}.", capitalize(&error.to_string())), "code": error.code() }),
            )
        }
    };
    if item.version != version {
        return Response::json(
            409,
            &json!({ "error": INBOX_CHANGED, "code": "conflict", "item": view }),
        );
    }
    let note_id = note_id.unwrap_or_else(|| suggestion_note_id(&item.id));
    let note = match ResearchNote::from_json(json!({
        "id": note_id,
        "kind": if draft.question { "question" } else { "observation" },
        "text": draft.text,
        "visibility": "private",
    })) {
        Ok(note) => note,
        Err(diagnostics) => return notebook_diagnostics(diagnostics),
    };
    let contributors = source_contributors(state);
    let snapshot = match notebook_store::load(&state.root, &contributors) {
        Ok(snapshot) => snapshot,
        Err(error) => return notebook_store_error(state, error, None),
    };
    match notebook_store::create_note(&state.root, &snapshot.revision, note, &contributors) {
        Ok(saved) => {
            eprintln!(
                "admin: suggestion {id} copied into research note {note_id} by {}",
                session.user
            );
            Response::json(
                201,
                &json!({
                    "ok": true,
                    "note": { "id": note_id },
                    "revision": saved.revision,
                    "item": view,
                }),
            )
        }
        Err(error) => notebook_store_error(state, error, Some((false, &note_id))),
    }
}

/// `POST engagement/suggestions/link`: the author's own, explicit record that
/// an accepted suggestion became, or is becoming, future work they made: a
/// draft or series by its slug, or a Source Library record by its id (RD13,
/// ADRs 0157 and 0162). The request names the item, the version the author
/// saw and the target; the item is read again from the hosted store, the one
/// grant rule decides whether this account may act on it (the site Admin or a
/// coordinator of its work, on an accepted suggestion still kept), and the
/// hosted function decides again from its stored row and keeps the link in
/// the row's details with a private audit event. Nothing is created, fetched,
/// published or sent: the draft, series or source must already be the
/// author's own, and none of them is read, opened or checked.
fn link_suggestion_to_future_work(
    state: &AppState,
    req: &Request,
    session: &auth::Session,
) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let Some(version) = body["version"]
        .as_u64()
        .filter(|version| (1..=i32::MAX as u64).contains(version))
    else {
        return Response::error(422, "Send the suggestion's version as you loaded it");
    };
    let (Some(kind), Some(target)) = (
        body["conversion"]["kind"]
            .as_str()
            .and_then(openblog_core::future_suggestion::ConversionKind::from_id),
        body["conversion"]["id"].as_str(),
    ) else {
        return Response::json(
            422,
            &json!({ "error": "Choose what it was linked to and name it.", "code": "invalidTarget" }),
        );
    };
    let (protocol, third_perspectives, item) =
        match hosted_inbox_item(state, moderation_inbox::Source::Feedback, &id) {
            Ok(found) => found,
            Err(response) => return response,
        };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    link_suggestion_with(
        state,
        &sources,
        session,
        protocol,
        third_perspectives,
        &item,
        version,
        kind,
        target,
        |request| hosted_moderation_call(state, &[], Some(request)),
    )
}

/// The link once the hosted item is read: everything that decides it, and
/// the one hosted call, which a test replaces.
#[allow(clippy::too_many_arguments)]
fn link_suggestion_with(
    state: &AppState,
    sources: &InboxSources,
    session: &auth::Session,
    protocol: moderation_inbox::Protocol,
    third_perspectives: bool,
    item: &moderation_inbox::InboxItem,
    version: u64,
    kind: openblog_core::future_suggestion::ConversionKind,
    target: &str,
    hosted: impl FnOnce(&Json) -> Result<(u16, Json), Response>,
) -> Response {
    let id = item.id.clone();
    let published = published_feedback_file(state);
    let perspectives = published_perspectives_file(state);
    let (link, view, role) = sources.inbox(session, protocol, third_perspectives, |inbox| {
        (
            // A request made against an older version of the item is stale
            // whatever the link is, so it is answered before the link is
            // judged: the author reloads and sees what changed.
            (item.version == version).then(|| inbox.link_to_future_work(item, kind, target)),
            inbox_view(inbox, item, published.as_ref(), perspectives.as_ref()),
            inbox.actor(item).role(),
        )
    });
    let Some(link) = link else {
        return Response::json(
            409,
            &json!({ "error": INBOX_CHANGED, "code": "conflict", "item": view }),
        );
    };
    let link = match link {
        Ok(link) => link,
        Err(openblog_core::future_suggestion::ConversionError::Denied) => {
            return Response::json(
                403,
                &json!({ "error": "You cannot link this suggestion to future work.", "code": "denied" }),
            )
        }
        Err(openblog_core::future_suggestion::ConversionError::WrongKind) => {
            return Response::error(404, "No such suggestion")
        }
        Err(error) => {
            return Response::json(
                422,
                &json!({ "error": format!("{}.", capitalize(&error.to_string())), "code": error.code() }),
            )
        }
    };
    let request = json!({
        "source": "feedback",
        "id": id,
        "action": "convert",
        "from": item.state.id(),
        "expectedVersion": version,
        "actor": session.user,
        "actorRole": role.id(),
        "conversion": { "kind": link.kind.id(), "id": link.id },
    });
    let reread = |value: &Json| moderation_inbox::InboxItem::from_value(&value["item"]).ok();
    let changed = match hosted(&request) {
        Ok((200, value)) => match reread(&value) {
            Some(changed)
                if changed.id == id
                    && changed.state == item.state
                    && changed.suggestion().is_some_and(|suggestion| {
                        suggestion
                            .conversions
                            .iter()
                            .any(|stored| stored.kind == link.kind && stored.id == link.id)
                    }) =>
            {
                changed
            }
            _ => {
                return Response::error(
                    502,
                    "hosted engagement returned an invalid moderation response",
                )
            }
        },
        Ok((409, value)) => {
            let current = reread(&value).and_then(|current| {
                sources.inbox(session, protocol, third_perspectives, |inbox| {
                    inbox_view(inbox, &current, published.as_ref(), perspectives.as_ref())
                })
            });
            return Response::json(
                409,
                &json!({ "error": INBOX_CHANGED, "code": "conflict", "item": current }),
            );
        }
        Ok((403, _)) => {
            return Response::json(
                403,
                &json!({ "error": "You cannot link this suggestion to future work.", "code": "denied" }),
            )
        }
        // A refusal the hosted rules gave (a suggestion that is not accepted,
        // a full list, a link made twice) keeps its own code, so the author
        // is told why instead of being sent to a missing page.
        Ok((422, value)) => {
            let code = value["code"]
                .as_str()
                .filter(|code| {
                    (1..=32).contains(&code.len()) && code.bytes().all(|b| b.is_ascii_alphabetic())
                })
                .unwrap_or("invalid");
            return Response::json(
                422,
                &json!({ "error": "This link is not allowed.", "code": code }),
            );
        }
        Ok(_) => return Response::error(404, "No such suggestion"),
        Err(response) => return response,
    };
    eprintln!(
        "admin: suggestion {id} linked to a {} by {} as {}",
        link.kind.id(),
        session.user,
        role.id()
    );
    let view = sources.inbox(session, protocol, third_perspectives, |inbox| {
        inbox_view(inbox, &changed, published.as_ref(), perspectives.as_ref())
    });
    Response::json(
        200,
        &json!({
            "ok": true,
            "item": view,
            "published": false,
        }),
    )
}

// ---- Correction decisions (ADR 0117)
//
// The author's decision about what a reader's suggested source or correction
// meant for the work, recorded from the Moderation inbox beside moderation,
// never instead of it. Admin decides it with the one policy and this
// account's role on the item's work, checks it against the post's own
// revision notes and the claims file, and the hosted function checks it
// again from the stored row before appending it to the item's log with an
// audit event. A decision never edits a post, a citation, a claim or the
// Source Library: revision notes and evidence links are recorded first,
// with their own tools, and the decision points at them. Nothing is
// e-mailed to anyone.

/// What a decision needs that only this server holds: the post's
/// `evidenceRevisions` items exactly as written, and the claims file.
fn post_revision_items(state: &AppState, post: &str) -> Result<Vec<String>, String> {
    let config = site::load_config(&state.root)?;
    let path = resolve_content_path(&state.root, &config, post)?;
    let source = fs::read_to_string(&path).map_err(|_| "No such post".to_string())?;
    let document = frontmatter::parse(&source)?;
    Ok(
        match document
            .front_matter
            .fields
            .get(openblog_core::claim_publication::REVISIONS_FIELD)
        {
            Some(Value::List(items)) => items.clone(),
            Some(Value::Scalar(item)) if !item.trim().is_empty() => vec![item.clone()],
            _ => Vec::new(),
        },
    )
}

/// The decision form's choices that only this server can list, added to the
/// items of an inbox page that offer "Record decision": the post's revision
/// notes as written, and the evidence links in the claims file on the post's
/// claims. Both are recorded with their own tools; the form only points at
/// them.
fn add_decision_choices(state: &AppState, published: &Site, items: &mut [Json]) {
    let offered = |item: &Json| item["recordDecision"].is_object();
    if !items.iter().any(offered) {
        return;
    }
    let claims = claims_store::load(&state.root, &source_contributors(state))
        .ok()
        .map(|snapshot| snapshot.claims);
    let mut notes: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for item in items.iter_mut().filter(|item| offered(item)) {
        let Some(post) = item["recordDecision"]["post"].as_str().map(str::to_string) else {
            item["recordDecision"]["revisionNotes"] = json!([]);
            item["recordDecision"]["claimEvidence"] = json!([]);
            continue;
        };
        let items_of = notes
            .entry(post.clone())
            .or_insert_with(|| post_revision_items(state, &post).unwrap_or_default());
        item["recordDecision"]["revisionNotes"] = json!(items_of);
        let slug = published
            .posts
            .iter()
            .find(|candidate| candidate.source.replace('\\', "/") == post)
            .map(|candidate| candidate.slug.as_str());
        let links: Vec<Json> = match (&claims, slug) {
            (Some(set), Some(slug)) => set
                .claims
                .iter()
                .filter(|claim| claim.post == slug)
                .flat_map(|claim| {
                    set.links_of(&claim.id)
                        .filter(|link| set.is_projected(link))
                        .map(move |link| {
                        json!({
                            "claim": claim.id,
                            "link": link.id,
                            "label": format!("{} → {} ({}, {})", claim.id, link.id, link.relation.as_str(), link.evidence.source),
                        })
                    })
                })
                .collect(),
            _ => Vec::new(),
        };
        item["recordDecision"]["claimEvidence"] = Json::Array(links);
    }
}

/// A decision request's content, read strictly: ids from their closed lists,
/// links as `{post, note}` and `{claim, link}`, and text as given (the policy
/// trims and bounds it).
fn decision_content(
    body: &Json,
) -> Result<openblog_core::correction_decision::DecisionContent, String> {
    use openblog_core::correction_decision::{
        ClaimEvidenceRef, DecisionContent, DecisionOutcome, DeclineReason, Extent, RevisionLink,
    };
    let text = |key: &str| -> Result<Option<String>, String> {
        match &body[key] {
            Json::Null => Ok(None),
            Json::String(value) if value.trim().is_empty() => Ok(None),
            Json::String(value) => Ok(Some(value.clone())),
            _ => Err(format!("`{key}` must be text")),
        }
    };
    let outcome = body["outcome"]
        .as_str()
        .and_then(DecisionOutcome::from_id)
        .ok_or("Choose what you decided")?;
    let extent = text("extent")?
        .map(|id| Extent::from_id(&id).ok_or("Choose all of it or part of it"))
        .transpose()?;
    let decline_reason = text("declineReason")?
        .map(|id| DeclineReason::from_id(&id).ok_or("Choose one of the listed reasons"))
        .transpose()?;
    let revision_note = match &body["revisionNote"] {
        Json::Null => None,
        value => Some(
            serde_json::from_value::<RevisionLink>(value.clone())
                .map_err(|_| "A revision note is the post and one of its notes")?,
        ),
    };
    let claim_evidence = match &body["claimEvidence"] {
        Json::Null => None,
        value => Some(
            serde_json::from_value::<ClaimEvidenceRef>(value.clone())
                .map_err(|_| "Claim evidence is a claim and one of its evidence links")?,
        ),
    };
    Ok(DecisionContent {
        outcome,
        extent,
        decline_reason,
        rationale: text("rationale")?,
        revision_note,
        claim_evidence,
        addressed_by: text("addressedBy")?,
    })
}

/// Whether the text revision the author read is the item's now. A
/// clarification the reader answered raises it, and a decision is only ever
/// about the text its author saw.
fn decision_revision_is_current(seen: u64, current: u32) -> bool {
    seen == u64::from(current)
}

/// Whether the hosted function refused a decision because the item changed
/// under the author (stale, closed, or awaiting the reader's answer), as
/// opposed to refusing its content.
fn hosted_decision_changed(response: &Response) -> bool {
    serde_json::from_slice::<Json>(&response.body)
        .ok()
        .and_then(|body| body["code"].as_str().map(str::to_string))
        .is_some_and(|code| {
            matches!(
                code.as_str(),
                "stale" | "itemClosed" | "awaitingClarification"
            )
        })
}

/// `POST engagement/moderation/decision`: record the author's correction
/// decision on one suggested source or correction. The request names the
/// item, how many decisions on it the author saw, the outcome and what it
/// rests on, the passage check the author read when the passage moved, and
/// the author's local day. Who is deciding comes from the session.
fn record_correction_decision(
    state: &AppState,
    req: &Request,
    session: &auth::Session,
) -> Response {
    use openblog_core::correction_decision::{passage_check_from_id, DecisionErrorCode};
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let Some(expected) = body["expectedDecisions"]
        .as_u64()
        .filter(|count| *count <= 1000)
    else {
        return Response::error(422, "Send how many decisions you saw on the item");
    };
    // The text revision the author read: a decision is about that text, so a
    // clarification that changed it since makes the request stale.
    let Some(seen_revision) = body["itemRevision"]
        .as_u64()
        .filter(|revision| (1..=u64::from(u32::MAX)).contains(revision))
    else {
        return Response::error(422, "Send the revision of the item’s text you read");
    };
    let content = match decision_content(&body) {
        Ok(content) => content,
        Err(error) => return Response::json(422, &json!({ "error": error, "code": "malformed" })),
    };
    let confirmed_check = match body["confirmCheck"].as_str() {
        None => None,
        Some(id) => match passage_check_from_id(id) {
            Some(check) => Some(check),
            None => return Response::error(422, "Send the passage check you read"),
        },
    };
    let Some(decided) = body["decided"].as_str() else {
        return Response::error(422, "Send the day of the decision");
    };
    // The author's local day: never more than a day ahead of this server's
    // UTC day, since UTC offsets span at most one day.
    let latest = DateTime::from_unix(clock::now().unix() + 86_400).ymd();
    if decided > latest.as_str() {
        return Response::json(
            422,
            &json!({ "error": "A decision cannot be dated in the future.", "code": "invalidDay" }),
        );
    }
    let (protocol, third_perspectives, item) =
        match hosted_inbox_item(state, moderation_inbox::Source::Feedback, &id) {
            Ok(found) => found,
            Err(response) => return response,
        };
    if item
        .feedback()
        .is_none_or(|hosted| hosted.decisions.is_none())
    {
        return Response::json(
            422,
            &json!({ "error": "The hosted service does not store correction decisions yet: run supabase/feedback.sql again and set OPENBLOG_CORRECTIONS_ENABLED=true.", "code": "unavailable" }),
        );
    }
    // The item another decision addressed, read again, and only on the same
    // post: an item elsewhere never confirms or denies anything.
    let addressed = match &content.addressed_by {
        Some(other) => {
            match hosted_inbox_item(
                state,
                moderation_inbox::Source::Feedback,
                &other.to_ascii_lowercase(),
            ) {
                Ok((_, _, other)) if other.work == item.work => other
                    .feedback()
                    .and_then(|hosted| hosted.decisions.clone())
                    .map(|log| (log, other.revision)),
                _ => None,
            }
        }
        _ => None,
    };
    let sources = match inbox_sources(state) {
        Ok(sources) => sources,
        Err(response) => return response,
    };
    let published = published_feedback_file(state);
    let perspectives = published_perspectives_file(state);
    let conflict_with = |current: &moderation_inbox::InboxItem| {
        let view = sources.inbox(session, protocol, third_perspectives, |inbox| {
            inbox_view(inbox, current, published.as_ref(), perspectives.as_ref())
        });
        let mut views: Vec<Json> = view.into_iter().collect();
        add_decision_choices(state, &sources.published, &mut views);
        Response::json(
            409,
            &json!({ "error": "Someone decided on this item, or it changed, since you loaded it. Review it again before deciding.", "code": "conflict", "item": views.pop() }),
        )
    };
    if !decision_revision_is_current(seen_revision, item.revision) {
        return conflict_with(&item);
    }
    let decided_now = sources.inbox(session, protocol, third_perspectives, |inbox| {
        let view = inbox_view(inbox, &item, published.as_ref(), perspectives.as_ref());
        let role = inbox.actor(&item).role();
        let decision = inbox.record_decision(
            &item,
            moderation_inbox::DecisionDraft {
                expected_decisions: expected as u32,
                content: content.clone(),
                confirmed_check,
                decided,
            },
            addressed.as_ref().map(|(log, revision)| (log, *revision)),
        );
        (view, role, decision)
    });
    let (_, role, decision) = decided_now;
    let refused =
        |code: &str, message: &str| Response::json(422, &json!({ "error": message, "code": code }));
    let decision = match decision {
        Ok(decision) => decision,
        Err(error) if error.code == DecisionErrorCode::Denied => {
            return Response::json(
                403,
                &json!({ "error": "You cannot record a correction decision on this item.", "code": "denied" }),
            )
        }
        Err(error) if error.code == DecisionErrorCode::Stale => return conflict_with(&item),
        Err(error) => {
            let code = serde_json::to_value(error.code)
                .ok()
                .and_then(|code| code.as_str().map(str::to_string))
                .unwrap_or_default();
            return refused(&code, &format!("{}.", capitalize(&error.message)));
        }
    };
    // What only this server can check: the note is in the post's front
    // matter, and the evidence link is in the claims file on a claim of
    // this post. Both are recorded first, with their own tools.
    let status = lock(&state.build);
    let transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    if let Some(link) = &decision.content.revision_note {
        match post_revision_items(state, &link.post) {
            Ok(items) if link.found_in(&items) => {}
            _ => {
                return refused(
                    "revisionNoteNotFound",
                    "The post’s revision notes do not hold that note. Add it to the post first, then choose it.",
                )
            }
        }
    }
    if let Some(evidence) = &decision.content.claim_evidence {
        let snapshot = match claims_store::load(&state.root, &source_contributors(state)) {
            Ok(snapshot) => snapshot,
            Err(_) => {
                return refused(
                    "unknownClaimEvidence",
                    "The claims file cannot be read, so the evidence link cannot be checked.",
                )
            }
        };
        if let Err(error) = evidence.check(&snapshot.claims) {
            let code = serde_json::to_value(error.code)
                .ok()
                .and_then(|code| code.as_str().map(str::to_string))
                .unwrap_or_default();
            return refused(&code, &format!("{}.", capitalize(&error.message)));
        }
        let slug = moderation_inbox::InboxItem::facts(&item)
            .work
            .and_then(|work| feedback_moderation::post_for_work(&sources.published, work))
            .map(|post| post.slug.clone());
        let claim_post = snapshot
            .claims
            .claim(&evidence.claim)
            .map(|claim| claim.post.clone());
        // An item whose post is unknown can link no claim: nothing says the
        // claim is about the same post.
        if slug.is_none() || claim_post != slug {
            return refused(
                "claimElsewhere",
                "That evidence link is on a claim of another post.",
            );
        }
    }
    // The hosted call is slow and can fail: the lock is for reading the post
    // and the claims only.
    drop(transaction);
    drop(status);
    let request = json!({
        "id": id,
        "expectedDecisions": expected,
        "actor": session.user,
        "actorRole": role.id(),
        "decision": decision.to_value(),
    });
    let reread = |value: &Json| moderation_inbox::InboxItem::from_value(&value["item"]).ok();
    let changed = match hosted_inbox_request(
        state,
        "admin/decisions",
        &[],
        Some(("POST", &request)),
    ) {
        Ok((200, value)) => match reread(&value) {
            Some(changed)
                if changed.id == id
                    && changed.state == item.state
                    && changed
                        .feedback()
                        .and_then(|hosted| hosted.decisions.as_ref())
                        .and_then(|log| log.current())
                        == Some(&decision) =>
            {
                changed
            }
            _ => {
                return Response::error(
                    502,
                    "hosted engagement returned an invalid decision response",
                )
            }
        },
        Ok((409, value)) => {
            return match reread(&value) {
                Some(current) => conflict_with(&current),
                None => conflict_with(&item),
            };
        }
        Ok((403, _)) => {
            return Response::json(
                403,
                &json!({ "error": "You cannot record a correction decision on this item.", "code": "denied" }),
            )
        }
        Ok((404, _)) => return Response::error(404, "No such item"),
        Ok(_) => return Response::error(502, "Hosted engagement returned an unexpected answer"),
        Err(response) if response.status == 422 && hosted_decision_changed(&response) => {
            // The item closed, or a clarification was asked, between Admin's
            // read and the hosted one: read it again and say it changed.
            return match hosted_inbox_item(state, moderation_inbox::Source::Feedback, &id) {
                Ok((_, _, current)) => conflict_with(&current),
                Err(response) => response,
            };
        }
        Err(response) => return response,
    };
    eprintln!(
        "admin: correction decision on feedback {id}: {} by {} as {}",
        decision.content.outcome.id(),
        session.user,
        role.id()
    );
    // An item already on its post shows the author's outcome there now; one that is not stays
    // unpublished, because a decision never publishes a note.
    let (outcome_published, outcome_error, build) = match publish_decision_outcome(state, &changed)
    {
        Ok(Some(build)) => (true, None, Some(build)),
        Ok(None) => (false, None, None),
        Err(error) => (false, Some(error), None),
    };
    let published = published_feedback_file(state);
    let view = sources.inbox(session, protocol, third_perspectives, |inbox| {
        inbox_view(inbox, &changed, published.as_ref(), perspectives.as_ref())
    });
    let mut views: Vec<Json> = view.into_iter().collect();
    add_decision_choices(state, &sources.published, &mut views);
    Response::json(
        200,
        &json!({
            "item": views.pop(),
            "decision": {
                "outcome": decision.content.outcome.id(),
                "label": decision.content.outcome.label(),
                "sequence": decision.sequence,
            },
            "outcomePublished": outcome_published,
            "publishError": outcome_error,
            "build": build,
        }),
    )
}

/// Whether the hosted function stored `to`: exactly, or, for a comment
/// under the older schema, as the `status` value ADR 0102 maps it to (a
/// removed comment is stored as rejected).
fn stored_as(
    protocol: moderation_inbox::Protocol,
    changed: &moderation_inbox::InboxItem,
    to: ModerationState,
) -> bool {
    changed.state == to
        || (protocol == moderation_inbox::Protocol::Legacy
            && changed.source == moderation_inbox::Source::Comment
            && changed.state.id() == to.legacy_comment_status())
}

fn capitalize(text: &str) -> String {
    let mut chars = text.chars();
    chars.next().map_or_else(String::new, |first| {
        first.to_uppercase().chain(chars).collect()
    })
}

/// `POST engagement/feedback/publish`: put an approved item on its post
/// again, after a failed write or an approval made outside Admin.
fn publish_feedback(state: &AppState, req: &Request) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    // Read through the inbox, which carries the decisions: a note put on its post again after a
    // failed write carries the author's decision with it.
    let item = match hosted_inbox_item(state, moderation_inbox::Source::Feedback, &id) {
        Ok((_, _, item)) => item,
        Err(response) => return response,
    };
    let Some(item) = item.feedback() else {
        return Response::error(404, "No such feedback item");
    };
    let site = match feedback_site(state) {
        Ok(site) => site,
        Err(response) => return response,
    };
    let claims = claims_for_publication(state);
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match reader_feedback_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    if let Err(error) = publish_approved_feedback(&path, &site, item, claims.as_ref()) {
        return Response::error(409, &error);
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!("admin: feedback {id} published");
    Response::json(200, &json!({ "published": true, "build": build }))
}

/// `POST engagement/feedback/publish-decision`: make the decision published with an approved note
/// the one in force, after a decision whose file write failed (ADR 0119).
fn update_published_decision(state: &AppState, req: &Request) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let item = match hosted_inbox_item(state, moderation_inbox::Source::Feedback, &id) {
        Ok((_, _, item)) => item,
        Err(response) => return response,
    };
    match publish_decision_outcome(state, &item) {
        Ok(Some(build)) => {
            eprintln!("admin: published decision of feedback {id} updated");
            Response::json(200, &json!({ "published": true, "build": build }))
        }
        Ok(None) => Response::error(
            409,
            "The note is not published, or its decision cannot be published now",
        ),
        Err(error) => Response::error(409, &error),
    }
}

/// `POST engagement/feedback/unpublish`: take a removed or rejected item off
/// its post again, after a removal whose file write failed or a decision made
/// outside Admin.
fn unpublish_moderated(state: &AppState, req: &Request) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let item = match hosted_feedback_item(state, &id) {
        Ok(item) => item,
        Err(response) => return response,
    };
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match reader_feedback_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    if let Err(error) = unpublish_moderated_feedback(&path, &item) {
        return Response::error(409, &error);
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!("admin: feedback {id} unpublished");
    Response::json(200, &json!({ "published": false, "build": build }))
}

/// Every note the site publishes, each as its post shows it now, with the
/// file's revision for conflict-safe responses.
fn published_feedback_view(
    file: &feedback_publication::ReaderFeedbackFile,
    etag: &str,
    site: &Site,
) -> Json {
    let mut items = Vec::with_capacity(file.items.len());
    for item in &file.items {
        let post = site
            .posts
            .iter()
            .find(|post| post.source.replace('\\', "/") == item.post);
        let public = post.and_then(|post| {
            let document = PassageDocument::of_post(post, &site.config);
            feedback_publication::project(&[item], post, &document, site.config.engagement.evidence)
                .pop()
        });
        items.push(json!({
            "id": item.id,
            "post": item.post,
            "postTitle": post.map(|post| post.title.clone()),
            "postUrl": post.map(|post| post.url.clone()),
            "kind": item.kind.id(),
            "kindLabel": item.kind.label(),
            "body": item.body,
            "received": item.received,
            "approved": item.approved,
            "name": item.name,
            "response": item.response,
            "public": public,
        }));
    }
    json!({ "etag": etag, "items": items })
}

/// `GET engagement/feedback/published`: the notes the site publishes. Needs
/// no hosted service.
fn published_feedback(state: &AppState) -> Response {
    let path = match reader_feedback_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let (file, etag) = match load_reader_feedback(&path) {
        Ok(loaded) => loaded,
        Err(response) => return response,
    };
    let site = match site::load_site(&state.root, true, Some(clock::now())) {
        Ok((site, _)) => site,
        Err(error) => return Response::error(500, &error),
    };
    Response::json(200, &published_feedback_view(&file, &etag, &site))
}

/// `PUT engagement/feedback/response`: set or clear the author's public
/// response to a published note. The request names the file revision it
/// loaded; a file changed since is a conflict and nothing is written.
fn respond_to_feedback(state: &AppState, req: &Request) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let id = match feedback_id(&body["id"]) {
        Ok(id) => id,
        Err(response) => return response,
    };
    let Some(sent) = body["etag"].as_str() else {
        return Response::error(
            422,
            "Send the revision of the published feedback you loaded",
        );
    };
    let response_text = match &body["response"] {
        Json::Null => None,
        Json::String(text) => Some(text.as_str()),
        _ => return Response::error(422, "A response is text"),
    };
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = match reader_feedback_path(state) {
        Ok(path) => path,
        Err(response) => return response,
    };
    let (mut file, current) = match load_reader_feedback(&path) {
        Ok(loaded) => loaded,
        Err(response) => return response,
    };
    if current != sent {
        return Response::error(
            409,
            "The published feedback changed since you loaded it. Reload before responding.",
        );
    }
    if let Err(error) = file.respond(&id, response_text, clock::now()) {
        return Response::error(422, &error);
    }
    let etag = match write_reader_feedback(&path, &file) {
        Ok(etag) => etag,
        Err(error) => return Response::error(500, &error),
    };
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!("admin: feedback {id} response saved");
    Response::json(
        200,
        &json!({ "etag": etag, "response": file.get(&id).and_then(|item| item.response.clone()), "build": build }),
    )
}

/// `POST engagement/feedback/revision-note`: record a public revision note in
/// a post's `evidenceRevisions` front matter (ADR 0075), the author's own
/// words about what changed. It never edits the post's text; accepting a
/// suggestion stays a separate edit.
fn record_revision_note(state: &AppState, req: &Request) -> Response {
    let body = match feedback_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let Some(rel) = body["post"].as_str() else {
        return Response::error(422, "Name the post the note is about");
    };
    if check_rel_path(rel) != Ok("posts") {
        return Response::error(422, "Revision notes belong to posts");
    }
    let note = match revision_note_item(
        body["date"].as_str(),
        body["claim"].as_str(),
        body["note"].as_str().unwrap_or(""),
        clock::now(),
    ) {
        Ok(note) => note,
        Err(error) => return Response::error(422, &error),
    };
    let mut status = lock(&state.build);
    let _transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let config = match site::load_config(&state.root) {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    let path = match resolve_content_path(&state.root, &config, rel) {
        Ok(path) => path,
        Err(error) => return Response::error(400, &error),
    };
    let current = match fs::read_to_string(&path) {
        Ok(current) => current,
        Err(_) => return Response::error(404, "No such post"),
    };
    let source = match with_revision_note(&current, note) {
        Ok(source) => source,
        Err(error) => return Response::error(422, &format!("{rel}: {error}")),
    };
    if let Err(problems) =
        validate_candidate(&state.root, &config, rel, &source, &CreditEdit::Unchanged)
    {
        return Response::json(
            422,
            &json!({ "error": "The note can't be added to this post yet.", "problems": problems }),
        );
    }
    if let Err(error) = write_atomic(&path, &source) {
        return Response::error(500, &error);
    }
    let build = feedback_build_json(&state.rebuild_locked(&mut status));
    eprintln!("admin: revision note added to {rel}");
    Response::json(
        200,
        &json!({ "post": rel, "etag": etag(&source), "build": build }),
    )
}

/// One `evidenceRevisions` item, `YYYY-MM-DD[ claim-id]: what changed`,
/// checked with the build's rules. The date defaults to today.
fn revision_note_item(
    date: Option<&str>,
    claim: Option<&str>,
    note: &str,
    today: DateTime,
) -> Result<String, String> {
    let date = date
        .map(str::trim)
        .filter(|date| !date.is_empty())
        .map_or_else(|| today.ymd(), str::to_string);
    let note = note.trim();
    if note.contains(['\n', '\r']) {
        return Err("Keep a revision note to one line".into());
    }
    let item = match claim.map(str::trim).filter(|claim| !claim.is_empty()) {
        Some(claim) => format!("{date} {claim}: {note}"),
        None => format!("{date}: {note}"),
    };
    openblog_core::claim_publication::revision_notes(std::slice::from_ref(&item))
        .map_err(|error| error.replace("item 1: ", ""))?;
    Ok(item)
}

/// A post's source with one more revision note, every other field and the
/// body kept. The whole list is checked again, so a note is never added to a
/// list the build would refuse.
fn with_revision_note(source: &str, note: String) -> Result<String, String> {
    let document = frontmatter::parse(source)?;
    let mut fields = document.front_matter.fields.clone();
    let field = openblog_core::claim_publication::REVISIONS_FIELD;
    let mut items = match fields.get(field) {
        Some(Value::List(items)) => items.clone(),
        Some(Value::Scalar(item)) if !item.trim().is_empty() => vec![item.clone()],
        _ => Vec::new(),
    };
    items.push(note);
    openblog_core::claim_publication::revision_notes(&items)?;
    fields.insert(field.to_string(), Value::List(items));
    Ok(frontmatter::compose(&fields, &document.body))
}

struct ProjectSkillFile {
    filename: String,
    source: String,
    etag: String,
    parsed: Result<SkillDefinition, Vec<String>>,
}

fn assistant_skills_dir(root: &Path, create: bool) -> Result<PathBuf, String> {
    let skills = crate::assistant_storage::contained_target(root, Path::new("assistant/skills"))?;
    if create {
        fs::create_dir_all(&skills)
            .map_err(|error| format!("cannot create {}: {error}", skills.display()))?;
    }
    Ok(skills)
}

fn read_project_skills(root: &Path) -> Result<Vec<ProjectSkillFile>, String> {
    let directory = assistant_skills_dir(root, false)?;
    if !directory.exists() {
        return Ok(Vec::new());
    }
    let mut paths = fs::read_dir(&directory)
        .map_err(|error| format!("cannot read {}: {error}", directory.display()))?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| path.extension().and_then(|value| value.to_str()) == Some("md"))
        .collect::<Vec<_>>();
    paths.sort();
    let mut files = Vec::new();
    for path in paths {
        let filename = path
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or("invalid.md")
            .to_string();
        if fs::symlink_metadata(&path).is_ok_and(|metadata| metadata.file_type().is_symlink()) {
            files.push(ProjectSkillFile {
                filename,
                source: String::new(),
                etag: String::new(),
                parsed: Err(vec![
                    "Replace this symlink with a regular Markdown skill file.".into(),
                ]),
            });
            continue;
        }
        let bytes =
            fs::read(&path).map_err(|error| format!("cannot read {}: {error}", path.display()))?;
        if bytes.len() > MAX_SKILL_BYTES {
            files.push(ProjectSkillFile {
                filename,
                source: String::new(),
                etag: etag_bytes(&bytes),
                parsed: Err(vec![format!(
                    "Reduce this skill below {MAX_SKILL_BYTES} bytes."
                )]),
            });
            continue;
        }
        let source = match String::from_utf8(bytes.clone()) {
            Ok(source) => source,
            Err(_) => {
                files.push(ProjectSkillFile {
                    filename,
                    source: String::new(),
                    etag: etag_bytes(&bytes),
                    parsed: Err(vec!["Save this skill as UTF-8 Markdown.".into()]),
                });
                continue;
            }
        };
        files.push(ProjectSkillFile {
            filename,
            etag: etag(&source),
            parsed: parse_skill(&source),
            source,
        });
    }
    Ok(files)
}

struct SkillSummaryState<'a> {
    source: &'a str,
    selectable: bool,
    override_state: &'a str,
    errors: Vec<String>,
    raw: Option<&'a str>,
    etag: Option<&'a str>,
    file_id: Option<&'a str>,
}

fn skill_summary(definition: &SkillDefinition, state: SkillSummaryState<'_>) -> Json {
    json!({
        "id": definition.id,
        "name": definition.name,
        "description": definition.description,
        "version": definition.version,
        "scopes": definition.scopes,
        "output": definition.output,
        "source": state.source,
        "valid": state.errors.is_empty(),
        "selectable": state.selectable && state.errors.is_empty(),
        "overrideState": state.override_state,
        "errors": state.errors,
        "raw": state.raw,
        "etag": state.etag,
        "fileId": state.file_id,
    })
}

fn builtin_skills() -> Vec<SkillDefinition> {
    BUILTIN_SKILL_SOURCES
        .iter()
        .map(|(id, source)| {
            let definition = parse_skill(source).expect("built-in assistant skills are valid");
            debug_assert_eq!(*id, definition.id);
            definition
        })
        .collect()
}

fn project_skill_id_counts(projects: &[ProjectSkillFile]) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for project in projects {
        if let Ok(skill) = &project.parsed {
            *counts.entry(skill.id.clone()).or_default() += 1;
        }
    }
    counts
}

fn active_project_skill<'a>(
    projects: &'a [ProjectSkillFile],
    id_counts: &BTreeMap<String, usize>,
    id: &str,
    overrides_builtin: bool,
) -> Result<Option<&'a SkillDefinition>, &'static str> {
    if id_counts.get(id).copied().unwrap_or_default() > 1 {
        return Err("A selected project skill ID is duplicated");
    }
    let Some((project, skill)) = projects.iter().find_map(|project| {
        let skill = project.parsed.as_ref().ok()?;
        (skill.id == id).then_some((project, skill))
    }) else {
        return Ok(None);
    };
    if project.filename.trim_end_matches(".md") != skill.id {
        return Ok(None);
    }
    if overrides_builtin && skill.override_builtin.as_deref() != Some(id) {
        return Err("A selected project skill does not explicitly override its built-in");
    }
    Ok(Some(skill))
}

fn assistant_skills(state: &AppState) -> Response {
    let builtins = builtin_skills();
    let projects = match read_project_skills(&state.root) {
        Ok(projects) => projects,
        Err(error) => return Response::error(500, &error),
    };
    let id_counts = project_skill_id_counts(&projects);
    let builtin_ids = builtins
        .iter()
        .map(|skill| skill.id.as_str())
        .collect::<Vec<_>>();
    let active_overrides = builtin_ids
        .iter()
        .filter_map(|id| {
            active_project_skill(&projects, &id_counts, id, true)
                .ok()
                .flatten()
        })
        .map(|skill| skill.id.as_str())
        .collect::<Vec<_>>();
    let mut items = builtins
        .iter()
        .map(|skill| {
            let overridden = active_overrides.contains(&skill.id.as_str());
            skill_summary(
                skill,
                SkillSummaryState {
                    source: "built-in",
                    selectable: !overridden,
                    override_state: if overridden { "overridden" } else { "none" },
                    errors: Vec::new(),
                    raw: None,
                    etag: None,
                    file_id: None,
                },
            )
        })
        .collect::<Vec<_>>();
    for project in projects {
        match project.parsed {
            Ok(skill) => {
                let mut errors = Vec::new();
                let file_id = project.filename.trim_end_matches(".md");
                if file_id != skill.id {
                    errors.push(format!(
                        "Change `id` to `{file_id}` so it matches the project skill filename."
                    ));
                }
                if id_counts.get(&skill.id).copied().unwrap_or_default() > 1 {
                    errors.push(format!(
                        "Project skill ID `{}` is declared more than once.",
                        skill.id
                    ));
                }
                let overrides_builtin = builtin_ids.contains(&skill.id.as_str());
                if overrides_builtin && skill.override_builtin.as_deref() != Some(skill.id.as_str())
                {
                    errors.push(format!(
                        "Add `override: {}` to explicitly replace the built-in skill.",
                        skill.id
                    ));
                }
                let active = overrides_builtin && errors.is_empty();
                items.push(skill_summary(
                    &skill,
                    SkillSummaryState {
                        source: "project",
                        selectable: true,
                        override_state: if active { "active" } else { "none" },
                        errors,
                        raw: Some(&project.source),
                        etag: Some(&project.etag),
                        file_id: Some(file_id),
                    },
                ));
            }
            Err(errors) => {
                let id = frontmatter::parse(&project.source)
                    .ok()
                    .and_then(|document| document.front_matter.get("id").map(str::to_string))
                    .unwrap_or_else(|| project.filename.trim_end_matches(".md").to_string());
                items.push(json!({
                    "id": id,
                    "name": project.filename,
                    "description": "Invalid project skill",
                    "version": "",
                    "scopes": [],
                    "output": null,
                    "source": "project",
                    "valid": false,
                    "selectable": false,
                    "overrideState": "none",
                    "errors": errors,
                    "raw": project.source,
                    "etag": project.etag,
                    "fileId": project.filename.trim_end_matches(".md"),
                }));
            }
        }
    }
    Response::json(200, &json!({ "skills": items }))
}

fn valid_skill_path_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 80
        && id.as_bytes()[0].is_ascii_lowercase()
        && id
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
}

fn validate_skill_write(
    source: &str,
    expected_id: Option<&str>,
) -> Result<SkillDefinition, Response> {
    if source.len() > MAX_SKILL_BYTES || source.contains('\0') {
        return Err(Response::error(
            413,
            "Skill Markdown is too large or contains invalid data",
        ));
    }
    let skill = parse_skill(source).map_err(|errors| {
        Response::json(422, &json!({ "error": "Invalid skill", "errors": errors }))
    })?;
    if expected_id.is_some_and(|id| id != skill.id) {
        return Err(Response::error(
            400,
            "A skill ID cannot change during an edit",
        ));
    }
    let builtin = BUILTIN_SKILL_SOURCES.iter().any(|(id, _)| *id == skill.id);
    if builtin && skill.override_builtin.as_deref() != Some(skill.id.as_str()) {
        return Err(Response::error(
            409,
            "A project skill can replace a built-in only with a matching `override` declaration",
        ));
    }
    Ok(skill)
}

fn skill_request_body(req: &Request) -> Result<(Json, String), Response> {
    require_json(req)?;
    let body: Json =
        serde_json::from_slice(&req.body).map_err(|_| Response::error(400, "Invalid JSON"))?;
    let source = body["source"]
        .as_str()
        .ok_or_else(|| Response::error(400, "Missing skill Markdown in `source`"))?
        .to_string();
    Ok((body, source))
}

fn create_assistant_skill(state: &AppState, req: &Request) -> Response {
    let (_, source) = match skill_request_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let skill = match validate_skill_write(&source, None) {
        Ok(skill) => skill,
        Err(response) => return response,
    };
    let _transaction = lock(&state.build);
    let directory = match assistant_skills_dir(&state.root, true) {
        Ok(directory) => directory,
        Err(error) => return Response::error(500, &error),
    };
    let path = directory.join(format!("{}.md", skill.id));
    if path.exists() {
        return Response::error(409, "A project skill with this ID already exists");
    }
    if let Err(error) = write_atomic(&path, &source) {
        return Response::error(500, &error);
    }
    Response::json(201, &json!({ "id": skill.id, "etag": etag(&source) }))
}

fn update_assistant_skill(state: &AppState, req: &Request) -> Response {
    let id = req.query.get("id").map(String::as_str).unwrap_or("");
    if !valid_skill_path_id(id) {
        return Response::error(400, "Invalid skill ID");
    }
    let (body, source) = match skill_request_body(req) {
        Ok(body) => body,
        Err(response) => return response,
    };
    let skill = match validate_skill_write(&source, Some(id)) {
        Ok(skill) => skill,
        Err(response) => return response,
    };
    let _transaction = lock(&state.build);
    let directory = match assistant_skills_dir(&state.root, false) {
        Ok(directory) => directory,
        Err(error) => return Response::error(500, &error),
    };
    let path = directory.join(format!("{id}.md"));
    if fs::symlink_metadata(&path).is_ok_and(|metadata| metadata.file_type().is_symlink()) {
        return Response::error(400, "Project skill symlinks cannot be edited");
    }
    let current = match fs::read_to_string(&path) {
        Ok(source) => source,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Response::error(404, "Project skill not found")
        }
        Err(error) => return Response::error(500, &format!("Cannot read project skill: {error}")),
    };
    if body["etag"].as_str() != Some(etag(&current).as_str()) {
        return Response::error(
            409,
            "Skill changed since it was opened; reload before saving",
        );
    }
    if let Err(error) = write_atomic(&path, &source) {
        return Response::error(500, &error);
    }
    Response::json(200, &json!({ "id": skill.id, "etag": etag(&source) }))
}

fn assistant_context_target(
    root: &Path,
    context_type: &str,
    visibility: &str,
    document_path: Option<&str>,
) -> Result<(PathBuf, &'static str, &'static str), Response> {
    let (context_type, relative) = match context_type {
        "author" => ("author", PathBuf::from("author.md")),
        "site" => ("site", PathBuf::from("site.md")),
        "voice" => ("voice", PathBuf::from("voice.md")),
        "post" => {
            let document_path = document_path
                .ok_or_else(|| Response::error(400, "Post context requires documentPath"))?;
            if check_rel_path(document_path).ok() != Some("posts") {
                return Err(Response::error(
                    400,
                    "Post context requires a valid post path",
                ));
            }
            let file_name = Path::new(document_path)
                .file_name()
                .and_then(|name| name.to_str())
                .filter(|name| name.ends_with(".md"))
                .ok_or_else(|| Response::error(400, "Post context requires a Markdown post"))?;
            ("post", PathBuf::from("posts").join(file_name))
        }
        _ => {
            return Err(Response::error(
                400,
                "Context type must be author, site, voice, or post",
            ))
        }
    };
    let (visibility, base) = match visibility {
        "portable" => ("portable", PathBuf::from("assistant/context")),
        "private" => ("private", PathBuf::from(".openblog/private/context")),
        _ => {
            return Err(Response::error(
                400,
                "Context visibility must be portable or private",
            ))
        }
    };
    let target = crate::assistant_storage::contained_target(root, &base.join(relative))
        .map_err(|error| Response::error(400, &error))?;
    Ok((target, context_type, visibility))
}

fn assistant_context_document(
    root: &Path,
    context_type: &str,
    visibility: &str,
    document_path: Option<&str>,
) -> Result<Json, Response> {
    let (path, context_type, visibility) =
        assistant_context_target(root, context_type, visibility, document_path)?;
    let name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("context.md");
    let id = if context_type == "post" {
        format!("{visibility}:post:{name}")
    } else {
        format!("{visibility}:{context_type}")
    };
    match fs::read(&path) {
        Ok(bytes) if bytes.len() > MAX_ASSISTANT_CONTEXT_BYTES => Ok(json!({
            "id": id,
            "name": name,
            "contextType": context_type,
            "visibility": visibility,
            "exists": true,
            "valid": false,
            "content": "",
            "characters": 0,
            "etag": etag_bytes(&bytes),
            "guidance": format!("This context file exceeds the {} KiB limit. Shorten it before selecting it.", MAX_ASSISTANT_CONTEXT_BYTES / 1024),
        })),
        Ok(bytes) => match String::from_utf8(bytes.clone()) {
            Ok(content) => Ok(json!({
                "id": id,
                "name": name,
                "contextType": context_type,
                "visibility": visibility,
                "exists": true,
                "valid": true,
                "content": content,
                "characters": content.chars().count(),
                "etag": etag_bytes(&bytes),
            })),
            Err(_) => Ok(json!({
                "id": id,
                "name": name,
                "contextType": context_type,
                "visibility": visibility,
                "exists": true,
                "valid": false,
                "content": "",
                "characters": 0,
                "etag": etag_bytes(&bytes),
                "guidance": "This context file is not valid UTF-8. Replace it here or remove it, then save UTF-8 Markdown.",
            })),
        },
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(json!({
            "id": id,
            "name": name,
            "contextType": context_type,
            "visibility": visibility,
            "exists": false,
            "valid": true,
            "content": "",
            "characters": 0,
            "etag": null,
        })),
        Err(error) => Err(Response::error(
            500,
            &format!("Cannot read assistant context: {error}"),
        )),
    }
}

fn assistant_reference_target(
    root: &Path,
    visibility: &str,
    name: &str,
) -> Result<(PathBuf, &'static str), Response> {
    let valid_name = !name.is_empty()
        && name.len() <= 160
        && Path::new(name).file_name().and_then(|value| value.to_str()) == Some(name)
        && !name.chars().any(char::is_control)
        && matches!(
            Path::new(name).extension().and_then(|value| value.to_str()),
            Some("md" | "txt")
        );
    if !valid_name {
        return Err(Response::error(
            422,
            "References require a safe .md or .txt filename",
        ));
    }
    let (visibility, base) = match visibility {
        "portable" => ("portable", PathBuf::from("assistant/context/references")),
        "private" => (
            "private",
            PathBuf::from(".openblog/private/context/references"),
        ),
        _ => {
            return Err(Response::error(
                400,
                "Reference visibility must be portable or private",
            ))
        }
    };
    let target = crate::assistant_storage::contained_target(root, &base.join(name))
        .map_err(|error| Response::error(400, &error))?;
    Ok((target, visibility))
}

fn assistant_text_descriptor(id: String, name: &str, visibility: &str, bytes: Vec<u8>) -> Json {
    if bytes.len() > MAX_ASSISTANT_CONTEXT_BYTES {
        return json!({
            "id": id, "name": name, "visibility": visibility,
            "exists": true, "valid": false, "content": "", "characters": 0,
            "etag": etag_bytes(&bytes),
            "guidance": "This source exceeds the 64 KiB Assistant context limit."
        });
    }
    match String::from_utf8(bytes.clone()) {
        Ok(content) => json!({
            "id": id, "name": name, "visibility": visibility,
            "exists": true, "valid": true, "content": content,
            "characters": content.chars().count(), "etag": etag_bytes(&bytes)
        }),
        Err(_) => json!({
            "id": id, "name": name, "visibility": visibility,
            "exists": true, "valid": false, "content": "", "characters": 0,
            "etag": etag_bytes(&bytes),
            "guidance": "This source is not valid UTF-8 text and cannot be selected."
        }),
    }
}

fn assistant_references(root: &Path) -> Result<Vec<Json>, Response> {
    let mut references = Vec::new();
    for (visibility, directory) in [
        ("portable", root.join("assistant/context/references")),
        ("private", root.join(".openblog/private/context/references")),
    ] {
        let entries = match fs::read_dir(&directory) {
            Ok(entries) => entries,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
            Err(error) => {
                return Err(Response::error(
                    500,
                    &format!("Cannot read Assistant references: {error}"),
                ))
            }
        };
        for entry in entries {
            let entry = entry.map_err(|error| {
                Response::error(500, &format!("Cannot inspect Assistant reference: {error}"))
            })?;
            let metadata = entry.file_type().map_err(|error| {
                Response::error(500, &format!("Cannot inspect Assistant reference: {error}"))
            })?;
            if !metadata.is_file() || metadata.is_symlink() {
                continue;
            }
            let name = entry.file_name().to_string_lossy().into_owned();
            if assistant_reference_target(root, visibility, &name).is_err() {
                continue;
            }
            let bytes = fs::read(entry.path()).map_err(|error| {
                Response::error(500, &format!("Cannot read Assistant reference: {error}"))
            })?;
            if String::from_utf8(bytes.clone())
                .is_ok_and(|source| crate::url_context::is_snapshot_markdown(&source))
            {
                continue;
            }
            references.push(assistant_text_descriptor(
                format!("{visibility}:reference:{name}"),
                &name,
                visibility,
                bytes,
            ));
        }
    }
    references.sort_by(|left, right| left["id"].as_str().cmp(&right["id"].as_str()));
    Ok(references)
}

fn assistant_post_snapshots(root: &Path) -> Result<Vec<Json>, Response> {
    let config = site::load_config(root).map_err(|error| Response::error(500, &error))?;
    let content_root = root.join(&config.paths.content);
    let posts_root = content_root.join("posts");
    let mut snapshots = Vec::new();
    if !posts_root.is_dir() {
        return Ok(snapshots);
    }
    fn collect_markdown(directory: &Path, paths: &mut Vec<PathBuf>) -> Result<(), Response> {
        let entries = fs::read_dir(directory).map_err(|error| {
            Response::error(500, &format!("Cannot inspect post snapshots: {error}"))
        })?;
        for entry in entries {
            let entry = entry.map_err(|error| {
                Response::error(500, &format!("Cannot inspect post snapshot: {error}"))
            })?;
            let file_type = entry.file_type().map_err(|error| {
                Response::error(500, &format!("Cannot inspect post snapshot: {error}"))
            })?;
            if file_type.is_symlink() {
                continue;
            }
            if file_type.is_dir() {
                collect_markdown(&entry.path(), paths)?;
            } else if file_type.is_file()
                && entry.path().extension().and_then(|value| value.to_str()) == Some("md")
            {
                paths.push(entry.path());
            }
        }
        Ok(())
    }
    let mut paths = Vec::new();
    collect_markdown(&posts_root, &mut paths)?;
    paths.sort();
    for path in paths {
        let relative = path
            .strip_prefix(&content_root)
            .map_err(|_| Response::error(500, "Post snapshot escaped the content directory"))?
            .to_string_lossy()
            .replace('\\', "/");
        let bytes = fs::read(&path).map_err(|error| {
            Response::error(500, &format!("Cannot read post snapshot: {error}"))
        })?;
        let mut descriptor = assistant_text_descriptor(
            format!("post:{relative}"),
            path.file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("post.md"),
            "source",
            bytes,
        );
        descriptor["path"] = json!(relative);
        descriptor["kind"] = json!("postSnapshot");
        snapshots.push(descriptor);
    }
    snapshots.sort_by(|left, right| left["path"].as_str().cmp(&right["path"].as_str()));
    Ok(snapshots)
}

fn assistant_context_catalog(state: &AppState, req: &Request) -> Response {
    let mut documents = Vec::new();
    for (visibility, context_type) in [
        ("portable", "author"),
        ("portable", "site"),
        ("private", "author"),
        ("private", "site"),
    ] {
        match assistant_context_document(&state.root, context_type, visibility, None) {
            Ok(document) => documents.push(document),
            Err(response) => return response,
        }
    }
    let mut voice_guides = Vec::new();
    for visibility in ["portable", "private"] {
        match assistant_context_document(&state.root, "voice", visibility, None) {
            Ok(document) => voice_guides.push(document),
            Err(response) => return response,
        }
    }
    if let Some(document_path) = req.query.get("path") {
        for visibility in ["portable", "private"] {
            match assistant_context_document(&state.root, "post", visibility, Some(document_path)) {
                Ok(document) => documents.push(document),
                Err(response) => return response,
            }
        }
    }
    for visibility in ["portable", "private"] {
        match assistant_url_context_documents(&state.root, visibility) {
            Ok(mut references) => documents.append(&mut references),
            Err(response) => return response,
        }
    }
    let git = crate::git::Git::new(&state.root);
    let private_safety = if git.is_repo() {
        let ignored = [
            ".openblog/private/context/author.md",
            ".openblog/private/context/site.md",
            ".openblog/private/context/posts/.openblog-ignore-probe.md",
            ".openblog/private/context/references/.openblog-ignore-probe.txt",
            ".openblog/private/context/voice/.openblog-ignore-probe.md",
        ]
        .iter()
        .all(|path| git.run(&["check-ignore", "-q", "--no-index", path]).is_ok());
        let tracked = git
            .run(&["ls-files", "--", ".openblog/private"])
            .is_ok_and(|paths| !paths.trim().is_empty());
        let tracked_voice_files: Vec<String> = git
            .run(&[
                "ls-files",
                "--",
                ".openblog/private/context/voice",
                ".openblog/private/voice",
            ])
            .map(|paths| {
                paths
                    .lines()
                    .map(|path| path.trim().to_string())
                    .filter(|path| !path.is_empty())
                    .collect()
            })
            .unwrap_or_default();
        let warning = if let Some(first) = tracked_voice_files.first() {
            let more = tracked_voice_files.len() - 1;
            Some(format!(
                "Your private voice sample {first}{} is tracked by Git, so it could be published or shared. Remove it from Git with `git rm --cached` and make sure /.openblog/private/ is in .gitignore.",
                if more == 0 {
                    String::new()
                } else {
                    format!(" (and {more} more)")
                }
            ))
        } else if tracked {
            Some("Private assistant content is already tracked by Git. Remove it from the index and rotate any exposed secrets before using it.".to_string())
        } else if !ignored {
            Some("Private assistant content is not ignored by Git. Add /.openblog/private/ to .gitignore before saving sensitive context.".to_string())
        } else {
            None
        };
        json!({ "gitRepository": true, "ignored": ignored, "tracked": tracked, "trackedVoiceFiles": tracked_voice_files, "warning": warning })
    } else {
        json!({ "gitRepository": false, "ignored": null, "tracked": false, "trackedVoiceFiles": [], "warning": null })
    };
    Response::json(
        200,
        &json!({
            "documents": documents,
            "references": match assistant_references(&state.root) {
                Ok(references) => references,
                Err(response) => return response,
            },
            "postSnapshots": match assistant_post_snapshots(&state.root) {
                Ok(posts) => posts,
                Err(response) => return response,
            },
            "voiceGuides": voice_guides,
            "voiceSamples": crate::voice_assistant::catalog_entries(&state.root),
            "voiceBudget": crate::voice_assistant::budget(),
            "voiceGaps": crate::voice_assistant::gaps_json(&crate::voice_assistant::gaps_for(
                &state.root,
                crate::voice_assistant::read_guide(&state.root).as_ref().map(|(_, text)| text.as_str()),
            )),
            "privateSafety": private_safety
        }),
    )
}

fn assistant_context_mutation(
    req: &Request,
) -> Result<(Json, String, String, Option<String>), Response> {
    require_json(req)?;
    let body: Json = serde_json::from_slice(&req.body)
        .map_err(|_| Response::error(400, "Invalid context request"))?;
    let context_type = body["contextType"]
        .as_str()
        .ok_or_else(|| Response::error(400, "Missing contextType"))?
        .to_string();
    let visibility = body["visibility"]
        .as_str()
        .ok_or_else(|| Response::error(400, "Missing visibility"))?
        .to_string();
    let document_path = body["documentPath"].as_str().map(str::to_string);
    Ok((body, context_type, visibility, document_path))
}

fn post_context_source(fields: &Json) -> Result<String, Response> {
    let fields = fields
        .as_object()
        .ok_or_else(|| Response::error(400, "Post context requires fields"))?;
    let mut source = String::new();
    for (key, heading) in [
        ("goal", "Goal"),
        ("audience", "Audience"),
        ("learningOutcomes", "Learning outcomes"),
        ("sources", "Sources"),
        ("constraints", "Constraints"),
    ] {
        let value = fields.get(key).and_then(Json::as_str).unwrap_or("").trim();
        if value.contains('\0') {
            return Err(Response::error(422, "Post context must be UTF-8 text"));
        }
        source.push_str(&format!("<!-- openblog:{key}:start -->\n"));
        source.push_str("## ");
        source.push_str(heading);
        source.push_str("\n\n");
        source.push_str(value);
        source.push_str(&format!("\n<!-- openblog:{key}:end -->\n\n"));
    }
    Ok(source)
}

fn save_assistant_context(state: &AppState, req: &Request) -> Response {
    let (body, context_type, visibility, document_path) = match assistant_context_mutation(req) {
        Ok(value) => value,
        Err(response) => return response,
    };
    let (path, _, _) = match assistant_context_target(
        &state.root,
        &context_type,
        &visibility,
        document_path.as_deref(),
    ) {
        Ok(value) => value,
        Err(response) => return response,
    };
    let content = if context_type == "post" {
        match post_context_source(&body["fields"]) {
            Ok(content) => content,
            Err(response) => return response,
        }
    } else {
        match body["content"].as_str() {
            Some(content) if !content.contains('\0') => content.to_string(),
            _ => return Response::error(400, "Context content must be UTF-8 text"),
        }
    };
    if content.len() > MAX_ASSISTANT_CONTEXT_BYTES {
        return Response::error(413, "Context files are limited to 64 KiB of UTF-8 text");
    }
    if context_type == "voice"
        && visibility == "portable"
        && crate::voice_store::guide_is_private_derived(&state.root, &content)
    {
        return Response::error(
            422,
            "This guide quotes private samples; save it as private. Portable context is git-tracked",
        );
    }
    let _content_lock = lock(&state.build);
    let _filesystem_lock = match content_transaction(state) {
        Ok(value) => value,
        Err(response) => return response,
    };
    if context_type == "post" {
        let config = match site::load_config(&state.root) {
            Ok(config) => config,
            Err(error) => return Response::error(500, &error),
        };
        let document_path = document_path
            .as_deref()
            .expect("validated post context path");
        let document = match resolve_content_path(&state.root, &config, document_path) {
            Ok(document) => document,
            Err(error) => return Response::error(400, &error),
        };
        if !document.is_file() {
            return Response::error(404, "The associated post does not exist");
        }
    }
    let current = match fs::read(&path) {
        Ok(bytes) => Some(bytes),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
        Err(error) => return Response::error(500, &format!("Cannot read context: {error}")),
    };
    let expected = body["etag"].as_str();
    let matches = match &current {
        Some(bytes) => expected == Some(etag_bytes(bytes).as_str()),
        None => body["etag"].is_null(),
    };
    if !matches {
        return Response::error(409, "Context changed since it was opened; reload and retry");
    }
    if let Err(error) = write_atomic(&path, &content) {
        return Response::error(500, &error);
    }
    match assistant_context_document(
        &state.root,
        &context_type,
        &visibility,
        document_path.as_deref(),
    ) {
        Ok(document) => Response::json(200, &json!({ "document": document })),
        Err(response) => response,
    }
}

fn delete_assistant_context(state: &AppState, req: &Request) -> Response {
    let (body, context_type, visibility, document_path) = match assistant_context_mutation(req) {
        Ok(value) => value,
        Err(response) => return response,
    };
    let (path, _, _) = match assistant_context_target(
        &state.root,
        &context_type,
        &visibility,
        document_path.as_deref(),
    ) {
        Ok(value) => value,
        Err(response) => return response,
    };
    let _content_lock = lock(&state.build);
    let _filesystem_lock = match content_transaction(state) {
        Ok(value) => value,
        Err(response) => return response,
    };
    let current = match fs::read(&path) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Response::error(404, "Context file does not exist")
        }
        Err(error) => return Response::error(500, &format!("Cannot read context: {error}")),
    };
    if body["etag"].as_str() != Some(etag_bytes(&current).as_str()) {
        return Response::error(409, "Context changed since it was opened; reload and retry");
    }
    match fs::remove_file(&path) {
        Ok(()) => Response::json(200, &json!({ "deleted": true })),
        Err(error) => Response::error(500, &format!("Cannot remove context: {error}")),
    }
}

fn assistant_reference_request(req: &Request) -> Result<(Json, String, String), Response> {
    require_json(req)?;
    let body: Json = serde_json::from_slice(&req.body)
        .map_err(|_| Response::error(400, "Invalid reference request"))?;
    let name = body["name"]
        .as_str()
        .ok_or_else(|| Response::error(400, "Missing reference name"))?
        .to_string();
    let visibility = body["visibility"]
        .as_str()
        .ok_or_else(|| Response::error(400, "Missing reference visibility"))?
        .to_string();
    Ok((body, name, visibility))
}

fn create_assistant_reference(state: &AppState, req: &Request) -> Response {
    let (body, name, visibility) = match assistant_reference_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let (path, visibility) = match assistant_reference_target(&state.root, &visibility, &name) {
        Ok(target) => target,
        Err(response) => return response,
    };
    let content = match body["content"].as_str() {
        Some(content) if !content.contains('\0') => content,
        _ => return Response::error(422, "References must be UTF-8 text"),
    };
    if content.len() > MAX_ASSISTANT_CONTEXT_BYTES {
        return Response::error(413, "References are limited to 64 KiB of UTF-8 text");
    }
    let _content_lock = lock(&state.build);
    let _filesystem_lock = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    if path.exists() {
        return Response::error(409, "A reference with that name already exists");
    }
    if let Err(error) = write_atomic(&path, content) {
        return Response::error(500, &error);
    }
    let bytes = content.as_bytes().to_vec();
    Response::json(
        201,
        &json!({
            "reference": assistant_text_descriptor(
                format!("{visibility}:reference:{name}"),
                &name,
                visibility,
                bytes,
            )
        }),
    )
}

/// Resolve the selected review skills for a review of `scope`: the whole document, a selection or a
/// section. A skill must declare the scope it is used for (ADR 0290).
fn resolve_review_skills(
    root: &Path,
    ids: &[String],
    scope: SkillScope,
) -> Result<Vec<ReviewSkill>, Response> {
    let projects = read_project_skills(root).map_err(|error| Response::error(500, &error))?;
    let id_counts = project_skill_id_counts(&projects);
    let builtins = builtin_skills();
    ids.iter()
        .map(|id| resolve_review_skill(id, &builtins, &projects, &id_counts, scope))
        .collect()
}

fn resolve_review_skill(
    id: &str,
    builtins: &[SkillDefinition],
    projects: &[ProjectSkillFile],
    id_counts: &BTreeMap<String, usize>,
    scope: SkillScope,
) -> Result<ReviewSkill, Response> {
    if !valid_skill_path_id(id) {
        return Err(Response::error(400, "Invalid selected skill ID"));
    }
    let builtin = builtins.iter().find(|skill| skill.id == id);
    let project = active_project_skill(projects, id_counts, id, builtin.is_some())
        .map_err(|message| Response::error(409, message))?;
    let skill = match (builtin, project) {
        (Some(_), Some(project)) => project.clone(),
        (Some(builtin), None) => builtin.clone(),
        (None, Some(project)) => project.clone(),
        (None, None) => return Err(Response::error(400, "Selected skill is unavailable")),
    };
    if skill.output != SkillOutputKind::Review || !skill.scopes.contains(&scope) {
        let what = match scope {
            SkillScope::Document => "complete-document review",
            SkillScope::Selection => "review of selected text",
            SkillScope::Section => "review of one section",
        };
        return Err(Response::error(
            400,
            &format!("Selected skill does not support {what}"),
        ));
    }
    Ok(ReviewSkill {
        id: skill.id,
        version: skill.version,
        instructions: skill.body,
    })
}

/// Resolve every selected context id on the server, for review, completion and the voice-guide
/// task. A voice sample is read again from the store each time and counted against the request
/// budget (ADR 0278); the browser only ever names it.
fn resolve_review_contexts(root: &Path, ids: &[String]) -> Result<Vec<ReviewContext>, Response> {
    let context = ids
        .iter()
        .map(|id| resolve_review_context(root, id))
        .collect::<Result<Vec<_>, _>>()?;
    crate::voice_assistant::check_budget(&context)
        .map_err(|message| Response::error(400, &message))?;
    Ok(context)
}

fn resolve_review_context(root: &Path, id: &str) -> Result<ReviewContext, Response> {
    let parts = id.split(':').collect::<Vec<_>>();
    if let ["voice", visibility, file] = parts.as_slice() {
        let visibility = crate::voice_store::Visibility::parse(visibility)
            .ok_or_else(|| Response::error(400, "Invalid selected context ID"))?;
        return crate::voice_assistant::review_context(root, visibility, file)
            .map_err(|message| Response::error(400, &message));
    }
    let document = match parts.as_slice() {
        [visibility @ ("portable" | "private"), context_type @ ("author" | "site" | "voice")] => {
            assistant_context_document(root, context_type, visibility, None)?
        }
        [visibility @ ("portable" | "private"), "post", name] => {
            let document_path = format!("posts/{name}");
            assistant_context_document(root, "post", visibility, Some(&document_path))?
        }
        [visibility @ ("portable" | "private"), "reference", _] => {
            let manual = assistant_references(root)?
                .into_iter()
                .find(|document| document["id"] == id);
            match manual {
                Some(document) => document,
                None => assistant_url_context_documents(root, visibility)?
                    .into_iter()
                    .find(|document| document["id"] == id)
                    .ok_or_else(|| Response::error(400, "Selected reference is unavailable"))?,
            }
        }
        ["post", _] => assistant_post_snapshots(root)?
            .into_iter()
            .find(|document| document["id"] == id)
            .ok_or_else(|| Response::error(400, "Selected post snapshot is unavailable"))?,
        _ => return Err(Response::error(400, "Invalid selected context ID")),
    };
    if document["exists"] != true || document["valid"] != true {
        return Err(Response::error(
            400,
            "Selected context is unavailable or invalid",
        ));
    }
    ReviewContext::new(
        id,
        document["name"].as_str().unwrap_or(""),
        document["content"].as_str().unwrap_or(""),
    )
    .map_err(|error| Response::error(400, error))
}

fn selected_ids(body: &Json, field: &str, maximum: usize) -> Result<Vec<String>, Response> {
    let values = body[field]
        .as_array()
        .ok_or_else(|| Response::error(400, &format!("`{field}` must be an array")))?;
    if values.is_empty() && field == "skillIds" {
        return Err(Response::error(400, "Select at least one review skill"));
    }
    if values.len() > maximum {
        return Err(Response::error(400, &format!("Too many selected {field}")));
    }
    let mut ids = Vec::with_capacity(values.len());
    for value in values {
        let id = value
            .as_str()
            .filter(|id| !id.is_empty())
            .ok_or_else(|| Response::error(400, &format!("`{field}` contains an invalid ID")))?;
        if ids.iter().any(|existing| existing == id) {
            return Err(Response::error(
                400,
                &format!("`{field}` contains a duplicate ID"),
            ));
        }
        ids.push(id.to_string());
    }
    Ok(ids)
}

fn review_source_hash(title: &str, metadata: &Json, markdown: &str) -> String {
    let snapshot = serde_json::to_vec(&json!({
        "title": title,
        "metadata": metadata,
        "markdown": markdown,
    }))
    .expect("JSON source snapshot is serializable");
    let digest = Blake2s256::digest(snapshot);
    digest.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn review_error(error: crate::assistant::AssistantError) -> Response {
    let (status, code) = match error.kind {
        AssistantErrorKind::NotConfigured => (404, "not-configured"),
        AssistantErrorKind::InvalidConfiguration => (400, "invalid-configuration"),
        AssistantErrorKind::MissingCredential => (503, "missing-credential"),
        AssistantErrorKind::Timeout => (504, "timeout"),
        AssistantErrorKind::InvalidJson | AssistantErrorKind::InvalidResult => {
            (502, "invalid-result")
        }
        AssistantErrorKind::Transport
        | AssistantErrorKind::ProviderStatus
        | AssistantErrorKind::ResponseRead => (502, "provider-error"),
    };
    Response::json(
        status,
        &json!({ "error": error.public_message(), "code": code }),
    )
}

fn generate_document_review(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid review request"),
    };
    let source = &body["source"];
    let title = match source["title"].as_str() {
        Some(title) if title.chars().count() <= 500 && !title.contains('\0') => title,
        _ => return Response::error(400, "Review source needs a bounded UTF-8 title"),
    };
    let metadata = match source["metadata"].as_object() {
        Some(_) => source["metadata"].clone(),
        None => return Response::error(400, "Review source metadata must be an object"),
    };
    if let Err(error) = fields_from_json(&metadata) {
        return Response::error(400, &format!("Invalid review source metadata: {error}"));
    }
    let markdown = match source["markdown"].as_str() {
        Some(markdown) if markdown.len() <= MAX_DOCUMENT_BYTES && !markdown.contains('\0') => {
            markdown
        }
        _ => return Response::error(400, "Review Markdown is too large or invalid"),
    };
    // An optional bounded passage: a selection or a section, in code-point offsets (ADR 0290).
    let passage = match &body["passage"] {
        Json::Null => None,
        Json::Object(object) => {
            let kind = object
                .get("kind")
                .and_then(Json::as_str)
                .and_then(PassageKind::parse);
            let offset = |key: &str| {
                object
                    .get(key)
                    .and_then(Json::as_u64)
                    .and_then(|value| usize::try_from(value).ok())
            };
            match (kind, offset("start"), offset("end")) {
                (Some(kind), Some(start), Some(end)) if object.len() == 3 => {
                    match ReviewPassage::new(kind, start, end, markdown) {
                        Ok(passage) => Some(passage),
                        Err(error) => return Response::error(400, &error),
                    }
                }
                _ => {
                    return Response::error(
                        400,
                        "`passage` must be { kind: selection | section, start, end }",
                    )
                }
            }
        }
        _ => {
            return Response::error(
                400,
                "`passage` must be { kind: selection | section, start, end }",
            )
        }
    };
    let skill_ids = match selected_ids(&body, "skillIds", 12) {
        Ok(ids) => ids,
        Err(response) => return response,
    };
    let context_ids = match selected_ids(&body, "contextIds", 16) {
        Ok(ids) => ids,
        Err(response) => return response,
    };
    let scope = passage.map_or(SkillScope::Document, |p| p.kind.scope());
    let (skills, context) = {
        let _assistant_lock = lock(&state.build);
        let skills = match resolve_review_skills(&state.root, &skill_ids, scope) {
            Ok(skills) => skills,
            Err(response) => return response,
        };
        let context = match resolve_review_contexts(&state.root, &context_ids) {
            Ok(context) => context,
            Err(response) => return response,
        };
        (skills, context)
    };
    let (config, credential) = match assistant_provider_snapshot(state) {
        Ok(snapshot) => snapshot,
        Err(response) => return response,
    };
    let provider = match configured_assistant_provider(
        &config,
        credential,
        assistant_provider_timeout(config.knowledge_checks.provider, cfg!(test)),
    ) {
        Ok(provider) => provider,
        Err(error) => return review_error(error),
    };
    let hash = review_source_hash(title, &metadata, markdown);
    let document = AssistantDocument {
        title: title.to_string(),
        metadata,
        markdown: markdown.to_string(),
        hash: hash.clone(),
    };
    let model = config.knowledge_checks.model.clone();
    let request = match passage {
        None => AssistantRequest::document_review(model, document, skills.clone(), context.clone()),
        Some(passage) => AssistantRequest::passage_review(
            model,
            document,
            skills.clone(),
            context.clone(),
            passage,
        ),
    };
    let scope_json = match passage {
        None => {
            json!({ "kind": "document", "start": 0, "end": markdown.chars().count(), "unit": "unicode-code-points" })
        }
        Some(passage) => {
            json!({ "kind": passage.kind.as_str(), "start": passage.start, "end": passage.end, "unit": "unicode-code-points" })
        }
    };
    let _provider_permit = match state.assistant_operations.try_acquire() {
        Some(permit) => permit,
        None => {
            return Response::json(
                429,
                &json!({ "error": "Two Assistant operations are already running; try again shortly", "code": "concurrency-limit" }),
            )
        }
    };
    let findings = match provider.generate(&request) {
        Ok(AssistantResult::Review(findings)) => findings,
        Ok(AssistantResult::KnowledgeChecks(_) | AssistantResult::CodeInteraction(_)) => {
            return Response::error(502, "Assistant provider returned the wrong result type")
        }
        Ok(
            AssistantResult::Completion(_)
            | AssistantResult::VoiceGuide(_)
            | AssistantResult::JobDraft(_),
        ) => return Response::error(502, "Assistant provider returned the wrong result type"),
        Err(error) => return review_error(error),
    };
    let review_id = match auth::random_token() {
        Ok(token) => token,
        Err(error) => return Response::error(500, &error),
    };
    Response::json(
        200,
        &json!({
            "reviewId": review_id,
            "schemaVersion": ASSISTANT_SCHEMA_VERSION,
            "sourceHash": hash,
            "scope": scope_json,
            "skills": skills.iter().map(|skill| json!({ "id": skill.id, "version": skill.version })).collect::<Vec<_>>(),
            "context": context.iter().map(|document| json!({ "id": document.identity(), "name": document.name(), "visibility": document.visibility().as_str() })).collect::<Vec<_>>(),
            "provider": { "type": "generic-https", "model": config.knowledge_checks.model },
            "research": { "enabled": false },
            "createdAt": clock::now().rfc3339(),
            "findings": findings.findings,
        }),
    )
}

fn generate_inline_completion(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid completion request"),
    };
    let source = &body["source"];
    let title = match source["title"].as_str() {
        Some(title) if title.chars().count() <= 500 && !title.contains('\0') => title,
        _ => return Response::error(400, "Completion source needs a bounded UTF-8 title"),
    };
    let metadata = match source["metadata"].as_object() {
        Some(_) => source["metadata"].clone(),
        None => return Response::error(400, "Completion source metadata must be an object"),
    };
    if let Err(error) = fields_from_json(&metadata) {
        return Response::error(400, &format!("Invalid completion source metadata: {error}"));
    }
    let bounded_text = |field: &str, maximum: usize| {
        source[field]
            .as_str()
            .filter(|value| value.chars().count() <= maximum && !value.contains('\0'))
    };
    let markdown = match bounded_text("markdown", 100_000) {
        Some(value) => value,
        None => return Response::error(400, "Completion Markdown is too large or invalid"),
    };
    let prefix = match bounded_text("prefix", 8_000) {
        Some(value) => value,
        None => return Response::error(400, "Completion prefix is too large or invalid"),
    };
    let suffix = match bounded_text("suffix", 8_000) {
        Some(value) => value,
        None => return Response::error(400, "Completion suffix is too large or invalid"),
    };
    let editor_mode = match source["editorMode"].as_str() {
        Some(mode @ ("visual" | "markdown")) => mode,
        _ => return Response::error(400, "Completion editorMode must be visual or markdown"),
    };
    let context_ids = match selected_ids(&body, "contextIds", 16) {
        Ok(ids) => ids,
        Err(response) => return response,
    };
    let context = {
        let _assistant_lock = lock(&state.build);
        match resolve_review_contexts(&state.root, &context_ids) {
            Ok(context) => context,
            Err(response) => return response,
        }
    };
    let (config, credential) = match assistant_provider_snapshot(state) {
        Ok(snapshot) => snapshot,
        Err(response) => return response,
    };
    let provider = match configured_assistant_provider(
        &config,
        credential,
        assistant_provider_timeout(config.knowledge_checks.provider, cfg!(test)),
    ) {
        Ok(provider) => provider,
        Err(error) => return review_error(error),
    };
    let request = AssistantRequest::inline_completion(
        config.knowledge_checks.model,
        AssistantCompletionSource {
            title: title.to_string(),
            metadata,
            markdown: markdown.to_string(),
            prefix: prefix.to_string(),
            suffix: suffix.to_string(),
            editor_mode: editor_mode.to_string(),
        },
        context,
    );
    let _provider_permit = match state.assistant_operations.try_acquire() {
        Some(permit) => permit,
        None => {
            return Response::json(
                429,
                &json!({ "error": "Two Assistant operations are already running; try again shortly", "code": "concurrency-limit" }),
            )
        }
    };
    match provider.generate(&request) {
        Ok(AssistantResult::Completion(completion)) => Response::json(200, &json!(completion)),
        Ok(
            AssistantResult::KnowledgeChecks(_)
            | AssistantResult::CodeInteraction(_)
            | AssistantResult::VoiceGuide(_)
            | AssistantResult::JobDraft(_)
            | AssistantResult::Review(_),
        ) => Response::error(502, "Assistant provider returned the wrong result type"),
        Err(error) => review_error(error),
    }
}

fn delete_assistant_reference(state: &AppState, req: &Request) -> Response {
    let (body, name, visibility) = match assistant_reference_request(req) {
        Ok(request) => request,
        Err(response) => return response,
    };
    let (path, _) = match assistant_reference_target(&state.root, &visibility, &name) {
        Ok(target) => target,
        Err(response) => return response,
    };
    let _content_lock = lock(&state.build);
    let _filesystem_lock = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let bytes = match fs::read(&path) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Response::error(404, "Reference does not exist")
        }
        Err(error) => return Response::error(500, &format!("Cannot read reference: {error}")),
    };
    if body["etag"].as_str() != Some(etag_bytes(&bytes).as_str()) {
        return Response::error(
            409,
            "Reference changed since it was opened; reload and retry",
        );
    }
    match fs::remove_file(&path) {
        Ok(()) => Response::json(200, &json!({ "deleted": true })),
        Err(error) => Response::error(500, &format!("Cannot remove reference: {error}")),
    }
}

// URL snapshots are retrieved only on explicit author action and saved separately
// after inspection; review selection reads the saved snapshot without refetching.
fn retrieve_url_context(req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid URL context request"),
    };
    if body["confirmed"] != true {
        return Response::error(400, "Confirm retrieval before contacting this URL");
    }
    let source = match body["url"].as_str() {
        Some(source) => source,
        None => return Response::error(400, "Missing URL"),
    };
    match crate::url_context::validate_public_url(source) {
        Ok(_) => match crate::url_context::fetch_url_snapshot(source, &clock::now().rfc3339()) {
            Ok(snapshot) => Response::json(200, &json!({ "snapshot": snapshot })),
            Err(error) => Response::error(502, &error),
        },
        Err(error) => Response::error(400, &error),
    }
}

fn url_context_directory(root: &Path, visibility: &str) -> Result<PathBuf, Response> {
    let relative = match visibility {
        "portable" => Path::new("assistant/context/references"),
        "private" => Path::new(".openblog/private/context/references"),
        _ => {
            return Err(Response::error(
                400,
                "Snapshot visibility must be portable or private",
            ))
        }
    };
    crate::assistant_storage::contained_target(root, relative)
        .map_err(|error| Response::error(400, &error))
}

fn assistant_url_context_documents(root: &Path, visibility: &str) -> Result<Vec<Json>, Response> {
    let directory = url_context_directory(root, visibility)?;
    if !directory.exists() {
        return Ok(Vec::new());
    }
    let mut paths = fs::read_dir(&directory)
        .map_err(|error| Response::error(500, &format!("Cannot read URL snapshots: {error}")))?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| path.extension().and_then(|value| value.to_str()) == Some("md"))
        .collect::<Vec<_>>();
    paths.sort();
    let mut documents = Vec::new();
    for path in paths {
        let file_id = path
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or("invalid");
        if fs::symlink_metadata(&path).is_ok_and(|metadata| metadata.file_type().is_symlink()) {
            documents.push(json!({
                "id": format!("{visibility}:reference:{file_id}"), "name": format!("{file_id}.md"),
                "contextType": "reference", "visibility": visibility, "exists": true,
                "valid": false, "selectable": false, "untrusted": true, "content": "",
                "characters": 0, "guidance": "Replace this symlink with a regular URL snapshot file."
            }));
            continue;
        }
        let bytes = fs::read(&path)
            .map_err(|error| Response::error(500, &format!("Cannot read URL snapshot: {error}")))?;
        let source = match String::from_utf8(bytes.clone()) {
            Ok(source) => source,
            Err(_) => continue,
        };
        if !crate::url_context::is_snapshot_markdown(&source) {
            continue;
        }
        let parsed = crate::url_context::parse_snapshot_markdown(&source);
        match parsed {
            Ok(snapshot) => documents.push(json!({
                "id": format!("{visibility}:reference:{file_id}"), "name": format!("{file_id}.md"),
                "contextType": "reference", "visibility": visibility, "exists": true,
                "valid": true, "selectable": true, "untrusted": true,
                "content": snapshot.text, "characters": snapshot.text.chars().count(),
                "sourceUrl": snapshot.source_url, "canonicalUrl": snapshot.canonical_url,
                "retrievedAt": snapshot.retrieved_at, "contentType": snapshot.content_type,
                "etag": etag_bytes(&bytes)
            })),
            Err(error) => documents.push(json!({
                "id": format!("{visibility}:reference:{file_id}"), "name": format!("{file_id}.md"),
                "contextType": "reference", "visibility": visibility, "exists": true,
                "valid": false, "selectable": false, "untrusted": true, "content": "",
                "characters": 0, "etag": etag_bytes(&bytes), "guidance": error
            })),
        }
    }
    Ok(documents)
}

fn save_url_context(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid URL snapshot request"),
    };
    if body["confirmed"] != true {
        return Response::error(400, "Confirm saving this inspected URL snapshot");
    }
    let visibility = body["visibility"].as_str().unwrap_or("");
    let file_id = body["fileId"].as_str().unwrap_or("");
    if !valid_skill_path_id(file_id) {
        return Response::error(
            400,
            "Snapshot file ID must use lowercase letters, digits, and hyphens",
        );
    }
    let snapshot: crate::url_context::UrlContextSnapshot =
        match serde_json::from_value(body["snapshot"].clone()) {
            Ok(snapshot) => snapshot,
            Err(_) => return Response::error(400, "URL snapshot metadata is incomplete"),
        };
    let source = match crate::url_context::snapshot_markdown(&snapshot) {
        Ok(source) => source,
        Err(error) => return Response::error(400, &error),
    };
    let directory = match url_context_directory(&state.root, visibility) {
        Ok(directory) => directory,
        Err(response) => return response,
    };
    let _content_lock = lock(&state.build);
    let _filesystem_lock = match content_transaction(state) {
        Ok(value) => value,
        Err(response) => return response,
    };
    if let Err(error) = fs::create_dir_all(&directory) {
        return Response::error(
            500,
            &format!("Cannot create URL snapshot directory: {error}"),
        );
    }
    let path = directory.join(format!("{file_id}.md"));
    if path.exists() {
        return Response::error(409, "A URL snapshot with this file ID already exists");
    }
    if let Err(error) = write_atomic(&path, &source) {
        return Response::error(500, &error);
    }
    Response::json(
        201,
        &json!({ "id": format!("{visibility}:reference:{file_id}"), "etag": etag(&source) }),
    )
}

fn generate_quiz(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let context = body["context"].as_str().unwrap_or("").trim();
    let count = body["count"].as_u64().unwrap_or(0);
    if context.is_empty() || context.chars().count() > 50_000 {
        return Response::error(
            400,
            "Select between 1 and 50,000 characters of article text",
        );
    }
    if !(1..=3).contains(&count) {
        return Response::error(400, "Question count must be between one and three");
    }

    let (config, credential) = match assistant_provider_snapshot(state) {
        Ok(snapshot) => snapshot,
        Err(response) => return response,
    };
    let provider = match configured_assistant_provider(
        &config,
        credential,
        assistant_provider_timeout(config.knowledge_checks.provider, cfg!(test)),
    ) {
        Ok(provider) => provider,
        Err(error) => {
            let status = match error.kind {
                AssistantErrorKind::NotConfigured => 404,
                AssistantErrorKind::InvalidConfiguration => 400,
                AssistantErrorKind::MissingCredential => 503,
                _ => 500,
            };
            return Response::error(status, error.public_message());
        }
    };
    let request = AssistantRequest::knowledge_checks(
        config.knowledge_checks.model,
        context.to_string(),
        KnowledgeCheckCount::new(count as u8).expect("the request count was validated above"),
    );
    let _provider_permit = match state.assistant_operations.try_acquire() {
        Some(permit) => permit,
        None => {
            return Response::error(
                429,
                "Two Assistant operations are already running; try again shortly",
            )
        }
    };
    match provider.generate(&request) {
        Ok(AssistantResult::KnowledgeChecks(result)) => Response::json(200, &json!(result)),
        Ok(
            AssistantResult::Review(_)
            | AssistantResult::CodeInteraction(_)
            | AssistantResult::VoiceGuide(_)
            | AssistantResult::JobDraft(_),
        ) => Response::error(502, "Assistant provider returned the wrong result type"),
        Ok(AssistantResult::Completion(_)) => {
            Response::error(502, "Assistant provider returned the wrong result type")
        }
        Err(error) => Response::error(502, error.public_message()),
    }
}

fn generate_code_interaction(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let context = body["context"].as_str().unwrap_or("").trim();
    if context.is_empty() || context.chars().count() > 50_000 {
        return Response::error(
            400,
            "Select between 1 and 50,000 characters of article text",
        );
    }
    let kind = match body["kind"].as_str().and_then(CodeInteractionKind::parse) {
        Some(kind) => kind,
        None => return Response::error(400, "Code interaction kind must be example or challenge"),
    };
    let language = match CodeInteractionLanguage::parse(body["language"].as_str().unwrap_or("rust"))
    {
        Some(language) => language,
        None => return Response::error(400, "Code interaction language is invalid"),
    };
    let (config, credential) = match assistant_provider_snapshot(state) {
        Ok(snapshot) => snapshot,
        Err(response) => return response,
    };
    let language_allowed = matches!(language.as_str(), "rust" | "web")
        || (!config.code_runner.endpoint.is_empty()
            && config
                .code_runner
                .languages
                .iter()
                .any(|allowed| allowed == language.as_str()));
    if !language_allowed {
        return Response::error(
            400,
            "Code interaction language is not enabled for this site",
        );
    }
    let provider = match configured_assistant_provider(
        &config,
        credential,
        assistant_provider_timeout(config.knowledge_checks.provider, cfg!(test)),
    ) {
        Ok(provider) => provider,
        Err(error) => return review_error(error),
    };
    let request = AssistantRequest::code_interaction(
        config.knowledge_checks.model,
        context.to_string(),
        kind,
        language,
    );
    let _provider_permit = match state.assistant_operations.try_acquire() {
        Some(permit) => permit,
        None => {
            return Response::json(
                429,
                &json!({ "error": "Two Assistant operations are already running; try again shortly", "code": "concurrency-limit" }),
            )
        }
    };
    code_interaction_response(provider.generate(&request))
}

fn code_interaction_response(
    result: Result<AssistantResult, crate::assistant::AssistantError>,
) -> Response {
    match result {
        Ok(AssistantResult::CodeInteraction(interaction)) => {
            Response::json(200, &json!(interaction))
        }
        Ok(
            AssistantResult::KnowledgeChecks(_)
            | AssistantResult::Review(_)
            | AssistantResult::VoiceGuide(_)
            | AssistantResult::JobDraft(_)
            | AssistantResult::Completion(_),
        ) => Response::error(502, "Assistant provider returned the wrong result type"),
        Err(error) => review_error(error),
    }
}

fn status(state: &AppState) -> Response {
    let s = lock(&state.build);
    Response::json(
        200,
        &json!({
            "now": clock::now().rfc3339(),
            "lastBuilt": s.last_built.map(|d| d.rfc3339()),
            "lastError": s.last_error,
            "nextDue": s.next_due.map(|d| d.rfc3339()),
            "scheduled": s.scheduled.iter().map(|(t, slug, d)| json!({ "title": t, "slug": slug, "date": d })).collect::<Vec<_>>(),
        }),
    )
}

fn list_documents(state: &AppState, req: &Request) -> Response {
    let _content_transaction = lock(&state.build);
    let kind = req.query.get("kind").map(String::as_str).unwrap_or("posts");
    if !matches!(kind, "posts" | "series" | "pages" | "services") {
        return Response::error(400, "kind must be posts, series, pages, or services");
    }
    let config = match site::load_config(&state.root) {
        Ok(c) => c,
        Err(e) => return Response::error(500, &e),
    };
    let sources = match site::read_sources(&state.root, &config) {
        Ok(s) => s,
        Err(e) => return Response::error(500, &e),
    };
    let files = match kind {
        "posts" => &sources.posts,
        "series" => &sources.series,
        "services" => &sources.services,
        _ => &sources.pages,
    };
    let credit_sidecars = openblog_core::model::associate_credit_sidecars(&sources);
    let now = clock::now();
    let mut items: Vec<(i64, Json)> = Vec::new();
    for file in files {
        let normalized_path = file.path.replace('\\', "/");
        let explicit_credits = openblog_core::contributor::sidecar_path(&normalized_path)
            .is_some_and(|sidecar_path| {
                sources
                    .credits
                    .iter()
                    .any(|sidecar| sidecar.path.replace('\\', "/") == sidecar_path)
            });
        let credit_mode = if explicit_credits {
            "explicit"
        } else {
            "inherited"
        };
        let item = match kind {
            "posts" => {
                if let Some(error) = credit_sidecars.post_errors.get(&normalized_path) {
                    (
                        i64::MIN,
                        json!({ "path": file.path, "title": file.path, "status": "error", "error": error, "creditMode": credit_mode }),
                    )
                } else {
                    let sidecar = credit_sidecars.by_post.get(&normalized_path).copied();
                    match openblog_core::model::load_post_with_credits(
                        file,
                        &config,
                        RenderOptions::default(),
                        sidecar,
                    ) {
                        Ok(p) => {
                            let status = if p.draft {
                                "draft"
                            } else if p.date > now {
                                "scheduled"
                            } else {
                                "published"
                            };
                            (
                                p.date.unix(),
                                json!({
                                    "path": file.path, "title": p.title, "slug": p.slug, "date": p.date.rfc3339(),
                                    "status": status, "series": p.series, "tags": p.tags.iter().map(|t| t.name.clone()).collect::<Vec<_>>(),
                                    "url": p.url, "words": p.word_count,
                                    "creditMode": credit_mode,
                                }),
                            )
                        }
                        Err(e) => (
                            i64::MIN,
                            json!({ "path": file.path, "title": file.path, "status": "error", "error": e, "creditMode": credit_mode }),
                        ),
                    }
                }
            }
            _ => match frontmatter::parse(&file.contents) {
                Ok(doc) => {
                    let stem = file
                        .path
                        .rsplit('/')
                        .next()
                        .unwrap_or("")
                        .trim_end_matches(".md");
                    let title = doc
                        .front_matter
                        .get("name")
                        .or_else(|| doc.front_matter.get("title"))
                        .unwrap_or(stem)
                        .to_string();
                    let status = if kind == "services"
                        && doc.front_matter.get_bool("draft").unwrap_or(false)
                    {
                        "draft"
                    } else {
                        "published"
                    };
                    (
                        0,
                        json!({ "path": file.path, "title": title, "slug": slugify(stem), "status": status }),
                    )
                }
                Err(e) => (
                    i64::MIN,
                    json!({ "path": file.path, "title": file.path, "status": "error", "error": e }),
                ),
            },
        };
        items.push(item);
    }
    items.sort_by_key(|item| std::cmp::Reverse(item.0));
    Response::json(
        200,
        &json!({ "kind": kind, "items": items.into_iter().map(|(_, j)| j).collect::<Vec<_>>() }),
    )
}

fn get_document(state: &AppState, req: &Request) -> Response {
    let _content_transaction = lock(&state.build);
    let Some(rel) = req.query.get("path") else {
        return Response::error(400, "Missing ?path=");
    };
    let config = match site::load_config(&state.root) {
        Ok(c) => c,
        Err(e) => return Response::error(500, &e),
    };
    let path = match resolve_content_path(&state.root, &config, rel) {
        Ok(p) => p,
        Err(e) => return Response::error(400, &e),
    };
    let text = match fs::read_to_string(&path) {
        Ok(t) => t,
        Err(_) => return Response::error(404, "No such document"),
    };
    let kind = check_rel_path(rel).unwrap_or("posts");
    let (credits, credit_etag, credit_error) = if kind == "posts" {
        let sidecar = match resolve_credit_path(&state.root, &config, rel) {
            Ok(path) => path,
            Err(error) => return Response::error(400, &error),
        };
        document_credits(&sidecar, &config)
    } else {
        (Json::Null, Json::Null, Json::Null)
    };
    match frontmatter::parse(&text) {
        Ok(doc) => {
            let resolved_profile = if kind == "posts" {
                json!(openblog_core::profile::resolve(&doc.front_matter).id)
            } else {
                Json::Null
            };
            Response::json(
                200,
                &json!({ "path": rel, "kind": kind, "etag": etag(&text), "fields": fields_to_json(&doc.front_matter.fields), "body": doc.body, "resolvedProfile": resolved_profile, "credits": credits, "creditEtag": credit_etag, "creditError": credit_error }),
            )
        }
        Err(e) => Response::json(
            200,
            &json!({ "path": rel, "kind": kind, "etag": etag(&text), "raw": text, "error": e, "credits": credits, "creditEtag": credit_etag, "creditError": credit_error }),
        ),
    }
}

fn document_credits(sidecar: &Path, config: &SiteConfig) -> (Json, Json, Json) {
    let bytes = match fs::read(sidecar) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return (Json::Null, Json::Null, Json::Null);
        }
        Err(error) => {
            return (
                Json::Null,
                Json::Null,
                Json::String(format!("cannot read {}: {error}", sidecar.display())),
            );
        }
    };
    let credit_etag = Json::String(etag_bytes(&bytes));
    let text = match std::str::from_utf8(&bytes) {
        Ok(text) => text,
        Err(error) => {
            return (
                Json::Null,
                credit_etag,
                Json::String(format!("{} is not UTF-8: {error}", sidecar.display())),
            );
        }
    };
    let value: Json = match serde_json::from_str(text) {
        Ok(value) => value,
        Err(error) => {
            return (
                Json::Null,
                credit_etag,
                Json::String(format!("cannot parse {}: {error}", sidecar.display())),
            );
        }
    };
    if value.get("version").and_then(Json::as_u64) != Some(1) {
        return (
            Json::Null,
            credit_etag,
            Json::String(format!(
                "{} must use credit file version 1",
                sidecar.display()
            )),
        );
    }
    let Some(credits) = value.get("credits").and_then(Json::as_array) else {
        return (
            Json::Null,
            credit_etag,
            Json::String(format!("{} has no credits array", sidecar.display())),
        );
    };
    let credit_error =
        openblog_core::contributor::resolve(&config.author, &config.contributors, Some(text))
            .err()
            .map(Json::String)
            .unwrap_or(Json::Null);
    (Json::Array(credits.clone()), credit_etag, credit_error)
}

fn contributor_registry_response(config_bytes: &[u8], config: &SiteConfig) -> Response {
    Response::json(
        200,
        &json!({
            "etag": etag_bytes(config_bytes),
            "contributors": config.contributors,
            "author": config.author,
        }),
    )
}

fn get_contributors(state: &AppState) -> Response {
    let _content_transaction = lock(&state.build);
    let path = state.root.join(site::CONFIG_FILE);
    let bytes = match fs::read(&path) {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::error(500, &format!("cannot read {}: {error}", path.display()))
        }
    };
    let text = match std::str::from_utf8(&bytes) {
        Ok(text) => text,
        Err(error) => {
            return Response::error(500, &format!("{} is not UTF-8: {error}", path.display()))
        }
    };
    match SiteConfig::from_json(text) {
        Ok(config) => contributor_registry_response(&bytes, &config),
        Err(error) => Response::error(500, &error),
    }
}

fn referenced_removed_contributors(
    root: &Path,
    config: &SiteConfig,
    removed: &[String],
) -> Result<Vec<String>, String> {
    if removed.is_empty() {
        return Ok(Vec::new());
    }
    let sources = site::read_sources(root, config)?;
    let mut references = Vec::new();
    for sidecar in sources.credits {
        let Ok(value) = serde_json::from_str::<Json>(&sidecar.contents) else {
            continue;
        };
        let Some(credits) = value.get("credits").and_then(Json::as_array) else {
            continue;
        };
        if credits.iter().any(|credit| {
            credit
                .get("contributor")
                .and_then(Json::as_str)
                .is_some_and(|id| removed.iter().any(|removed| removed == id))
        }) {
            references.push(sidecar.path);
        }
    }
    references.sort();
    references.dedup();
    Ok(references)
}

fn save_contributors(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let Some(contributors) = body.get("contributors").and_then(Json::as_object) else {
        return Response::error(422, "contributors must be an object");
    };
    if contributors.len() > 500 {
        return Response::error(422, "contributors has too many entries");
    }

    let mut status = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = state.root.join(site::CONFIG_FILE);
    let current_bytes = match fs::read(&path) {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::error(500, &format!("cannot read {}: {error}", path.display()))
        }
    };
    if body.get("etag").and_then(Json::as_str) != Some(etag_bytes(&current_bytes).as_str()) {
        return Response::error(
            409,
            "Site settings changed on disk since you opened Contributors. Reload before saving.",
        );
    }
    let current_text = match std::str::from_utf8(&current_bytes) {
        Ok(text) => text,
        Err(error) => {
            return Response::error(500, &format!("{} is not UTF-8: {error}", path.display()))
        }
    };
    let current_config = match SiteConfig::from_json(current_text) {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    let mut candidate_json: Json = match serde_json::from_str(current_text) {
        Ok(Json::Object(object)) => Json::Object(object),
        Ok(_) => return Response::error(500, "openblog.json must contain a JSON object"),
        Err(error) => return Response::error(500, &format!("invalid openblog.json: {error}")),
    };
    candidate_json["contributors"] = Json::Object(contributors.clone());
    let candidate_text = match serde_json::to_string(&candidate_json) {
        Ok(text) => text,
        Err(error) => {
            return Response::error(422, &format!("cannot serialize contributors: {error}"))
        }
    };
    let candidate_config = match SiteConfig::from_json(&candidate_text) {
        Ok(config) => config,
        Err(error) => return Response::error(422, &error),
    };
    let removed = current_config
        .contributors
        .keys()
        .filter(|id| !candidate_config.contributors.contains_key(*id))
        .cloned()
        .collect::<Vec<_>>();
    let references = match referenced_removed_contributors(&state.root, &current_config, &removed) {
        Ok(references) => references,
        Err(error) => return Response::error(422, &error),
    };
    if !references.is_empty() {
        return Response::json(
            422,
            &json!({
                "error": "Referenced contributors cannot be removed. Update these post credits first.",
                "paths": references,
            }),
        );
    }
    // A binding follows its registry key by name, so a bound key must never be freed for reuse.
    let bound = match crate::shared_publications::bound_contributor_ids(&state.root) {
        Ok(bound) => bound,
        Err(error) => return Response::error(500, &error),
    };
    let bound_removed = removed
        .iter()
        .filter(|id| bound.contains(*id))
        .collect::<Vec<_>>();
    if !bound_removed.is_empty() {
        return Response::json(
            422,
            &json!({
                "error": "Contributors who take part in a shared reflection cannot be removed.",
                "contributors": bound_removed,
            }),
        );
    }
    // Interpretations in the source library name interpreters by registry key
    // (ADR 0087). The library lock is held until the registry is written.
    let (_library_lock, interpreted) = match source_store::interpreters_in_use(
        &state.root,
        &current_config.contributors,
        &removed,
    ) {
        Ok(found) => found,
        Err(error) => return Response::error(422, &error),
    };
    if !interpreted.is_empty() {
        let contributors: std::collections::BTreeSet<&str> =
            interpreted.iter().map(|(key, _)| key.as_str()).collect();
        let interpretations: std::collections::BTreeSet<&str> =
            interpreted.iter().map(|(_, id)| id.as_str()).collect();
        return Response::json(
            422,
            &json!({
                "error": "Contributors named as interpreters in the source library cannot be removed. Change those interpretations first.",
                "contributors": contributors,
                "interpretations": interpretations,
            }),
        );
    }

    candidate_json["contributors"] = json!(candidate_config.contributors);
    let written = match serde_json::to_string_pretty(&candidate_json) {
        Ok(text) => format!("{text}\n"),
        Err(error) => {
            return Response::error(500, &format!("cannot serialize openblog.json: {error}"))
        }
    };
    if let Err(error) = write_atomic(&path, &written) {
        return Response::error(500, &error);
    }
    let build = state.rebuild_locked(&mut status);
    let build_json = match build {
        Ok(report) => json!({ "ok": true, "posts": report.posts, "files": report.files }),
        Err(error) => json!({ "ok": false, "error": error }),
    };
    eprintln!("admin: updated contributor registry");
    state_arc(state).auto_publish("Update contributor registry".into());
    Response::json(
        200,
        &json!({
            "etag": etag(&written),
            "contributors": candidate_config.contributors,
            "author": candidate_config.author,
            "build": build_json,
        }),
    )
}

// ---------------------------------------------------------------------------
// Shared publications
// ---------------------------------------------------------------------------

/// The create request. Unknown fields are refused, so a body cannot name an Admin user,
/// participant, role, or binding: identity comes from the session and the registry.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct SharedPublicationRequest {
    #[serde(default)]
    title: String,
    #[serde(default)]
    guiding_question: String,
    #[serde(default)]
    contributor_id: String,
    sources: Vec<SharedSourceRequest>,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct SharedSourceRequest {
    kind: SourceKind,
    #[serde(default)]
    title: String,
    #[serde(default)]
    url: String,
    #[serde(default)]
    creator: String,
    #[serde(default)]
    publisher: String,
    #[serde(default)]
    published: String,
    #[serde(default)]
    isbn: String,
}

fn shared_problem(field: &str, message: &str) -> Response {
    Response::json(422, &json!({ "error": message, "field": field }))
}

/// A field-specific message for the requester's own submission. It never repeats a value.
fn shared_publication_problem(error: SharedPublicationError) -> Response {
    let source_message = |index: usize, field: SourceField| {
        let number = index + 1;
        let (key, message) = match field {
            SourceField::Title => ("title", format!("Source {number}: add a title with visible text, up to 300 bytes, on one line.")),
            SourceField::Url => ("url", format!("Source {number}: paste a full web address that starts with https:// or http://, without a username or password.")),
            SourceField::Creator => ("creator", format!("Source {number}: shorten who made it to 200 bytes on one line.")),
            SourceField::Publisher => ("publisher", format!("Source {number}: shorten the publisher to 200 bytes on one line.")),
            SourceField::Published => ("published", format!("Source {number}: write the date briefly, such as 2019 or March 2021.")),
            SourceField::Isbn => ("isbn", format!("Source {number}: an ISBN has 10 or 13 digits and is only used for books.")),
        };
        shared_problem(&format!("sources.{index}.{key}"), &message)
    };
    match error {
        SharedPublicationError::TitleOrQuestionRequired => {
            shared_problem("title", "Add a working title or a guiding question.")
        }
        SharedPublicationError::Title => shared_problem(
            "title",
            "Use a title with visible text, up to 300 bytes, on one line.",
        ),
        SharedPublicationError::GuidingQuestion => shared_problem(
            "guidingQuestion",
            "Use a guiding question with visible text, up to 1,000 bytes, on one line.",
        ),
        SharedPublicationError::NoSources => {
            shared_problem("sources", "Add the source you are reflecting on.")
        }
        SharedPublicationError::TooManySources => {
            shared_problem("sources", "A shared reflection can list at most 20 sources.")
        }
        SharedPublicationError::Source { index, field } => source_message(index, field),
        SharedPublicationError::Creator => shared_problem(
            "contributorId",
            "This contributor profile cannot join a shared reflection. Check its public name in Contributors.",
        ),
        SharedPublicationError::InvalidRecord => {
            Response::error(500, "The shared reflection could not be prepared.")
        }
    }
}

/// What a bound participant may read about a publication: never bindings, other participants,
/// Admin usernames, or contribution drafts.
fn shared_publication_summary(record: &SharedPublication, roles: &[AuthorizationRole]) -> Json {
    json!({
        "publicationId": record.publication_id,
        "title": record.title,
        "guidingQuestion": record.guiding_question,
        "sources": record.sources,
        "roles": roles,
    })
}

/// Server-side identity facts for authorization: current account names and registry keys.
fn collaboration_identities(
    root: &Path,
    config: &SiteConfig,
) -> Result<(Vec<String>, Vec<String>), Response> {
    let users = Users::load(&root.join(&config.admin.users_file))
        .map_err(|error| Response::error(500, &error))?;
    Ok((
        users.users.iter().map(|user| user.name.clone()).collect(),
        config.contributors.keys().cloned().collect(),
    ))
}

fn list_shared_publications(state: &AppState, session: &auth::Session) -> Response {
    let _content_transaction = lock(&state.build);
    let config = match site::load_config(&state.root) {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    let (admin_users, contributor_ids) = match collaboration_identities(&state.root, &config) {
        Ok(identities) => identities,
        Err(response) => return response,
    };
    let admin_users = admin_users.iter().map(String::as_str).collect::<Vec<_>>();
    let contributor_ids = contributor_ids
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    let records = match crate::shared_publications::load_all(&state.root) {
        Ok(records) => records,
        Err(error) => return Response::error(500, &error),
    };
    let publications = records
        .iter()
        .filter_map(|(_, record)| {
            let identities = openblog_core::invitation::Identities {
                active_admin_users: &admin_users,
                contributor_ids: &contributor_ids,
            };
            record
                .authorize(
                    &session.user,
                    &identities,
                    AuthorizationAction::ViewPublication,
                    AuthorizationTarget::Publication,
                )
                .ok()
                .map(|binding| shared_publication_summary(record, &binding.roles))
        })
        .collect::<Vec<_>>();
    Response::json(200, &json!({ "publications": publications }))
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct SourceMetadataRequest {
    url: String,
}

/// Optional help for one source link: the embed the renderer would use (found offline) and, for
/// a supported provider, bounded suggestions labelled with their provider. Nothing is stored and
/// no outcome is an error, so authoring never depends on a provider answering.
fn shared_source_metadata(req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<SourceMetadataRequest>(&req.body) else {
        return Response::error(400, "Send the link to look up.");
    };
    if body.url.len() > 2048 {
        return Response::json(200, &json!({ "status": "unsupported" }));
    }
    use crate::source_metadata::Lookup;
    let embed_json = |found: &openblog_core::embed::Embed| json!({ "provider": found.provider, "link": found.link, "linkLabel": found.link_label });
    let payload = match crate::source_metadata::lookup(&body.url) {
        Lookup::Unsupported => json!({ "status": "unsupported" }),
        Lookup::Unavailable(message, found) => {
            json!({ "status": "unavailable", "message": message, "embed": embed_json(&found) })
        }
        Lookup::Found(suggestion, found) => {
            json!({ "status": "found", "suggestion": suggestion, "embed": embed_json(&found) })
        }
    };
    Response::json(200, &payload)
}

fn create_shared_publication(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<SharedPublicationRequest>(&req.body) else {
        return shared_problem(
            "",
            "This shared reflection request is not valid. Reload Admin Studio and try again.",
        );
    };
    if !openblog_core::collaboration::valid_admin_username(&session.user) {
        return shared_problem(
            "",
            "Your sign-in name cannot join a shared reflection. Ask the site owner for an account named with lowercase letters, digits, dots, hyphens, or underscores.",
        );
    }
    let _status = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let config = match site::load_config(&state.root) {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    let Some(contributor) = config.contributors.get(&body.contributor_id) else {
        return shared_problem(
            "contributorId",
            "Choose the contributor profile you will appear as.",
        );
    };
    let new = NewSharedPublication {
        publication_id: String::new(),
        title: body.title,
        guiding_question: body.guiding_question,
        sources: body
            .sources
            .into_iter()
            .map(|source| NewSourceReference {
                kind: source.kind,
                title: source.title,
                url: source.url,
                creator: source.creator,
                publisher: source.publisher,
                published: source.published,
                isbn: source.isbn,
            })
            .collect(),
        creator: NewParticipant {
            admin_user: session.user.clone(),
            contributor_id: body.contributor_id.clone(),
            display_name: contributor.name.clone(),
        },
    };
    match crate::shared_publications::create(&state.root, new) {
        Ok(record) => {
            eprintln!(
                "admin: created shared publication {}",
                record.publication_id
            );
            let roles = record.authorization.bindings[0].roles.clone();
            Response::json(
                201,
                &json!({ "publication": shared_publication_summary(&record, &roles) }),
            )
        }
        Err(crate::shared_publications::CreateError::Invalid(error)) => {
            shared_publication_problem(error)
        }
        Err(crate::shared_publications::CreateError::Storage(error)) => {
            eprintln!("admin: shared publication not stored: {error}");
            Response::error(
                500,
                "The shared reflection could not be saved. Nothing was created; try again.",
            )
        }
    }
}

// ---------------------------------------------------------------------------
// Shared publication invitations
// ---------------------------------------------------------------------------

/// Invitation requests name the publication and the invited account; the inviter always comes
/// from the session. Unknown fields are refused.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct InviteRequest {
    publication_id: String,
    admin_user: String,
    contributor_id: String,
    roles: Vec<AuthorizationRole>,
    #[serde(default)]
    lifetime_days: u32,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct InvitationActionRequest {
    publication_id: String,
    invitation_id: String,
    #[serde(default)]
    lifetime_days: u32,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct InvitationTokenRequest {
    token: String,
    #[serde(default)]
    contributor_id: String,
}

const INVITATION_UNAVAILABLE: &str = "This invitation cannot be used. It may have expired, been withdrawn, already been answered, or be meant for a different account.";

fn invitation_not_found() -> Response {
    Response::error(
        404,
        "That shared reflection was not found, or you cannot invite people to it.",
    )
}

fn invitation_problem(error: InvitationError) -> Response {
    match error {
        InvitationError::Denied => invitation_not_found(),
        InvitationError::Unavailable => Response::error(400, INVITATION_UNAVAILABLE),
        InvitationError::Invalid(field) => {
            let (name, message) = match field {
                InvitationField::AdminUser => (
                    "adminUser",
                    "Choose an Admin account that is not already taking part or invited.",
                ),
                InvitationField::ContributorId => (
                    "contributorId",
                    "Choose a contributor profile that is not already taking part or invited.",
                ),
                InvitationField::Roles => {
                    ("roles", "Choose at least one role, without repeating any.")
                }
                InvitationField::Lifetime => {
                    ("lifetimeDays", "An invitation can last from 1 to 30 days.")
                }
                InvitationField::Capacity => (
                    "",
                    "This shared reflection has too many invitations or participants. Revoke some and try again.",
                ),
            };
            shared_problem(name, message)
        }
    }
}

fn invitation_summary(invitation: &Invitation, now: i64) -> Json {
    json!({
        "id": invitation.id,
        "adminUser": invitation.admin_user,
        "contributorId": invitation.contributor_id,
        "roles": invitation.roles,
        "state": invitation.status(now),
        "createdAt": invitation.created_at,
        "expiresAt": invitation.expires_at,
    })
}

fn new_invitation_ids() -> Result<(String, String), String> {
    let bytes: [u8; 6] = auth::random_bytes()?;
    let id = format!(
        "invitation-{}",
        bytes.iter().map(|b| format!("{b:02x}")).collect::<String>()
    );
    Ok((id, auth::random_token()?))
}

/// Everything a request to change invitations needs, loaded in one transaction: the record, the
/// current identities, and the lock guards. The guards drop with this value.
struct InvitationTransaction<'a> {
    // Fields drop in declaration order. The lock file must go before the build mutex is
    // released: otherwise the next request waiting on the mutex finds the lock file still there
    // and is refused as if another write were active.
    _filesystem: Option<crate::transaction::ContentTransactionLock>,
    _build: MutexGuard<'a, BuildStatus>,
    record: Option<SharedPublication>,
    admin_users: Vec<String>,
    contributor_ids: Vec<String>,
    contributors: std::collections::BTreeMap<String, String>,
}

fn invitation_transaction<'a>(
    state: &'a AppState,
    publication_id: &str,
) -> Result<InvitationTransaction<'a>, Response> {
    let build = lock(&state.build);
    let filesystem = content_transaction(state)?;
    let config = site::load_config(&state.root).map_err(|error| Response::error(500, &error))?;
    let (admin_users, contributor_ids) = collaboration_identities(&state.root, &config)?;
    let record = crate::shared_publications::load(&state.root, publication_id)
        .map_err(|error| Response::error(500, &error))?;
    Ok(InvitationTransaction {
        _build: build,
        _filesystem: filesystem,
        record,
        admin_users,
        contributor_ids,
        contributors: config
            .contributors
            .iter()
            .map(|(key, contributor)| (key.clone(), contributor.name.clone()))
            .collect(),
    })
}

impl InvitationTransaction<'_> {
    fn with_identities<T>(&self, run: impl FnOnce(&Identities<'_>) -> T) -> T {
        let admin_users = self
            .admin_users
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>();
        let contributor_ids = self
            .contributor_ids
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>();
        run(&Identities {
            active_admin_users: &admin_users,
            contributor_ids: &contributor_ids,
        })
    }

    fn store(&self, root: &Path, next: &SharedPublication) -> Result<(), Response> {
        let previous = self.record.as_ref().ok_or_else(invitation_not_found)?;
        match crate::shared_publications::replace(root, previous, next) {
            Ok(()) => Ok(()),
            Err(crate::shared_publications::ReplaceError::Conflict) => Err(Response::error(
                409,
                "This shared reflection changed while you were working. Reload and try again.",
            )),
            Err(crate::shared_publications::ReplaceError::TooLarge) => Err(Response::error(
                500,
                "The invitation could not be saved. Nothing changed; try again.",
            )),
            Err(crate::shared_publications::ReplaceError::Storage(error)) => {
                eprintln!("admin: invitation not stored: {error}");
                Err(Response::error(
                    500,
                    "The invitation could not be saved. Nothing changed; try again.",
                ))
            }
        }
    }
}

fn invitation_link(token: &str) -> String {
    format!("/admin/#/shared/accept/{token}")
}

fn list_invitations(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return invitation_not_found();
    };
    let transaction = match invitation_transaction(state, publication_id) {
        Ok(transaction) => transaction,
        Err(response) => return response,
    };
    let Some(record) = &transaction.record else {
        return invitation_not_found();
    };
    let now = clock::now().unix();
    transaction.with_identities(|identities| {
        match record.invitations_for(&session.user, identities) {
            Ok(invitations) => Response::json(
                200,
                &json!({
                    "invitations": invitations
                        .iter()
                        .map(|invitation| invitation_summary(invitation, now))
                        .collect::<Vec<_>>(),
                }),
            ),
            Err(error) => invitation_problem(error),
        }
    })
}

fn bad_invitation_request() -> Response {
    shared_problem(
        "",
        "This invitation request is not valid. Reload Admin Studio and try again.",
    )
}

fn create_invitation(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<InviteRequest>(&req.body) else {
        return bad_invitation_request();
    };
    let transaction = match invitation_transaction(state, &body.publication_id) {
        Ok(transaction) => transaction,
        Err(response) => return response,
    };
    let Some(record) = &transaction.record else {
        return invitation_not_found();
    };
    let (id, secret) = match new_invitation_ids() {
        Ok(ids) => ids,
        Err(error) => return Response::error(500, &error),
    };
    let new = NewInvitation {
        id,
        secret,
        admin_user: body.admin_user,
        contributor_id: body.contributor_id,
        roles: body.roles,
        lifetime_days: body.lifetime_days,
    };
    let now = clock::now().unix();
    let invited = transaction
        .with_identities(|identities| record.invite(&session.user, identities, &new, now));
    finish_invitation(state, &transaction, invited, &new.id, now)
}

fn finish_invitation(
    state: &AppState,
    transaction: &InvitationTransaction<'_>,
    result: Result<(SharedPublication, String), InvitationError>,
    invitation_id: &str,
    now: i64,
) -> Response {
    let (next, token) = match result {
        Ok(result) => result,
        Err(error) => return invitation_problem(error),
    };
    if let Err(response) = transaction.store(&state.root, &next) {
        return response;
    }
    eprintln!("admin: issued shared publication invitation {invitation_id}");
    let Some(invitation) = next
        .invitations
        .iter()
        .find(|invitation| invitation.id == invitation_id)
    else {
        return Response::error(500, "The invitation could not be prepared.");
    };
    Response::json(
        201,
        &json!({
            "invitation": invitation_summary(invitation, now),
            "token": token,
            "link": invitation_link(&token),
        }),
    )
    .with_header("Cache-Control", "no-store")
}

fn revoke_invitation(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<InvitationActionRequest>(&req.body) else {
        return bad_invitation_request();
    };
    let transaction = match invitation_transaction(state, &body.publication_id) {
        Ok(transaction) => transaction,
        Err(response) => return response,
    };
    let Some(record) = &transaction.record else {
        return invitation_not_found();
    };
    let now = clock::now().unix();
    let result = transaction.with_identities(|identities| {
        record.revoke_invitation(&session.user, identities, &body.invitation_id, now)
    });
    let next = match result {
        Ok(next) => next,
        Err(error) => return invitation_problem(error),
    };
    if let Err(response) = transaction.store(&state.root, &next) {
        return response;
    }
    eprintln!(
        "admin: revoked shared publication invitation {}",
        body.invitation_id
    );
    let summary = next
        .invitations
        .iter()
        .find(|invitation| invitation.id == body.invitation_id)
        .map(|invitation| invitation_summary(invitation, now));
    Response::json(200, &json!({ "invitation": summary }))
}

fn reissue_invitation(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<InvitationActionRequest>(&req.body) else {
        return bad_invitation_request();
    };
    let transaction = match invitation_transaction(state, &body.publication_id) {
        Ok(transaction) => transaction,
        Err(response) => return response,
    };
    let Some(record) = &transaction.record else {
        return invitation_not_found();
    };
    let (id, secret) = match new_invitation_ids() {
        Ok(ids) => ids,
        Err(error) => return Response::error(500, &error),
    };
    let replacement = NewInvitation {
        id,
        secret,
        lifetime_days: body.lifetime_days,
        ..NewInvitation::default()
    };
    let now = clock::now().unix();
    let result = transaction.with_identities(|identities| {
        record.reissue_invitation(
            &session.user,
            identities,
            &body.invitation_id,
            &replacement,
            now,
        )
    });
    finish_invitation(state, &transaction, result, &replacement.id, now)
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct MemberRequest {
    publication_id: String,
    participant_id: String,
    expected_revision: u64,
    #[serde(default)]
    roles: Vec<AuthorizationRole>,
}

fn member_problem(error: MemberError) -> Response {
    match error {
        MemberError::Denied => Response::error(
            404,
            "That shared reflection or member was not found, or you cannot manage it.",
        ),
        MemberError::Stale => Response::error(
            409,
            "The members changed while you were working. Reload to see the current list, then try again.",
        ),
        MemberError::Roles => {
            shared_problem("roles", "Choose at least one role, without repeating any.")
        }
        MemberError::Invalid => Response::error(
            400,
            "That change would leave the shared reflection in an invalid state.",
        ),
    }
}

fn list_members(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return invitation_not_found();
    };
    let transaction = match invitation_transaction(state, publication_id) {
        Ok(transaction) => transaction,
        Err(response) => return response,
    };
    let Some(record) = &transaction.record else {
        return invitation_not_found();
    };
    transaction.with_identities(
        |identities| match record.members_for(&session.user, identities) {
            Ok(members) => Response::json(
                200,
                &json!({
                    "revision": record.authorization.revision,
                    "members": members,
                    "audit": record.audit_for(&session.user, identities).unwrap_or_default(),
                }),
            ),
            Err(error) => member_problem(error),
        },
    )
}

/// Changes who can sign in to one reflection. Only the policy changes; the participant, their
/// drafts, approvals, and credit stay as they were.
fn change_member(
    state: &AppState,
    req: &Request,
    session: &auth::Session,
    remove: bool,
) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<MemberRequest>(&req.body) else {
        return bad_invitation_request();
    };
    let transaction = match invitation_transaction(state, &body.publication_id) {
        Ok(transaction) => transaction,
        Err(response) => return response,
    };
    let Some(record) = &transaction.record else {
        return invitation_not_found();
    };
    let result = transaction.with_identities(|identities| {
        if remove {
            record.remove_member(
                &session.user,
                identities,
                &body.participant_id,
                body.expected_revision,
                clock::now().unix(),
            )
        } else {
            record.change_member_roles(
                &session.user,
                identities,
                &body.participant_id,
                &body.roles,
                body.expected_revision,
                clock::now().unix(),
            )
        }
    });
    let next = match result {
        Ok(next) => next,
        Err(error) => return member_problem(error),
    };
    if let Err(response) = transaction.store(&state.root, &next) {
        return response;
    }
    reconcile_approvals(state, &transaction, &next);
    eprintln!(
        "admin: {} a member of shared publication {}",
        if remove {
            "removed"
        } else {
            "changed roles of"
        },
        body.publication_id
    );
    Response::json(200, &json!({ "revision": next.authorization.revision }))
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct DraftSaveRequest {
    publication_id: String,
    expected_revision: u64,
    markdown: String,
}

/// Every refusal to touch a draft reads the same, so it cannot confirm that a reflection, a
/// participant, or another person's draft exists.
fn draft_not_found() -> Response {
    Response::error(
        404,
        "That shared reflection was not found, or you cannot write a draft in it.",
    )
}

fn draft_json(view: &DraftView) -> Json {
    json!({ "stamp": view.stamp, "markdown": view.markdown })
}

/// The requester's own participant id once `SharedPublication::authorize` allows them to edit
/// their draft; the single entry point decides, so a Reader, a stale binding, or a removed
/// account gets nothing.
fn draft_owner(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    session: &auth::Session,
) -> Option<String> {
    let own = record
        .authorization
        .bindings
        .iter()
        .find(|binding| binding.admin_user == session.user)?
        .participant_id
        .clone();
    transaction
        .with_identities(|identities| {
            record
                .authorize(
                    &session.user,
                    identities,
                    AuthorizationAction::EditDraft,
                    AuthorizationTarget::Participant(&own),
                )
                .map(|binding| binding.participant_id.clone())
        })
        .ok()
}

/// The set with every current participant admitted, so a participant who joined later can save.
fn draft_set_for(
    stored: Option<&DraftSet>,
    record: &SharedPublication,
) -> Result<DraftSet, DraftError> {
    let ids = record
        .collaboration
        .participants
        .iter()
        .map(|participant| participant.id.as_str())
        .collect::<Vec<_>>();
    let mut set = match stored {
        Some(set) => set.clone(),
        None => DraftSet::new(&ids)?,
    };
    for id in ids {
        set.admit(id)?;
    }
    Ok(set)
}

fn draft_request_target<'a>(
    state: &'a AppState,
    publication_id: &str,
    session: &auth::Session,
) -> Result<(InvitationTransaction<'a>, String), Response> {
    let transaction = invitation_transaction(state, publication_id)?;
    let own = match &transaction.record {
        Some(record) => draft_owner(&transaction, record, session),
        None => None,
    };
    match own {
        Some(own) => Ok((transaction, own)),
        None => Err(draft_not_found()),
    }
}

/// Reads only the signed-in participant's own latest draft. Nobody else's draft has a route.
fn read_own_draft(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return draft_not_found();
    };
    let (transaction, own) = match draft_request_target(state, publication_id, session) {
        Ok(found) => found,
        Err(response) => return response,
    };
    let stored = match crate::shared_publications::load_drafts(&state.root, publication_id) {
        Ok(stored) => stored,
        Err(error) => {
            eprintln!("admin: drafts not readable for {publication_id}: {error}");
            return Response::error(500, "Your draft could not be read. Nothing was changed.");
        }
    };
    drop(transaction);
    let draft = stored
        .set
        .as_ref()
        .and_then(|set| set.view(&own, &own, &[own.as_str()]).ok())
        .map(|view| draft_json(&view));
    Response::json(200, &json!({ "draft": draft }))
}

/// Saves the signed-in participant's own draft as a new revision. A save built on an older
/// revision is refused with the newer copy; the caller keeps what it typed and nothing is
/// overwritten.
fn save_own_draft(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<DraftSaveRequest>(&req.body) else {
        return shared_problem(
            "",
            "This draft request is not valid. Reload Admin Studio and try again.",
        );
    };
    let (transaction, own) = match draft_request_target(state, &body.publication_id, session) {
        Ok(found) => found,
        Err(response) => return response,
    };
    let record = transaction.record.as_ref().expect("authorized record");
    let stored = match crate::shared_publications::load_drafts(&state.root, &body.publication_id) {
        Ok(stored) => stored,
        Err(error) => {
            eprintln!(
                "admin: drafts not readable for {}: {error}",
                body.publication_id
            );
            return Response::error(500, "Your draft could not be saved. Nothing was changed.");
        }
    };
    let Ok(mut set) = draft_set_for(stored.set.as_ref(), record) else {
        return Response::error(500, "Your draft could not be saved. Nothing was changed.");
    };
    let now = clock::now().unix();
    match set.save(&own, &own, body.expected_revision, &body.markdown, now) {
        Ok(stamp) => {
            match crate::shared_publications::replace_drafts(
                &state.root,
                &body.publication_id,
                &stored,
                &set,
            ) {
                Ok(()) => {
                    reconcile_approvals(state, &transaction, record);
                    eprintln!(
                        "admin: saved draft revision {} of shared publication {}",
                        stamp.number, body.publication_id
                    );
                    Response::json(200, &json!({ "stamp": stamp }))
                }
                Err(crate::shared_publications::ReplaceError::Conflict) => Response::error(
                    409,
                    "Your draft changed while you were saving. Reload to see the newer copy.",
                ),
                Err(crate::shared_publications::ReplaceError::TooLarge) => draft_limit_problem(),
                Err(crate::shared_publications::ReplaceError::Storage(error)) => {
                    eprintln!("admin: draft not stored: {error}");
                    Response::error(500, "Your draft could not be saved. Nothing was changed.")
                }
            }
        }
        Err(DraftError::Stale) => {
            let current = set
                .view(&own, &own, &[own.as_str()])
                .ok()
                .map(|view| draft_json(&view));
            Response::json(
                409,
                &json!({
                    "error": "Your draft changed since you last read it. Your text was not saved and nothing was overwritten; compare it with the newer copy.",
                    "current": current,
                }),
            )
        }
        Err(DraftError::Invalid) => shared_problem(
            "markdown",
            "That draft is too large or contains characters that cannot be saved.",
        ),
        Err(DraftError::LimitReached) => draft_limit_problem(),
        Err(DraftError::Denied) => draft_not_found(),
    }
}

// ---------------------------------------------------------------------------
// Approval, scheduling and publication of a shared reflection (ADR 0022)
// ---------------------------------------------------------------------------

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct ApproveRequest {
    publication_id: String,
    /// The token the approver read with the combined preview.
    seen: String,
    affirmed: bool,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct PublicationRequest {
    publication_id: String,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct ScheduleRequest {
    publication_id: String,
    /// RFC 3339 time to publish, or null to cancel a pending schedule.
    #[serde(default)]
    publish_at: Option<String>,
}

/// Every refusal to approve, schedule or publish for someone who may not reads the same.
fn publish_not_found() -> Response {
    Response::error(
        404,
        "That shared reflection was not found, or you cannot do that with it.",
    )
}

fn published_already() -> Response {
    Response::error(
        409,
        "This shared reflection is already published. Nothing was changed.",
    )
}

fn publish_request_problem() -> Response {
    shared_problem(
        "",
        "This request is not valid. Reload Admin Studio and try again.",
    )
}

fn publish_failed(error: &str) -> Response {
    // The detail is logged without prose: it names a path or an I/O error, never a draft.
    eprintln!("admin: shared publication not published: {error}");
    Response::error(
        500,
        "The reflection could not be published. Nothing was changed.",
    )
}

fn publish_store_problem(error: crate::shared_publications::ReplaceError) -> Response {
    use crate::shared_publications::ReplaceError;
    match error {
        ReplaceError::Conflict => Response::error(
            409,
            "This shared reflection changed while you were working. Reload and try again; nothing was changed.",
        ),
        ReplaceError::TooLarge => publish_failed("state too large"),
        ReplaceError::Storage(error) => publish_failed(&error),
    }
}

/// Everything the gate reads, loaded in the request's transaction.
struct GateInputs {
    drafts: DraftSet,
    structure: crate::shared_publications::StoredStructure,
    synthesis: openblog_core::synthesis::SynthesisSet,
    moments: MomentSet,
    approvals: crate::shared_publications::StoredApprovals,
    outcome: crate::shared_publications::StoredOutcome,
    active: Vec<String>,
}

fn gate_inputs(
    state: &AppState,
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
) -> Result<GateInputs, Response> {
    let id = &record.publication_id;
    let stored = load_reveal_drafts(state, id)?;
    let drafts = draft_set_for(stored.set.as_ref(), record)
        .map_err(|_| publish_failed("drafts are not usable"))?;
    let synthesis = crate::shared_publications::load_synthesis(&state.root, id)
        .map_err(|error| publish_failed(&error))?
        .set;
    let moments = crate::shared_publications::load_moments(&state.root, id)
        .map_err(|error| publish_failed(&error))?
        .set;
    let approvals = crate::shared_publications::load_approvals_for_update(&state.root, id)
        .map_err(|error| publish_failed(&error))?;
    let structure = crate::shared_publications::load_structure(&state.root, id)
        .map_err(|error| publish_failed(&error))?;
    let outcome = crate::shared_publications::load_outcome(&state.root, id)
        .map_err(|error| publish_failed(&error))?;
    Ok(GateInputs {
        drafts,
        structure,
        synthesis,
        moments,
        approvals,
        outcome,
        active: active_drafters(transaction, record),
    })
}

/// The grant check, always through the single entry point. A requester without the grant, or
/// whose account, key or participant is gone, learns nothing; only one who holds it can be told
/// that approvals are missing.
fn authorize_publisher(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    admin_user: &str,
    schedule: bool,
) -> Result<(), Response> {
    transaction
        .with_identities(|identities| {
            if schedule {
                record
                    .authorize(
                        admin_user,
                        identities,
                        AuthorizationAction::Schedule,
                        AuthorizationTarget::Publication,
                    )
                    .map_err(|_| PublishError::Denied)?;
            }
            record.authorize_publish(admin_user, identities)
        })
        .map_err(|error| match error {
            PublishError::Denied => publish_not_found(),
            PublishError::Unapproved => Response::json(
                409,
                &json!({ "error": "Every author must approve the current piece before it can be published. Nothing was changed.", "missing": [] }),
            ),
        })
}

/// A post ready to write, checked against the site before anything is written.
struct Prepared {
    assembly: openblog_core::assembly::Assembly,
    path: PathBuf,
    sidecar: PathBuf,
    previous_document: Option<Vec<u8>>,
    previous_sidecar: Option<Vec<u8>>,
}

/// Assemble the approved piece and prove the site accepts it, without writing anything. Refusals
/// never repeat prose: they name authors whose approval is missing, or say the piece could not
/// be made.
fn prepare_post(
    state: &AppState,
    record: &SharedPublication,
    inputs: &GateInputs,
    date: DateTime,
) -> Result<Prepared, Response> {
    use openblog_core::assembly::{assemble, AssemblyError};
    let active = inputs.active.iter().map(String::as_str).collect::<Vec<_>>();
    let build = |date: &str| {
        assemble(
            record,
            inputs.structure.structure.as_ref(),
            &inputs.drafts,
            &inputs.synthesis,
            &inputs.moments,
            &inputs.approvals.set,
            &active,
            date,
        )
    };
    let mut assembly = match build(&date.rfc3339()) {
        Ok(assembly) => assembly,
        Err(AssemblyError::Blocked { missing }) => {
            return Err(Response::json(
                409,
                &json!({
                    "error": "Every required author must approve the current piece first. Nothing was changed.",
                    "missing": missing,
                }),
            ))
        }
        Err(AssemblyError::UnsafeMarkup) => {
            return Err(shared_problem(
                "",
                "A section contains raw HTML or an unsafe link, which shared reflections do not publish. Ask its author to remove it and approve again. Nothing was changed.",
            ))
        }
        Err(AssemblyError::ReservedSectionAnchor) => {
            return Err(shared_problem(
                "",
                "A section heading uses an anchor reserved for the generated continuing conversation (`continuing-the-conversation` or `conversation-<category>[-<n>]`). Ask its author to rename the heading and approve again. Nothing was changed.",
            ))
        }
        Err(AssemblyError::UnsafeConversationItem(rule, item)) => {
            return Err(shared_problem(
                "",
                &format!(
                    "The continuing conversation cannot be published: {} contains {}. Ask its author to edit the item and approve it again. Nothing was changed.",
                    item.describe(),
                    rule.describe()
                ),
            ))
        }
        Err(AssemblyError::Invalid) => {
            return Err(shared_problem(
                "",
                "This reflection cannot be published yet: it needs a title and at least one written section. Nothing was changed.",
            ))
        }
        Err(AssemblyError::ArrangementMismatch) => {
            return Err(shared_problem(
                "",
                "The arrangement no longer matches the drafts: a turn names a part an author has since removed. Ask a coordinator to arrange the piece again; the combined preview shows where. Nothing was changed.",
            ))
        }
        Err(AssemblyError::UnresolvedMoment) => {
            return Err(shared_problem(
                "",
                "A moment proposed for the piece no longer fits its source: the source was removed or its kind changed. Ask its author to edit the moment or keep it private, then approve again. Nothing was changed.",
            ))
        }
        Err(AssemblyError::UnsafeMoment) => {
            return Err(shared_problem(
                "",
                "A moment proposed for the piece has an observation that would change how another part of the piece reads, such as a link reference or an unclosed code block. Ask its author to edit the observation, then approve again. Nothing was changed.",
            ))
        }
        Err(AssemblyError::RuleUnmet { named, roles }) => {
            return Err(Response::json(
                409,
                &json!({
                    "error": "The approval rule cannot be met as things stand: a person it names is no longer an author, or no author holds a role it lists. Change the rule, or restore that access or role. Nothing was changed.",
                    "unmetNamed": named,
                    "unmetRoles": roles,
                }),
            ))
        }
    };
    let config = site::load_config(&state.root).map_err(|error| publish_failed(&error))?;
    let path = resolve_content_path(&state.root, &config, &assembly.path)
        .map_err(|error| publish_failed(&error))?;
    let sidecar = resolve_credit_path(&state.root, &config, &assembly.path)
        .map_err(|error| publish_failed(&error))?;
    let previous_document = read_optional_bytes(&path).map_err(|error| publish_failed(&error))?;
    let previous_sidecar = read_optional_bytes(&sidecar).map_err(|error| publish_failed(&error))?;
    if let Some(existing) = &previous_document {
        let same = |candidate: &openblog_core::assembly::Assembly| {
            existing == candidate.source.as_bytes()
                && previous_sidecar.as_deref() == Some(candidate.credits.as_bytes())
        };
        if !same(&assembly) {
            // An earlier attempt may have been interrupted after writing: it keeps its date.
            let original = std::str::from_utf8(existing)
                .ok()
                .and_then(|text| frontmatter::parse(text).ok())
                .and_then(|document| document.front_matter.get("date").map(str::to_string))
                .and_then(|date| build(&date).ok());
            match original {
                Some(candidate) if same(&candidate) => assembly = candidate,
                _ => {
                    return Err(Response::error(
                        409,
                        "A different file already occupies this reflection's place. Nothing was changed.",
                    ))
                }
            }
        }
    }
    if validate_candidate(
        &state.root,
        &config,
        &assembly.path,
        &assembly.source,
        &CreditEdit::Set(assembly.credits.clone()),
    )
    .is_err()
    {
        // The problems quote the authors' prose, which the requester may not be entitled to read.
        return Err(shared_problem(
            "",
            "The combined piece could not be built into the site. Ask the authors to review the combined preview. Nothing was changed.",
        ));
    }
    Ok(Prepared {
        assembly,
        path,
        sidecar,
        previous_document,
        previous_sidecar,
    })
}

/// Write the Post and its credits, record the outcome, and rebuild, as one unit: if any step
/// fails, every earlier one is undone and public output is rebuilt from the restored content.
/// Publishing an already-published reflection changes nothing and succeeds again.
///
/// The rebuild is a full build, so while the site publishes curated context
/// (`curatedContext.publish`) and `selections.json` cannot be read, publishing is refused and
/// rolled back, naming the file, until it is repaired or the switch is turned off (ADR 0191). An
/// ordinary post save is not stopped: it is `200` with `build.ok` false.
fn commit_publication(
    state: &AppState,
    transaction: &mut InvitationTransaction<'_>,
    record: &SharedPublication,
    date: DateTime,
) -> Result<Json, Response> {
    use crate::shared_publications::replace_outcome;
    use openblog_core::assembly::Outcome;
    let inputs = gate_inputs(state, transaction, record)?;
    if matches!(inputs.outcome.outcome, Some(Outcome::Published { .. })) {
        return Ok(json!({ "state": "published", "alreadyPublished": true }));
    }
    let prepared = prepare_post(state, record, &inputs, date)?;
    let id = &record.publication_id;
    let rollback_files = |prepared: &Prepared| {
        let _ = restore_file(&prepared.path, prepared.previous_document.as_deref());
        let _ = restore_file(&prepared.sidecar, prepared.previous_sidecar.as_deref());
    };
    if let Some(parent) = prepared.path.parent() {
        fs::create_dir_all(parent).map_err(|error| publish_failed(&error.to_string()))?;
    }
    write_document_with_credits(
        &prepared.path,
        &prepared.sidecar,
        &prepared.assembly.source,
        &CreditEdit::Set(prepared.assembly.credits.clone()),
    )
    .map_err(|error| publish_failed(&error))?;
    let published = Outcome::published(clock::now().unix());
    let stored = match replace_outcome(&state.root, id, &inputs.outcome, Some(&published)) {
        Ok(stored) => stored,
        Err(error) => {
            rollback_files(&prepared);
            return Err(publish_store_problem(error));
        }
    };
    if let Err(error) = state.rebuild_locked(&mut transaction._build) {
        let _ = replace_outcome(&state.root, id, &stored, inputs.outcome.outcome.as_ref());
        rollback_files(&prepared);
        let _ = state.rebuild_locked(&mut transaction._build);
        return Err(publish_failed(&error));
    }
    eprintln!("admin: published shared publication {id}");
    if let Some(title) = &record.title {
        state_arc(state).auto_publish(title.clone());
    }
    Ok(json!({ "state": "published", "alreadyPublished": false }))
}

/// Publish the approved piece now. The publish grant is necessary but never enough: every
/// required author's approval must match the content as it is at this moment.
fn publish_shared(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<PublicationRequest>(&req.body) else {
        return publish_request_problem();
    };
    let mut transaction = match invitation_transaction(state, &body.publication_id) {
        Ok(transaction) => transaction,
        Err(response) => return response,
    };
    let Some(record) = transaction.record.clone() else {
        return publish_not_found();
    };
    if let Err(response) = authorize_publisher(&transaction, &record, &session.user, false) {
        return response;
    }
    match commit_publication(state, &mut transaction, &record, clock::now()) {
        Ok(result) => Response::json(200, &result),
        Err(response) => response,
    }
}

/// Hold the approved piece privately until a time, or cancel that. Nothing enters content until
/// the time comes, and then only if the approvals still match (checked again by the scheduler).
fn schedule_shared(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    use crate::shared_publications::replace_outcome;
    use openblog_core::assembly::Outcome;
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<ScheduleRequest>(&req.body) else {
        return publish_request_problem();
    };
    let transaction = match invitation_transaction(state, &body.publication_id) {
        Ok(transaction) => transaction,
        Err(response) => return response,
    };
    let Some(record) = transaction.record.clone() else {
        return publish_not_found();
    };
    if let Err(response) = authorize_publisher(&transaction, &record, &session.user, true) {
        return response;
    }
    let inputs = match gate_inputs(state, &transaction, &record) {
        Ok(inputs) => inputs,
        Err(response) => return response,
    };
    if matches!(inputs.outcome.outcome, Some(Outcome::Published { .. })) {
        return published_already();
    }
    let id = &record.publication_id;
    let Some(text) = &body.publish_at else {
        if inputs.outcome.outcome.is_some() {
            if let Err(error) = replace_outcome(&state.root, id, &inputs.outcome, None) {
                return publish_store_problem(error);
            }
        }
        return Response::json(200, &json!({ "state": "unscheduled" }));
    };
    let Some(at) = DateTime::parse(text).filter(|at| at.unix() > clock::now().unix()) else {
        return shared_problem(
            "publishAt",
            "Choose a time in the future, as a date and time such as 2030-01-31T09:00:00Z. To publish now, use Publish.",
        );
    };
    // Refuse now what would be refused later: unapproved or unbuildable pieces are never held.
    if let Err(response) = prepare_post(state, &record, &inputs, at) {
        return response;
    }
    let next = Outcome::scheduled(at.unix(), &session.user);
    if inputs.outcome.outcome.as_ref() != Some(&next) {
        if let Err(error) = replace_outcome(&state.root, id, &inputs.outcome, Some(&next)) {
            return publish_store_problem(error);
        }
    }
    Response::json(
        200,
        &json!({ "state": "scheduled", "publishAt": at.rfc3339() }),
    )
}

/// Publish every scheduled reflection whose time has come. Each one is checked again against
/// the content and the scheduling account's grant as they are now, so an edit, a removal or a
/// withdrawn approval after scheduling holds it back, privately, until it is approved again.
fn fire_due_shared_publications(state: &AppState) {
    use openblog_core::assembly::Outcome;
    let now = clock::now().unix();
    for id in crate::shared_publications::outcome_ids(&state.root) {
        let due = match crate::shared_publications::load_outcome(&state.root, &id) {
            Ok(stored) => matches!(
                stored.outcome,
                Some(Outcome::Scheduled { publish_at, .. }) if publish_at <= now
            ),
            Err(_) => false,
        };
        if !due {
            continue;
        }
        let Ok(mut transaction) = invitation_transaction(state, &id) else {
            continue;
        };
        let Some(record) = transaction.record.clone() else {
            continue;
        };
        let Ok(stored) = crate::shared_publications::load_outcome(&state.root, &id) else {
            continue;
        };
        let Some(Outcome::Scheduled {
            publish_at,
            requested_by,
            ..
        }) = stored.outcome
        else {
            continue;
        };
        if publish_at > now
            || authorize_publisher(&transaction, &record, &requested_by, true).is_err()
        {
            continue;
        }
        let _ = commit_publication(
            state,
            &mut transaction,
            &record,
            DateTime::from_unix(publish_at),
        );
    }
}

/// An author approves the exact piece they read. The approval is theirs alone: it needs their
/// own draft grant and their own approve grant, an affirmation, and the token from the preview;
/// a token the piece has moved past is refused and nothing is recorded.
fn approve_piece(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    match serde_json::from_slice::<ApproveRequest>(&req.body) {
        Ok(body) => change_approval(
            state,
            session,
            &body.publication_id,
            Some((&body.seen, body.affirmed)),
        ),
        Err(_) => publish_request_problem(),
    }
}

fn withdraw_approval(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    match serde_json::from_slice::<PublicationRequest>(&req.body) {
        Ok(body) => change_approval(state, session, &body.publication_id, None),
        Err(_) => publish_request_problem(),
    }
}

fn change_approval(
    state: &AppState,
    session: &auth::Session,
    publication_id: &str,
    approving: Option<(&str, bool)>,
) -> Response {
    use openblog_core::approval::ApprovalError;
    let (transaction, own) = match draft_request_target(state, publication_id, session) {
        Ok(found) => found,
        Err(_) => return publish_not_found(),
    };
    let record = transaction.record.clone().expect("authorized record");
    let allowed = transaction
        .with_identities(|identities| {
            record.authorize(
                &session.user,
                identities,
                AuthorizationAction::ApproveContribution,
                AuthorizationTarget::Participant(&own),
            )
        })
        .is_ok();
    if !allowed {
        return publish_not_found();
    }
    let inputs = match gate_inputs(state, &transaction, &record) {
        Ok(inputs) => inputs,
        Err(response) => return response,
    };
    if matches!(
        inputs.outcome.outcome,
        Some(openblog_core::assembly::Outcome::Published { .. })
    ) {
        return published_already();
    }
    let active = inputs.active.iter().map(String::as_str).collect::<Vec<_>>();
    let mut next = inputs.approvals.set.clone();
    let result = match approving {
        Some((seen, affirmed)) => openblog_core::assembly::with_subject(
            &record,
            inputs.structure.structure.as_ref(),
            &inputs.drafts,
            &inputs.synthesis,
            &inputs.moments,
            &active,
            |subject| {
                next.approve(&own, &own, subject, seen, affirmed, clock::now().unix())
                    .map(|()| true)
            },
        ),
        None => next.withdraw(&own, &own),
    };
    match result {
        Ok(true) => {}
        Ok(false) => return Response::json(200, &json!({ "withdrawn": false })),
        Err(ApprovalError::Stale) => {
            return Response::error(
                409,
                "The piece changed after you read it. Reload the combined preview and read it again; nothing was recorded.",
            )
        }
        Err(ApprovalError::Invalid) => {
            return shared_problem(
                "affirmed",
                "Confirm that you approve publishing exactly the piece you read, and reload the preview if the piece has no sections yet.",
            )
        }
        Err(ApprovalError::Denied) => return publish_not_found(),
    }
    if let Err(error) = crate::shared_publications::replace_approvals(
        &state.root,
        publication_id,
        &inputs.approvals,
        &next,
    ) {
        return publish_store_problem(error);
    }
    eprintln!(
        "admin: {} for shared publication {publication_id}",
        if approving.is_some() {
            "approval recorded"
        } else {
            "approval withdrawn"
        }
    );
    Response::json(
        200,
        &if approving.is_some() {
            json!({ "approved": true })
        } else {
            json!({ "withdrawn": true })
        },
    )
}

// ---------------------------------------------------------------------------
// Shared synthesis: the continuing conversation (ADR 0025)
// ---------------------------------------------------------------------------

/// Every refusal reads the same, so a request cannot confirm that a reflection, an item or an
/// author exists.
fn synthesis_not_found() -> Response {
    Response::error(
        404,
        "That shared reflection was not found, or you cannot work on its continuing conversation.",
    )
}

/// The requester's own participant id once `SharedPublication::authorize` allows `EditSynthesis`.
fn synthesis_owner(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    session: &auth::Session,
) -> Option<String> {
    own_grant(
        transaction,
        record,
        session,
        AuthorizationAction::EditSynthesis,
    )
}

/// Participants who may author or be named on synthesis items now, decided per binding by the
/// single entry point.
fn synthesis_authors(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
) -> Vec<String> {
    grant_holders(transaction, record, AuthorizationAction::EditSynthesis)
}

/// The requester's own participant id once `SharedPublication::authorize` allows `action` on it.
fn own_grant(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    session: &auth::Session,
    action: AuthorizationAction,
) -> Option<String> {
    let own = record
        .authorization
        .bindings
        .iter()
        .find(|binding| binding.admin_user == session.user)?
        .participant_id
        .clone();
    transaction
        .with_identities(|identities| {
            record
                .authorize(
                    &session.user,
                    identities,
                    action,
                    AuthorizationTarget::Participant(&own),
                )
                .map(|binding| binding.participant_id.clone())
        })
        .ok()
}

/// Participants who hold `action` on themselves now, decided per binding by the single entry
/// point.
fn grant_holders(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    action: AuthorizationAction,
) -> Vec<String> {
    record
        .authorization
        .bindings
        .iter()
        .filter(|binding| {
            transaction
                .with_identities(|identities| {
                    record.authorize(
                        &binding.admin_user,
                        identities,
                        action,
                        AuthorizationTarget::Participant(&binding.participant_id),
                    )
                })
                .is_ok()
        })
        .map(|binding| binding.participant_id.clone())
        .collect()
}

fn participant_name(record: &SharedPublication, id: &str) -> String {
    record
        .collaboration
        .participants
        .iter()
        .find(|participant| participant.id == id)
        .map(|participant| participant.display_name.clone())
        .unwrap_or_default()
}

/// The synthesis as one author sees it. Items carry prose, so this is built only after the
/// requester was authorized and `SynthesisSet::view` accepted them as an author.
fn synthesis_json(
    set: &openblog_core::synthesis::SynthesisSet,
    record: &SharedPublication,
    own: &str,
    authors: &[&str],
) -> Option<Json> {
    let items = set.view(own, authors).ok()?;
    let who = |id: &str| json!({ "id": id, "displayName": participant_name(record, id) });
    let items: Vec<Json> = items
        .iter()
        .map(|item| {
            json!({
                "id": item.id(),
                "kind": item.kind(),
                "markdown": item.markdown(),
                "revision": item.revision(),
                "contributors": item.contributors().iter().map(|id| who(id)).collect::<Vec<_>>(),
                "approved": item.approved_by().into_iter().map(who).collect::<Vec<_>>(),
                "awaiting": item.awaiting().into_iter().map(who).collect::<Vec<_>>(),
                "mine": item.contributors().iter().any(|id| id == own),
                "approvedByYou": item.approved_by().contains(&own),
            })
        })
        .collect();
    Some(json!({
        "revision": set.revision(),
        "items": items,
        "authors": authors.iter().map(|id| who(id)).collect::<Vec<_>>(),
        "you": own,
    }))
}

fn read_synthesis(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return synthesis_not_found();
    };
    let Ok(transaction) = invitation_transaction(state, publication_id) else {
        return synthesis_not_found();
    };
    let Some(record) = &transaction.record else {
        return synthesis_not_found();
    };
    let Some(own) = synthesis_owner(&transaction, record, session) else {
        return synthesis_not_found();
    };
    let stored = match crate::shared_publications::load_synthesis(&state.root, publication_id) {
        Ok(stored) => stored,
        Err(error) => {
            eprintln!("admin: synthesis not readable for {publication_id}: {error}");
            return Response::error(500, "The continuing conversation could not be read.");
        }
    };
    let authors = synthesis_authors(&transaction, record);
    let authors = authors.iter().map(String::as_str).collect::<Vec<_>>();
    match synthesis_json(&stored.set, record, &own, &authors) {
        Some(json) => Response::json(200, &json),
        None => synthesis_not_found(),
    }
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct SynthesisRequest {
    publication_id: String,
    /// The set revision the caller read; any other revision is refused as a conflict.
    expected_revision: u64,
    change: SynthesisChange,
}

#[derive(serde::Deserialize)]
#[serde(tag = "action", rename_all = "camelCase", deny_unknown_fields)]
enum SynthesisChange {
    Add {
        kind: openblog_core::synthesis::SynthesisKind,
        markdown: String,
        #[serde(default)]
        others: Vec<String>,
    },
    Edit {
        id: String,
        #[serde(default)]
        kind: Option<openblog_core::synthesis::SynthesisKind>,
        #[serde(default)]
        markdown: Option<String>,
        #[serde(default, rename = "addContributors")]
        add_contributors: Vec<String>,
    },
    Withdraw {
        id: String,
    },
    Approve {
        id: String,
    },
    Reorder {
        order: Vec<String>,
    },
}

/// One change to the synthesis, by an authorized author, against the revision they read. A
/// refused or failed change stores nothing, and a stored one also reconciles the piece's
/// approvals in the same transaction.
fn change_synthesis(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    use openblog_core::synthesis::{NewSynthesisItem, SynthesisEdit, SynthesisError};
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<SynthesisRequest>(&req.body) else {
        return shared_problem(
            "",
            "This request is not valid. Reload Admin Studio and try again.",
        );
    };
    let Ok(transaction) = invitation_transaction(state, &body.publication_id) else {
        return synthesis_not_found();
    };
    let Some(record) = &transaction.record else {
        return synthesis_not_found();
    };
    let Some(own) = synthesis_owner(&transaction, record, session) else {
        return synthesis_not_found();
    };
    let stored = match crate::shared_publications::load_synthesis(&state.root, &body.publication_id)
    {
        Ok(stored) => stored,
        Err(error) => {
            eprintln!(
                "admin: synthesis not readable for {}: {error}",
                body.publication_id
            );
            return Response::error(500, "The continuing conversation could not be changed.");
        }
    };
    match crate::shared_publications::load_outcome(&state.root, &body.publication_id) {
        Ok(stored_outcome)
            if matches!(
                stored_outcome.outcome,
                Some(openblog_core::assembly::Outcome::Published { .. })
            ) =>
        {
            return published_already()
        }
        Ok(_) => {}
        Err(error) => return publish_failed(&error),
    }
    let authors = synthesis_authors(&transaction, record);
    let authors = authors.iter().map(String::as_str).collect::<Vec<_>>();
    let expected = body.expected_revision;
    let mut next = stored.set.clone();
    let result = match &body.change {
        SynthesisChange::Add {
            kind,
            markdown,
            others,
        } => {
            let others = others.iter().map(String::as_str).collect::<Vec<_>>();
            next.add(
                &own,
                &authors,
                expected,
                NewSynthesisItem {
                    kind: *kind,
                    markdown,
                    others: &others,
                },
            )
            .map(|_| ())
        }
        SynthesisChange::Edit {
            id,
            kind,
            markdown,
            add_contributors,
        } => {
            let added = add_contributors
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>();
            next.edit(
                &own,
                &authors,
                expected,
                id,
                SynthesisEdit {
                    kind: *kind,
                    markdown: markdown.as_deref(),
                    add_contributors: &added,
                },
            )
        }
        SynthesisChange::Withdraw { id } => next.withdraw(&own, &authors, expected, id),
        SynthesisChange::Approve { id } => next.approve_item(&own, &authors, expected, id),
        SynthesisChange::Reorder { order } => {
            let order = order.iter().map(String::as_str).collect::<Vec<_>>();
            next.reorder(&own, &authors, expected, &order)
        }
    };
    match result {
        Ok(()) => {}
        Err(SynthesisError::Denied) => return synthesis_not_found(),
        Err(SynthesisError::Stale) => {
            return Response::error(
                409,
                "The continuing conversation changed since you read it. Reload to see the current items; nothing was changed.",
            )
        }
        Err(SynthesisError::Rule(rule)) => {
            return shared_problem(
                "markdown",
                &format!("That item contains {}. Nothing was changed.", rule.describe()),
            )
        }
        Err(SynthesisError::Invalid) => {
            return shared_problem(
                "markdown",
                "That item is empty, too large, contains characters that cannot be saved, or names someone who is not an author.",
            )
        }
    }
    if next != stored.set {
        match crate::shared_publications::replace_synthesis(
            &state.root,
            &body.publication_id,
            &stored,
            &next,
        ) {
            Ok(()) => {}
            Err(crate::shared_publications::ReplaceError::Conflict) => {
                return Response::error(
                    409,
                    "The continuing conversation changed while you were saving. Reload to see the current items; nothing was changed.",
                )
            }
            Err(crate::shared_publications::ReplaceError::TooLarge) => {
                return shared_problem(
                    "markdown",
                    "The continuing conversation has reached its size limit, so this change was not saved.",
                )
            }
            Err(crate::shared_publications::ReplaceError::Storage(error)) => {
                eprintln!("admin: synthesis not stored: {error}");
                return Response::error(
                    500,
                    "The continuing conversation could not be changed. Nothing was changed.",
                );
            }
        }
        reconcile_approvals(state, &transaction, record);
        eprintln!(
            "admin: continuing conversation changed in shared publication {}",
            body.publication_id
        );
    }
    match synthesis_json(&next, record, &own, &authors) {
        Some(json) => Response::json(200, &json),
        None => synthesis_not_found(),
    }
}

// ---------------------------------------------------------------------------
// Media moments: located observations and quotations in a shared source (ADR 0062 to 0064)
// ---------------------------------------------------------------------------

/// Every refusal reads the same, so a request cannot confirm that a reflection, a moment or an
/// author exists.
fn moments_not_found() -> Response {
    Response::error(
        404,
        "That shared reflection was not found, or you cannot work on its moments.",
    )
}

/// The requester's own participant id once `SharedPublication::authorize` allows `EditMoments`.
fn moment_owner(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    session: &auth::Session,
) -> Option<String> {
    own_grant(
        transaction,
        record,
        session,
        AuthorizationAction::EditMoments,
    )
}

/// Participants who may hold moments now, decided per binding by the single entry point.
fn moment_authors(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
) -> Vec<String> {
    grant_holders(transaction, record, AuthorizationAction::EditMoments)
}

fn moment_json(moment: &Moment, record: &SharedPublication) -> Json {
    let notices: Vec<Json> = moment
        .quotation()
        .map(|quotation| quotation.notices())
        .unwrap_or_default()
        .into_iter()
        .map(|notice| json!({ "code": notice.code(), "message": notice.message() }))
        .collect();
    json!({
        "id": moment.id(),
        "source": moment.source(),
        "locators": moment.locators(),
        "location": location_text(moment.locators()),
        // The one attribution line every view uses (ADR 0065), built from the record as it is now.
        "attribution": moment.attribution(&record.sources).text(),
        "quotation": moment.quotation(),
        "notices": notices,
        "observation": moment.observation(),
        "intent": moment.intent(),
        "link": moment.link(&record.sources).map(|link| json!({ "href": link.href, "atTime": link.at_time })),
    })
}

/// The moments one author may see: their own (private and proposed alike), and the proposed
/// moments each other author revealed with the draft revision the requester may read now. Built
/// only after the requester was authorized; `MomentSet::own` and `MomentSet::revealed` decide
/// the rest, so nothing unrevealed or private to someone else is ever in it.
fn moments_json(
    set: &MomentSet,
    record: &SharedPublication,
    own: &str,
    authors: &[&str],
    drafts: Option<(&DraftSet, &[&str])>,
) -> Option<Json> {
    let mine: Vec<Json> = set
        .own(own, authors)
        .ok()?
        .into_iter()
        .map(|moment| moment_json(moment, record))
        .collect();
    let mut shared = Vec::new();
    for owner in authors.iter().filter(|owner| **owner != own) {
        // Only the owner's latest revision counts, exactly as the combined preview reads it.
        let readable = drafts.and_then(|(drafts, active)| {
            let view = drafts.view(own, owner, active).ok()?;
            let latest = drafts.current_stamp(owner)?;
            (view.stamp.number == latest.number).then_some(latest.number)
        });
        let moments = set
            .revealed(own, authors, owner, readable)
            .unwrap_or_default();
        if !moments.is_empty() {
            shared.push(json!({
                "participant": { "id": owner, "displayName": participant_name(record, owner) },
                "moments": moments.into_iter().map(|moment| moment_json(moment, record)).collect::<Vec<_>>(),
            }));
        }
    }
    let sources: Vec<Json> = record
        .sources
        .iter()
        .map(|source| {
            json!({
                "id": source.id,
                "kind": source.kind,
                "kindLabel": source.kind.label(),
                "title": source.title,
                "url": source.url.as_deref().and_then(openblog_core::collaboration::normalize_source_url),
            })
        })
        .collect();
    Some(json!({
        "revision": set.revision(),
        "moments": mine,
        "shared": shared,
        "sources": sources,
        "you": own,
        "quotationGuide": quotation_guide(),
    }))
}

/// The rights guidance and quotation thresholds, from the core definitions, so the panel's live
/// guidance and warnings say exactly what the preview says (ADR 0065). Holds no author text.
fn quotation_guide() -> Json {
    use openblog_core::media_moment::{
        QuotationNotice, QuotationRights, BRIEF_QUOTATION_CHARS, MAX_QUOTATION_CHARS,
        MAX_RIGHTS_NOTE_BYTES, RIGHTS_STATEMENT,
    };
    let notices: serde_json::Map<String, Json> = [
        QuotationNotice::NoSpeaker,
        QuotationNotice::Long,
        QuotationNotice::LongForBriefQuotation,
    ]
    .into_iter()
    .map(|notice| (notice.code().to_string(), json!(notice.message())))
    .collect();
    json!({
        "briefQuotationChars": BRIEF_QUOTATION_CHARS,
        "maxQuotationChars": MAX_QUOTATION_CHARS,
        "maxRightsNoteBytes": MAX_RIGHTS_NOTE_BYTES,
        "statement": RIGHTS_STATEMENT,
        "rights": QuotationRights::ALL
            .iter()
            .map(|rights| json!({ "value": rights.tag(), "label": rights.label(), "guidance": rights.guidance() }))
            .collect::<Vec<_>>(),
        "notices": notices,
    })
}

/// Read the stored moments with the drafts they are revealed against. Failures are logged without
/// content and reported as one message.
fn load_moment_state(
    state: &AppState,
    publication_id: &str,
    record: &SharedPublication,
) -> Result<(crate::shared_publications::StoredMoments, DraftSet), String> {
    let moments = crate::shared_publications::load_moments(&state.root, publication_id)?;
    let drafts = crate::shared_publications::load_drafts(&state.root, publication_id)?;
    let drafts = draft_set_for(drafts.set.as_ref(), record)
        .map_err(|_| "drafts are not usable".to_string())?;
    Ok((moments, drafts))
}

fn read_moments(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return moments_not_found();
    };
    let Ok(transaction) = invitation_transaction(state, publication_id) else {
        return moments_not_found();
    };
    let Some(record) = &transaction.record else {
        return moments_not_found();
    };
    let Some(own) = moment_owner(&transaction, record, session) else {
        return moments_not_found();
    };
    let (stored, drafts) = match load_moment_state(state, publication_id, record) {
        Ok(loaded) => loaded,
        Err(error) => {
            eprintln!("admin: moments not readable for {publication_id}: {error}");
            return Response::error(500, "The moments could not be read. Nothing was changed.");
        }
    };
    let authors = moment_authors(&transaction, record);
    let authors = authors.iter().map(String::as_str).collect::<Vec<_>>();
    let active = active_drafters(&transaction, record);
    let active = active.iter().map(String::as_str).collect::<Vec<_>>();
    match moments_json(
        &stored.set,
        record,
        &own,
        &authors,
        Some((&drafts, &active)),
    ) {
        Some(json) => Response::json(200, &json),
        None => moments_not_found(),
    }
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct MomentsRequest {
    publication_id: String,
    /// The set revision the caller read; any other revision is refused as a conflict.
    expected_revision: u64,
    change: MomentChange,
}

/// What a participant submits for one of their moments. The participant is the session's, never
/// a field: an unknown field (an identity, a credit, a link, a visibility flag) is refused.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct MomentBody {
    source: String,
    locators: Vec<openblog_core::research_notes::Locator>,
    #[serde(default)]
    quotation: Option<openblog_core::media_moment::Quotation>,
    #[serde(default)]
    observation: Option<String>,
    intent: openblog_core::media_moment::MomentIntent,
}

impl From<MomentBody> for openblog_core::media_moment::MomentInput {
    fn from(body: MomentBody) -> Self {
        Self {
            source: body.source,
            locators: body.locators,
            quotation: body.quotation,
            observation: body.observation,
            intent: body.intent,
        }
    }
}

#[derive(serde::Deserialize)]
#[serde(tag = "action", rename_all = "camelCase", deny_unknown_fields)]
enum MomentChange {
    Add { moment: MomentBody },
    Edit { id: String, moment: MomentBody },
    Remove { id: String },
}

/// A refused moment, naming the field or rule from the requester's own submission and never
/// repeating what was submitted.
fn moment_problem(error: openblog_core::media_moment::MomentError) -> Response {
    use openblog_core::media_moment::{MomentError, MomentField, MomentRule};
    let (field, message): (&str, String) = match error {
        MomentError::Denied => return moments_not_found(),
        MomentError::Stale => {
            return Response::error(
                409,
                "The moments changed since you read them. Reload to see the current moments; what you typed is still here and nothing was changed.",
            )
        }
        MomentError::Invalid(MomentField::Source) => ("source", "Choose one of this reflection's sources. A moment keeps its source: to locate another source, add a new moment.".into()),
        MomentError::Invalid(MomentField::Locators) => ("locators", "Give a location: a timestamp as seconds or h:mm:ss (such as 75 or 1:02:03), or a page, chapter, section, line or canonical reference, without surrounding spaces, brackets or semicolons. A range needs an end.".into()),
        MomentError::Invalid(MomentField::Quotation) => ("quotation", "Keep the quotation to 1,000 characters of text, without control or direction-override characters. Moments quote; they never hold a transcript.".into()),
        MomentError::Invalid(MomentField::Speaker) => ("speaker", "Write the speaker's name on one line, up to 200 bytes, without surrounding spaces.".into()),
        MomentError::Invalid(MomentField::Language) => ("language", "Use a language tag such as en or pt-BR.".into()),
        MomentError::Invalid(MomentField::RightsNote) => ("rightsNote", "Write the rights note on one line, up to 500 bytes, without surrounding spaces or control or direction-override characters.".into()),
        MomentError::Invalid(MomentField::Observation) => ("observation", "Keep the observation to 8 KiB of Markdown, without control or direction-override characters.".into()),
        MomentError::Invalid(MomentField::Content) => ("content", "Add a quotation, an observation, or both.".into()),
        MomentError::Invalid(MomentField::Limit) => ("", "This reflection has reached its limit of 100 moments, or the moments are too large to store. Nothing was changed.".into()),
        MomentError::Rule(rule) => (
            match rule {
                MomentRule::LocatorDoesNotFitSource => "locators",
                MomentRule::RightsUnknown => "rights",
                MomentRule::Markup => "observation",
            },
            format!("That moment has {}. Nothing was changed.", rule.describe()),
        ),
    };
    shared_problem(field, &message)
}

/// One change to the requester's own moments, against the revision they read. A refused or
/// failed change stores nothing; a stored one reconciles the piece's approvals in the same
/// transaction, because a moment proposed for the piece is part of what every approval binds.
fn change_moments(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<MomentsRequest>(&req.body) else {
        return shared_problem(
            "",
            "This request is not valid. Reload Admin Studio and try again.",
        );
    };
    let Ok(transaction) = invitation_transaction(state, &body.publication_id) else {
        return moments_not_found();
    };
    let Some(record) = &transaction.record else {
        return moments_not_found();
    };
    let Some(own) = moment_owner(&transaction, record, session) else {
        return moments_not_found();
    };
    let (stored, drafts) = match load_moment_state(state, &body.publication_id, record) {
        Ok(loaded) => loaded,
        Err(error) => {
            eprintln!(
                "admin: moments not readable for {}: {error}",
                body.publication_id
            );
            return Response::error(
                500,
                "The moments could not be changed. Nothing was changed.",
            );
        }
    };
    match is_published(state, &body.publication_id) {
        Ok(true) => return published_already(),
        Ok(false) => {}
        Err(response) => return response,
    }
    let authors = moment_authors(&transaction, record);
    let authors = authors.iter().map(String::as_str).collect::<Vec<_>>();
    let expected = body.expected_revision;
    let mut next = stored.set.clone();
    let result = match body.change {
        MomentChange::Add { moment } => next
            .add(&own, &authors, expected, &record.sources, moment.into())
            .map(|_| ()),
        MomentChange::Edit { id, moment } => next.edit(
            &own,
            &authors,
            expected,
            &record.sources,
            &id,
            moment.into(),
        ),
        MomentChange::Remove { id } => next.remove(&own, &authors, expected, &id),
    };
    if let Err(error) = result {
        return moment_problem(error);
    }
    if next != stored.set {
        match crate::shared_publications::replace_moments(
            &state.root,
            &body.publication_id,
            &stored,
            &next,
        ) {
            Ok(()) => {}
            Err(crate::shared_publications::ReplaceError::Conflict) => {
                return Response::error(
                    409,
                    "The moments changed while you were saving. Reload to see the current moments; what you typed is still here and nothing was changed.",
                )
            }
            Err(crate::shared_publications::ReplaceError::TooLarge) => {
                return moment_problem(openblog_core::media_moment::MomentError::Invalid(
                    openblog_core::media_moment::MomentField::Limit,
                ))
            }
            Err(crate::shared_publications::ReplaceError::Storage(error)) => {
                eprintln!("admin: moments not stored: {error}");
                return Response::error(
                    500,
                    "The moments could not be changed. Nothing was changed.",
                );
            }
        }
        reconcile_approvals(state, &transaction, record);
        eprintln!(
            "admin: moments changed in shared publication {}",
            body.publication_id
        );
    }
    let active = active_drafters(&transaction, record);
    let active = active.iter().map(String::as_str).collect::<Vec<_>>();
    match moments_json(&next, record, &own, &authors, Some((&drafts, &active))) {
        Some(json) => Response::json(200, &json),
        None => moments_not_found(),
    }
}

/// What became of the requester's proposed moments when they offered a revision.
#[derive(Debug, PartialEq, Eq)]
enum OfferedMoments {
    /// The moments as they are now go with the offered revision.
    Shared,
    /// That revision (or a newer one) was already sealed with other moments: a seal is write-once,
    /// so later changes stay private until a newer revision is offered.
    Changed,
    /// The moments could not be read or stored. Nothing about them changed and they stay private;
    /// offering the revision again seals them.
    Failed,
}

/// The sentence an offer's response carries when the moments could not be stored. It names no
/// moment and holds no author text.
const MOMENTS_NOT_SHARED: &str = "Your moments could not be shared with this revision, so they stay private. Take back your offer if it still stands, then offer this revision again to share them.";

/// Seal the requester's proposed moments to the draft revision they just offered (ADR 0063,
/// 0064), after the offer was stored. `None` when the requester holds no moments. A failure is
/// logged without content and leaves the moments unsealed, so it fails closed: they stay private.
fn seal_offered_moments(
    state: &AppState,
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    own: &str,
    revision: u64,
) -> Option<OfferedMoments> {
    let id = &record.publication_id;
    let authors = moment_authors(transaction, record);
    let authors = authors.iter().map(String::as_str).collect::<Vec<_>>();
    if !authors.contains(&own) {
        return None;
    }
    let stored = match crate::shared_publications::load_moments(&state.root, id) {
        Ok(stored) => stored,
        Err(error) => {
            eprintln!("admin: moments not sealed for {id}: {error}");
            return Some(OfferedMoments::Failed);
        }
    };
    let mut next = stored.set.clone();
    let sealed = match next.seal(own, &authors, revision) {
        Ok(sealed) => sealed,
        Err(error) => {
            eprintln!("admin: moments not sealed for {id}: {error}");
            return Some(OfferedMoments::Failed);
        }
    };
    if next != stored.set {
        if let Err(error) =
            crate::shared_publications::replace_moments(&state.root, id, &stored, &next)
        {
            eprintln!("admin: moments not sealed for {id}: {error:?}");
            return Some(OfferedMoments::Failed);
        }
    }
    Some(if sealed {
        OfferedMoments::Shared
    } else {
        OfferedMoments::Changed
    })
}

/// Drop approvals that no longer match after a change to the author set or the prose, in the
/// same transaction as that change, so removing and restoring an author or reverting an edit
/// cannot bring back consent given earlier. Validity is also recomputed on every read, so a
/// failure here still fails closed; it is logged without any content.
fn reconcile_approvals(
    state: &AppState,
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
) {
    let id = &record.publication_id;
    let result = (|| -> Result<(), String> {
        let stored = crate::shared_publications::load_approvals_for_update(&state.root, id)?;
        let drafts = load_reveal_drafts(state, id).map_err(|_| "drafts are not usable")?;
        let drafts =
            draft_set_for(drafts.set.as_ref(), record).map_err(|_| "drafts are not usable")?;
        // The synthesis follows the author set in the same write (ADR 0025): attribution to
        // someone who can no longer author it goes, and so does an item nobody speaks for.
        let mut synthesis = crate::shared_publications::load_synthesis(&state.root, id)?;
        let authors = synthesis_authors(transaction, record);
        let authors = authors.iter().map(String::as_str).collect::<Vec<_>>();
        let mut reconciled = synthesis.set.clone();
        if reconciled.reconcile(&authors) {
            crate::shared_publications::replace_synthesis(&state.root, id, &synthesis, &reconciled)
                .map_err(|_| "synthesis not stored".to_string())?;
            synthesis.set = reconciled;
        }
        // Moments follow the author set in the same way (ADR 0063): someone who can no longer
        // hold moments loses them and their seals, and restoring them brings neither back.
        let mut moments = crate::shared_publications::load_moments(&state.root, id)?;
        let holders = moment_authors(transaction, record);
        let holders = holders.iter().map(String::as_str).collect::<Vec<_>>();
        let mut kept = moments.set.clone();
        if kept.reconcile(&holders) {
            crate::shared_publications::replace_moments(&state.root, id, &moments, &kept)
                .map_err(|_| "moments not stored".to_string())?;
            moments.set = kept;
        }
        let active = active_drafters(transaction, record);
        let active = active.iter().map(String::as_str).collect::<Vec<_>>();
        let structure = crate::shared_publications::load_structure(&state.root, id)?;
        let mut next = stored.set.clone();
        let dropped = openblog_core::assembly::with_subject(
            record,
            structure.structure.as_ref(),
            &drafts,
            &synthesis.set,
            &moments.set,
            &active,
            |subject| next.reconcile(subject),
        );
        if matches!(dropped, Ok(count) if count > 0) {
            crate::shared_publications::replace_approvals(&state.root, id, &stored, &next)
                .map_err(|_| "approvals not stored".to_string())?;
        }
        Ok(())
    })();
    if let Err(error) = result {
        eprintln!("admin: approvals not reconciled for {id}: {error}");
    }
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct RevealPolicyRequest {
    publication_id: String,
    policy: RevealPolicy,
    /// The policy the requester read. When it is no longer current the change is refused, so two
    /// coordinators cannot overwrite each other unseen (ADR 0052). Required: a request that does
    /// not say what it replaces could silently overwrite a change made elsewhere.
    expected_policy: RevealPolicy,
    /// That the requester accepts that a real change clears every standing offer.
    #[serde(default)]
    confirmed: bool,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct RevealReadyRequest {
    publication_id: String,
    /// The exact revision of the caller's own draft to offer, or null to take the offer back.
    revision: Option<u64>,
}

/// Participants who currently hold the draft grant, decided by the single entry point for each
/// binding. A removed or downgraded member is absent, so they neither block nor join a reveal.
fn active_drafters(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
) -> Vec<String> {
    record
        .authorization
        .bindings
        .iter()
        .filter(|binding| {
            transaction
                .with_identities(|identities| {
                    record.authorize(
                        &binding.admin_user,
                        identities,
                        AuthorizationAction::EditDraft,
                        AuthorizationTarget::Participant(&binding.participant_id),
                    )
                })
                .is_ok()
        })
        .map(|binding| binding.participant_id.clone())
        .collect()
}

fn store_drafts(
    state: &AppState,
    publication_id: &str,
    stored: &crate::shared_publications::StoredDrafts,
    set: &DraftSet,
    success: Json,
) -> Response {
    match crate::shared_publications::replace_drafts(&state.root, publication_id, stored, set) {
        Ok(()) => Response::json(200, &success),
        Err(crate::shared_publications::ReplaceError::Conflict) => Response::error(
            409,
            "Sharing changed while you were saving. Reload to see the current state; nothing was changed.",
        ),
        Err(crate::shared_publications::ReplaceError::TooLarge) => draft_limit_problem(),
        Err(crate::shared_publications::ReplaceError::Storage(error)) => {
            eprintln!("admin: reveal state not stored: {error}");
            Response::error(500, "Sharing could not be changed. Nothing was changed.")
        }
    }
}

fn load_reveal_drafts(
    state: &AppState,
    publication_id: &str,
) -> Result<crate::shared_publications::StoredDrafts, Response> {
    crate::shared_publications::load_drafts(&state.root, publication_id).map_err(|error| {
        eprintln!("admin: drafts not readable for {publication_id}: {error}");
        Response::error(500, "Sharing could not be read. Nothing was changed.")
    })
}

/// Whether the signed-in user may choose the reveal policy, decided by the single entry point.
fn may_set_policy(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    session: &auth::Session,
) -> bool {
    transaction
        .with_identities(|identities| {
            record.authorize(
                &session.user,
                identities,
                AuthorizationAction::SetRevealPolicy,
                AuthorizationTarget::Publication,
            )
        })
        .is_ok()
}

/// The comparison for the signed-in participant: one slot per contract participant, in contract
/// order, each their own latest revision, a revision revealed to them, or a placeholder. A
/// coordinator who is not a drafter gets the policy only.
fn read_reveal_state(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return draft_not_found();
    };
    let Ok(transaction) = invitation_transaction(state, publication_id) else {
        return draft_not_found();
    };
    let Some(record) = &transaction.record else {
        return draft_not_found();
    };
    let own = draft_owner(&transaction, record, session);
    let coordinator = may_set_policy(&transaction, record, session);
    if own.is_none() && !coordinator {
        return draft_not_found();
    }
    let stored = match load_reveal_drafts(state, publication_id) {
        Ok(stored) => stored,
        Err(response) => return response,
    };
    let Ok(set) = draft_set_for(stored.set.as_ref(), record) else {
        return Response::error(500, "Sharing could not be read. Nothing was changed.");
    };
    let mut slots = Vec::new();
    let mut ready = false;
    if let Some(own) = &own {
        ready = set.is_ready(own);
        let participants = &record.collaboration.participants;
        let order = participants
            .iter()
            .map(|p| p.id.as_str())
            .collect::<Vec<_>>();
        let active = active_drafters(&transaction, record);
        let active = active.iter().map(String::as_str).collect::<Vec<_>>();
        let Ok(compared) = set.compare(own, &order, &active) else {
            return draft_not_found();
        };
        for (participant, slot) in participants.iter().zip(compared) {
            let (kind, view, offered) = match &slot {
                ComparisonSlot::Own(view) => ("own", Some(view), false),
                ComparisonSlot::Revealed(view) => ("revealed", Some(view), false),
                ComparisonSlot::Private { ready } => ("private", None, *ready),
            };
            slots.push(json!({
                "participantId": participant.id,
                "displayName": participant.display_name,
                "kind": kind,
                "ready": offered,
                "stamp": view.map(|v| &v.stamp),
                "markdown": view.map(|v| &v.markdown),
            }));
        }
    }
    Response::json(
        200,
        &json!({ "policy": set.policy(), "ready": ready, "slots": slots, "canSetPolicy": coordinator }),
    )
}

/// The combined review preview for an active author: every author's section at its exact current
/// revision where the signed-in author is entitled to it, with each author's approval state.
/// Read-only: it writes no draft, approval or content, and every refusal is the same not-found as
/// a missing publication, so it never says whether a publication or a draft exists.
fn read_combined_preview(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return draft_not_found();
    };
    let (transaction, own) = match draft_request_target(state, publication_id, session) {
        Ok(found) => found,
        Err(response) => return response,
    };
    let record = transaction.record.as_ref().expect("authorized record");
    let stored = match load_reveal_drafts(state, publication_id) {
        Ok(stored) => stored,
        Err(response) => return response,
    };
    let Ok(set) = draft_set_for(stored.set.as_ref(), record) else {
        return Response::error(500, "The preview could not be built. Nothing was changed.");
    };
    let approvals = match crate::shared_publications::load_approvals(&state.root, publication_id) {
        Ok(approvals) => approvals,
        Err(error) => {
            eprintln!("admin: approvals not readable for {publication_id}: {error}");
            return Response::error(500, "The preview could not be built. Nothing was changed.");
        }
    };
    let synthesis = match crate::shared_publications::load_synthesis(&state.root, publication_id) {
        Ok(stored) => stored.set,
        Err(error) => {
            eprintln!("admin: synthesis not readable for {publication_id}: {error}");
            return Response::error(500, "The preview could not be built. Nothing was changed.");
        }
    };
    let active = active_drafters(&transaction, record);
    let active = active.iter().map(String::as_str).collect::<Vec<_>>();
    let moments = match crate::shared_publications::load_moments(&state.root, publication_id) {
        Ok(stored) => stored.set,
        Err(error) => {
            eprintln!("admin: moments not readable for {publication_id}: {error}");
            return Response::error(500, "The preview could not be built. Nothing was changed.");
        }
    };
    let show_synthesis = synthesis_owner(&transaction, record, session).is_some();
    let config = site::load_config(&state.root).unwrap_or_default();
    let structure = match crate::shared_publications::load_structure(&state.root, publication_id) {
        Ok(structure) => structure,
        Err(error) => {
            eprintln!("admin: arrangement not readable for {publication_id}: {error}");
            return Response::error(500, "The preview could not be built. Nothing was changed.");
        }
    };
    let Ok(preview) = openblog_core::preview::build(
        record,
        structure.structure.as_ref(),
        &set,
        &synthesis,
        &moments,
        &approvals,
        &own,
        &active,
        show_synthesis,
        config.render_options(),
    ) else {
        return draft_not_found();
    };
    drop(transaction);
    // The document is served from its own address with its own policy, so a sandboxed frame can
    // show it without the Admin page's policy and without scripts, forms, images or fetches.
    let token = match auth::random_token() {
        Ok(token) => token,
        Err(error) => {
            eprintln!("admin: preview token unavailable: {error}");
            return Response::error(500, "The preview could not be built. Nothing was changed.");
        }
    };
    let mut summary = serde_json::to_value(&preview).unwrap_or(Json::Null);
    if let Some(object) = summary.as_object_mut() {
        object.remove("document");
        object.insert(
            "previewUrl".into(),
            json!(format!("/admin/api/preview/{token}")),
        );
    }
    let mut previews = lock(&state.previews);
    previews.push(PreviewDocument {
        token,
        html: preview.document,
        csp: openblog_core::preview::PREVIEW_CSP.to_string(),
    });
    if previews.len() > 16 {
        previews.remove(0);
    }
    Response::json(200, &json!({ "preview": summary }))
}

/// A coordinator chooses how drafts may be revealed, against the policy they read. A real change
/// needs an explicit confirmation, because it clears every standing offer; it reveals nothing.
/// Resubmitting the current policy is a no-op that writes nothing.
fn set_reveal_policy(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<RevealPolicyRequest>(&req.body) else {
        return shared_problem(
            "",
            "This sharing request is not valid. Reload Admin Studio and try again.",
        );
    };
    let Ok(transaction) = invitation_transaction(state, &body.publication_id) else {
        return draft_not_found();
    };
    let Some(record) = &transaction.record else {
        return draft_not_found();
    };
    if !may_set_policy(&transaction, record, session) {
        return draft_not_found();
    }
    let stored = match load_reveal_drafts(state, &body.publication_id) {
        Ok(stored) => stored,
        Err(response) => return response,
    };
    let Ok(mut set) = draft_set_for(stored.set.as_ref(), record) else {
        return Response::error(500, "Sharing could not be changed. Nothing was changed.");
    };
    if body.expected_policy != set.policy() {
        return Response::error(
            409,
            "The sharing rule changed since you loaded it. Reload to see the current rule; nothing was changed.",
        );
    }
    if body.policy == set.policy() {
        return Response::json(200, &json!({ "policy": set.policy(), "changed": false }));
    }
    if !body.confirmed {
        return shared_problem(
            "confirmed",
            "Confirm that changing the sharing rule clears every standing offer, so everyone offers again. Nothing was changed.",
        );
    }
    set.set_policy(body.policy);
    eprintln!(
        "admin: changed the reveal policy of shared publication {}",
        body.publication_id
    );
    store_drafts(
        state,
        &body.publication_id,
        &stored,
        &set,
        json!({ "policy": set.policy(), "changed": true }),
    )
}

// ---------------------------------------------------------------------------
// The approval rule of a shared reflection (ADR 0052)
// ---------------------------------------------------------------------------

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct ApprovalPolicyRequest {
    publication_id: String,
    /// The policy revision the requester read.
    expected_revision: u64,
    policy: openblog_core::approval::ApprovalPolicy,
    /// That the requester accepts that a real change clears every standing approval.
    #[serde(default)]
    confirmed: bool,
}

/// Every refusal reads the same, so a request cannot confirm that a reflection exists.
fn approval_policy_not_found() -> Response {
    Response::error(
        404,
        "That shared reflection was not found, or you cannot choose its approval rule.",
    )
}

/// Whether the signed-in user may choose the approval rule, decided by the single entry point,
/// and under whose authority: only a site owner may drop someone the rule requires (ADR 0052).
fn approval_rule_authority(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    session: &auth::Session,
) -> Option<openblog_core::approval::RuleAuthority> {
    use openblog_core::approval::RuleAuthority;
    transaction
        .with_identities(|identities| {
            record
                .authorize(
                    &session.user,
                    identities,
                    AuthorizationAction::SetApprovalPolicy,
                    AuthorizationTarget::Publication,
                )
                .map(|binding| {
                    if binding.roles.contains(&AuthorizationRole::SiteOwner) {
                        RuleAuthority::SiteOwner
                    } else {
                        RuleAuthority::Coordinator
                    }
                })
        })
        .ok()
}

/// Active authors who hold the approve grant for themselves: the only people a named or
/// role-based rule may add, because nobody else can ever approve.
fn active_approvers(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    active: &[String],
) -> Vec<String> {
    record
        .authorization
        .bindings
        .iter()
        .filter(|binding| active.contains(&binding.participant_id))
        .filter(|binding| {
            transaction
                .with_identities(|identities| {
                    record.authorize(
                        &binding.admin_user,
                        identities,
                        AuthorizationAction::ApproveContribution,
                        AuthorizationTarget::Participant(&binding.participant_id),
                    )
                })
                .is_ok()
        })
        .map(|binding| binding.participant_id.clone())
        .collect()
}

/// The rule and where the piece stands under it, for someone who holds the policy grant (who
/// also holds the publish grant, so may already learn who has not approved, ADR 0022). Display
/// names and roles only: no prose, revision or digest.
fn approval_policy_json(
    record: &SharedPublication,
    inputs: &GateInputs,
    set: &openblog_core::approval::ApprovalSet,
    approvers: &[String],
) -> Json {
    use openblog_core::assembly::{display_names, with_subject};
    let active = inputs.active.iter().map(String::as_str).collect::<Vec<_>>();
    let (rule, required, missing) = with_subject(
        record,
        inputs.structure.structure.as_ref(),
        &inputs.drafts,
        &inputs.synthesis,
        &inputs.moments,
        &active,
        |subject| {
            let required = set.required(subject);
            let missing = required
                .iter()
                .filter(|id| !set.is_approved(subject, id))
                .cloned()
                .collect::<Vec<_>>();
            (
                openblog_core::preview::rule_for(record, set, subject),
                required,
                missing,
            )
        },
    );
    let people = record
        .collaboration
        .participants
        .iter()
        .filter(|participant| approvers.contains(&participant.id))
        .map(|participant| {
            json!({ "participantId": participant.id, "displayName": participant.display_name })
        })
        .collect::<Vec<_>>();
    // People the rule names who can no longer approve (removed, or without the approve grant),
    // so Admin can show them as chosen and let them be cleared instead of keeping them unseen.
    let former = match &set.policy().requirement {
        openblog_core::approval::ApprovalRequirement::NamedAuthors(named) => named
            .iter()
            .filter(|id| !approvers.contains(id))
            .map(|id| {
                let name = record
                    .collaboration
                    .participants
                    .iter()
                    .find(|participant| &participant.id == id)
                    .map_or("Someone no longer in this reflection", |participant| {
                        participant.display_name.as_str()
                    });
                json!({ "participantId": id, "displayName": name })
            })
            .collect::<Vec<_>>(),
        _ => Vec::new(),
    };
    json!({
        "policy": rule.policy,
        "revision": rule.revision,
        "summary": rule.summary,
        "unmetNamed": rule.unmet_named,
        "unmetRoles": rule.unmet_roles,
        "required": display_names(record, required.iter().map(String::as_str)),
        "missing": display_names(record, missing.iter().map(String::as_str)),
        "approvers": people,
        "formerApprovers": former,
        "published": matches!(
            inputs.outcome.outcome,
            Some(openblog_core::assembly::Outcome::Published { .. })
        ),
    })
}

/// The approval rule, for a site owner or coordinator. Everyone else gets the same not-found as
/// a missing publication; authors see the rule in the combined preview.
fn read_approval_policy(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return approval_policy_not_found();
    };
    let Ok(transaction) = invitation_transaction(state, publication_id) else {
        return approval_policy_not_found();
    };
    let Some(record) = transaction.record.clone() else {
        return approval_policy_not_found();
    };
    let Some(authority) = approval_rule_authority(&transaction, &record, session) else {
        return approval_policy_not_found();
    };
    let inputs = match gate_inputs(state, &transaction, &record) {
        Ok(inputs) => inputs,
        Err(response) => return response,
    };
    let approvers = active_approvers(&transaction, &record, &inputs.active);
    let mut response = approval_policy_json(&record, &inputs, &inputs.approvals.set, &approvers);
    if let Some(object) = response.as_object_mut() {
        object.insert(
            "mayDropApprovers".into(),
            json!(authority == openblog_core::approval::RuleAuthority::SiteOwner),
        );
    }
    Response::json(200, &response)
}

/// A site owner or coordinator changes whose approval publication needs, against the policy
/// revision they read and with an explicit confirmation, because a real change clears every
/// standing approval. The change is written with a compare-and-swap, so a concurrent approval or
/// policy change is a conflict, never an overwrite, and the response re-evaluates the piece
/// under the new rule. It records no approval for anyone.
fn set_approval_policy(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    use openblog_core::approval::{role_with_article, PolicyChange, PolicyError};
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<ApprovalPolicyRequest>(&req.body) else {
        return shared_problem(
            "policy",
            "This approval rule is not valid. Reload Admin Studio and try again.",
        );
    };
    let Ok(transaction) = invitation_transaction(state, &body.publication_id) else {
        return approval_policy_not_found();
    };
    let Some(record) = transaction.record.clone() else {
        return approval_policy_not_found();
    };
    let Some(authority) = approval_rule_authority(&transaction, &record, session) else {
        return approval_policy_not_found();
    };
    let inputs = match gate_inputs(state, &transaction, &record) {
        Ok(inputs) => inputs,
        Err(response) => return response,
    };
    if matches!(
        inputs.outcome.outcome,
        Some(openblog_core::assembly::Outcome::Published { .. })
    ) {
        return published_already();
    }
    let approvers = active_approvers(&transaction, &record, &inputs.active);
    let approver_ids = approvers.iter().map(String::as_str).collect::<Vec<_>>();
    let active = inputs.active.iter().map(String::as_str).collect::<Vec<_>>();
    let mut next = inputs.approvals.set.clone();
    let result = openblog_core::assembly::with_subject(
        &record,
        inputs.structure.structure.as_ref(),
        &inputs.drafts,
        &inputs.synthesis,
        &inputs.moments,
        &active,
        |subject| {
            next.change_policy(
                body.policy.clone(),
                body.expected_revision,
                body.confirmed,
                authority,
                subject,
                &approver_ids,
            )
        },
    );
    let cleared = match result {
        Ok(PolicyChange::Unchanged) => None,
        Ok(PolicyChange::Changed { cleared }) => Some(cleared),
        Err(PolicyError::Stale) => {
            return Response::error(
                409,
                "The approval rule changed since you loaded it. Reload to see the current rule; nothing was changed.",
            )
        }
        Err(PolicyError::Invalid) => {
            return shared_problem(
                "policy",
                "Choose at least one person or role, each only once. Nothing was changed.",
            )
        }
        Err(PolicyError::Unconfirmed) => {
            return shared_problem(
                "confirmed",
                "Confirm that changing the rule clears every approval, so every required author approves again. Nothing was changed.",
            )
        }
        Err(PolicyError::DropsApprovers(dropped)) => {
            let names = openblog_core::assembly::display_names(
                &record,
                dropped.iter().map(String::as_str),
            );
            let who = if names.is_empty() {
                "someone the current rule requires".to_string()
            } else {
                names.join(", ")
            };
            return Response::json(
                403,
                &json!({
                    "error": format!(
                        "Only a site owner can change the rule so that {who} no longer has to approve. You can keep or add people who must approve. Nothing was changed."
                    ),
                    "field": "policy",
                }),
            );
        }
        Err(PolicyError::Unmeetable(gaps)) => {
            let mut problems = Vec::new();
            let names = openblog_core::assembly::display_names(
                &record,
                gaps.named.iter().map(String::as_str),
            );
            let unknown = gaps.named.len() - names.len();
            if !names.is_empty() {
                problems.push(format!("{} cannot approve this piece", names.join(", ")));
            }
            if unknown > 0 {
                problems.push("a chosen person is not part of this reflection".to_string());
            }
            for role in &gaps.roles {
                problems.push(format!("no author is {}", role_with_article(*role)));
            }
            return shared_problem(
                "policy",
                &format!(
                    "This rule could never be met: {}. Only authors with the contributor role can approve. Nothing was changed.",
                    problems.join("; ")
                ),
            );
        }
    };
    if cleared.is_some() {
        if let Err(error) = crate::shared_publications::replace_approvals(
            &state.root,
            &body.publication_id,
            &inputs.approvals,
            &next,
        ) {
            return publish_store_problem(error);
        }
        eprintln!(
            "admin: changed the approval rule of shared publication {}",
            body.publication_id
        );
    }
    let mut response = approval_policy_json(&record, &inputs, &next, &approvers);
    if let Some(object) = response.as_object_mut() {
        object.insert("changed".into(), json!(cleared.is_some()));
        object.insert("cleared".into(), json!(cleared.unwrap_or(0)));
    }
    Response::json(200, &response)
}

// ---------------------------------------------------------------------------
// Layout and arrangement of a shared reflection (ADR 0031)
// ---------------------------------------------------------------------------

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct ArrangementRequest {
    publication_id: String,
    /// The revision of the arrangement the caller read: 0 when none was stored.
    expected_revision: u64,
    structure: Json,
}

/// The layouts the Admin offers, with plain labels.
fn arrangement_layouts() -> Json {
    json!([
        { "value": "sequential", "label": "Sequential", "help": "One section after another, in reading order." },
        { "value": "sideBySide", "label": "Side by side", "help": "Sections sit in columns on wide screens and read one after another on narrow ones." },
        { "value": "pointCounterpoint", "label": "Point and counterpoint", "help": "Two columns on wide screens when exactly two people take part; with three or more it reads as one column. Optional labels are yours; nothing is implied about who agrees." },
        { "value": "alternatingDialogue", "label": "Alternating dialogue", "help": "Turns alternate like a conversation on wide screens, switching side when the speaker changes, each under its author's name." },
        { "value": "roundtable", "label": "Roundtable", "help": "Turns sit in a grid that fits any number of participants and reads in the same order." },
    ])
}

/// Whether the signed-in user may arrange the reflection, decided by the single entry point.
fn may_arrange(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    session: &auth::Session,
) -> bool {
    transaction
        .with_identities(|identities| {
            record.authorize(
                &session.user,
                identities,
                AuthorizationAction::ArrangeReflection,
                AuthorizationTarget::Publication,
            )
        })
        .is_ok()
}

/// The stored arrangement, who is in the piece, and whether the caller may change it. It holds no
/// prose, no part counts and no draft state, so any member may read it; everyone else gets the
/// same not-found as a missing publication.
fn read_arrangement(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return draft_not_found();
    };
    let Ok(transaction) = invitation_transaction(state, publication_id) else {
        return draft_not_found();
    };
    let Some(record) = &transaction.record else {
        return draft_not_found();
    };
    let member = transaction
        .with_identities(|identities| {
            record.authorize(
                &session.user,
                identities,
                AuthorizationAction::ViewPublication,
                AuthorizationTarget::Publication,
            )
        })
        .is_ok();
    if !member {
        return draft_not_found();
    }
    let stored = match crate::shared_publications::load_structure(&state.root, publication_id) {
        Ok(stored) => stored,
        Err(error) => {
            eprintln!("admin: arrangement not readable for {publication_id}: {error}");
            return Response::error(
                500,
                "The arrangement could not be read. Nothing was changed.",
            );
        }
    };
    let participants: Vec<Json> = record
        .collaboration
        .participants
        .iter()
        .map(|p| json!({ "id": p.id, "displayName": p.display_name }))
        .collect();
    Response::json(
        200,
        &json!({
            "structure": stored.structure,
            "participants": participants,
            "layouts": arrangement_layouts(),
            "canArrange": may_arrange(&transaction, record, session),
        }),
    )
}

/// A coordinator stores the layout and arrangement. The write names the revision it was built on
/// and is refused if another write got there first. It does not read a draft, so it cannot tell
/// the coordinator whether a part exists; a stale reference is caught by the combined preview and
/// the publish gate. Standing approvals that no longer match are dropped in the same request.
fn save_arrangement(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    use openblog_core::reflection::{ReflectionError, ReflectionStructure};
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<ArrangementRequest>(&req.body) else {
        return shared_problem(
            "",
            "This arrangement request is not valid. Reload Admin Studio and try again.",
        );
    };
    let Ok(transaction) = invitation_transaction(state, &body.publication_id) else {
        return draft_not_found();
    };
    let Some(record) = transaction.record.clone() else {
        return draft_not_found();
    };
    if !may_arrange(&transaction, &record, session) {
        return draft_not_found();
    }
    if matches!(
        crate::shared_publications::load_outcome(&state.root, &body.publication_id)
            .map(|stored| stored.outcome),
        Ok(Some(openblog_core::assembly::Outcome::Published { .. }))
    ) {
        return published_already();
    }
    let stored = match crate::shared_publications::load_structure(&state.root, &body.publication_id)
    {
        Ok(stored) => stored,
        Err(error) => {
            eprintln!(
                "admin: arrangement not readable for {}: {error}",
                body.publication_id
            );
            return Response::error(
                500,
                "The arrangement could not be saved. Nothing was changed.",
            );
        }
    };
    let current = stored.structure.as_ref().map_or(0, |s| s.revision);
    if current != body.expected_revision {
        return Response::error(
            409,
            "The arrangement changed while you were editing it. Reload to see the current one; nothing was changed.",
        );
    }
    let invalid = || {
        shared_problem(
            "structure",
            "That arrangement is not valid. Use one or more rounds, each with turns that name a participant and a part, and keep round prompts short and on one line.",
        )
    };
    let Ok(source) = serde_json::to_string(&body.structure) else {
        return invalid();
    };
    let next = match &stored.structure {
        Some(existing) => existing.replace_from_json(&source, body.expected_revision),
        None => ReflectionStructure::from_json(&source).and_then(|next| {
            if next.revision == 1 {
                Ok(next)
            } else {
                Err(ReflectionError::Invalid)
            }
        }),
    };
    let Ok(next) = next else {
        return invalid();
    };
    let known = |id: &str| {
        record
            .collaboration
            .participants
            .iter()
            .any(|p| p.id.eq_ignore_ascii_case(id))
    };
    if !next
        .rounds
        .iter()
        .flat_map(|r| &r.turns)
        .all(|t| known(&t.draft))
    {
        return invalid();
    }
    match crate::shared_publications::replace_structure(
        &state.root,
        &body.publication_id,
        &stored,
        &next,
    ) {
        Ok(()) => {}
        Err(crate::shared_publications::ReplaceError::Conflict) => {
            return Response::error(
                409,
                "The arrangement changed while you were saving. Reload to see the current one; nothing was changed.",
            )
        }
        Err(crate::shared_publications::ReplaceError::TooLarge) => return invalid(),
        Err(crate::shared_publications::ReplaceError::Storage(error)) => {
            eprintln!("admin: arrangement not stored: {error}");
            return Response::error(500, "The arrangement could not be saved. Nothing was changed.");
        }
    }
    reconcile_approvals(state, &transaction, &record);
    eprintln!(
        "admin: arranged shared publication {} at revision {}",
        body.publication_id, next.revision
    );
    Response::json(200, &json!({ "structure": next }))
}

/// A drafter offers one exact revision of their own draft, or takes the offer back. When the
/// policy condition is met the same write commits the reveal for everyone involved.
fn set_reveal_ready(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<RevealReadyRequest>(&req.body) else {
        return shared_problem(
            "",
            "This sharing request is not valid. Reload Admin Studio and try again.",
        );
    };
    let (transaction, own) = match draft_request_target(state, &body.publication_id, session) {
        Ok(found) => found,
        Err(response) => return response,
    };
    let record = transaction.record.as_ref().expect("authorized record");
    let stored = match load_reveal_drafts(state, &body.publication_id) {
        Ok(stored) => stored,
        Err(response) => return response,
    };
    let Ok(mut set) = draft_set_for(stored.set.as_ref(), record) else {
        return Response::error(500, "Sharing could not be changed. Nothing was changed.");
    };
    let active = active_drafters(&transaction, record);
    let active = active.iter().map(String::as_str).collect::<Vec<_>>();
    let outcome = match body.revision {
        Some(revision) => set.mark_ready(&own, revision, &active),
        None => set
            .unready(&own)
            .map(|()| ReadyOutcome::Waiting { waiting_for: 0 }),
    };
    let success = match outcome {
        Ok(ReadyOutcome::Revealed) => json!({ "ready": false, "revealed": true }),
        Ok(ReadyOutcome::Waiting { waiting_for }) => json!({
            "ready": body.revision.is_some(),
            "revealed": false,
            "waitingFor": if body.revision.is_some() { json!(waiting_for) } else { Json::Null },
        }),
        Err(DraftError::Invalid) => {
            return shared_problem(
                "revision",
                "Sharing is off for this reflection. Ask a coordinator to turn it on first.",
            )
        }
        Err(DraftError::LimitReached) => return draft_limit_problem(),
        Err(_) => return draft_not_found(),
    };
    eprintln!(
        "admin: reveal readiness changed in shared publication {}",
        body.publication_id
    );
    let mut success = success;
    let stored_response = store_drafts(state, &body.publication_id, &stored, &set, Json::Null);
    if stored_response.status != 200 {
        return stored_response;
    }
    // The offer is stored, so the proposed moments go with exactly this revision. Sealing after
    // the offer fails closed: if it cannot be written the moments simply stay private.
    if let Some(revision) = body.revision {
        let sealed = seal_offered_moments(state, &transaction, record, &own, revision);
        if let (Some(sealed), Some(object)) = (sealed, success.as_object_mut()) {
            match sealed {
                OfferedMoments::Shared => object.insert("momentsShared".into(), json!(true)),
                OfferedMoments::Changed => object.insert("momentsShared".into(), json!(false)),
                OfferedMoments::Failed => {
                    object.insert("momentsShared".into(), Json::Null);
                    object.insert("momentsNote".into(), json!(MOMENTS_NOT_SHARED))
                }
            };
        }
    }
    Response::json(200, &success)
}

// ---------------------------------------------------------------------------
// Series placement (ADR 0038, ADR 0039)
// ---------------------------------------------------------------------------

/// Every refusal to read or arrange a publication's series, whatever the reason.
fn series_not_found() -> Response {
    Response::error(
        404,
        "That shared reflection was not found, or you cannot see or arrange its series.",
    )
}

fn series_problem(field: &str, error: openblog_core::shared_series::SeriesError) -> Response {
    use openblog_core::shared_series::SeriesError;
    match error {
        SeriesError::Reference => shared_problem(
            field,
            "Use a series title with visible text, up to 120 bytes, on one line.",
        ),
        SeriesError::NoAddress => {
            shared_problem(field, "A series title needs at least one letter or digit.")
        }
    }
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct PlacementBody {
    series: String,
    #[serde(default)]
    order: Option<u32>,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct PlacementRequest {
    publication_id: String,
    expected_revision: u64,
    placement: Option<PlacementBody>,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct SeriesCreateRequest {
    publication_id: String,
    title: String,
    #[serde(default)]
    premise: String,
}

fn may(
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    session: &auth::Session,
    action: AuthorizationAction,
) -> bool {
    transaction
        .with_identities(|identities| {
            record.authorize(
                &session.user,
                identities,
                action,
                AuthorizationTarget::Publication,
            )
        })
        .is_ok()
}

fn is_published(state: &AppState, publication_id: &str) -> Result<bool, Response> {
    crate::shared_publications::load_outcome(&state.root, publication_id)
        .map(|stored| {
            matches!(
                stored.outcome,
                Some(openblog_core::assembly::Outcome::Published { .. })
            )
        })
        .map_err(|error| publish_failed(&error))
}

/// What a participant sees about the placement: the stored choice, the public series to choose
/// from, and the reading order a placement would produce. Everything except the placement is
/// read from the public site (no drafts, nothing scheduled), so no other publication's unsaved
/// collaboration state can appear in it.
fn series_view(
    state: &AppState,
    transaction: &InvitationTransaction<'_>,
    record: &SharedPublication,
    session: &auth::Session,
    preview_of: Option<&openblog_core::shared_series::SeriesPlacement>,
) -> Response {
    let published = match is_published(state, &record.publication_id) {
        Ok(published) => published,
        Err(response) => return response,
    };
    let site = match site::load_site(&state.root, false, Some(clock::now())) {
        Ok((site, _)) => site,
        Err(error) => {
            eprintln!("admin: series list unavailable: {error}");
            return Response::error(
                500,
                "The site's series could not be read. Nothing was changed.",
            );
        }
    };
    let preview = preview_of
        .or(record.series.as_ref())
        .map(|placement| openblog_core::shared_series::order_preview(&site, placement, !published));
    Response::json(
        200,
        &json!({
            "revision": record.series_revision,
            "placement": record.series,
            "canPlace": !published && may(transaction, record, session, AuthorizationAction::PlaceInSeries),
            "canCreate": may(transaction, record, session, AuthorizationAction::CreateSeries),
            "published": published,
            "series": openblog_core::shared_series::series_choices(&site),
            "preview": preview,
        }),
    )
}

/// Any participant reads the placement. `series` and `order` in the query preview another
/// choice without storing it.
fn read_series(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    let Some(publication_id) = req.query.get("publicationId") else {
        return series_not_found();
    };
    let Ok(transaction) = invitation_transaction(state, publication_id) else {
        return series_not_found();
    };
    let Some(record) = &transaction.record else {
        return series_not_found();
    };
    if !may(
        &transaction,
        record,
        session,
        AuthorizationAction::ViewPublication,
    ) {
        return series_not_found();
    }
    let candidate = match req.query.get("series") {
        None => None,
        Some(series) => {
            let order =
                match req.query.get("order").map(String::as_str) {
                    None | Some("") => None,
                    Some(order) => match order.parse::<u32>() {
                        Ok(order) => Some(order),
                        Err(_) => return shared_problem(
                            "order",
                            "Use a whole number of 0 or more for the position, or leave it empty.",
                        ),
                    },
                };
            match openblog_core::shared_series::SeriesPlacement::new(series, order) {
                Ok(placement) => Some(placement),
                Err(error) => return series_problem("series", error),
            }
        }
    };
    series_view(state, &transaction, record, session, candidate.as_ref())
}

/// A site owner or coordinator sets, changes or removes the placement against the revision they
/// read. The placement is public output bound into every approval, so approvals are reconciled
/// in the same write (ADR 0038). A refused change stores nothing.
fn set_series(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    use openblog_core::shared_series::{PlacementError, SeriesPlacement};
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<PlacementRequest>(&req.body) else {
        return shared_problem(
            "",
            "This series request is not valid. Use a whole number of 0 or more for the position, then try again.",
        );
    };
    let Ok(transaction) = invitation_transaction(state, &body.publication_id) else {
        return series_not_found();
    };
    let Some(record) = &transaction.record else {
        return series_not_found();
    };
    if !may(
        &transaction,
        record,
        session,
        AuthorizationAction::PlaceInSeries,
    ) {
        return series_not_found();
    }
    match is_published(state, &body.publication_id) {
        Ok(true) => return published_already(),
        Ok(false) => {}
        Err(response) => return response,
    }
    let placement = match body.placement {
        None => None,
        Some(placement) => match SeriesPlacement::new(&placement.series, placement.order) {
            Ok(placement) => Some(placement),
            Err(error) => return series_problem("series", error),
        },
    };
    let result = transaction.with_identities(|identities| {
        record.place_in_series(&session.user, identities, placement, body.expected_revision)
    });
    let next = match result {
        Ok(next) => next,
        Err(PlacementError::Denied) => return series_not_found(),
        Err(PlacementError::Stale) => {
            return Response::error(
                409,
                "The series placement changed while you were working. Reload to see the current choice; nothing was changed.",
            )
        }
        Err(PlacementError::Invalid(error)) => return series_problem("series", error),
    };
    if next != *record {
        if let Err(response) = transaction.store(&state.root, &next) {
            return response;
        }
        reconcile_approvals(state, &transaction, &next);
        eprintln!(
            "admin: series placement changed in shared publication {}",
            body.publication_id
        );
    }
    series_view(state, &transaction, &next, session, None)
}

/// A site owner adds a new series definition: its name and recurring premise. It is ordinary
/// site content, validated and built like a save from the Series editor, and it places nothing.
fn create_series(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    use openblog_core::shared_series::{series_definition, DefinitionError};
    if let Err(response) = require_json(req) {
        return response;
    }
    let Ok(body) = serde_json::from_slice::<SeriesCreateRequest>(&req.body) else {
        return shared_problem(
            "",
            "This series request is not valid. Reload Admin Studio and try again.",
        );
    };
    let mut status = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let Ok(config) = site::load_config(&state.root) else {
        return series_not_found();
    };
    let Ok((admin_users, contributor_ids)) = collaboration_identities(&state.root, &config) else {
        return series_not_found();
    };
    let Ok(Some(record)) = crate::shared_publications::load(&state.root, &body.publication_id)
    else {
        return series_not_found();
    };
    let admin_users = admin_users.iter().map(String::as_str).collect::<Vec<_>>();
    let contributor_ids = contributor_ids
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    let identities = Identities {
        active_admin_users: &admin_users,
        contributor_ids: &contributor_ids,
    };
    if record
        .authorize(
            &session.user,
            &identities,
            AuthorizationAction::CreateSeries,
            AuthorizationTarget::Publication,
        )
        .is_err()
    {
        return series_not_found();
    }
    let definition = match series_definition(&body.title, &body.premise) {
        Ok(definition) => definition,
        Err(DefinitionError::Title(error)) => return series_problem("title", error),
        Err(DefinitionError::Premise) => {
            return shared_problem(
                "premise",
                "Keep the premise to one line of up to 500 bytes, without control characters.",
            )
        }
    };
    let exists = || {
        Response::error(
            409,
            "A series with that address already exists. Choose it from the list instead; its name and premise are edited under Series.",
        )
    };
    let path = match resolve_content_path(&state.root, &config, &definition.path) {
        Ok(path) => path,
        Err(_) => {
            return shared_problem(
                "title",
                "That title cannot name a series file. Shorten it or use plainer characters.",
            )
        }
    };
    if path.exists() {
        return exists();
    }
    match site::load_site(&state.root, true, None) {
        Ok((site, _)) => {
            if site
                .series_by_slug(&definition.slug)
                .is_some_and(|series| series.source.is_some())
            {
                return exists();
            }
        }
        Err(error) => return Response::error(500, &error),
    }
    if let Err(problems) = validate_candidate(
        &state.root,
        &config,
        &definition.path,
        &definition.source,
        &CreditEdit::Unchanged,
    ) {
        return Response::json(
            422,
            &json!({ "error": "This series can't be created yet.", "problems": problems }),
        );
    }
    if let Err(error) = write_atomic(&path, &definition.source) {
        eprintln!("admin: series definition not written: {error}");
        return Response::error(500, "The series could not be created. Nothing was changed.");
    }
    let build = state.rebuild_locked(&mut status);
    eprintln!("admin: created {}", definition.path);
    let name = openblog_core::shared_series::SeriesPlacement::new(&body.title, None)
        .map(|placement| placement.series)
        .unwrap_or_default();
    state_arc(state).auto_publish(name.clone());
    Response::json(
        201,
        &json!({
            "slug": definition.slug,
            "name": name,
            "path": definition.path,
            "build": { "ok": build.is_ok() },
        }),
    )
}

/// No room for another revision. Saved revisions are intact; only this change was refused.
fn draft_limit_problem() -> Response {
    shared_problem(
        "markdown",
        "This draft has reached its limit of saved revisions or storage, so this change was not saved. Your earlier revisions are intact; keep a copy of your latest text.",
    )
}

fn change_member_roles(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    change_member(state, req, session, false)
}

fn remove_member(state: &AppState, req: &Request, session: &auth::Session) -> Response {
    change_member(state, req, session, true)
}

/// Accepting and declining only need the token. Every attempt counts against a per-account
/// limit and a success refunds it, so guessing tokens is bounded without locking a real invitee
/// out for long.
fn answer_invitation(
    state: &AppState,
    req: &Request,
    session: &auth::Session,
    accept: bool,
) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let key = format!("invitation:{}", session.user);
    if let Err(wait) = lock(&state.throttle).reserve(&key) {
        return Response::error(
            429,
            &format!("Too many invitation attempts. Try again in {wait} seconds."),
        )
        .with_header("Retry-After", &wait.to_string());
    }
    let Ok(body) = serde_json::from_slice::<InvitationTokenRequest>(&req.body) else {
        return Response::error(400, INVITATION_UNAVAILABLE);
    };
    let Some(publication_id) = openblog_core::invitation::token_publication_id(&body.token) else {
        return Response::error(400, INVITATION_UNAVAILABLE);
    };
    let transaction = match invitation_transaction(state, publication_id) {
        Ok(transaction) => transaction,
        Err(response) => return response,
    };
    let Some(record) = &transaction.record else {
        return Response::error(400, INVITATION_UNAVAILABLE);
    };
    let now = clock::now().unix();
    let result = if accept {
        match transaction.contributors.get(&body.contributor_id) {
            Some(display_name) => transaction.with_identities(|identities| {
                record.accept_invitation(
                    &session.user,
                    identities,
                    &body.token,
                    &body.contributor_id,
                    display_name,
                    now,
                )
            }),
            None => Err(InvitationError::Unavailable),
        }
    } else {
        record.decline_invitation(&session.user, &body.token, now)
    };
    let next = match result {
        Ok(next) => next,
        Err(error) => return invitation_problem(error),
    };
    if let Err(response) = transaction.store(&state.root, &next) {
        return response;
    }
    lock(&state.throttle).clear(&key);
    if accept {
        reconcile_approvals(state, &transaction, &next);
    }
    eprintln!(
        "admin: {} a shared publication invitation for {publication_id}",
        if accept { "accepted" } else { "declined" }
    );
    if !accept {
        return Response::json(200, &json!({ "declined": true }));
    }
    let roles = next
        .authorization
        .bindings
        .iter()
        .find(|binding| binding.admin_user == session.user)
        .map(|binding| binding.roles.clone())
        .unwrap_or_default();
    Response::json(
        200,
        &json!({ "publication": shared_publication_summary(&next, &roles) }),
    )
}

// ---------------------------------------------------------------------------
// Writing
// ---------------------------------------------------------------------------

enum CreditEdit {
    Unchanged,
    Remove,
    Set(String),
}

fn credit_sidecar_contents(value: &Json) -> Result<Option<String>, String> {
    if value.is_null() {
        return Ok(None);
    }
    let credits = value.as_array().ok_or("credits must be an array or null")?;
    if credits.len() > 100 {
        return Err("credits has too many contributors".into());
    }
    serde_json::to_string_pretty(&json!({ "version": 1, "credits": credits }))
        .map(Some)
        .map_err(|error| format!("cannot serialize credits: {error}"))
}

fn requested_credit_edit(body: &Json, kind: &str) -> Result<CreditEdit, String> {
    let Some(object) = body.as_object() else {
        return Err("request body must be an object".into());
    };
    let Some(credits) = object.get("credits") else {
        return Ok(CreditEdit::Unchanged);
    };
    if kind != "posts" {
        return Err("credits are only available for posts".into());
    }
    match credit_sidecar_contents(credits)? {
        Some(contents) => Ok(CreditEdit::Set(contents)),
        None => Ok(CreditEdit::Remove),
    }
}

fn apply_credit_edit_to_sources(
    sources: &mut openblog_core::Sources,
    rel: &str,
    edit: &CreditEdit,
) {
    let Some(sidecar_path) = openblog_core::contributor::sidecar_path(rel) else {
        return;
    };
    if matches!(edit, CreditEdit::Unchanged) {
        return;
    }
    sources.credits.retain(|file| file.path != sidecar_path);
    if let CreditEdit::Set(contents) = edit {
        sources.credits.push(SourceFile {
            path: sidecar_path,
            contents: contents.clone(),
        });
    }
}

/// Check that the site still loads and renders with `rel` set to `source`.
/// Only problems that involve the edited file are reported; unrelated broken
/// files are surfaced by the rebuild instead of blocking every save.
fn validate_candidate(
    root: &Path,
    config: &SiteConfig,
    rel: &str,
    source: &str,
    credit_edit: &CreditEdit,
) -> Result<(), Vec<String>> {
    let excluded_sidecar = (!matches!(credit_edit, CreditEdit::Unchanged))
        .then(|| openblog_core::contributor::sidecar_path(rel))
        .flatten();
    let mut sources = site::read_sources_excluding(root, config, excluded_sidecar.as_deref())
        .map_err(|e| vec![e])?;
    for bucket in [
        &mut sources.posts,
        &mut sources.series,
        &mut sources.pages,
        &mut sources.services,
    ] {
        bucket.retain(|f| f.path != rel);
    }
    sources.add(SourceFile {
        path: rel.to_string(),
        contents: source.to_string(),
    });
    apply_credit_edit_to_sources(&mut sources, rel, credit_edit);
    let themes = site::load_themes(root, config).map_err(|e| vec![e])?;
    match Site::load(
        config.clone(),
        sources,
        LoadOptions {
            include_drafts: true,
            now: None,
            preview_source: None,
        },
    ) {
        Ok(site) => generate(&site, &themes).map(|_| ()).map_err(|e| vec![e]),
        Err(errors) => {
            let sidecar = openblog_core::contributor::sidecar_path(rel);
            let mine: Vec<String> = errors
                .into_iter()
                .filter(|error| {
                    error.contains(rel)
                        || sidecar.as_deref().is_some_and(|path| error.contains(path))
                })
                .collect();
            if mine.is_empty() {
                Ok(())
            } else {
                Err(mine)
            }
        }
    }
}

fn write_atomic_bytes(path: &Path, contents: &[u8]) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .map_err(|e| format!("cannot create {}: {e}", parent.display()))?;
    }
    let tmp = path.with_extension("md.tmp");
    fs::write(&tmp, contents).map_err(|e| format!("cannot write {}: {e}", tmp.display()))?;
    crate::fsutil::replace_file(&tmp, path).map_err(|e| {
        let _ = fs::remove_file(&tmp);
        format!("cannot replace {}: {e}", path.display())
    })
}

fn write_atomic(path: &Path, contents: &str) -> Result<(), String> {
    write_atomic_bytes(path, contents.as_bytes())
}

fn restore_file(path: &Path, previous: Option<&[u8]>) -> Result<(), String> {
    match previous {
        Some(contents) => write_atomic_bytes(path, contents),
        None if path.exists() => crate::fsutil::retry_transient(|| fs::remove_file(path))
            .map_err(|error| format!("cannot remove {} during rollback: {error}", path.display())),
        None => Ok(()),
    }
}

fn read_optional_bytes(path: &Path) -> Result<Option<Vec<u8>>, String> {
    match fs::read(path) {
        Ok(contents) => Ok(Some(contents)),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(format!("cannot read {}: {error}", path.display())),
    }
}

fn write_document_with_credits(
    path: &Path,
    sidecar: &Path,
    source: &str,
    credit_edit: &CreditEdit,
) -> Result<(), String> {
    write_document_with_credits_using(path, sidecar, source, credit_edit, mutate_credit_sidecar)
}

fn mutate_credit_sidecar(sidecar: &Path, credit_edit: &CreditEdit) -> Result<(), String> {
    match credit_edit {
        CreditEdit::Set(contents) => write_atomic(sidecar, contents),
        CreditEdit::Remove if sidecar.exists() => fs::remove_file(sidecar)
            .map_err(|error| format!("cannot remove {}: {error}", sidecar.display())),
        CreditEdit::Remove | CreditEdit::Unchanged => Ok(()),
    }
}

fn write_document_with_credits_using(
    path: &Path,
    sidecar: &Path,
    source: &str,
    credit_edit: &CreditEdit,
    mutate_sidecar: impl FnOnce(&Path, &CreditEdit) -> Result<(), String>,
) -> Result<(), String> {
    if matches!(credit_edit, CreditEdit::Unchanged) {
        return write_atomic(path, source);
    }
    let previous_document = read_optional_bytes(path)?;
    let previous_sidecar = read_optional_bytes(sidecar)?;
    write_atomic(path, source)?;
    let credit_result = mutate_sidecar(sidecar, credit_edit);
    if let Err(error) = credit_result {
        let document_rollback = restore_file(path, previous_document.as_deref());
        let credit_rollback = restore_file(sidecar, previous_sidecar.as_deref());
        return Err(match (document_rollback, credit_rollback) {
            (Ok(()), Ok(())) => error,
            (document, credits) => format!(
                "{error}; rollback failed (document: {}; credits: {})",
                document.err().unwrap_or_else(|| "ok".into()),
                credits.err().unwrap_or_else(|| "ok".into())
            ),
        });
    }
    Ok(())
}

#[derive(Debug)]
struct StagedTrack {
    pending: PathBuf,
    target: PathBuf,
    url: String,
    contents: Vec<u8>,
}

fn field_scalar<'a>(fields: &'a BTreeMap<String, Value>, key: &str) -> Option<&'a str> {
    match fields.get(key) {
        Some(Value::Scalar(value)) => Some(value.trim()),
        _ => None,
    }
}

fn staged_track(
    root: &Path,
    config: &SiteConfig,
    body: &Json,
    fields: &mut BTreeMap<String, Value>,
) -> Result<Option<StagedTrack>, String> {
    let Some(token) = body.get("trackToken").and_then(Json::as_str) else {
        return Ok(None);
    };
    if field_scalar(fields, "profile") != Some("field-journal")
        || field_scalar(fields, "locationPrivacy") != Some("exact")
    {
        return Err("staged tracks require the Field journal profile in Exact mode".into());
    }
    if token.len() != 64 || !token.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err("invalid staged track token".into());
    }
    let pending = root
        .join(".openblog/pending-tracks")
        .join(format!("{token}.gpx"));
    let contents =
        fs::read(&pending).map_err(|_| "staged track expired; import the GPX again".to_string())?;
    let source =
        std::str::from_utf8(&contents).map_err(|_| "staged GPX is not UTF-8".to_string())?;
    validate_gpx(source)?;
    let name = body
        .get("trackName")
        .and_then(Json::as_str)
        .unwrap_or("track.gpx");
    let stem = sanitize_upload_stem(name);
    let year = clock::now().civil().year;
    let dir_rel = format!("tracks/uploads/{year}");
    let static_dir = root.join(&config.paths.static_dir);
    let mut file_name = format!("{stem}.gpx");
    let mut number = 2;
    while static_dir.join(&dir_rel).join(&file_name).exists() {
        file_name = format!("{stem}-{number}.gpx");
        number += 1;
    }
    let relative = format!("{dir_rel}/{file_name}");
    let url = format!("/{relative}");
    fields.insert("route".into(), Value::Scalar(url.clone()));
    Ok(Some(StagedTrack {
        pending,
        target: static_dir.join(relative),
        url,
        contents,
    }))
}

fn static_track_path(root: &Path, config: &SiteConfig, route: &str) -> Option<PathBuf> {
    let relative = route.strip_prefix("/tracks/uploads/")?;
    if relative.is_empty()
        || !relative.ends_with(".gpx")
        || relative.contains("..")
        || !relative
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'/' | b'-' | b'_' | b'.'))
    {
        return None;
    }
    Some(
        root.join(&config.paths.static_dir)
            .join("tracks/uploads")
            .join(relative),
    )
}

fn track_is_referenced_elsewhere(
    root: &Path,
    config: &SiteConfig,
    route: &str,
    excluded_document: &Path,
) -> bool {
    fn visit(dir: &Path, route: &str, excluded_document: &Path) -> bool {
        let Ok(entries) = fs::read_dir(dir) else {
            // If ownership cannot be proven exclusive, preserve the asset.
            return true;
        };
        for entry in entries {
            let Ok(entry) = entry else {
                return true;
            };
            let Ok(file_type) = entry.file_type() else {
                return true;
            };
            let path = entry.path();
            if file_type.is_dir() {
                if visit(&path, route, excluded_document) {
                    return true;
                }
            } else if file_type.is_file()
                && path != excluded_document
                && path.extension().and_then(|value| value.to_str()) == Some("md")
            {
                let Ok(source) = fs::read_to_string(&path) else {
                    return true;
                };
                let Ok(document) = frontmatter::parse(&source) else {
                    return true;
                };
                if document.front_matter.get("route") == Some(route) {
                    return true;
                }
            }
        }
        false
    }

    visit(&root.join(&config.paths.content), route, excluded_document)
}

fn write_document_bundle(
    path: &Path,
    sidecar: &Path,
    source: &str,
    credit_edit: &CreditEdit,
    upload: Option<&StagedTrack>,
    retire: Option<&(PathBuf, PathBuf)>,
) -> Result<(), String> {
    let previous_document = read_optional_bytes(path)?;
    let previous_sidecar = read_optional_bytes(sidecar)?;
    let previous_upload = match upload {
        Some(track) => read_optional_bytes(&track.target)?,
        None => None,
    };
    write_document_with_credits(path, sidecar, source, credit_edit)?;
    let result = (|| {
        if let Some(track) = upload {
            write_atomic_bytes(&track.target, &track.contents)?;
        }
        if let Some((from, to)) = retire {
            if let Some(parent) = to.parent() {
                fs::create_dir_all(parent)
                    .map_err(|error| format!("cannot create {}: {error}", parent.display()))?;
            }
            crate::fsutil::retry_transient(|| fs::rename(from, to)).map_err(|error| {
                format!("cannot retire private track {}: {error}", from.display())
            })?;
        }
        Ok(())
    })();
    if let Err(error) = result {
        let _ = restore_file(path, previous_document.as_deref());
        let _ = restore_file(sidecar, previous_sidecar.as_deref());
        if let Some(track) = upload {
            let _ = restore_file(&track.target, previous_upload.as_deref());
        }
        return Err(error);
    }
    Ok(())
}

/// New file path for a created document, derived from its fields.
fn derive_new_path(kind: &str, fields: &BTreeMap<String, Value>) -> Result<String, String> {
    let get = |k: &str| match fields.get(k) {
        Some(Value::Scalar(s)) if !s.trim().is_empty() => Some(s.trim().to_string()),
        _ => None,
    };
    if kind == "services" {
        return match get("id").filter(|id| openblog_core::service::check_id(id).is_ok()) {
            Some(id) => Ok(format!("services/{id}.md")),
            None => Err(
                "a service needs an id of lowercase letters, digits and hyphens to name its file"
                    .into(),
            ),
        };
    }
    let slug = get("slug")
        .map(|s| slugify(&s))
        .or_else(|| get("title").or_else(|| get("name")).map(|t| slugify(&t)))
        .unwrap_or_default();
    let slug = openblog_core::slug::limit(&slug, 80);
    if slug.is_empty() {
        return Err("a title (or slug) is needed to name the file".into());
    }
    match kind {
        "posts" => {
            let date = get("date")
                .and_then(|d| DateTime::parse(&d))
                .unwrap_or_else(clock::now);
            Ok(format!("posts/{}-{slug}.md", date.ymd()))
        }
        "series" => Ok(format!("series/{slug}.md")),
        "pages" => Ok(format!("pages/{slug}.md")),
        _ => Err("kind must be posts, series, pages, or services".into()),
    }
}

fn save_document(state: &AppState, req: &Request, existing_path: Option<String>) -> Response {
    if let Err(r) = require_json(req) {
        return r;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(b) => b,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let mut fields = match fields_from_json(&body["fields"]) {
        Ok(f) => f,
        Err(e) => return Response::error(422, &e),
    };
    let text_body = body["body"].as_str().unwrap_or("");
    if text_body.len() > MAX_DOCUMENT_BYTES || text_body.contains('\0') {
        return Response::error(413, "The post body is too large");
    }
    // A capture id makes creation idempotent: the same id never creates a second draft (ADR 0297).
    let capture_id = match body.get("captureId") {
        None | Some(Json::Null) => None,
        Some(Json::String(id))
            if existing_path.is_none() && openblog_core::capture::valid_id(id) =>
        {
            Some(id.clone())
        }
        Some(_) => return Response::error(422, "That capture id is not valid"),
    };
    let mut status = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let config = match site::load_config(&state.root) {
        Ok(c) => c,
        Err(e) => return Response::error(500, &e),
    };
    let capture_ledger = capture_id
        .as_ref()
        .map(|id| captures_dir(state).join(format!("{id}.json")));
    if let Some(ledger) = &capture_ledger {
        match read_optional_bytes(ledger) {
            Ok(Some(bytes)) => return replayed_capture(state, &config, &bytes),
            Ok(None) => {}
            Err(error) => return Response::error(500, &error),
        }
    }
    let field_journal = field_scalar(&fields, "profile") == Some("field-journal");
    let exact_location = field_journal && field_scalar(&fields, "locationPrivacy") == Some("exact");
    if field_journal && !exact_location {
        fields.remove("route");
    }
    let track_upload = match staged_track(&state.root, &config, &body, &mut fields) {
        Ok(track) => track,
        Err(error) => return Response::error(422, &error),
    };
    let mut source = frontmatter::compose(&fields, text_body);

    let (rel, created) = match existing_path {
        Some(rel) => (rel, false),
        None => {
            let kind = body["kind"].as_str().unwrap_or("posts");
            match derive_new_path(kind, &fields) {
                Ok(rel) => (rel, true),
                Err(e) => return Response::error(422, &e),
            }
        }
    };
    let path = match resolve_content_path(&state.root, &config, &rel) {
        Ok(p) => p,
        Err(e) => return Response::error(400, &e),
    };
    let kind = check_rel_path(&rel).unwrap_or("posts");
    let credit_path = if kind == "posts" {
        match resolve_credit_path(&state.root, &config, &rel) {
            Ok(path) => Some(path),
            Err(error) => return Response::error(400, &error),
        }
    } else {
        None
    };
    let credit_edit = match requested_credit_edit(&body, kind) {
        Ok(edit) => edit,
        Err(error) => return Response::error(422, &error),
    };

    let mut retired_track = None;
    if created {
        if path.exists() {
            return Response::error(
                409,
                "A file with that name already exists. Change the title, slug, or date.",
            );
        }
        if matches!(credit_edit, CreditEdit::Unchanged)
            && credit_path.as_ref().is_some_and(|path| path.exists())
        {
            return Response::error(
                409,
                "A credit sidecar with that name already exists. Reload with a credits-aware Admin client or move the orphaned sidecar.",
            );
        }
    } else {
        let current = match fs::read_to_string(&path) {
            Ok(t) => t,
            Err(_) => return Response::error(404, "No such document"),
        };
        match body["etag"].as_str() {
            Some(sent) if sent == etag(&current) => {}
            _ => {
                return Response::error(
                    409,
                    "This file changed on disk since you opened it. Reload it before saving.",
                )
            }
        }
        let replacement = track_upload.as_ref().map(|track| track.url.as_str());
        if let Ok(document) = frontmatter::parse(&current) {
            let old_field_journal = openblog_core::profile::resolve(&document.front_matter)
                .behavior
                == openblog_core::profile::ProfileBehavior::FieldJournal;
            if old_field_journal && !exact_location {
                fields.remove("route");
                source = frontmatter::compose(&fields, text_body);
            }
            if old_field_journal {
                if let Some(old_route) = document.front_matter.get("route") {
                    if (!exact_location || replacement.is_some_and(|url| url != old_route))
                        && !track_is_referenced_elsewhere(&state.root, &config, old_route, &path)
                    {
                        if let Some(old_path) = static_track_path(&state.root, &config, old_route) {
                            if old_path.is_file() {
                                let trash = state.root.join(".openblog/trash/tracks");
                                let name = old_path
                                    .file_name()
                                    .and_then(|name| name.to_str())
                                    .unwrap_or("track.gpx")
                                    .to_string();
                                let stamp = clock::now().rfc3339().replace(':', "");
                                let target = unique_trash_target(&trash, &stamp, &name);
                                retired_track = Some((old_path, target));
                            }
                        }
                    }
                }
            }
        }
    }

    if !matches!(credit_edit, CreditEdit::Unchanged) {
        let sidecar = credit_path.as_ref().expect("post credit path");
        let current = match read_optional_bytes(sidecar) {
            Ok(current) => current,
            Err(error) => return Response::error(500, &error),
        };
        let expected = body.get("creditEtag").and_then(Json::as_str);
        let matches = match current.as_deref() {
            Some(contents) => {
                let current_etag = etag_bytes(contents);
                expected == Some(current_etag.as_str())
            }
            None => body.get("creditEtag").is_none_or(Json::is_null),
        };
        if !matches {
            return Response::error(
                409,
                "The post credits changed on disk since you opened them. Reload before saving.",
            );
        }
        // A shared reflection's credits list each contributor once, in the
        // order they first appear in the body (ADR 0030). An edit that breaks
        // that order would stop its sections being attributed to their
        // authors, so it is refused rather than saved (ADR 0136).
        if let CreditEdit::Set(contents) = &credit_edit {
            let before = current
                .as_deref()
                .and_then(|bytes| std::str::from_utf8(bytes).ok());
            let published = attributed_perspective::AttributedSections::from_published(
                text_body,
                before,
                &config.contributors,
            );
            let edited = attributed_perspective::AttributedSections::from_published(
                text_body,
                Some(contents),
                &config.contributors,
            );
            if !published.sections().is_empty() && edited.sections().is_empty() {
                return Response::error(
                    422,
                    "These credits no longer match the order in which each contributor first appears in this shared reflection, so readers could no longer write to or answer each author’s own section. List each contributor once, in the order they first appear.",
                );
            }
        }
    }

    if !created {
        // A bound body states each section's author (ADR 0136) and only
        // compose writes that. A manual edit may not change the binding
        // sequence, nor move an existing turn to another name or contributor,
        // whether through the body, the credits or both at once.
        if let Err(message) = refuse_turn_rebinding(
            &path,
            credit_path.as_deref(),
            text_body,
            &credit_edit,
            &config,
        ) {
            return Response::error(422, &message);
        }
    }

    if let Err(problems) = validate_candidate(&state.root, &config, &rel, &source, &credit_edit) {
        return Response::json(
            422,
            &json!({ "error": "This can't be saved yet.", "problems": problems }),
        );
    }
    let sidecar = credit_path.as_deref().unwrap_or(&path);
    if let Err(e) = write_document_bundle(
        &path,
        sidecar,
        &source,
        &credit_edit,
        track_upload.as_ref(),
        retired_track.as_ref(),
    ) {
        return Response::error(500, &e);
    }
    if let Some(track) = &track_upload {
        let _ = fs::remove_file(&track.pending);
    }
    if let Some(ledger) = &capture_ledger {
        // Best effort: the draft exists either way, and its slug carries the capture id.
        let audio = capture_id
            .as_deref()
            .and_then(|id| stored_capture_audio(state, id));
        if let Err(error) = fsutil::write_file(
            ledger,
            openblog_core::capture::ledger_text(&rel, audio.as_deref()).as_bytes(),
        ) {
            eprintln!("admin: cannot record capture: {error}");
        }
    }

    let now = clock::now();
    let build = state.rebuild_locked(&mut status);
    let build_json = match &build {
        Ok(r) => {
            json!({ "ok": true, "posts": r.posts, "scheduled": r.scheduled, "nextDue": r.next_due.map(|d| d.rfc3339()) })
        }
        Err(e) => json!({ "ok": false, "error": e }),
    };
    let (post_status, url) = describe(&rel, &source, &config, now);
    eprintln!("admin: {} {rel}", if created { "created" } else { "saved" });
    let title = fields
        .get("title")
        .or_else(|| fields.get("name"))
        .and_then(|v| match v {
            Value::Scalar(s) => Some(s.clone()),
            _ => None,
        })
        .unwrap_or_else(|| rel.clone());
    state_arc(state).auto_publish(title);
    let credit_etag = match credit_path.as_deref() {
        Some(sidecar) => match read_optional_bytes(sidecar) {
            Ok(contents) => contents.map(|contents| etag_bytes(&contents)),
            Err(error) => return Response::error(500, &error),
        },
        None => None,
    };
    Response::json(
        if created { 201 } else { 200 },
        &json!({ "path": rel, "etag": etag(&source), "creditEtag": credit_etag, "status": post_status, "url": url, "build": build_json, "trackUrl": track_upload.as_ref().map(|track| &track.url) }),
    )
}

/// The answer to a capture id the server has already turned into a draft: the same draft, nothing written.
fn replayed_capture(state: &AppState, config: &SiteConfig, ledger: &[u8]) -> Response {
    let rel = match openblog_core::capture::parse_ledger(&String::from_utf8_lossy(ledger)) {
        Ok(rel) => rel,
        Err(error) => return Response::error(409, &error),
    };
    let source = resolve_content_path(&state.root, config, &rel)
        .ok()
        .and_then(|path| fs::read_to_string(path).ok());
    let (post_status, url, current_etag) = match &source {
        Some(source) => {
            let (status, url) = describe(&rel, source, config, clock::now());
            (status, url, Some(etag(source)))
        }
        None => ("removed", None, None),
    };
    Response::json(
        200,
        &json!({ "path": rel, "etag": current_etag, "status": post_status, "url": url, "duplicate": true }),
    )
}

/// Refuse a save that would change who a published shared-reflection turn is
/// attributed to (ADR 0136). Compares the stored body with the stored credits
/// against the new body with the credits as they will be after the save.
fn refuse_turn_rebinding(
    path: &Path,
    sidecar: Option<&Path>,
    new_body: &str,
    credit_edit: &CreditEdit,
    config: &SiteConfig,
) -> Result<(), String> {
    let Ok(old_source) = fs::read_to_string(path) else {
        return Ok(());
    };
    let Ok(old_document) = frontmatter::parse(&old_source) else {
        return Ok(());
    };
    let old_credits = match sidecar {
        Some(sidecar) => read_optional_bytes(sidecar)?,
        None => None,
    };
    let old_credits = old_credits.and_then(|bytes| String::from_utf8(bytes).ok());
    let new_credits = match credit_edit {
        CreditEdit::Unchanged => old_credits.clone(),
        CreditEdit::Remove => None,
        CreditEdit::Set(contents) => Some(contents.clone()),
    };
    if attributed_perspective::turn_binding_sequence(&old_document.body)
        != attributed_perspective::turn_binding_sequence(new_body)
    {
        return Err("The `ob-turn-by-` classes that bind each section of a shared reflection to its author can only be written by composing the reflection, so a manual edit may not add, remove, reorder or change them.".into());
    }
    let old = attributed_perspective::AttributedSections::from_published(
        &old_document.body,
        old_credits.as_deref(),
        &config.contributors,
    );
    if old.sections().is_empty() {
        return Ok(());
    }
    let new = attributed_perspective::AttributedSections::from_published(
        new_body,
        new_credits.as_deref(),
        &config.contributors,
    );
    let moved = old.sections().iter().enumerate().any(|(index, section)| {
        new.sections().get(index).is_some_and(|next| {
            next.author != section.author || next.contribution != section.contribution
        })
    });
    if moved {
        return Err("This edit would move an existing section of a shared reflection to another author’s name or contributor id, so it is refused. Edit the words, not who they are attributed to.".into());
    }
    Ok(())
}

/// Publication status and public URL of a just-saved document.
fn describe(
    rel: &str,
    source: &str,
    config: &SiteConfig,
    now: DateTime,
) -> (&'static str, Option<String>) {
    if !rel.starts_with("posts/") {
        return ("published", None);
    }
    let file = SourceFile {
        path: rel.to_string(),
        contents: source.to_string(),
    };
    match openblog_core::model::load_post(&file, config, RenderOptions::default()) {
        Ok(p) if p.draft => ("draft", None),
        Ok(p) if p.date > now => ("scheduled", Some(p.url)),
        Ok(p) => ("published", Some(p.url)),
        Err(_) => ("error", None),
    }
}

fn unique_trash_target(trash: &Path, stamp: &str, name: &str) -> PathBuf {
    let mut target = trash.join(format!("{stamp}-{name}"));
    let mut number = 1;
    while target.exists() {
        target = trash.join(format!("{stamp}-{number}-{name}"));
        number += 1;
    }
    target
}

fn post_context_path_pairs(
    root: &Path,
    old_document: &str,
    new_document: &str,
) -> Result<Vec<(PathBuf, PathBuf)>, Response> {
    let mut pairs = Vec::new();
    for visibility in ["portable", "private"] {
        let (old, _, _) = assistant_context_target(root, "post", visibility, Some(old_document))?;
        let (new, _, _) = assistant_context_target(root, "post", visibility, Some(new_document))?;
        if old.exists() {
            if !old.is_file() {
                return Err(Response::error(
                    409,
                    "Associated post context is not a file",
                ));
            }
            pairs.push((old, new));
        }
    }
    Ok(pairs)
}

fn move_files_transactionally(moves: &[(PathBuf, PathBuf)]) -> Result<(), String> {
    for (from, to) in moves {
        if !from.is_file() {
            return Err(format!("source file does not exist: {}", from.display()));
        }
        if to.exists() {
            return Err(format!("destination already exists: {}", to.display()));
        }
    }
    for (_, to) in moves {
        if let Some(parent) = to.parent() {
            fs::create_dir_all(parent)
                .map_err(|error| format!("cannot create {}: {error}", parent.display()))?;
        }
    }
    let mut moved = Vec::new();
    for (from, to) in moves {
        if let Err(error) = crate::fsutil::retry_transient(|| fs::rename(from, to)) {
            let mut rollback_errors = Vec::new();
            for (moved_from, moved_to) in moved.iter().rev() {
                if let Err(rollback) =
                    crate::fsutil::retry_transient(|| fs::rename(moved_to, moved_from))
                {
                    rollback_errors.push(rollback.to_string());
                }
            }
            return Err(format!(
                "cannot move {}: {error}; rollback: {}",
                from.display(),
                if rollback_errors.is_empty() {
                    "ok".into()
                } else {
                    rollback_errors.join("; ")
                }
            ));
        }
        moved.push((from.clone(), to.clone()));
    }
    Ok(())
}

fn rename_document(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid rename request"),
    };
    let Some(old_rel) = body["path"].as_str() else {
        return Response::error(400, "Missing path");
    };
    let Some(new_rel) = body["newPath"].as_str() else {
        return Response::error(400, "Missing newPath");
    };
    if old_rel == new_rel {
        return Response::error(422, "The new document path is unchanged");
    }
    if check_rel_path(old_rel).ok() != Some("posts")
        || check_rel_path(new_rel).ok() != Some("posts")
    {
        return Response::error(422, "Only post Markdown paths can be renamed here");
    }
    let mut status = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let config = match site::load_config(&state.root) {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    let old_path = match resolve_content_path(&state.root, &config, old_rel) {
        Ok(path) => path,
        Err(error) => return Response::error(400, &error),
    };
    let new_path = match resolve_content_path(&state.root, &config, new_rel) {
        Ok(path) => path,
        Err(error) => return Response::error(400, &error),
    };
    let source = match fs::read_to_string(&old_path) {
        Ok(source) => source,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Response::error(404, "No such document")
        }
        Err(error) => return Response::error(500, &format!("Cannot read document: {error}")),
    };
    if body["etag"].as_str() != Some(etag(&source).as_str()) {
        return Response::error(
            409,
            "Document changed since it was opened; reload and retry",
        );
    }
    let mut moves = vec![(old_path, new_path)];
    let old_credit = match resolve_credit_path(&state.root, &config, old_rel) {
        Ok(path) => path,
        Err(error) => return Response::error(400, &error),
    };
    if old_credit.is_file() {
        let new_credit = match resolve_credit_path(&state.root, &config, new_rel) {
            Ok(path) => path,
            Err(error) => return Response::error(400, &error),
        };
        moves.push((old_credit, new_credit));
    }
    match post_context_path_pairs(&state.root, old_rel, new_rel) {
        Ok(context_moves) => moves.extend(context_moves),
        Err(response) => return response,
    }
    if let Err(error) = move_files_transactionally(&moves) {
        let status = if error.contains("destination already exists") {
            409
        } else {
            500
        };
        return Response::error(status, &format!("Cannot rename document bundle: {error}"));
    }
    let build = state.rebuild_locked(&mut status);
    let build_json = match build {
        Ok(report) => json!({ "ok": true, "posts": report.posts }),
        Err(error) => json!({ "ok": false, "error": error }),
    };
    Response::json(
        200,
        &json!({ "ok": true, "path": new_rel, "etag": etag(&source), "build": build_json }),
    )
}

fn delete_document(state: &AppState, req: &Request) -> Response {
    let Some(rel) = req.query.get("path") else {
        return Response::error(400, "Missing ?path=");
    };
    let mut status = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let config = match site::load_config(&state.root) {
        Ok(c) => c,
        Err(e) => return Response::error(500, &e),
    };
    let path = match resolve_content_path(&state.root, &config, rel) {
        Ok(p) => p,
        Err(e) => return Response::error(400, &e),
    };
    if !path.is_file() {
        return Response::error(404, "No such document");
    }
    let managed_track = fs::read_to_string(&path)
        .ok()
        .and_then(|source| frontmatter::parse(&source).ok())
        .filter(|document| {
            openblog_core::profile::resolve(&document.front_matter).behavior
                == openblog_core::profile::ProfileBehavior::FieldJournal
        })
        .and_then(|document| {
            document
                .front_matter
                .get("route")
                .filter(|route| !track_is_referenced_elsewhere(&state.root, &config, route, &path))
                .and_then(|route| static_track_path(&state.root, &config, route))
        })
        .filter(|track| track.is_file());
    // Never destroy content: move it to a trash folder that can be restored from.
    let trash = state.root.join(".openblog").join("trash");
    if let Err(e) = fs::create_dir_all(&trash) {
        return Response::error(500, &format!("cannot create the trash folder: {e}"));
    }
    let stamp = clock::now().rfc3339().replace(':', "");
    let name = rel.replace('/', "_");
    let target = unique_trash_target(&trash, &stamp, &name);
    let sidecar = if check_rel_path(rel).ok() == Some("posts") {
        match resolve_credit_path(&state.root, &config, rel) {
            Ok(path) => Some(path),
            Err(error) => return Response::error(400, &error),
        }
    } else {
        None
    };
    let sidecar_target = sidecar.as_ref().filter(|path| path.is_file()).map(|_| {
        let sidecar_name = openblog_core::contributor::sidecar_path(rel)
            .unwrap_or_else(|| format!("{rel}.credits.json"))
            .replace('/', "_");
        unique_trash_target(&trash, &stamp, &sidecar_name)
    });
    let track_target = managed_track.as_ref().map(|track| {
        let name = track
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("track.gpx");
        unique_trash_target(&trash.join("tracks"), &stamp, name)
    });
    let mut context_moves = Vec::new();
    if check_rel_path(rel).ok() == Some("posts") {
        for visibility in ["portable", "private"] {
            let (context, _, _) =
                match assistant_context_target(&state.root, "post", visibility, Some(rel)) {
                    Ok(target) => target,
                    Err(response) => return response,
                };
            if context.exists() {
                if !context.is_file() {
                    return Response::error(409, "Associated post context is not a file");
                }
                let context_name = context
                    .file_name()
                    .and_then(|name| name.to_str())
                    .unwrap_or("post.md");
                let context_target = unique_trash_target(
                    &trash.join("context"),
                    &stamp,
                    &format!("{visibility}-{context_name}"),
                );
                context_moves.push((context, context_target));
            }
        }
    }
    let mut moves = vec![(path.clone(), target.clone())];
    if let (Some(sidecar), Some(sidecar_target)) = (&sidecar, &sidecar_target) {
        moves.push((sidecar.clone(), sidecar_target.clone()));
    }
    if let (Some(track), Some(track_target)) = (&managed_track, &track_target) {
        moves.push((track.clone(), track_target.clone()));
    }
    moves.extend(context_moves.iter().cloned());
    if let Err(error) = move_files_transactionally(&moves) {
        return Response::error(
            500,
            &format!("cannot move document bundle to trash: {error}"),
        );
    }
    eprintln!("admin: deleted {rel} (kept in .openblog/trash)");
    let build = state.rebuild_locked(&mut status);
    let build_json = match &build {
        Ok(r) => json!({ "ok": true, "posts": r.posts }),
        Err(e) => json!({ "ok": false, "error": e }),
    };
    Response::json(
        200,
        &json!({
            "ok": true,
            "trashedTo": target.file_name().map(|n| n.to_string_lossy().into_owned()),
            "trashedCreditsTo": sidecar_target.and_then(|path| path.file_name().map(|name| name.to_string_lossy().into_owned())),
            "trashedTrackTo": track_target.and_then(|path| path.file_name().map(|name| name.to_string_lossy().into_owned())),
            "trashedContextTo": context_moves.into_iter().filter_map(|(_, path)| path.file_name().map(|name| name.to_string_lossy().into_owned())).collect::<Vec<_>>(),
            "build": build_json
        }),
    )
}

fn rebuild(state: &AppState) -> Response {
    match state.rebuild() {
        Ok(r) => Response::json(
            200,
            &json!({ "ok": true, "posts": r.posts, "scheduled": r.scheduled, "files": r.files }),
        ),
        Err(e) => Response::json(500, &json!({ "ok": false, "error": e })),
    }
}

fn acknowledge_portability(state: &AppState, req: &Request) -> Response {
    if let Err(response) = require_json(req) {
        return response;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let Some(path) = body["path"].as_str() else {
        return Response::error(400, "Missing post path");
    };
    let Some(expected_revision) = body["sourceRevision"].as_str() else {
        return Response::error(400, "Missing source revision");
    };
    let Some(capability_id) = body["capabilityId"].as_str() else {
        return Response::error(400, "Missing capability ID");
    };
    let Some(representation) = body["representation"].as_str() else {
        return Response::error(400, "Missing representation");
    };
    let Some(destination) = body["destination"].as_str() else {
        return Response::error(400, "Missing destination");
    };
    let Some(expected_etag) = body["expectedEtag"].as_str() else {
        return Response::error(400, "Missing portability acknowledgement version");
    };
    let acknowledgement = PortabilityAcknowledgement {
        source_revision: expected_revision.to_string(),
        capability_id: capability_id.to_string(),
        representation: representation.to_string(),
        destination: destination.to_string(),
    };
    if let Err(error) = validate_portability_acknowledgement(&acknowledgement) {
        return Response::error(422, &error);
    }

    let config = match site::load_config(&state.root) {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    let sidecar_path = match resolve_portability_acknowledgement_path(&state.root, &config, path) {
        Ok(path) => path,
        Err(error) => return Response::error(422, &error),
    };
    let _guard = lock(&state.portability_acknowledgements);
    let (mut sidecar, current_etag) = match load_portability_acknowledgements(&sidecar_path) {
        Ok(sidecar) => sidecar,
        Err(error) => return Response::error(422, &error),
    };
    if current_etag != expected_etag {
        return Response::error(
            409,
            "Portability acknowledgements changed on disk; refresh the preview and retry.",
        );
    }

    let (preview_site, _) = match site::load_site(&state.root, true, Some(clock::now())) {
        Ok(site) => site,
        Err(error) => return Response::error(422, &error),
    };
    let Some(post) = preview_site.posts.iter().find(|post| post.source == path) else {
        return Response::error(404, "Post was not found");
    };
    let projection = match admin_portable_projection(&preview_site, post, &preview_site.config) {
        Ok(projection) => projection,
        Err(error) => return Response::error(422, &error),
    };
    let revision = match projection.source_revision() {
        Ok(revision) => revision,
        Err(error) => return Response::error(422, &error),
    };
    if revision != expected_revision {
        return Response::error(
            409,
            "The source changed since this preview was rendered; refresh before acknowledging.",
        );
    }
    let portable = match projection.portable_html() {
        Ok(portable) => portable,
        Err(error) => return Response::error(422, &error),
    };
    let has_warning = portable.diagnostics.iter().any(|diagnostic| {
        diagnostic.severity == openblog_core::portability::DiagnosticSeverity::Warning
            && diagnostic.capability_id.as_deref() == Some(capability_id)
    });
    if !has_warning {
        return Response::error(
            422,
            "Only a current, source-scoped portability warning can be acknowledged.",
        );
    }
    if sidecar.acknowledgements.contains(&acknowledgement) {
        return Response::json(
            200,
            &json!({
                "acknowledgements": sidecar.acknowledgements,
                "etag": current_etag,
            }),
        );
    }
    if sidecar.acknowledgements.len() >= MAX_PORTABILITY_ACKNOWLEDGEMENTS {
        return Response::error(
            422,
            "The portability acknowledgement sidecar is full; remove stale records first.",
        );
    }
    sidecar.acknowledgements.push(acknowledgement);
    sidecar.acknowledgements.sort_by(|left, right| {
        (
            &left.source_revision,
            &left.capability_id,
            &left.representation,
            &left.destination,
        )
            .cmp(&(
                &right.source_revision,
                &right.capability_id,
                &right.representation,
                &right.destination,
            ))
    });
    let contents = match serde_json::to_string_pretty(&sidecar) {
        Ok(contents) => contents,
        Err(error) => {
            return Response::error(
                500,
                &format!("cannot serialize portability acknowledgements: {error}"),
            )
        }
    };
    if let Err(error) = write_atomic(&sidecar_path, &contents) {
        return Response::error(500, &error);
    }
    Response::json(
        200,
        &json!({
            "acknowledgements": sidecar.acknowledgements,
            "etag": etag(&contents),
        }),
    )
}

/// A document as the editor holds it, loaded into the site the way a preview
/// loads it: unsaved fields and body, credits as edited, drafts left out
/// except this one. The build lock is held while it lives.
struct DraftSite<'s> {
    /// Held until [`DraftSite::release`], so a caller can drop the lock as
    /// soon as it has read the files it needs.
    guard: Option<MutexGuard<'s, BuildStatus>>,
    site: openblog_core::Site,
    themes: openblog_core::theme::ThemeSet,
    rel: String,
    kind: String,
    /// The composed source, front matter and body, as it would be saved.
    source: String,
    /// The line of the composed source where the editor's first body line is.
    first_body_line: usize,
    portable_config: openblog_core::config::SiteConfig,
}

impl DraftSite<'_> {
    /// Let go of the build lock: the files are read, the rest is computation.
    fn release(&mut self) {
        self.guard = None;
    }
}

fn load_draft_site<'s>(state: &'s AppState, body: &Json) -> Result<DraftSite<'s>, Response> {
    let text_body = body["body"].as_str().unwrap_or("");
    if text_body.len() > MAX_DOCUMENT_BYTES || text_body.contains('\0') {
        return Err(Response::error(413, "The post body is too large"));
    }
    let fields = match fields_from_json(&body["fields"]) {
        Ok(fields) => fields,
        Err(e) => return Err(Response::error(422, &e)),
    };
    let kind = body["kind"].as_str().unwrap_or("posts").to_string();
    if !matches!(kind.as_str(), "posts" | "pages" | "series" | "services") {
        return Err(Response::error(
            422,
            "kind must be posts, series, pages, or services",
        ));
    }
    let rel = match body["path"].as_str().filter(|path| !path.is_empty()) {
        Some(path) => match check_rel_path(path) {
            Ok(path_kind) if path_kind == kind => path.to_string(),
            Ok(_) => {
                return Err(Response::error(
                    422,
                    "path does not match the document kind",
                ))
            }
            Err(e) => return Err(Response::error(422, &e)),
        },
        None => match derive_new_path(&kind, &fields) {
            Ok(path) => path,
            Err(e) => return Err(Response::error(422, &e)),
        },
    };
    let source = frontmatter::compose(&fields, text_body);
    let header_lines = frontmatter::compose(&fields, "").matches('\n').count();
    let leading = text_body.len() - text_body.trim_start_matches(['\r', '\n']).len();
    let leading_lines = text_body[..leading].matches('\n').count();
    let draft_source = source.clone();
    let credit_edit = match requested_credit_edit(body, &kind) {
        Ok(edit) => edit,
        Err(error) => return Err(Response::error(422, &error)),
    };
    let guard = lock(&state.build);
    let mut config = match site::load_config(&state.root) {
        Ok(config) => config,
        Err(e) => return Err(Response::error(500, &e)),
    };
    if kind == "posts" {
        if let Err(error) = resolve_credit_path(&state.root, &config, &rel) {
            return Err(Response::error(400, &error));
        }
    }
    let excluded_sidecar = (!matches!(credit_edit, CreditEdit::Unchanged))
        .then(|| openblog_core::contributor::sidecar_path(&rel))
        .flatten();
    let mut sources =
        match site::read_sources_excluding(&state.root, &config, excluded_sidecar.as_deref()) {
            Ok(sources) => sources,
            Err(e) => return Err(Response::error(500, &e)),
        };
    for bucket in [
        &mut sources.posts,
        &mut sources.series,
        &mut sources.pages,
        &mut sources.services,
    ] {
        bucket.retain(|file| file.path != rel);
    }
    sources.add(SourceFile {
        path: rel.clone(),
        contents: source,
    });
    apply_credit_edit_to_sources(&mut sources, &rel, &credit_edit);
    let portable_config = config.clone();
    // Owner-supplied analytics/comments snippets are intentionally disabled in
    // an unpublished preview. Theme assets and built-in components still run.
    config.snippets = Default::default();
    config.analytics.builtin = false;
    config.analytics.show_views = false;
    config.analytics.endpoint.clear();
    config.engagement.enabled = false;
    let (preview_site, themes) = match site::load_site_from_sources_listing(
        &state.root,
        config,
        sources,
        LoadOptions {
            include_drafts: false,
            now: Some(clock::now()),
            preview_source: Some(rel.clone()),
        },
    ) {
        Ok(loaded) => loaded,
        Err(errors) => {
            // Name the previewed document's own problems, as saving does;
            // other documents are listed only when nothing else explains it.
            let sidecar = openblog_core::contributor::sidecar_path(&rel);
            let mine: Vec<String> = errors
                .iter()
                .filter(|error| {
                    error.contains(&rel)
                        || sidecar.as_deref().is_some_and(|path| error.contains(path))
                })
                .cloned()
                .collect();
            let shown = if mine.is_empty() { errors } else { mine };
            return Err(Response::error(422, &site::content_problems(&shown)));
        }
    };
    Ok(DraftSite {
        guard: Some(guard),
        site: preview_site,
        themes,
        rel,
        kind,
        source: draft_source,
        first_body_line: (header_lines + 1).saturating_sub(leading_lines),
        portable_config,
    })
}

/// The research review of a post before it is published or scheduled (#62,
/// ADR 0123): what the existing research checks say about the draft as the
/// editor holds it, grouped by what blocks the build and by outcome, with the
/// author's acknowledgements matched (ADR 0124). It reads only; it never
/// saves the post, changes research files or publishes anything. A post that
/// uses neither the Research profile nor citations is not reviewed
/// (`applies: false`), so publishing it works exactly as before.
fn review_before_publication(state: &AppState, req: &Request) -> Response {
    use openblog_core::publication_review::PublicationReview;
    if let Err(r) = require_json(req) {
        return r;
    }
    let mut body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    if body["kind"].as_str().unwrap_or("posts") != "posts" || !body["fields"].is_object() {
        return Response::error(
            422,
            "Only a post's fields and body are reviewed before publication",
        );
    }
    // The post is read as a draft, so a citation the build would refuse once
    // it is published is listed as a finding that blocks publishing, instead
    // of stopping the review (ADR 0049, ADR 0123).
    body["fields"]["draft"] = json!("true");
    let draft = match load_draft_site(state, &body) {
        Ok(draft) => draft,
        Err(response) => return response,
    };
    let Some(post) = draft
        .site
        .posts
        .iter()
        .find(|post| post.source == draft.rel)
    else {
        return Response::error(422, "The post was not found in the site model");
    };
    let evidence: Vec<_> = draft
        .site
        .evidence
        .iter()
        .filter(|finding| finding.source.path == draft.rel)
        .cloned()
        .collect();
    let source_review: Vec<_> = draft
        .site
        .source_review
        .iter()
        .filter(|finding| finding.path.as_deref() == Some(draft.rel.as_str()))
        .cloned()
        .collect();
    let citations_opted_in = body["fields"]["citations"]
        .as_str()
        .is_some_and(|style| !style.trim().is_empty());
    // The same test as Evidence Studio's: the Research profile, citations, or a citation finding.
    let applies = post.research.is_some()
        || citations_opted_in
        || post.citations().is_some()
        || evidence
            .iter()
            .any(|finding| finding.code.to_string().starts_with("citation-"));
    let (acknowledgements, ack_info) = research_review::acknowledgements(&state.root);
    let (findings, not_reviewed) = if applies {
        let document = match frontmatter::parse(&draft.source) {
            Ok(document) => document,
            Err(error) => return Response::error(422, &error),
        };
        let gathered = research_review::gather(
            &state.root,
            &draft.portable_config,
            &research_review::DraftPost {
                path: &draft.rel,
                slug: &post.slug,
                markdown: &document.body,
                body_line: document.body_line,
                evidence,
                source_review,
            },
        );
        (gathered.findings, gathered.not_reviewed)
    } else {
        (Vec::new(), Vec::new())
    };
    let review = PublicationReview::new(findings, &acknowledgements);
    let mut view = research_review::view(&review, applies, &not_reviewed, &ack_info);
    view["post"] = json!(draft.rel);
    view["firstBodyLine"] = json!(draft.first_body_line);
    Response::json(200, &view)
}

/// What the research projections will publish for the whole site, and why
/// everything else is withheld (#63, ADR 0125): the same load, projections
/// and manifest a build of the saved files uses. Read-only and Admin-only.
fn boundary_site(state: &AppState) -> Response {
    // The build lock covers the content snapshot only. The research stores
    // have their own atomic-replace protocol, so reading them, projecting
    // and building the manifest happen without holding it.
    let guard = lock(&state.build);
    let loaded = site::load_site(&state.root, state.include_drafts, Some(clock::now()));
    // The public-input check reads the content and static folders, so it runs
    // under the same lock as the load: a save cannot land between the two.
    let refused = loaded.as_ref().ok().and_then(|(site, _)| {
        crate::private_guard::refuse_private_research_in_public_inputs(&state.root, &site.config)
            .err()
    });
    drop(guard);
    let (mut site, themes) = match loaded {
        Ok(loaded) => loaded,
        Err(error) => {
            return Response::json(
                422,
                &json!({
                    "error": format!(
                        "The site could not be loaded, so nothing can be previewed: {} Nothing was changed.",
                        error.lines().next().unwrap_or_default()
                    ),
                }),
            )
        }
    };
    let shared = crate::boundary::Shared::read(&state.root, &site.config);
    let mut manifest = crate::boundary::site_preview(&state.root, &mut site, &shared);
    // Text of private research found in the output the saved files generate.
    let (matches, text_refusal) = crate::boundary::preview_text(&state.root, &site, &themes);
    manifest.text_matches = matches;
    let refused = refused.or(text_refusal);
    let mut view = serde_json::to_value(&manifest).unwrap_or_else(|_| json!({}));
    view["refused"] = json!(refused);
    Response::json(200, &view)
}

/// The research readiness report of the saved site (#194, ADR 0150): the
/// same findings, codes and order `openblog check`, `openblog build` and the
/// preview print, from the same load. Read-only and Admin-only: it writes
/// nothing, repairs nothing and publishes nothing.
fn readiness_site(state: &AppState) -> Response {
    // The report is of every saved post, so the site is loaded once, as that
    // report reads it, and kept while the saved files stay as they are.
    let guard = lock(&state.build);
    let loaded = crate::readiness::saved_site(&state.root);
    drop(guard);
    match loaded {
        Ok(site) => Response::json(
            200,
            &crate::readiness::report_of_all(&state.root, &site).view(),
        ),
        Err(error) => Response::json(
            422,
            &json!({
                "error": format!(
                    "The site could not be loaded, so the research report cannot be read: {} Nothing was changed.",
                    error.lines().next().unwrap_or_default()
                ),
            }),
        ),
    }
}

/// What one post will publish of the research, from the editor's unsaved
/// fields and body, read as the review reads them (#63, ADR 0125): its
/// citations' public descriptions, its claim evidence, and the atlas and
/// comparison pages it links to, with why the rest is withheld.
fn boundary_post(state: &AppState, req: &Request) -> Response {
    if let Err(r) = require_json(req) {
        return r;
    }
    let mut body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    if body["kind"].as_str().unwrap_or("posts") != "posts" || !body["fields"].is_object() {
        return Response::error(422, "Only a post's fields and body are previewed");
    }
    // Read as a draft, as the review reads it, so a citation the build would
    // refuse once published does not stop the preview (ADR 0123).
    body["fields"]["draft"] = json!("true");
    let mut draft = match load_draft_site(state, &body) {
        Ok(draft) => draft,
        Err(response) => return response,
    };
    draft.release();
    let shared = crate::boundary::Shared::read(&state.root, &draft.site.config);
    let blocked = crate::boundary::project_with(&state.root, &mut draft.site, &shared);
    let stores = crate::boundary::Stores::read(&state.root, &shared);
    let Some(post) = draft
        .site
        .posts
        .iter()
        .find(|post| post.source == draft.rel)
    else {
        return Response::error(422, "The post was not found in the site model");
    };
    let manifest = crate::boundary::manifest(&draft.site, &stores, &blocked, Some(post));
    Response::json(
        200,
        &serde_json::to_value(&manifest).unwrap_or_else(|_| json!({})),
    )
}

/// Acknowledge an advisory finding, or withdraw an acknowledgement (ADR 0124).
/// Only a code the contract lets an author acknowledge is accepted; the
/// change names the file's revision and is written atomically or not at all.
fn change_acknowledgement(state: &AppState, req: &Request, add: bool) -> Response {
    use openblog_core::publication_review::Acknowledgement;
    if let Err(r) = require_json(req) {
        return r;
    }
    if req.body.len() > 16 * 1024 {
        return Response::error(413, "An acknowledgement is limited to 16 KiB");
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(body) => body,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let Some(revision) = body["revision"].as_str() else {
        return Response::error(400, "Missing acknowledgements revision");
    };
    let acknowledgement: Acknowledgement =
        match serde_json::from_value(body["acknowledgement"].clone()) {
            Ok(acknowledgement) => acknowledgement,
            Err(error) => {
                return Response::error(422, &format!("Invalid acknowledgement: {error}"))
            }
        };
    if let Some(problem) = acknowledgement.problem() {
        return Response::error(
            422,
            &format!("Not acknowledged: {problem}. Nothing was changed."),
        );
    }
    let result = research_review::change(&state.root, revision, |set| {
        if add {
            set.add(acknowledgement.clone())
        } else {
            set.withdraw(&acknowledgement);
            Ok(())
        }
    });
    match result {
        Ok(snapshot) => Response::json(
            200,
            &json!({ "revision": snapshot.revision, "acknowledged": add }),
        ),
        Err(research_review::StoreError::Conflict) => Response::json(
            409,
            &json!({
                "error": "The acknowledgements changed since this review was read. Nothing was changed; review again.",
                "conflict": true,
                "revision": research_review::load(&state.root).ok().map(|snapshot| snapshot.revision),
            }),
        ),
        Err(error @ research_review::StoreError::Invalid(_)) => Response::json(
            422,
            &json!({
                "error": format!("{error}. Nothing was changed."),
                "file": research_review::ACKNOWLEDGEMENTS_FILE,
            }),
        ),
        Err(research_review::StoreError::Storage(message)) => Response::error(500, &message),
    }
}

/// Check one piece's form values and return the Markdown that holds it in a
/// post (ADR 0253). The engine is the only place a piece is validated or
/// written, so the Admin cannot save one the build would refuse. Nothing is
/// stored.
fn build_piece(req: &Request) -> Response {
    if let Err(r) = require_json(req) {
        return r;
    }
    if req.body.len() > MAX_PIECE_REQUEST_BYTES {
        return Response::error(413, "A piece is limited to 64 KiB");
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(b) => b,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let kind = body["kind"].as_str().unwrap_or("");
    if body["values"]
        .as_array()
        .is_some_and(|pairs| pairs.len() > MAX_PIECE_VALUES)
    {
        return Response::error(413, "That piece has too many details");
    }
    let Some(values) = body["values"].as_array().map(|pairs| {
        pairs
            .iter()
            .map(|pair| {
                (
                    pair[0].as_str().unwrap_or("").to_string(),
                    pair[1].as_str().unwrap_or("").to_string(),
                )
            })
            .collect::<Vec<_>>()
    }) else {
        return Response::error(400, "values must be a list of [field, value] pairs");
    };
    if kind == openblog_core::compare::FENCE {
        return match openblog_core::compare::from_values(&values) {
            Ok(pair) => Response::json(200, &json!({ "markdown": pair.to_markdown() })),
            Err(problems) => Response::json(
                422,
                &json!({ "error": "Check the highlighted details", "problems": problems }),
            ),
        };
    }
    match openblog_core::piece::Piece::from_values(kind, &values) {
        Ok(piece) => Response::json(200, &json!({ "markdown": piece.to_markdown() })),
        Err(problems) => Response::json(
            422,
            &json!({ "error": "Check the highlighted details", "problems": problems }),
        ),
    }
}

fn preview(state: &AppState, req: &Request) -> Response {
    if let Err(r) = require_json(req) {
        return r;
    }
    let body: Json = match serde_json::from_slice(&req.body) {
        Ok(b) => b,
        Err(_) => return Response::error(400, "Invalid JSON"),
    };
    let mut draft = match load_draft_site(state, &body) {
        Ok(draft) => draft,
        Err(response) => return response,
    };
    // A post that links atlas entries with `atlas:` (ADR 0172) is shown with
    // the links the build would make, resolved against the public atlas alone.
    // The draft is loaded, so the build lock is released before the atlas
    // store is read, and only the atlas is attached (never the comparisons or
    // claims, which no concept link needs). Any other document is previewed
    // exactly as before.
    if draft.kind == "posts"
        && draft
            .site
            .posts
            .iter()
            .any(|post| post.source == draft.rel && post.has_concept_links())
    {
        draft.release();
        let mut notes = Vec::new();
        if let Ok(atlas) = crate::site::published_atlas(&state.root, &draft.site.config, &mut notes)
        {
            draft.site.atlas = atlas;
        }
        draft.site.link_concepts();
    }
    let DraftSite {
        site: preview_site,
        themes,
        rel,
        kind,
        portable_config,
        ..
    } = &draft;
    let kind = kind.as_str();
    let rel = rel.as_str();
    let text_body = body["body"].as_str().unwrap_or("");
    let target = match kind {
        "posts" => preview_site
            .posts
            .iter()
            .find(|post| post.source == rel)
            .map(|post| {
                (
                    post.url.clone(),
                    preview_site.theme_for_post(post).to_string(),
                )
            }),
        "pages" => preview_site
            .pages
            .iter()
            .find(|page| page.source == rel)
            .map(|page| {
                (
                    page.url.clone(),
                    preview_site.theme_for_page(page).to_string(),
                )
            }),
        "series" => preview_site
            .series
            .iter()
            .find(|series| series.source.as_deref() == Some(rel))
            .map(|series| {
                (
                    series.url.clone(),
                    preview_site.theme_for_series(series).to_string(),
                )
            }),
        "services" => preview_site
            .services
            .iter()
            .find(|service| service.source == rel)
            .map(|service| (service.url.clone(), preview_site.config.theme.clone())),
        _ => None,
    };
    let Some((url, theme)) = target else {
        return Response::error(422, "Preview document was not found in the site model");
    };
    let research = preview_site
        .posts
        .iter()
        .find(|post| post.source == rel)
        .and_then(|post| post.research.as_ref())
        .map(|research| {
            json!({
                "doi": research.doi,
                "doiUrl": research.doi_url,
                "licenseUrl": research.license_url,
                "referenceCount": research.references.len(),
            })
        });
    // A post that opts in keeps its citation checks visible even when its
    // citations could not be published (a draft with a broken citation).
    let citations_opted_in = kind == "posts"
        && body["fields"]["citations"]
            .as_str()
            .is_some_and(|style| !style.trim().is_empty());
    let citations = preview_site
        .posts
        .iter()
        .find(|post| post.source == rel)
        .and_then(|post| post.citations().map(|summary| (post, summary)))
        .map(|(post, summary)| citation_preview(&post.slug, summary));
    let portable_preview = if kind == "posts" {
        let Some(post) = preview_site.posts.iter().find(|post| post.source == rel) else {
            return Response::error(422, "Preview post was not found in the site model");
        };
        // A published part of a collaborative series previews the series context its external
        // copies carry, exactly as an acknowledgement recomputes it (ADR 0041).
        let projection = match admin_portable_projection(preview_site, post, portable_config) {
            Ok(projection) => projection,
            Err(error) => return Response::error(422, &error),
        };
        let mut portable_html = match projection.portable_html() {
            Ok(output) => output,
            Err(error) => return Response::error(422, &error),
        };
        let portable_markdown = match projection.portable_markdown() {
            Ok(markdown) => markdown,
            Err(error) => return Response::error(422, &error),
        };
        let portable_text = match projection.portable_text() {
            Ok(text) => text,
            Err(error) => return Response::error(422, &error),
        };
        // compose() normalizes leading blank lines; locations must refer to the
        // unsaved editor body, not the composed production-preview document.
        let leading_lines = |text: &str| {
            text[..text.len() - text.trim_start_matches(['\r', '\n']).len()]
                .bytes()
                .filter(|byte| *byte == b'\n')
                .count()
        };
        let editor_lines = leading_lines(text_body);
        let composed_lines = leading_lines(post.authored_markdown());
        for diagnostic in &mut portable_html.diagnostics {
            if let Some(range) = &mut diagnostic.context.source_range {
                range.start_line = range.start_line.saturating_sub(composed_lines) + editor_lines;
                range.end_line = range.end_line.saturating_sub(composed_lines) + editor_lines;
            }
        }
        let source_revision = match projection.source_revision() {
            Ok(revision) => revision,
            Err(error) => return Response::error(422, &error),
        };
        let acknowledgement_path = match resolve_portability_acknowledgement_path(
            &state.root,
            &preview_site.config,
            rel,
        ) {
            Ok(path) => path,
            Err(error) => return Response::error(422, &error),
        };
        let (acknowledgements, acknowledgement_etag) =
            match load_portability_acknowledgements(&acknowledgement_path) {
                Ok(sidecar) => sidecar,
                Err(error) => return Response::error(422, &error),
            };
        let tags = post
            .tags
            .iter()
            .map(|tag| tag.name.clone())
            .collect::<Vec<_>>();
        let destination_tag_plans =
            openblog_core::portability::destination_policies().map(|policy| {
                openblog_core::portability::destination_tag_plan(policy.provider, rel, &tags)
            });
        let diagnostics_by_representation = ["portable-html", "portable-markdown", "portable-text"]
            .into_iter()
            .map(|representation| {
                (
                    representation.to_string(),
                    portable_html
                        .diagnostics
                        .iter()
                        .map(|diagnostic| diagnostic.scoped(representation, "portable-export"))
                        .collect::<Vec<_>>(),
                )
            })
            .collect::<std::collections::BTreeMap<_, _>>();
        let destination_content_plans = openblog_core::portability::destination_policies()
            .into_iter()
            .map(|policy| {
                openblog_core::portability::destination_content_plan(
                    policy.provider,
                    rel,
                    &portable_html,
                )
            })
            .collect::<Vec<_>>();
        json!({
            "html": portable_html.html,
            "markdown": portable_markdown,
            "text": portable_text,
            "capabilities": portable_html.capabilities,
            "diagnostics": portable_html.diagnostics,
            "diagnosticsByRepresentation": diagnostics_by_representation,
            "destinations": openblog_core::portability::destination_policies(),
            "destinationTagPlans": destination_tag_plans,
            "destinationContentPlans": destination_content_plans,
            "sourceRevision": source_revision,
            "acknowledgements": acknowledgements.acknowledgements,
            "acknowledgementEtag": acknowledgement_etag,
        })
    } else {
        Json::Null
    };
    let social = match social_metadata(preview_site, rel) {
        Ok(meta) => json!({
            "siteName": meta.site_name,
            "title": meta.title,
            "description": meta.description,
            "url": meta.url,
            "image": meta.image,
            "imageAlt": meta.image_alt.unwrap_or_default(),
            "type": meta.kind,
            "card": meta.card,
        }),
        Err(e) => return Response::error(422, &e),
    };
    let document = match generate_document(preview_site, themes, rel) {
        Ok(document) => document,
        Err(e) => return Response::error(422, &e),
    };
    let token = match auth::random_token() {
        Ok(token) => token,
        Err(e) => return Response::error(500, &e),
    };
    let csp = preview_csp(&preview_site.config);
    store_preview(state, &token, document.contents, csp);
    let accessibility: Vec<_> = preview_site
        .accessibility
        .iter()
        .filter(|finding| finding.source.path == rel || finding.scope == AuditScope::Site)
        .cloned()
        .collect();
    let evidence: Vec<_> = preview_site
        .evidence
        .iter()
        .filter(|finding| finding.source.path == rel)
        .cloned()
        .collect();
    Response::json(
        200,
        &json!({
            "previewUrl": format!("/admin/api/preview/{token}"),
            "url": url,
            "theme": theme,
            "social": social,
            "research": research,
            "citations": citations,
            "citationsOptedIn": citations_opted_in,
            "portablePreview": portable_preview,
            "warnings": preview_site.warnings,
            "accessibility": accessibility,
            "evidence": evidence
        }),
    )
}

/// What the previewed post's citations made public, with its portable
/// bibliography exports (ADR 0050). Both exports are built from the
/// references the preview published, so they match the notes exactly and
/// hold only their public description; each lists what its format omits.
fn citation_preview(slug: &str, summary: &openblog_core::bibliography::CitationSummary) -> Json {
    let export = |export: source_interchange::Export, extension: &str, media_type: &str| {
        json!({
            "filename": format!("{slug}-references.{extension}"),
            "mediaType": media_type,
            "count": export.count,
            "content": export.content,
            "losses": export.losses,
        })
    };
    json!({
        "style": summary.style.key(),
        "locale": summary.locale.key(),
        "citations": summary.citations,
        "notes": summary.notes,
        "references": summary.references.len(),
        "offline": true,
        "exports": {
            "csl-json": export(
                source_interchange::export_cited_csl_json(&summary.references),
                "json",
                "application/vnd.citationstyles.csl+json",
            ),
            "bibtex": export(
                source_interchange::export_cited_bibtex(&summary.references),
                "bib",
                "application/x-bibtex",
            ),
        },
    })
}

/// The policy every preview document is served under: it can load this site's own assets and the
/// configured asset origin, and nothing else.
fn preview_csp(config: &SiteConfig) -> String {
    let asset_origin = http_origin(&config.cdn.url);
    let script_sources = asset_origin
        .as_deref()
        .map(|origin| format!("'self' {origin}"))
        .unwrap_or_else(|| "'self'".to_string());
    let frame_sources = openblog_core::embed::FRAME_SOURCES;
    format!(
        "default-src 'none'; script-src 'unsafe-inline' {script_sources}; style-src 'unsafe-inline' 'self' https:; \
         img-src 'self' https: data:; font-src 'self' https: data:; connect-src 'self' https://play.rust-lang.org; \
         frame-src {frame_sources}; object-src 'none'; base-uri 'self'; form-action 'none'; frame-ancestors 'self'"
    )
}

/// Keep a preview document for `preview_document` to serve; only the newest sixteen are kept.
fn store_preview(state: &AppState, token: &str, html: String, csp: String) {
    let mut previews = lock(&state.previews);
    previews.push(PreviewDocument {
        token: token.to_string(),
        html,
        csp,
    });
    if previews.len() > 16 {
        previews.remove(0);
    }
}

fn preview_document(state: &AppState, token: &str) -> Response {
    if token.len() != 64 || !token.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Response::error(404, "Preview not found");
    }
    let document = lock(&state.previews)
        .iter()
        .find(|document| document.token == token)
        .map(|document| (document.html.clone(), document.csp.clone()));
    let Some((html, csp)) = document else {
        return Response::error(404, "Preview not found");
    };
    Response::new(200, "text/html; charset=utf-8", html.into_bytes())
        .with_header("Content-Security-Policy", &csp)
        .with_header("X-Frame-Options", "SAMEORIGIN")
        .with_header("Referrer-Policy", "no-referrer")
}

fn http_origin(value: &str) -> Option<String> {
    let value = value.trim();
    let (scheme, rest) = value.split_once("://")?;
    if !matches!(scheme, "http" | "https") {
        return None;
    }
    let authority = rest.split(['/', '?', '#']).next()?;
    if authority.is_empty()
        || !authority.bytes().all(|byte| {
            byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'-' | b':' | b'[' | b']')
        })
    {
        return None;
    }
    Some(format!("{scheme}://{authority}"))
}

// ---------------------------------------------------------------------------
// Uploads
// ---------------------------------------------------------------------------

/// The image type, judged by the file's own bytes (never the client's claim).
fn sniff_image(bytes: &[u8]) -> Option<&'static str> {
    if bytes.starts_with(&[0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A]) {
        Some("png")
    } else if bytes.starts_with(&[0xFF, 0xD8, 0xFF]) {
        Some("jpg")
    } else if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
        Some("gif")
    } else if bytes.len() > 12 && &bytes[0..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        Some("webp")
    } else if bytes.len() > 12
        && &bytes[4..8] == b"ftyp"
        && (&bytes[8..12] == b"avif" || &bytes[8..12] == b"avis")
    {
        Some("avif")
    } else {
        None
    }
}

fn sanitize_upload_stem(name: &str) -> String {
    let stem = name.rsplit(['/', '\\']).next().unwrap_or(name);
    let stem = stem.rsplit_once('.').map(|(s, _)| s).unwrap_or(stem);
    let cleaned: String = stem
        .to_lowercase()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
        .collect();
    let cleaned = cleaned
        .split('-')
        .filter(|p| !p.is_empty())
        .collect::<Vec<_>>()
        .join("-");
    let cleaned = openblog_core::slug::limit(&cleaned, 60);
    if cleaned.is_empty() {
        "image".to_string()
    } else {
        cleaned
    }
}

fn upload(state: &AppState, req: &Request) -> Response {
    let config = match site::load_config(&state.root) {
        Ok(c) => c,
        Err(e) => return Response::error(500, &e),
    };
    let max = config.admin.max_upload_mb as usize * 1024 * 1024;
    if req.body.is_empty() {
        return Response::error(400, "No image data");
    }
    if req.body.len() > max {
        return Response::error(
            413,
            &format!("Images can be at most {} MB", config.admin.max_upload_mb),
        );
    }
    let Some(ext) = sniff_image(&req.body) else {
        return Response::error(
            415,
            "Only PNG, JPEG, GIF, WebP, and AVIF images can be uploaded",
        );
    };
    let name = req.query.get("name").map(String::as_str).unwrap_or("image");
    // A capture's photo has a fixed name per capture id and slot, so sending it again lands on the same
    // file instead of a second copy (ADR 0297).
    let capture_stem = match (req.query.get("capture"), req.query.get("slot")) {
        (None, None) => None,
        (Some(id), Some(slot)) => {
            match slot
                .parse::<usize>()
                .ok()
                .and_then(|slot| openblog_core::capture::photo_stem(id, slot))
            {
                Some(stem) => Some(stem),
                None => return Response::error(400, "That capture id or photo slot is not valid"),
            }
        }
        _ => return Response::error(400, "A capture upload needs both capture and slot"),
    };
    let stem = sanitize_upload_stem(name);
    let year = clock::now().civil().year;
    let dir_rel = if capture_stem.is_some() {
        "images/uploads/captures".to_string()
    } else {
        format!("images/uploads/{year}")
    };
    let static_dir = state.root.join(&config.paths.static_dir);

    let _guard = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    if let Some(stem) = &capture_stem {
        let rel = format!("{dir_rel}/{stem}.{ext}");
        if static_dir.join(&rel).is_file() {
            let url = format!("/{rel}");
            return Response::json(
                200,
                &json!({ "url": url, "markdown": format!("![]({url})"), "duplicate": true }),
            );
        }
    }
    let mut file_name = format!("{}.{ext}", capture_stem.as_deref().unwrap_or(&stem));
    let mut n = 2;
    while capture_stem.is_none() && static_dir.join(&dir_rel).join(&file_name).exists() {
        file_name = format!("{stem}-{n}.{ext}");
        n += 1;
    }
    let rel = format!("{dir_rel}/{file_name}");
    if let Err(e) = fsutil::write_file(&static_dir.join(&rel), &req.body) {
        return Response::error(500, &e);
    }
    // Make it available immediately without a full rebuild.
    let out = state.out_dir(&config);
    if out.join(fsutil::MARKER).exists() {
        let _ = fsutil::write_file(&out.join(&rel), &req.body);
    }
    let url = format!("/{rel}");
    eprintln!("admin: uploaded {url} ({} bytes)", req.body.len());
    Response::json(
        201,
        &json!({ "url": url, "markdown": format!("![]({url})") }),
    )
}

/// The directory of a site's capture ledger and voice notes: private, never built, never served.
fn captures_dir(state: &AppState) -> PathBuf {
    state.root.join(".openblog/captures")
}

/// The stored voice note of a capture, if one was uploaded.
fn stored_capture_audio(state: &AppState, id: &str) -> Option<String> {
    openblog_core::capture::AUDIO_EXTENSIONS
        .iter()
        .filter_map(|extension| openblog_core::capture::audio_file_name(id, extension))
        .find(|name| captures_dir(state).join(name).is_file())
}

/// A capture's voice note (ADR 0298): checked by its bytes, bounded, and kept privately beside the capture's
/// ledger entry. It is never written under the static folder, so no build or export can publish it. Sending
/// the same capture's note again keeps the first and writes nothing.
fn upload_capture_audio(state: &AppState, req: &Request) -> Response {
    let Some(id) = req
        .query
        .get("capture")
        .filter(|id| openblog_core::capture::valid_id(id))
    else {
        return Response::error(400, "That capture id is not valid");
    };
    if req.body.is_empty() {
        return Response::error(400, "No audio data");
    }
    if req.body.len() > openblog_core::capture::MAX_AUDIO_BYTES {
        return Response::error(
            413,
            &format!(
                "A voice note can be at most {} MB",
                openblog_core::capture::MAX_AUDIO_BYTES / (1024 * 1024)
            ),
        );
    }
    let Some(extension) = openblog_core::capture::sniff_audio(&req.body) else {
        return Response::error(415, "That is not an audio recording this site can keep");
    };
    let Some(name) = openblog_core::capture::audio_file_name(id, extension) else {
        return Response::error(400, "That capture id is not valid");
    };
    let _guard = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    if stored_capture_audio(state, id).is_some() {
        return Response::json(200, &json!({ "stored": true, "duplicate": true }));
    }
    if let Err(error) = fsutil::write_file(&captures_dir(state).join(&name), &req.body) {
        return Response::error(500, &error);
    }
    eprintln!("admin: kept a voice note ({} bytes)", req.body.len());
    Response::json(201, &json!({ "stored": true, "bytes": req.body.len() }))
}

fn upload_track(state: &AppState, req: &Request) -> Response {
    let config = match site::load_config(&state.root) {
        Ok(config) => config,
        Err(error) => return Response::error(500, &error),
    };
    let max = config.admin.max_upload_mb as usize * 1024 * 1024;
    if req.body.is_empty() {
        return Response::error(400, "No GPX data");
    }
    if req.body.len() > max {
        return Response::error(
            413,
            &format!("Tracks can be at most {} MB", config.admin.max_upload_mb),
        );
    }
    let Ok(source) = std::str::from_utf8(&req.body) else {
        return Response::error(415, "GPX tracks must be UTF-8 XML");
    };
    if let Err(error) = validate_gpx(source) {
        return Response::error(415, &error);
    }
    let token = match auth::random_token() {
        Ok(token) => token,
        Err(error) => return Response::error(500, &error),
    };
    let pending_dir = state.root.join(".openblog/pending-tracks");
    let _guard = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    prune_staged_tracks(&pending_dir);
    if let Err(error) = fsutil::write_file(&pending_dir.join(format!("{token}.gpx")), &req.body) {
        return Response::error(500, &error);
    }
    eprintln!("admin: staged track {token} ({} bytes)", req.body.len());
    Response::json(201, &json!({ "token": token }))
}

fn discard_track(state: &AppState, req: &Request) -> Response {
    let Some(token) = req.query.get("token") else {
        return Response::error(400, "Missing track token");
    };
    if token.len() != 64 || !token.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Response::error(400, "Invalid track token");
    }
    let _guard = lock(&state.build);
    let _filesystem_transaction = match content_transaction(state) {
        Ok(lock) => lock,
        Err(response) => return response,
    };
    let path = state
        .root
        .join(".openblog/pending-tracks")
        .join(format!("{token}.gpx"));
    match fs::remove_file(path) {
        Ok(()) => Response::json(200, &json!({ "discarded": true })),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            Response::json(200, &json!({ "discarded": false }))
        }
        Err(error) => Response::error(500, &format!("cannot discard staged track: {error}")),
    }
}

fn prune_staged_tracks(dir: &Path) {
    let Ok(entries) = fs::read_dir(dir) else {
        return;
    };
    let max_age = Duration::from_secs(24 * 60 * 60);
    for entry in entries.flatten() {
        let path = entry.path();
        let stale = entry
            .metadata()
            .and_then(|metadata| metadata.modified())
            .and_then(|modified| modified.elapsed().map_err(std::io::Error::other))
            .is_ok_and(|age| age > max_age);
        if stale && path.extension().and_then(|value| value.to_str()) == Some("gpx") {
            let _ = fs::remove_file(path);
        }
    }
}

fn validate_gpx(source: &str) -> Result<(), String> {
    let lower = source.to_ascii_lowercase();
    if lower.contains("<!doctype")
        || lower.contains("<!entity")
        || lower.contains("<script")
        || lower.contains("<?xml-stylesheet")
    {
        return Err("Choose a GPX track without scripts or document entities".into());
    }
    let mut stack: Vec<String> = Vec::new();
    let mut root_seen = false;
    let mut closed_root = false;
    let mut points = 0usize;
    for tag in source
        .split('<')
        .skip(1)
        .filter_map(|part| part.split_once('>').map(|pair| pair.0))
    {
        let tag = tag.trim();
        if let Some(closing) = tag.strip_prefix('/') {
            let name = closing
                .split_ascii_whitespace()
                .next()
                .unwrap_or("")
                .rsplit(':')
                .next()
                .unwrap_or("")
                .to_ascii_lowercase();
            if stack.pop().as_deref() != Some(name.as_str()) {
                return Err("GPX XML elements are not properly nested".into());
            }
            if name == "gpx" {
                closed_root = true;
            }
            continue;
        }
        if tag.starts_with(['?', '!']) {
            continue;
        }
        let name = tag
            .split_ascii_whitespace()
            .next()
            .unwrap_or("")
            .trim_end_matches('/');
        let local_name = name.rsplit(':').next().unwrap_or(name).to_ascii_lowercase();
        if stack.is_empty() {
            if root_seen || closed_root {
                return Err("GPX must contain one document root".into());
            }
            root_seen = true;
            if local_name != "gpx" {
                return Err("GPX must be the document root".into());
            }
        }
        if local_name == "trkpt"
            && stack.iter().any(|name| name == "trk")
            && stack.iter().any(|name| name == "trkseg")
        {
            let lat = xml_attribute(tag, "lat").and_then(|value| value.parse::<f64>().ok());
            let lon = xml_attribute(tag, "lon").and_then(|value| value.parse::<f64>().ok());
            if lat.is_some_and(|value| value.is_finite() && value.abs() <= 90.0)
                && lon.is_some_and(|value| value.is_finite() && value.abs() <= 180.0)
            {
                points += 1;
            }
        }
        if tag.ends_with('/') {
            if local_name == "gpx" {
                closed_root = true;
            }
        } else {
            stack.push(local_name);
        }
    }
    if root_seen && closed_root && stack.is_empty() && points >= 2 {
        Ok(())
    } else {
        Err("Choose a valid GPX document with at least two bounded track points".into())
    }
}

fn xml_attribute<'a>(tag: &'a str, key: &str) -> Option<&'a str> {
    for (index, _) in tag.match_indices(key) {
        if index == 0 || !tag.as_bytes()[index - 1].is_ascii_whitespace() {
            continue;
        }
        let Some(candidate) = tag[index + key.len()..]
            .trim_start()
            .strip_prefix('=')
            .map(str::trim_start)
        else {
            continue;
        };
        let quote = candidate.as_bytes().first().copied()?;
        if !matches!(quote, b'\'' | b'"') {
            continue;
        }
        let value = &candidate[1..];
        return Some(&value[..value.find(quote as char)?]);
    }
    None
}

