    #[test]
    fn job_fields_save_as_one_nested_mapping_and_check_with_core_sentences() {
        let f = fixture("job-save");
        let session = login_ok(&f);
        let fields = json!({
            "title": "Oak floor", "date": "2026-10-21", "profile": "job",
            "job.trade": "flooring", "job.service": "hardwood-install",
            "job.place.town": "Maple Falls", "job.place.region": "WA",
            "job.started": "2026-10-14", "job.finished": "2026-10-16",
            "job.media.before": ["/images/before.jpg"],
        });
        let saved = handle(
            &f.state,
            &authed(
                json_req(
                    "POST",
                    "/admin/api/document",
                    json!({ "kind": "posts", "fields": fields, "body": "## Problem\n" }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(
            saved.status,
            201,
            "{}",
            String::from_utf8_lossy(&saved.body)
        );
        let path = body_json(&saved)["path"].as_str().unwrap().to_string();
        let on_disk = std::fs::read_to_string(f.state.root.join("content").join(&path)).unwrap();
        assert!(on_disk.contains("  media:\n    before:\n      - /images/before.jpg\n  place:\n    region: WA\n    town: Maple Falls\n"), "{on_disk}");
        let reread = handle(
            &f.state,
            &authed(
                req("GET", &format!("/admin/api/document?path={path}")),
                &session,
                false,
            ),
        );
        assert_eq!(
            body_json(&reread)["fields"]["job.place.town"],
            "Maple Falls"
        );

        let check = |fields: Json, csrf: bool| {
            handle(
                &f.state,
                &authed(
                    json_req("POST", "/admin/api/job/check", json!({ "fields": fields })),
                    &session,
                    csrf,
                ),
            )
        };
        let bad = check(
            json!({ "job.trade": "welding", "job.costBand": "cheap" }),
            true,
        );
        assert_eq!(bad.status, 200);
        let problems = body_json(&bad)["problems"].to_string();
        assert!(
            problems.contains("welding") && problems.contains("job.costBand"),
            "{problems}"
        );
        assert!(
            problems.contains("job.place.town"),
            "every problem at once: {problems}"
        );
        assert_eq!(check(json!({ "job.trade": "flooring" }), false).status, 403);
        let odd = check(json!({ "job..x": "a", "job.a.b.c.d": "b" }), true);
        assert_eq!(odd.status, 422);
        assert_eq!(
            handle(
                &f.state,
                &json_req("POST", "/admin/api/job/check", json!({}))
            )
            .status,
            401
        );
        assert_eq!(
            preflight(
                &f.state,
                &authed(req("POST", "/admin/api/job/check"), &session, true)
            )
            .unwrap(),
            MAX_JOB_CHECK_BYTES
        );
    }

    #[test]
    fn assistant_status_is_authenticated_and_never_exposes_credentials() {
        let _env = quiz_env();
        let _key = EnvRestore::capture("OPENBLOG_LESSONS_API_KEY");
        let f = fixture("assistant-status");

        assert_eq!(
            handle(&f.state, &req("GET", "/admin/api/assistant/status")).status,
            401
        );

        let session = login_ok(&f);
        std::env::remove_var("OPENBLOG_LESSONS_API_KEY");
        let missing = handle(
            &f.state,
            &authed(req("GET", "/admin/api/assistant/status"), &session, false),
        );
        assert_eq!(missing.status, 200);
        let missing_json = body_json(&missing);
        assert_eq!(missing_json["providerType"], "generic-https");
        assert_eq!(missing_json["configured"], false);
        assert_eq!(missing_json["capabilities"]["knowledgeChecks"], true);
        assert_eq!(missing_json["capabilities"]["review"], true);
        assert_eq!(missing_json["capabilities"]["context"], true);
        assert_eq!(missing_json["capabilities"]["interactions"], true);
        assert_eq!(missing_json["capabilities"]["autocomplete"], true);
        assert!(missing_json["message"]
            .as_str()
            .unwrap()
            .contains("Non-AI authoring remains available"));

        set_quiz_endpoint(
            &f,
            "https://endpoint-user:endpoint-password@assistant.example:8443/generate?api_key=query-secret",
        );
        std::env::set_var("OPENBLOG_LESSONS_API_KEY", "provider-secret-value");
        let configured = handle(
            &f.state,
            &authed(req("GET", "/admin/api/assistant/status"), &session, false),
        );
        assert_eq!(configured.status, 200);
        let configured_json = body_json(&configured);
        assert_eq!(configured_json["configured"], true);
        assert_eq!(configured_json["model"], "test");
        assert_eq!(
            configured_json["destination"],
            "https://assistant.example:8443"
        );
        let configured_body = String::from_utf8_lossy(&configured.body);
        assert!(!configured_body.contains("provider-secret-value"));
        assert!(!configured_body.contains("endpoint-user"));
        assert!(!configured_body.contains("endpoint-password"));
        assert!(!configured_body.contains("query-secret"));
    }

    #[test]
    fn appearance_settings_are_authenticated_conflict_safe_and_rebuild_public_pages() {
        let f = fixture("appearance-settings");
        let path = "/admin/api/appearance";
        assert_eq!(handle(&f.state, &req("GET", path)).status, 401);
        assert_eq!(
            handle(&f.state, &json_req("PUT", path, json!({}))).status,
            401
        );
        let session = login_ok(&f);
        let initial = body_json(&handle(
            &f.state,
            &authed(req("GET", path), &session, false),
        ));
        assert!(initial["colorSchemeToggle"].is_null());
        assert_eq!(initial["themeColorSchemeToggle"], true);
        let save = json!({"colorSchemeToggle": false, "etag": initial["etag"]});
        assert_eq!(
            handle(
                &f.state,
                &authed(json_req("PUT", path, save.clone()), &session, false)
            )
            .status,
            403
        );
        for invalid in [
            json!({}),
            json!({"colorSchemeToggle":"false"}),
            json!({"colorSchemeToggle":0}),
        ] {
            assert_eq!(
                handle(
                    &f.state,
                    &authed(json_req("PUT", path, invalid), &session, true)
                )
                .status,
                422
            );
        }
        let config_path = f.dir.join(site::CONFIG_FILE);
        let mut config: Json =
            serde_json::from_str(&fs::read_to_string(&config_path).unwrap()).unwrap();
        config["futureSetting"] = json!({"keep": true});
        fs::write(&config_path, serde_json::to_string_pretty(&config).unwrap()).unwrap();
        assert_eq!(
            handle(
                &f.state,
                &authed(json_req("PUT", path, save), &session, true)
            )
            .status,
            409
        );
        let mut settings = body_json(&handle(
            &f.state,
            &authed(req("GET", path), &session, false),
        ));
        for choice in [json!(false), json!(true), Json::Null] {
            let saved = handle(
                &f.state,
                &authed(
                    json_req(
                        "PUT",
                        path,
                        json!({
                            "colorSchemeToggle": choice, "etag": settings["etag"]
                        }),
                    ),
                    &session,
                    true,
                ),
            );
            assert_eq!(
                saved.status,
                200,
                "{}",
                String::from_utf8_lossy(&saved.body)
            );
            settings = body_json(&saved);
            assert!(settings["buildError"].is_null());
            let value: Json =
                serde_json::from_str(&fs::read_to_string(&config_path).unwrap()).unwrap();
            assert_eq!(value["colorSchemeToggle"], choice);
            assert_eq!(value["futureSetting"]["keep"], true);
            let html = fs::read_to_string(f.dir.join("dist/index.html")).unwrap();
            assert_eq!(html.contains("<ob-theme-toggle"), choice != false);
            assert_eq!(
                html.contains("localStorage.getItem(\"ob-scheme\")"),
                choice != false
            );
        }
        // Report that the setting was saved even if unrelated content prevents rebuilding.
        fs::write(
            f.dir.join("content/posts/broken.md"),
            "---\ntitle: Broken\ndate: invalid\n---\n",
        )
        .unwrap();
        let saved = handle(
            &f.state,
            &authed(
                json_req(
                    "PUT",
                    path,
                    json!({
                        "colorSchemeToggle": false, "etag": settings["etag"]
                    }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(saved.status, 200);
        let result = body_json(&saved);
        assert!(result["buildError"]
            .as_str()
            .is_some_and(|error| !error.is_empty()));
        assert_eq!(
            site::load_config(&f.dir).unwrap().color_scheme_toggle,
            Some(false)
        );
        let reloaded = body_json(&handle(
            &f.state,
            &authed(req("GET", path), &session, false),
        ));
        assert_eq!(result["etag"], reloaded["etag"]);
    }

    #[test]
    fn engagement_settings_are_authenticated_write_only_and_conflict_safe() {
        let _env = quiz_env();
        let _key = EnvRestore::capture(ENGAGEMENT_ENVIRONMENT_NAME);
        let _origin = EnvRestore::capture(ENGAGEMENT_ORIGIN_ENVIRONMENT_NAME);
        std::env::remove_var(ENGAGEMENT_ENVIRONMENT_NAME);
        std::env::remove_var(ENGAGEMENT_ORIGIN_ENVIRONMENT_NAME);
        let f = fixture("engagement-settings");
        assert_eq!(
            handle(&f.state, &req("GET", "/admin/api/engagement/settings")).status,
            401
        );
        let session = login_ok(&f);
        let initial = handle(
            &f.state,
            &authed(
                req("GET", "/admin/api/engagement/settings"),
                &session,
                false,
            ),
        );
        assert_eq!(initial.status, 200);
        let initial_json = body_json(&initial);
        assert_eq!(initial_json["enabled"], false);
        assert_eq!(initial_json["captcha"]["provider"], "off");
        assert_eq!(initial_json["captcha"]["scope"], "session");
        let put_captcha = |captcha: Json| {
            handle(
                &f.state,
                &authed(
                    json_req(
                        "PUT",
                        "/admin/api/engagement/settings",
                        json!({ "etag": initial_json["etag"], "captcha": captcha }),
                    ),
                    &session,
                    true,
                ),
            )
        };
        let secret_attempt = put_captcha(
            json!({ "provider": "turnstile", "siteKey": "public-key", "secret": "never-persist-this" }),
        );
        assert_eq!(secret_attempt.status, 422);
        assert!(!String::from_utf8_lossy(&secret_attempt.body).contains("never-persist-this"));
        for (invalid, hint) in [
            (json!({ "provider": "turnstile" }), "siteKey is required"),
            (json!({ "provider": "other" }), "turnstile"),
            (json!({ "scope": "always" }), "every-comment"),
            (
                json!({ "provider": "turnstile", "siteKey": "bad key!" }),
                "never put a secret",
            ),
        ] {
            let refused = put_captcha(invalid);
            assert_eq!(refused.status, 422);
            assert!(String::from_utf8_lossy(&refused.body).contains(hint));
        }
        assert!(!fs::read_to_string(f.dir.join(site::CONFIG_FILE))
            .unwrap()
            .contains("captcha"));
        let save = json!({
            "enabled": true,
            "comments": true,
            "analytics": true,
            "endpoint": "https://blog.example/api",
            "etag": initial_json["etag"],
            "credentialAction": "replace",
            "credential": "moderation-secret",
            "captcha": { "provider": "turnstile", "siteKey": " public-key ", "scope": "every-comment" },
        });
        assert_eq!(
            handle(
                &f.state,
                &authed(
                    json_req("PUT", "/admin/api/engagement/settings", save.clone()),
                    &session,
                    false,
                ),
            )
            .status,
            403
        );
        let saved = handle(
            &f.state,
            &authed(
                json_req("PUT", "/admin/api/engagement/settings", save),
                &session,
                true,
            ),
        );
        assert_eq!(saved.status, 200);
        assert_eq!(body_json(&saved)["captcha"]["siteKey"], "public-key");
        assert_eq!(body_json(&saved)["captcha"]["scope"], "every-comment");
        assert_eq!(body_json(&saved)["credential"]["configured"], true);
        assert!(!String::from_utf8_lossy(&saved.body).contains("moderation-secret"));
        let config = site::load_config(&f.dir).unwrap();
        assert!(
            config.engagement.enabled && config.engagement.comments && config.engagement.analytics
        );
        assert_eq!(config.engagement.endpoint, "https://blog.example/api");
        assert!(!config.engagement.feedback);

        // The passage-feedback opt-in, set in openblog.json, survives a save
        // that does not mention it, and can be changed explicitly.
        let config_path = f.dir.join(site::CONFIG_FILE);
        let mut on_disk: Json =
            serde_json::from_str(&fs::read_to_string(&config_path).unwrap()).unwrap();
        on_disk["engagement"]["feedback"] = json!(true);
        fs::write(
            &config_path,
            serde_json::to_string_pretty(&on_disk).unwrap(),
        )
        .unwrap();
        let current = body_json(&handle(
            &f.state,
            &authed(
                req("GET", "/admin/api/engagement/settings"),
                &session,
                false,
            ),
        ));
        assert_eq!(current["feedback"], true);
        let kept = handle(
            &f.state,
            &authed(
                json_req(
                    "PUT",
                    "/admin/api/engagement/settings",
                    json!({
                        "enabled": true,
                        "comments": false,
                        "analytics": true,
                        "endpoint": "https://blog.example/api",
                        "etag": current["etag"],
                        "credentialAction": "keep",
                    }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(kept.status, 200);
        let config = site::load_config(&f.dir).unwrap();
        assert!(config.engagement.feedback && !config.engagement.comments);
        assert!(config.engagement.captcha.enabled());
        assert_eq!(config.engagement.captcha.site_key, "public-key");
        assert_eq!(config.engagement.captcha.scope, "every-comment");
        let off = handle(
            &f.state,
            &authed(
                json_req(
                    "PUT",
                    "/admin/api/engagement/settings",
                    json!({
                        "enabled": true,
                        "comments": true,
                        "analytics": true,
                        "endpoint": "https://blog.example/api",
                        "feedback": false,
                        "etag": body_json(&kept)["etag"],
                        "credentialAction": "keep",
                    }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(off.status, 200);
        assert!(!site::load_config(&f.dir).unwrap().engagement.feedback);
        assert!(site::load_config(&f.dir)
            .unwrap()
            .engagement
            .captcha
            .enabled());
        let cleared = handle(
            &f.state,
            &authed(
                json_req(
                    "PUT",
                    "/admin/api/engagement/settings",
                    json!({
                        "enabled": true,
                        "comments": true,
                        "analytics": true,
                        "endpoint": "https://blog.example/api",
                        "etag": body_json(&off)["etag"],
                        "credentialAction": "keep",
                        "captcha": { "provider": "off" },
                    }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(cleared.status, 200);
        assert_eq!(body_json(&cleared)["captcha"]["provider"], "off");
        assert!(!fs::read_to_string(f.dir.join(site::CONFIG_FILE))
            .unwrap()
            .contains("captcha"));
        let off = cleared;
        let saved_json = body_json(&off);
        let moved = handle(
            &f.state,
            &authed(
                json_req(
                    "PUT",
                    "/admin/api/engagement/settings",
                    json!({
                        "enabled": true,
                        "comments": true,
                        "analytics": true,
                        "endpoint": "https://elsewhere.example/api",
                        "etag": saved_json["etag"],
                        "credentialAction": "keep",
                    }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(moved.status, 200);
        assert_eq!(body_json(&moved)["credential"]["configured"], false);
        assert!(
            engagement_credential(&f.dir, "https://elsewhere.example/api")
                .unwrap_err()
                .contains("different origin")
        );

        let stale = handle(
            &f.state,
            &authed(
                json_req(
                    "PUT",
                    "/admin/api/engagement/settings",
                    json!({ "enabled": false, "etag": initial_json["etag"] }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(stale.status, 409);
    }

    /// One received record about the whole of `post`, at `revision` (the
    /// post's own when `None`), from a reader whose name stays private.
    fn feedback_record(
        site: &Site,
        post: &openblog_core::Post,
        revision: Option<&str>,
        selector: &str,
    ) -> openblog_core::scholarly_feedback::ScholarlyFeedback {
        let document = PassageDocument::of_post(post, &site.config);
        let target = match selector {
            "work" => document.work_target(),
            _ => {
                let index = document
                    .sections
                    .iter()
                    .position(|section| section.anchor.is_some())
                    .unwrap_or(0);
                document.section_target(index).unwrap()
            }
        };
        openblog_core::scholarly_feedback::FeedbackSubmission::from_value(&json!({
            "version": 1,
            "kind": "question",
            "work": post.url,
            "revision": revision.unwrap_or(&document.revision),
            "target": target.to_value(),
            "body": "Why <b>this</b>?",
            "seenAt": "2026-10-26T09:58:00Z",
            "attribution": {"name": "Private Reader", "publishName": false},
        }))
        .unwrap()
        .receive(
            openblog_core::DateTime::parse("2026-10-26T10:00:00Z").unwrap(),
            openblog_core::feedback_provenance::FeedbackChannel::Hosted,
        )
        .unwrap()
    }

    const FEEDBACK_ITEM_ID: &str = "00000000-0000-4000-8000-0000000000a1";

    /// Switch passage feedback on in a fixture's openblog.json, with a hosted
    /// endpoint nothing in the test calls, so its kinds are shown (ADR 0101).
    fn enable_passage_feedback(dir: &Path) {
        let path = dir.join(site::CONFIG_FILE);
        let mut config: Json = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
        config["engagement"] = json!({
            "enabled": true,
            "feedback": true,
            "endpoint": "https://engagement.invalid/api",
        });
        fs::write(&path, serde_json::to_string_pretty(&config).unwrap()).unwrap();
    }

