    #[test]
    fn a_citation_problem_elsewhere_or_in_a_draft_never_blocks_a_preview_or_a_draft_save() {
        let f = fixture("citation-scope");
        fs::write(
            f.dir.join("content/posts/broken.md"),
            "---\ntitle: Broken\ndate: 2026-10-01\ncitations: notes\n---\nA claim [@nobody].\n",
        )
        .unwrap();
        let session = login_ok(&f);
        let send = |method: &str, route: &str, body: Json| {
            handle(
                &f.state,
                &authed(json_req(method, route, body), &session, true),
            )
        };
        let draft = json!({
            "kind": "posts",
            "path": "posts/not-yet.md",
            "fields": { "title": "Not yet", "date": "2026-10-23", "draft": "true", "citations": "notes" },
            "body": "Soon [@not-yet]."
        });
        let preview = send("POST", "/admin/api/preview", draft.clone());
        assert_eq!(
            preview.status,
            200,
            "{}",
            String::from_utf8_lossy(&preview.body)
        );
        // The draft's citations are not published, yet the preview says the
        // post opted in, so Evidence Studio stays active for its findings.
        let body: Json = serde_json::from_slice(&preview.body).unwrap();
        assert_eq!(body["citations"], Json::Null);
        assert_eq!(body["citationsOptedIn"], true);
        let saved = send("POST", "/admin/api/document", draft);
        assert_eq!(
            saved.status,
            201,
            "{}",
            String::from_utf8_lossy(&saved.body)
        );

        // The broken post's own preview names its problem and nothing else.
        let own = send(
            "POST",
            "/admin/api/preview",
            json!({
                "kind": "posts",
                "path": "posts/broken.md",
                "fields": { "title": "Broken", "date": "2026-10-01", "citations": "notes" },
                "body": "A claim [@nobody]."
            }),
        );
        assert_eq!(own.status, 422);
        let message = String::from_utf8_lossy(&own.body);
        assert!(
            message.contains("posts/broken.md: line 7: this post cites sources")
                && !message.contains("not-yet"),
            "{message}"
        );
    }

    #[test]
    fn preview_reports_citation_checks_and_offers_public_bibliography_exports() {
        let f = fixture("citation-preview");
        let library = f.dir.join(source_store::LIBRARY_FILE);
        fs::create_dir_all(library.parent().unwrap()).unwrap();
        fs::write(
            &library,
            r#"{"version":1,"sources":[
              {"id":"bare","kind":"work","title":"Bare","csl":{"type":"article-journal"},"secret":"PRIVATE-PREVIEW"},
              {"id":"other","kind":"work","title":"PRIVATE-PREVIEW uncited"}]}"#,
        )
        .unwrap();
        let before = fs::read(&library).unwrap();
        let session = login_ok(&f);
        let preview = handle(
            &f.state,
            &authed(
                json_req(
                    "POST",
                    "/admin/api/preview",
                    json!({
                        "kind": "posts",
                        "path": "posts/cited.md",
                        "fields": { "title": "Cited", "date": "2026-10-23", "citations": "notes" },
                        "body": "A claim [@bare, canonical 4]."
                    }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(
            preview.status,
            200,
            "{}",
            String::from_utf8_lossy(&preview.body)
        );
        let body = body_json(&preview);
        let citations = &body["citations"];
        assert_eq!(citations["style"], "notes");
        assert_eq!(citations["citations"], 1);
        assert_eq!(citations["references"], 1);
        assert_eq!(citations["offline"], true);
        let csl = &citations["exports"]["csl-json"];
        assert_eq!(csl["filename"], "cited-references.json");
        assert!(csl["content"]
            .as_str()
            .unwrap()
            .contains("\"id\": \"bare\""));
        let bibtex = &citations["exports"]["bibtex"];
        assert_eq!(bibtex["filename"], "cited-references.bib");
        assert!(bibtex["content"]
            .as_str()
            .unwrap()
            .starts_with("@article{bare,"));
        assert!(!body.to_string().contains("PRIVATE-PREVIEW"));
        let codes: Vec<&str> = body["evidence"]
            .as_array()
            .unwrap()
            .iter()
            .map(|finding| finding["code"].as_str().unwrap())
            .collect();
        assert!(
            codes.contains(&"citation-reference-incomplete"),
            "{codes:?}"
        );
        assert!(codes.contains(&"citation-location-review"), "{codes:?}");
        // A preview writes nothing.
        assert_eq!(fs::read(&library).unwrap(), before);
        assert!(!f.dir.join("content/posts/cited.md").exists());
    }

    #[test]
    fn the_preview_resolves_concept_links_against_the_public_atlas_and_reports_the_rest() {
        let f = fixture_with_sources("preview-concept-links");
        seeded_atlas(&f);
        let session = login_ok(&f);
        let preview = |body: &str| {
            let response = handle(
                &f.state,
                &authed(
                    json_req(
                        "POST",
                        "/admin/api/preview",
                        json!({
                            "kind": "posts",
                            "path": "posts/cave.md",
                            "fields": { "title": "Cave", "date": "2026-10-23" },
                            "body": body,
                        }),
                    ),
                    &session,
                    true,
                ),
            );
            assert_eq!(response.status, 200);
            let json = body_json(&response);
            let url = json["previewUrl"].as_str().unwrap().to_string();
            let document = handle(&f.state, &authed(req("GET", &url), &session, false));
            (json, String::from_utf8_lossy(&document.body).to_string())
        };
        let body = "See [the Republic](atlas:politeia), [a ghost](atlas:nobody) and [a private one](atlas:secret-thing).";

        // The atlas is not published: every link is its label, and the
        // warning says why. No raw `atlas:` address reaches the page.
        let (json, html) = preview(body);
        assert!(
            !html.contains("atlas:") && !html.contains("<ob-concept "),
            "{html}"
        );
        assert!(html.contains("the Republic"));
        let warnings = json["warnings"].to_string();
        assert!(
            warnings.contains("`atlas:politeia`") && warnings.contains("is off"),
            "{warnings}"
        );

        // Published: an approved entry is the ordinary link the build makes,
        // and an entry the atlas does not publish is plain text and a warning.
        let config_path = f.dir.join(site::CONFIG_FILE);
        let mut config: Json = serde_json::from_slice(&fs::read(&config_path).unwrap()).unwrap();
        config["knowledgeAtlas"] = json!({"publish": true});
        fs::write(&config_path, serde_json::to_vec_pretty(&config).unwrap()).unwrap();
        let (json, html) = preview(body);
        assert!(
            html.contains(
                "<a class=\"ob-concept\" href=\"/atlas/politeia/\" data-atlas-entry=\"politeia\""
            ),
            "{html}"
        );
        assert!(
            !html.contains("atlas:") && !html.contains("<ob-concept "),
            "{html}"
        );
        let warnings = json["warnings"].to_string();
        assert!(
            warnings.contains("`atlas:nobody`") && warnings.contains("`atlas:secret-thing`"),
            "{warnings}"
        );
        assert!(!warnings.contains("`atlas:politeia`"), "{warnings}");
        // A preview writes nothing, and a post without the syntax is unchanged.
        assert!(!f.dir.join("content/posts/cave.md").exists());
        let (json, html) = preview("Nothing linked.");
        assert!(!html.contains("ob-concept"));
        assert!(!json["warnings"].to_string().contains("concept link"));
    }

    #[test]
    fn a_cited_preview_loads_its_citation_previews_from_the_site_under_the_preview_policy() {
        let f = fixture("citation-preview-csp");
        let library = f.dir.join(source_store::LIBRARY_FILE);
        fs::create_dir_all(library.parent().unwrap()).unwrap();
        fs::write(
            &library,
            r#"{"version":1,"sources":[
              {"id":"hostile","kind":"work","title":"</script><img src=x onerror=alert(1)>"}]}"#,
        )
        .unwrap();
        let session = login_ok(&f);
        let preview = handle(
            &f.state,
            &authed(
                json_req(
                    "POST",
                    "/admin/api/preview",
                    json!({
                        "kind": "posts",
                        "path": "posts/cited.md",
                        "fields": { "title": "Cited", "date": "2026-10-23", "citations": "notes" },
                        "body": "A claim [@hostile, canonical 4]."
                    }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(preview.status, 200);
        let url = body_json(&preview)["previewUrl"]
            .as_str()
            .unwrap()
            .to_string();
        let document = handle(&f.state, &authed(req("GET", &url), &session, false));
        assert_eq!(document.status, 200);
        let html = String::from_utf8_lossy(&document.body);
        // The data is inert and the component comes from the site itself.
        assert_eq!(html.matches("id=\"ob-references\"").count(), 1);
        assert!(html.contains(
            "<script type=\"module\" src=\"/assets/components/ob-citation-previews.js?v="
        ));
        assert!(html.contains("<ob-citation-previews note-label=\"Go to note\">"));
        assert!(!html.contains("<img src=x"), "hostile text stays text");
        // The preview policy lets that same-origin module run and nothing the
        // component needs reaches beyond it: no inline handler is required,
        // no plugin, no other base, no outside frame ancestor.
        let csp = document
            .headers
            .iter()
            .find(|(name, _)| name == "Content-Security-Policy")
            .map(|(_, value)| value.clone())
            .unwrap();
        let directive = |name: &str| {
            csp.split(';')
                .map(str::trim)
                .find(|directive| directive.split_whitespace().next() == Some(name))
                .unwrap_or_else(|| panic!("{name} missing from {csp}"))
                .to_string()
        };
        assert!(directive("default-src").ends_with("'none'"), "{csp}");
        assert!(directive("script-src").contains("'self'"), "{csp}");
        assert_eq!(directive("object-src"), "object-src 'none'");
        assert_eq!(directive("base-uri"), "base-uri 'self'");
        assert_eq!(directive("frame-ancestors"), "frame-ancestors 'self'");
        // The module is served from the site, readable by the sandboxed
        // preview frame, and is the bundled component.
        let module = crate::serve::route(
            &f.state,
            &req("GET", "/assets/components/ob-citation-previews.js"),
            &f.dir.join("dist"),
        );
        assert_eq!(module.status, 200);
        assert!(module
            .headers
            .iter()
            .any(|(name, value)| name == "Content-Type" && value.contains("javascript")));
        assert!(module
            .headers
            .iter()
            .any(|(name, value)| name == "Access-Control-Allow-Origin" && value == "*"));
        assert!(String::from_utf8_lossy(&module.body).contains("class ObCitationPreviews"));
        // The Admin application itself keeps its strict policy.
        let admin = handle(&f.state, &req("GET", "/admin"));
        let strict = admin
            .headers
            .iter()
            .find(|(name, _)| name == "Content-Security-Policy")
            .unwrap();
        assert!(!strict.1.contains("unsafe-inline"), "{}", strict.1);
    }

    #[test]
    fn preview_evidence_is_scoped_to_the_current_research_document() {
        let f = fixture("preview-evidence");
        fs::write(
            f.dir.join("content/posts/unrelated.md"),
            "---\ntitle: Unrelated\ndate: 2026-10-22\nprofile: research\n---\nBody.\n",
        )
        .unwrap();
        let session = login_ok(&f);

        let preview = handle(
            &f.state,
            &authed(
                json_req(
                    "POST",
                    "/admin/api/preview",
                    json!({
                        "kind": "posts",
                        "path": "posts/current.md",
                        "fields": {
                            "title": "Current",
                            "date": "2026-10-23",
                            "profile": "research",
                            "doi": "invalid"
                        },
                        "body": "<!--\n## Abstract\n## References\n-->\n\nA claim.[^missing]"
                    }),
                ),
                &session,
                true,
            ),
        );
        assert_eq!(
            preview.status,
            200,
            "{}",
            String::from_utf8_lossy(&preview.body)
        );
        let findings = body_json(&preview)["evidence"].as_array().unwrap().clone();

        assert!(findings.iter().any(|finding| {
            finding["code"] == "doi-invalid" && finding["source"]["path"] == "posts/current.md"
        }));
        assert!(findings
            .iter()
            .any(|finding| finding["code"] == "footnote-unresolved"));
        assert!(findings
            .iter()
            .any(|finding| finding["code"] == "abstract-missing"));
        assert!(findings
            .iter()
            .any(|finding| finding["code"] == "references-missing"));
        assert_eq!(body_json(&preview)["research"]["doi"], "invalid");
        assert_eq!(body_json(&preview)["research"]["referenceCount"], 0);
        assert!(!findings
            .iter()
            .any(|finding| finding["source"]["path"] == "posts/unrelated.md"));
    }

